/**
 * Plan and line model: new lines, canonical LineInput output, local previews through engine.js,
 * bundle coverage (mirror of PlanCalculator's rule), plan documents and plan file import.
 *
 * A line in the workspace has exactly the LineInput keys of ARCHITECTURE §3.5. Fields that the
 * user has not filled are null (amounts and frequencies start EMPTY; only the plan length - period
 * unit and number of periods - starts at the store settings, and add-ons sold by quantity only
 * start at 1 purchase unit).
 *
 * @module plan
 */

import {
	validateLine,
	calculateLine,
	buildTimeline,
	normalizeUnit,
	dimensionOf,
	dateError,
	decimalError,
	canonicalAmount,
	parseAmount,
	formatScaled,
	FIELDS,
	MODES,
	PERIOD_UNITS,
	MAX_LABEL_LENGTH,
	CalculationError,
	ValidationError,
} from './engine.js';
import { isPlannable, modesFor } from './catalog.js';
import { MAX_TITLE_LENGTH, MAX_NOTES_LENGTH } from './store.js';

/** Plan document schema id and version. */
export const PLAN_SCHEMA = 'arp-plan';
export const PLAN_VERSION = 1;

/** Maximum plan file size (bytes). */
export const MAX_PLAN_BYTES = 65536;

const ID_PATTERN = /^[a-z0-9_-]{1,40}$/;
const ATTRIBUTE_KEY = /^attribute_[a-z0-9_%-]{1,190}$/;
const PLAN_KEYS = [ 'schema', 'version', 'title', 'start_date', 'lines', 'notes' ];

/**
 * Random line ID `l_xxxxxxxx`.
 *
 * @return {string} ID.
 */
export function newLineId() {
	const bytes = new Uint8Array( 6 );
	if ( typeof crypto !== 'undefined' && crypto.getRandomValues ) {
		crypto.getRandomValues( bytes );
	} else {
		for ( let i = 0; i < bytes.length; i++ ) {
			bytes[ i ] = Math.floor( Math.random() * 256 );
		}
	}
	return 'l_' + Array.from( bytes, ( b ) => ( b % 36 ).toString( 36 ) ).join( '' ) + Date.now().toString( 36 ).slice( -4 );
}

/**
 * RFC 4122 version 4 UUID (cart request IDs).
 *
 * @return {string} UUID.
 */
export function uuid4() {
	if ( typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function' ) {
		return crypto.randomUUID();
	}
	const b = new Uint8Array( 16 );
	if ( typeof crypto !== 'undefined' && crypto.getRandomValues ) {
		crypto.getRandomValues( b );
	} else {
		for ( let i = 0; i < 16; i++ ) {
			b[ i ] = Math.floor( Math.random() * 256 );
		}
	}
	b[ 6 ] = ( b[ 6 ] & 0x0f ) | 0x40;
	b[ 8 ] = ( b[ 8 ] & 0x3f ) | 0x80;
	const hex = Array.from( b, ( x ) => x.toString( 16 ).padStart( 2, '0' ) ).join( '' );
	return `${ hex.slice( 0, 8 ) }-${ hex.slice( 8, 12 ) }-${ hex.slice( 12, 16 ) }-${ hex.slice( 16, 20 ) }-${ hex.slice( 20 ) }`;
}

/**
 * A new line for a product. Amount, events and quantities start empty.
 *
 * @param {Object}      options              Options.
 * @param {number}      options.productId    Product ID.
 * @param {Object|null} options.unit         Resolved unit (null until a variant is chosen).
 * @param {Object}      options.selection    Variation attribute choices.
 * @param {Object}      options.defaults     { period_unit, periods } from the settings.
 * @param {string}      options.id           Line ID (generated when omitted).
 * @return {Object} Line.
 */
export function createLine( { productId, unit = null, selection = {}, defaults = {}, id = '' } ) {
	const line = {
		id: id || newLineId(),
		product_id: productId,
		variation_id: unit ? unit.variationId : 0,
		variation_attributes: { ...selection },
		mode: 'schedule',
		amount: null,
		unit: null,
		events_per_period: null,
		period_unit: PERIOD_UNITS.includes( defaults.period_unit ) ? defaults.period_unit : 'week',
		periods: Number.isInteger( defaults.periods ) && defaults.periods > 0 ? defaults.periods : null,
		start_date: null,
		override_quantity: null,
		manual_quantity: null,
		label: '',
	};
	return applyUnit( line, unit );
}

/**
 * Adapts a NEW line to its unit: allowed mode, preferred compatible unit and, for units that can
 * only be bought by quantity (add-ons, bundles), a purchase quantity of 1. Lines that already hold
 * the visitor's values go through adaptLine() instead, which never relabels or invents values.
 *
 * @param {Object}      line Line.
 * @param {Object|null} unit Unit.
 * @return {Object} Line (new object).
 */
export function applyUnit( line, unit ) {
	return adaptLine( line, unit, { fresh: true } ).line;
}

/**
 * Whether the visitor has entered any research or quantity value on the line.
 *
 * @param {Object} line Line.
 * @return {boolean} Has values.
 */
export function hasUserValues( line ) {
	return line.amount !== null || line.events_per_period !== null || line.manual_quantity !== null || line.override_quantity !== null;
}

/**
 * Converts an amount EXACTLY between two units of the same dimension (mcg ↔ mg ↔ g).
 *
 * @param {string} amount Canonical amount in `from`.
 * @param {string} from   Unit of the amount.
 * @param {string} to     Target unit.
 * @return {string|null} Canonical amount in `to`, or null when the units are of different
 *   dimensions or the result is not exact / not a valid amount (more than 4 decimals, too large).
 */
export function convertAmount( amount, from, to ) {
	const source = normalizeUnit( from );
	const target = normalizeUnit( to );
	if ( typeof amount !== 'string' || source === null || target === null || dimensionOf( source ) !== dimensionOf( target ) ) {
		return null;
	}
	if ( decimalError( amount ) !== null ) {
		return null;
	}
	if ( source === target ) {
		return canonicalAmount( amount );
	}
	try {
		const converted = formatScaled( parseAmount( amount, source ), target );
		return converted.exact && decimalError( converted.value ) === null ? canonicalAmount( converted.value ) : null;
	} catch ( e ) {
		return null;
	}
}

/**
 * Changes of a line when the visitor picks another unit: the amount is converted exactly within the
 * same dimension, otherwise it is cleared. An entered number is never kept under a new unit.
 *
 * @param {Object} line Line.
 * @param {string} unit New unit.
 * @return {{changes: Object, notice: Object|null}} Changes and, when the amount was touched, an
 *   explanation { type: converted|cleared, reason, from, to, amount, converted }.
 */
export function changeUnit( line, unit ) {
	const target = normalizeUnit( unit );
	if ( target === null || target === line.unit ) {
		return { changes: {}, notice: null };
	}
	if ( line.amount === null || line.unit === null ) {
		return { changes: { unit: target }, notice: null };
	}
	const converted = convertAmount( line.amount, line.unit, target );
	if ( converted !== null ) {
		return { changes: { unit: target, amount: converted }, notice: { type: 'converted', reason: '', from: line.unit, to: target, amount: line.amount, converted } };
	}
	return {
		changes: { unit: target, amount: null },
		notice: { type: 'cleared', reason: dimensionOf( line.unit ) === dimensionOf( target ) ? 'inexact' : 'dimension', from: line.unit, to: target, amount: line.amount, converted: null },
	};
}

/**
 * Adapts a line to a (new or reloaded) unit.
 *
 * - The mode must be one the unit allows (`modes` from the API). When a line that already holds
 *   values has to change mode, nothing is invented: a manual quantity is only pre-set to 1 while
 *   the visitor has not entered anything yet, and a notice explains the change.
 * - A stored unit that the unit no longer offers is converted exactly within its dimension;
 *   otherwise the amount is cleared with a notice. The number is never relabelled.
 *
 * @param {Object}      line    Line.
 * @param {Object|null} unit    Unit (null until a variant is chosen).
 * @param {Object}      options { fresh: boolean } — true for a brand-new line.
 * @return {{line: Object, notice: Object|null}} Adapted line and, when a value of the visitor was
 *   changed, an explanation { type: converted|cleared|mode, reason, from, to, amount, converted }.
 */
export function adaptLine( line, unit, options = {} ) {
	const next = { ...line, variation_id: unit ? unit.variationId : 0 };
	if ( ! unit ) {
		return { line: next, notice: null };
	}
	const fresh = options.fresh === true || ! hasUserValues( line );
	let notice = null;
	const modes = modesFor( unit );
	if ( modes.length > 0 && ! modes.includes( next.mode ) ) {
		const previous = next.mode;
		next.mode = modes[ 0 ];
		if ( ! fresh ) {
			notice = { type: 'mode', reason: '', from: previous, to: next.mode, amount: null, converted: null };
		}
	}
	if ( fresh && next.mode === 'manual' && modes.length === 1 && next.manual_quantity === null ) {
		next.manual_quantity = 1;
	}
	const compatible = unit.compatibleUnits;
	if ( compatible.length === 0 ) {
		next.unit = null;
		return { line: next, notice };
	}
	if ( next.unit !== null && compatible.includes( next.unit ) ) {
		return { line: next, notice };
	}
	const capacityUnit = unit.capacities.length > 0 ? unit.capacities[ 0 ].unit : null;
	const preferred = capacityUnit && compatible.includes( capacityUnit ) ? capacityUnit : compatible[ 0 ];
	if ( next.unit === null || next.amount === null ) {
		next.unit = preferred;
		return { line: next, notice };
	}
	// The stored unit is no longer offered: convert within the same dimension when that is exact.
	const dimension = dimensionOf( next.unit );
	const sameDimension = [ preferred, ...compatible.filter( ( u ) => u !== preferred ) ].filter( ( u ) => dimensionOf( u ) === dimension );
	for ( const candidate of sameDimension ) {
		const converted = convertAmount( next.amount, next.unit, candidate );
		if ( converted !== null ) {
			const change = { type: 'converted', reason: '', from: next.unit, to: candidate, amount: next.amount, converted };
			next.unit = candidate;
			next.amount = converted;
			return { line: next, notice: notice || change };
		}
	}
	const cleared = { type: 'cleared', reason: sameDimension.length > 0 ? 'inexact' : 'dimension', from: next.unit, to: preferred, amount: next.amount, converted: null };
	next.unit = preferred;
	next.amount = null;
	return { line: next, notice: notice || cleared };
}

/**
 * Canonical LineInput for the API (fields not used by the mode are null).
 *
 * @param {Object} line Workspace line.
 * @return {Object} LineInput.
 */
export function toLineInput( line ) {
	const schedule = line.mode === 'schedule';
	const calc = schedule || line.mode === 'direct';
	const attributes = {};
	for ( const [ key, value ] of Object.entries( line.variation_attributes || {} ) ) {
		if ( ATTRIBUTE_KEY.test( key ) && typeof value === 'string' ) {
			attributes[ key ] = value;
		}
	}
	return {
		id: line.id,
		product_id: line.product_id,
		variation_id: line.variation_id || 0,
		variation_attributes: attributes,
		mode: line.mode,
		amount: calc ? line.amount ?? null : null,
		unit: calc ? line.unit ?? null : null,
		events_per_period: schedule ? line.events_per_period ?? null : null,
		period_unit: schedule ? line.period_unit ?? null : null,
		periods: schedule ? line.periods ?? null : null,
		start_date: line.start_date || null,
		override_quantity: calc ? line.override_quantity ?? null : null,
		manual_quantity: line.mode === 'manual' ? line.manual_quantity ?? null : null,
		label: typeof line.label === 'string' ? line.label : '',
	};
}

/**
 * Whether every value required by the mode has been entered (no message noise before that).
 *
 * @param {Object} line Line.
 * @return {boolean} Complete.
 */
export function isComplete( line ) {
	if ( line.mode === 'manual' ) {
		return line.manual_quantity !== null;
	}
	if ( line.amount === null || line.unit === null ) {
		return false;
	}
	return line.mode === 'direct' || ( line.events_per_period !== null && line.periods !== null && !! line.period_unit );
}

/**
 * Units supplied by bundle lines, keyed by the line they are offered to — the mirror of
 * PlanCalculator's rule:
 *
 * 1. Only manual bundle lines whose own calculation succeeds supply units (quantity ×
 *    component.quantity purchase units per covered product + variation).
 * 2. In plan order, the supplied units are offered to the schedule/direct lines of that product +
 *    variation. A line that does not calculate (incomplete, invalid, blocked, incompatible unit…)
 *    is skipped and receives nothing. A line that calculates uses at most the units it requires
 *    (its `bundle_covered_units`); the rest carries over to the next line of the same unit.
 *
 * The value for a line is the number of units OFFERED to it (the calculator's
 * `bundleCoveredUnits` argument); its result reports how many it used.
 *
 * @param {Object[]} lines   Lines.
 * @param {Function} unitOf  ( line ) => unit|null.
 * @param {Object}   options previewLine() options (limits, planStart, priceDecimals, showPrices).
 * @return {Map<string, number>} line ID => units offered.
 */
export function bundleCoverage( lines, unitOf, options = {} ) {
	const preview = ( line, unit, covered ) => previewLine( line, unit, { ...options, covered, withTimeline: false } );
	const supplied = new Map();
	for ( const line of lines ) {
		const unit = line.mode === 'manual' ? unitOf( line ) : null;
		if ( ! unit || unit.containerType !== 'bundle' || ! Array.isArray( unit.components ) || unit.components.length === 0 ) {
			continue;
		}
		if ( preview( line, unit, 0 ).status !== 'ok' ) {
			continue;
		}
		for ( const component of unit.components ) {
			const key = component.product_id + ':' + ( component.variation_id || 0 );
			supplied.set( key, ( supplied.get( key ) || 0 ) + line.manual_quantity * component.quantity );
		}
	}
	const coverage = new Map();
	if ( supplied.size === 0 ) {
		return coverage;
	}
	for ( const line of lines ) {
		if ( line.mode !== 'schedule' && line.mode !== 'direct' ) {
			continue;
		}
		const key = line.product_id + ':' + ( line.variation_id || 0 );
		const remaining = supplied.get( key ) || 0;
		if ( remaining <= 0 ) {
			continue;
		}
		const outcome = preview( line, unitOf( line ), remaining );
		if ( outcome.status !== 'ok' || ! outcome.result ) {
			continue;
		}
		coverage.set( line.id, remaining );
		const used = Math.min( remaining, Math.max( 0, Number( outcome.result.bundle_covered_units ) || 0 ) );
		supplied.set( key, remaining - used );
	}
	return coverage;
}

/**
 * Local (preview) calculation of one line with engine.js.
 *
 * @param {Object}      line          Line.
 * @param {Object|null} unit          Unit.
 * @param {Object}      options       { planStart, priceDecimals, covered, showPrices, limits, withTimeline }
 *                                    (withTimeline: false skips the timeline when only the quantity is needed).
 * @return {{status: string, result: Object|null, timeline: Object|null, errors: Array, code: string}} Preview.
 *   status: incomplete | blocked | invalid | error | ok
 */
export function previewLine( line, unit, options = {} ) {
	const empty = { result: null, timeline: null, errors: [], code: '' };
	if ( ! unit ) {
		return { ...empty, status: 'incomplete' };
	}
	if ( ! isPlannable( unit ) ) {
		return { ...empty, status: 'blocked', code: unit.readiness };
	}
	if ( ! isComplete( line ) ) {
		return { ...empty, status: 'incomplete' };
	}
	const input = toLineInput( line );
	const validation = validateLine( input, options.limits || {} );
	if ( ! validation.ok ) {
		return { ...empty, status: 'invalid', errors: validation.errors };
	}
	try {
		const result = calculateLine(
			validation.line,
			unit.capacities,
			unit.packCount,
			options.showPrices === false ? '' : unit.price,
			Number.isInteger( options.priceDecimals ) ? options.priceDecimals : 2,
			options.covered || 0
		);
		let timeline = null;
		if ( result.mode === 'schedule' && options.withTimeline !== false ) {
			timeline = buildTimeline( validation.line, result, options.planStart || null );
		}
		return { status: 'ok', result, timeline, errors: [], code: '' };
	} catch ( e ) {
		if ( e instanceof CalculationError ) {
			return { ...empty, status: 'error', code: e.code };
		}
		if ( e instanceof ValidationError ) {
			return { ...empty, status: 'invalid', errors: e.errors };
		}
		return { ...empty, status: 'error', code: 'calculation_failed' };
	}
}

/**
 * Plan document (schema arp-plan v1) of a workspace.
 *
 * @param {Object} workspace Workspace state.
 * @return {Object} Plan.
 */
export function planDocument( workspace ) {
	return {
		schema: PLAN_SCHEMA,
		version: PLAN_VERSION,
		title: workspace.title || '',
		start_date: workspace.start_date || null,
		lines: workspace.lines.map( toLineInput ),
		notes: workspace.notes || '',
	};
}

/**
 * Whether the plan has any start date (calendar exports need one).
 *
 * @param {Object} plan Plan or workspace.
 * @return {boolean} Has a start date.
 */
export function hasStartDate( plan ) {
	return !! plan.start_date || ( Array.isArray( plan.lines ) && plan.lines.some( ( line ) => !! line.start_date && line.mode === 'schedule' ) );
}

/**
 * Integer in range or null.
 *
 * @param {*}      v   Value.
 * @param {number} min Minimum.
 * @param {number} max Maximum.
 * @return {number|null} Value.
 */
function intIn( v, min, max ) {
	return typeof v === 'number' && Number.isSafeInteger( v ) && v >= min && v <= max ? v : null;
}

/**
 * Sanitizes one stored line (drafts, plan files, account plans, shares): invalid values become
 * null, unknown keys are dropped. Returns null when the product or mode is unusable.
 *
 * @param {*}   raw  Raw line.
 * @param {Set} used IDs already used in the plan (new IDs are generated for duplicates).
 * @return {Object|null} Line.
 */
export function sanitizeLine( raw, used = new Set() ) {
	if ( ! raw || typeof raw !== 'object' || Array.isArray( raw ) ) {
		return null;
	}
	const productId = intIn( raw.product_id, 1, Number.MAX_SAFE_INTEGER );
	const mode = MODES.includes( raw.mode ) ? raw.mode : null;
	if ( productId === null || mode === null ) {
		return null;
	}
	let id = typeof raw.id === 'string' && ID_PATTERN.test( raw.id ) ? raw.id : newLineId();
	while ( used.has( id ) ) {
		id = newLineId();
	}
	used.add( id );
	const attributes = {};
	if ( raw.variation_attributes && typeof raw.variation_attributes === 'object' ) {
		for ( const [ key, value ] of Object.entries( raw.variation_attributes ) ) {
			if ( ATTRIBUTE_KEY.test( key ) && typeof value === 'string' && value.length <= 200 ) {
				attributes[ key ] = value;
			}
		}
	}
	const amount = typeof raw.amount === 'string' && decimalError( raw.amount ) === null ? canonicalAmount( raw.amount ) : null;
	const unit = typeof raw.unit === 'string' ? normalizeUnit( raw.unit ) : null;
	const line = {
		id,
		product_id: productId,
		variation_id: intIn( raw.variation_id, 0, Number.MAX_SAFE_INTEGER ) ?? 0,
		variation_attributes: attributes,
		mode,
		amount,
		unit: unit && dimensionOf( unit ) ? unit : null,
		events_per_period: intIn( raw.events_per_period, 1, 1000 ),
		period_unit: PERIOD_UNITS.includes( raw.period_unit ) ? raw.period_unit : 'week',
		periods: intIn( raw.periods, 1, 3660 ),
		start_date: typeof raw.start_date === 'string' && dateError( raw.start_date ) === null ? raw.start_date : null,
		override_quantity: intIn( raw.override_quantity, 0, 9999 ),
		manual_quantity: intIn( raw.manual_quantity, 1, 9999 ),
		label: typeof raw.label === 'string' ? raw.label.replace( /[\u0000-\u001F\u007F]/g, ' ' ).slice( 0, MAX_LABEL_LENGTH ) : '',
	};
	if ( mode === 'manual' && line.manual_quantity === null && intIn( raw.quantity, 1, 9999 ) !== null ) {
		line.manual_quantity = raw.quantity;
	}
	return line;
}

/**
 * Sanitizes a stored plan (any source) into workspace data.
 *
 * @param {*}      raw      Raw plan.
 * @param {number} maxLines Maximum lines kept.
 * @return {{title: string, start_date: string|null, notes: string, lines: Object[], dropped: number}} Plan.
 */
export function sanitizePlan( raw, maxLines = 100 ) {
	const plan = raw && typeof raw === 'object' ? raw : {};
	const used = new Set();
	const source = Array.isArray( plan.lines ) ? plan.lines : [];
	const lines = [];
	let dropped = 0;
	for ( const entry of source ) {
		const line = lines.length < maxLines ? sanitizeLine( entry, used ) : null;
		if ( line ) {
			lines.push( line );
		} else {
			dropped++;
		}
	}
	return {
		title: typeof plan.title === 'string' ? plan.title.replace( /[\u0000-\u001F\u007F]/g, ' ' ).slice( 0, MAX_TITLE_LENGTH ) : '',
		start_date: typeof plan.start_date === 'string' && dateError( plan.start_date ) === null ? plan.start_date : null,
		notes: typeof plan.notes === 'string' ? plan.notes.slice( 0, MAX_NOTES_LENGTH ) : '',
		lines,
		dropped,
	};
}

/**
 * Parses an imported plan file (.json, schema arp-plan v1, ≤ 64 KB).
 *
 * @param {string} text     File contents.
 * @param {number} maxLines Maximum lines.
 * @return {{ok: boolean, plan: Object|null, code: string}} Result. Codes: too_large, invalid_json,
 *   wrong_schema, unknown_field, too_many_lines, invalid_lines.
 */
export function parsePlanFile( text, maxLines = 100 ) {
	const size = typeof TextEncoder === 'function' ? new TextEncoder().encode( String( text ) ).length : String( text ).length;
	if ( size > MAX_PLAN_BYTES ) {
		return { ok: false, plan: null, code: 'too_large' };
	}
	let data;
	try {
		data = JSON.parse( String( text ).replace( /^﻿/, '' ) );
	} catch ( e ) {
		return { ok: false, plan: null, code: 'invalid_json' };
	}
	if ( ! data || typeof data !== 'object' || Array.isArray( data ) || data.schema !== PLAN_SCHEMA || data.version !== PLAN_VERSION ) {
		return { ok: false, plan: null, code: 'wrong_schema' };
	}
	if ( Object.keys( data ).some( ( key ) => ! PLAN_KEYS.includes( key ) ) ) {
		return { ok: false, plan: null, code: 'unknown_field' };
	}
	if ( ! Array.isArray( data.lines ) ) {
		return { ok: false, plan: null, code: 'invalid_lines' };
	}
	if ( data.lines.length > maxLines ) {
		return { ok: false, plan: null, code: 'too_many_lines' };
	}
	const unknownLineKey = data.lines.some( ( line ) => line && typeof line === 'object' && Object.keys( line ).some( ( key ) => ! FIELDS.includes( key ) ) );
	if ( unknownLineKey ) {
		return { ok: false, plan: null, code: 'unknown_field' };
	}
	const plan = sanitizePlan( data, maxLines );
	if ( plan.dropped > 0 ) {
		return { ok: false, plan: null, code: 'invalid_lines' };
	}
	return { ok: true, plan, code: '' };
}
