/**
 * Result message of a dialog that re-renders its content (Plans, Share).
 *
 * One role="status" and one role="alert" region are created once and never re-rendered or moved,
 * so screen readers announce a result exactly once: the text is written only when the message
 * changes, and a dialog re-render (e.g. a list reload) never inserts the same result again. The
 * visible message is a paragraph inside the matching region; it can take focus (tabindex -1) when
 * the control that triggered it no longer exists.
 *
 * @package Atlas\ResearchPlanner
 */

import { h, render } from '../app/dom.js';

/**
 * Stable identity of a message ('' = none).
 *
 * @param {{tone: string, text: string}|null} message Message.
 * @return {string} Key.
 */
export function messageKey( message ) {
	if ( ! message || ! message.text ) {
		return '';
	}
	return ( message.tone === 'error' ? 'error' : String( message.tone || 'info' ) ) + '\n' + String( message.text );
}

/**
 * Creates the persistent message regions.
 *
 * @return {{el: HTMLElement, set: Function, element: Function}} `el` to insert once; `set( message )`
 *   updates the regions (no DOM write when the message is unchanged) and returns the visible
 *   paragraph or null; `element()` returns the visible paragraph or null.
 */
export function createLiveMessage() {
	const status = h( 'div', { class: 'arp-live-message__region', role: 'status' } );
	const alert = h( 'div', { class: 'arp-live-message__region', role: 'alert' } );
	const el = h( 'div', { class: 'arp-live-message' }, status, alert );
	let key = '';
	let current = null;

	const set = ( message ) => {
		const next = messageKey( message );
		if ( next === key ) {
			return current;
		}
		key = next;
		render( status );
		render( alert );
		current = null;
		if ( '' === next ) {
			return null;
		}
		const tone = message.tone === 'error' ? 'error' : message.tone === 'success' ? 'success' : 'info';
		current = h( 'p', { class: [ 'arp-notice', 'arp-notice--' + tone ], tabindex: '-1' }, String( message.text ) );
		( 'error' === tone ? alert : status ).appendChild( current );
		return current;
	};

	return { el, set, element: () => current };
}
