const READINESS_CODES = [ 'product_not_found', 'unavailable', 'excluded_category', 'excluded_format', 'needs_mapping', 'disabled', 'unverified', 'stale_mapping', 'invalid' ];
const SHARE_TOKEN = /^[A-Za-z0-9_-]{43}$/;
/** ID of a protocol saved in the customer's account: a 36-character UUID (CHANGE-1.2.0 §8). */
const PROTOCOL_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * Deep links in a URL fragment: #add=<product ID>, #share=<token>, #protocol=<uuid> (a protocol
 * saved in the customer's account, opened from the account area; CHANGE-1.2.0 §8) and the store
 * protocol links #store-protocol=<id>, #store-protocol-edit=<id> and #store-protocols=…
 * (CHANGE-1.7.0 §6.8, `parseStoreLink()`).
 *
 * @param {string} fragment location.hash (with or without the leading '#').
 * @return {{add: string|null, share: string|null, protocol: string|null, store: Object|null}} Values as given; null when absent.
 */
export function parseDeepLink( fragment ) {
	const params = new URLSearchParams( String( fragment || '' ).replace( /^#/, '' ) );
	return { add: params.get( 'add' ), share: params.get( 'share' ), protocol: params.get( 'protocol' ), store: parseStoreLink( params ) };
}

/**
 * Whether a parsed fragment is a deep link the app consumes (rather than a step or in-page anchor).
 *
 * @param {{add: string|null, share: string|null, protocol: string|null, store: Object|null}} hash Parsed fragment.
 * @return {boolean} Deep link.
 */
export function isDeepLink( hash ) {
	return !! ( hash.add || hash.share ) || typeof hash.protocol === 'string' || !! hash.store;
}

/**
 * Saved-protocol ID of a #protocol= value: the UUID in lower case (as saved protocols are keyed),
 * or null when the value is not a 36-character UUID.
 *
 * @param {*} value #protocol= value.
 * @return {string|null} UUID.
 */
export function protocolId( value ) {
	return typeof value === 'string' && PROTOCOL_ID.test( value ) ? value.toLowerCase() : null;
}

/**
 * Whether loading a saved protocol failed because it cannot be found for this visitor: unknown,
 * another customer's or malformed IDs (404 arp_not_found) and a session that is no longer logged in
 * (401) all get the same not-found message.
 *
 * @param {*} error ApiError.
 * @return {boolean} Not found.
 */
export function isMissingProtocol( error ) {
	return !! error && ( error.status === 404 || error.status === 401 || error.code === 'arp_not_found' || error.code === 'rest_not_logged_in' );
}

/**
 * Creates the planner app.
 *
 * @param {HTMLElement} root   App root ([data-arp-root]).
 * @param {Object}      config Parsed #arp-config.
 * @return {{boot: Function, addProduct: Function}} App.
 */
export function createApp( root, config ) {
	const scope = root.closest( '.arp-planner' ) || root.parentElement;
	const locale = typeof config.locale === 'string' && config.locale !== '' ? config.locale : 'en-US';
	const maxLines = Number.isInteger( config.max_lines ) && config.max_lines > 0 ? config.max_lines : 25;
	// Durations are entered in weeks; a new line starts with the store's default number of periods.
	const defaults = { period_unit: 'week', periods: config.default_periods };
	const stalePriceMs = Math.max( 1, Number( config.stale_price_minutes ) || 15 ) * 60000;
	const showImages = config.show_images !== false;
	const showTimeline = config.show_timeline !== false;

	let currency = normalizeCurrency( config.currency );
	let features = { ...( config.features || {} ) };
	let limits = effectiveLimits( config.limits && typeof config.limits === 'object' ? config.limits : {} );
	let urls = { ...( config.urls || {} ) };
	let loggedIn = false;
	/** Store manager: may publish the workspace as a store protocol (GET /session store_protocols.can_publish). */
	let canPublish = false;
	/** The first list of store protocols was requested (it is requested once the session is known). */
	let storeProtocolsRequested = false;
	let booted = false;
	/** Settles once the first GET /session finished (or failed): who the visitor is and which features apply. */
	let settleSession = () => {};
	let sessionKnown = false;
	const sessionSettled = new Promise( ( resolve ) => {
		settleSession = () => {
			sessionKnown = true;
			resolve();
		};
	} );
	/** Pending openPlans() call (one at a time: repeated clicks while the session loads are ignored). */
	let plansOpening = null;

	const api = createApi( { root: config.rest_root } );
	const drafts = createDrafts();
	const store = createStore( workspaceReducer, initialWorkspace( '' ) );

	const products = new Map();
	const liveUnits = new Map();
	const results = new Map();
	const cartErrors = new Map();
	const cards = new Map();
	/** Line ID => explanation shown on the card after a unit or mode change touched its values. */
	const lineNotices = new Map();
	/** Removed line ID => inline "Undo" placeholder element. */
	const removedViews = new Map();
	let calc = { pending: false, error: '', calculatedAt: '', calculatedLocal: 0, totals: null, seq: 0 };
	let cartState = { phase: 'idle' };
	let meta = { kind: 'local' };
	let savedRevision = 0;
	let shared = null;
	let stale = false;
	let autosaveResult = { ok: true, code: null };
	let bootError = '';
	let renderQueued = false;
	let retryTimer = null;
	let bannerSignature = '';
	let plannedSignature = '';
	let staleAnnounced = false;
	/** Today in the site time zone (GET /session reports the authoritative value). */
	let siteToday = todayIn( config.timezone );
	/** The start date was filled in automatically for a new protocol and not changed since. */
	let autoStart = false;
	// Start weeks of the lines while the protocol start date is cleared (line ID => week).
	let clearedWeeks = new Map();
	/**
	 * Store protocols the workspace started from (CHANGE-1.7.0 §6.7): null, or { protocols: [ { id,
	 * name, updatedAt } ] (1–5, unique IDs, newest last), lines: Set of the line IDs that still carry
	 * the store's values (tag "From a pre-built protocol"), picks: Set of the line IDs whose option
	 * the customer picks }. Kept in the autosaved workspace meta only (never in the protocol).
	 */
	let storeOrigin = null;
	/** Lines whose "+1 spare" box the customer checked: the spare follows their calculated quantity. */
	const spareLines = new Set();

	/*
	 * Entry choice and views (CHANGE-1.7.1 §2.5). `hint`: the page config says the visitor sees a
	 * pre-built protocol (cache-safe: the guest answer, or the signed-in answer with WordPress's body
	 * class "logged-in"); it decides the first paint, the list response decides in the end.
	 */
	const hint = config.store_protocols_any === true || ( config.store_protocols_members === true && !! document.body && document.body.classList.contains( 'logged-in' ) );
	/** Requested view ('prebuilt' | 'own'); shown while the choice is (effectiveView()). */
	let view = 'own';
	/** The visitor can see a pre-built protocol (the hint until the first list answers). */
	let available = hint;
	/** Sequence of the pre-built links and button presses: a press stops a pending link. */
	let linkSeq = 0;
	/**
	 * Sequence of the pending product, group or section link whose own toast (none()) will explain an
	 * empty list: refreshAvailability() then announces nothing, so S52 is heard once (0: none).
	 */
	let noneLink = 0;
	/**
	 * The page was opened with a #share= link that is not handled yet (it waits for GET /session):
	 * the choice stays hidden, so it never appears and disappears before the shared protocol opens.
	 */
	let sharePending = false;
	/** Last element focused inside the root (a browser may drop focus from a hidden element first). */
	let lastFocus = null;
	/** Effective view and choice visibility of the last applyView() (null before the first). */
	let shownView = null;
	let choiceShown = false;

	const showPrices = () => config.price_display_policy !== 'hidden' && features.prices !== false;

	modalHost( scope );

	/* ================================================================ Layout. */

	render( root );
	root.removeAttribute( 'aria-busy' );
	root.classList.add( 'is-ready' );
	const announcer = createAnnouncer( root );

	const exportsMenu = createExportMenu( {
		api,
		getPlan: () => titledPlan(),
		getMeta: () => meta,
		getShareToken: () => ( shared ? shared.token : '' ),
		// The printed protocol names the pre-built protocols it started from (never for a shared protocol).
		getStoreProtocols: () => ( shared || ! storeOrigin ? [] : storeOrigin.protocols.map( ( entry ) => entry.id ) ),
		toast: ( message, tone ) => toaster.show( message, { tone } ),
	} );
	const toolbar = createToolbar( {
		onTitle: ( title ) => ! shared && store.dispatch( { type: 'workspace/title', title } ),
		onStart: ( startDate ) => setStartDate( startDate ),
		onPlans: () => openPlans(),
		onReset: () => resetWorkspace(),
	} );
	const plannedCount = ( id ) => store.getState().lines.filter( ( line ) => line.product_id === id ).length;
	// "Pre-built protocols" view (CHANGE-1.7.0 §6.3–§6.5, CHANGE-1.7.1 §2.9): "Use this protocol"
	// calls useStoreProtocol(); expected from the first paint while the hint says so; a section the
	// visitor cannot see never takes focus or speaks, and its dialogs never return focus into it.
	const storeProtocols = createStoreProtocols( {
		api,
		currency,
		showPrices: showPrices(),
		showImages,
		notice: typeof config.store_protocol_notice === 'string' ? config.store_protocol_notice : '',
		whatsapp: () => ( features.whatsapp && typeof config.whatsapp_number === 'string' && config.whatsapp_number !== '' ? { number: config.whatsapp_number, template: config.whatsapp_template } : null ),
		onUse: ( detail, ctx ) => useStoreProtocol( detail, ctx, 'use' ),
		announce: ( message ) => announcer.announce( message ),
		toast: ( message, options ) => toaster.show( message, options ),
		expected: hint,
		isShown: () => effectiveView() === 'prebuilt',
		focusFallback: () => ( entryShown() ? entry.el.querySelector( '[aria-pressed="true"]' ) : ownView.querySelector( '[role="tab"][aria-selected="true"]' ) ),
	} );
	const picker = createPicker( {
		api,
		currency,
		showPrices: showPrices(),
		showImages,
		allowedFormats: Array.isArray( config.allowed_formats ) ? config.allowed_formats : null,
		formatOrder: Array.isArray( config.format_order ) ? config.format_order : null,
		formatLabels: config.format_labels && typeof config.format_labels === 'object' ? config.format_labels : null,
		initialCategory: config.preselect ? config.preselect.category : '',
		onAdd: ( id ) => addProduct( id ),
		onRemove: ( id, name ) => removeProduct( id, name ),
		plannedCount,
		// "{n} pre-built protocols" on product cards (CHANGE-1.7.0 §6.9): the pre-built view first, its
		// heading focused before the filtered list is requested (CHANGE-1.7.1 §2.8).
		protocolCount: ( id ) => storeProtocols.productCount( id ),
		onShowProtocols: ( id, name ) => {
			setView( 'prebuilt' );
			revealPrebuilt();
			return storeProtocols.showProduct( id, name );
		},
		announce: ( message ) => announcer.announce( message ),
	} );
	// The counts arrive with the pre-built protocols, usually after the first products.
	storeProtocols.onCounts( () => picker.refreshProtocols() );
	// The list decides whether the choice and the pre-built view exist (CHANGE-1.7.1 §2.7).
	storeProtocols.onAvailability( () => refreshAvailability() );
	const combos = createCombos( {
		api,
		currency,
		showPrices: showPrices(),
		onAddAll: ( combo ) => addCombination( combo ),
		inProtocol: ( combo ) => comboInProtocol( combo, store.getState().lines ),
	} );

	// Step 1 summary bar: "{n} products · est. {price}" + "Plan quantities →" (hidden while empty).
	const stepBarText = h( 'p', { class: 'arp-stepbar__text', role: 'status' } );
	const stepBarButton = h(
		'button',
		{ type: 'button', class: 'arp-btn arp-btn--gold arp-stepbar__go', onClick: () => goToStep2( 'heading' ) },
		h( 'span', { class: 'arp-btn__label' }, __( 'Plan quantities' ) ),
		h( 'span', { 'aria-hidden': 'true' }, ' →' )
	);
	const stepBar = h( 'div', { class: 'arp-stepbar', hidden: true }, stepBarText, stepBarButton );

	const banners = h( 'div', { class: 'arp-banners' } );
	const workspaceTitleId = uid( 'ws-title' );
	const workspaceCount = h( 'p', { class: 'arp-workspace__count' } );
	const maxNotice = h( 'p', { class: 'arp-notice arp-notice--info', hidden: true } );
	const lineList = h( 'div', { class: 'arp-lines' } );
	const workspaceEmpty = h(
		'div',
		{ class: 'arp-empty arp-workspace__empty' },
		icon( 'box', 'arp-empty__icon' ),
		h( 'p', { class: 'arp-empty__title' }, __( 'Your protocol is empty' ) ),
		/* translators: %d: maximum number of items. */
		h( 'p', null, sprintf( __( 'Choose products in step 1 and select "Add to protocol". A protocol can contain up to %d products.' ), maxLines ) ),
		button( {
			label: __( 'Choose products' ),
			iconName: 'search',
			onClick: () => {
				steps.select( 0, { push: true } );
				picker.focus();
			},
		} )
	);
	const workspace = h(
		'section',
		{ class: 'arp-workspace', 'aria-labelledby': workspaceTitleId },
		h(
			'div',
			{ class: 'arp-section-head arp-section-head--bare' },
			h( 'h2', { class: 'arp-section-head__title', id: workspaceTitleId, tabindex: '-1' }, __( 'Plan & quantities' ) ),
			workspaceCount
		),
		h( 'div', { class: 'arp-card arp-start-card' }, toolbar.startEl ),
		maxNotice,
		workspaceEmpty,
		lineList
	);
	const timeline = showTimeline ? createTimeline() : null;
	const cartFlow = createCartFlow( {
		api,
		getItems: cartItems,
		flush: flushCalculation,
		returnFocus: () => summary.returnTarget(),
		setState: ( next ) => {
			cartState = next;
			scheduleRender();
			if ( next.phase === 'done' || next.phase === 'error' ) {
				setTimeout( () => summary.focusResult(), 0 );
			}
		},
		setLineErrors: ( map ) => {
			cartErrors.clear();
			map.forEach( ( messages, id ) => cartErrors.set( id, messages ) );
			scheduleRender();
		},
		announce: ( message, important ) => announcer.announce( message, important ),
	} );
	const summary = createSummary(
		{
			onAddAll: () => cartFlow.start(),
			onRetryCart: () => cartFlow.retry(),
			onSkipErrors: () => cartFlow.skipErrors(),
			onRefresh: () => refreshPrices(),
			onFocusLine: ( id ) => focusCard( id ),
			onSave: () => openPlans(),
			onCalendar: () => exportsMenu.run( 'ics' ),
			onShare: () => openShare(),
			onReview: () => {
				steps.select( 1, { push: true } );
				setView( 'own' );
				renderNow();
				scrollIntoViewSafe( summary.el );
				summary.focusHeading();
			},
		},
		exportsMenu.el
	);

	// Step 1 as in 1.6.0: the pre-built protocols have their own view (CHANGE-1.7.1 §2.3).
	const step1 = h( 'div', { class: 'arp-step arp-step--products' }, combos.el, h( 'div', { class: 'arp-card arp-products-card' }, picker.el ), stepBar );
	const step2 = h( 'div', { class: 'arp-step arp-step--plan' }, workspace, timeline ? timeline.el : null, summary.el );
	const steps = createSteps( {
		panels: [ step1, step2 ],
		onChange: () => {
			// Charts measure their width: draw them once their step is visible.
			if ( timeline ) {
				scheduleRender();
			}
			viewportGuard.update();
		},
	} );

	// The two views of the entry choice (CHANGE-1.7.1 §2.3, §2.4); applyView() shows one of them.
	const prebuiltViewId = uid( 'view-prebuilt' );
	const ownViewId = uid( 'view-own' );
	const prebuiltView = h( 'div', { class: 'arp-entry-view arp-entry-view--prebuilt', id: prebuiltViewId, hidden: true }, storeProtocols.el );
	const ownView = h( 'div', { class: 'arp-entry-view arp-entry-view--own', id: ownViewId }, steps.el );
	const entry = createEntryChoice( { ids: { prebuilt: prebuiltViewId, own: ownViewId }, onSelect: ( next ) => chooseView( next ) } );

	root.appendChild( h( 'div', { class: 'arp-layout' }, h( 'div', { class: 'arp-main' }, banners, toolbar.el, entry.el, prebuiltView, ownView ) ) );
	root.appendChild( summary.bar );
	// The focus rule of applyView() needs the last focused element: a browser may already have moved
	// focus to <body> when an element was hidden in the same task.
	root.addEventListener( 'focusin', ( event ) => {
		lastFocus = event.target;
	} );
	root.addEventListener( 'focusout', ( event ) => {
		const next = event.relatedTarget;
		if ( next && next.nodeType === 1 && ! root.contains( next ) ) {
			lastFocus = null;
		}
	} );
	const toaster = createToaster( root, {
		onChange: () => {
			// Toasts change the free area: refresh the scroll padding, then re-check the focus.
			viewportGuard.update();
			viewportGuard.check();
		},
	} );
	const viewportGuard = createViewportGuard();

	/**
	 * Shows step 2 and moves focus to its heading, or to a product block.
	 *
	 * @param {string} target 'heading' or a line ID.
	 */
	function goToStep2( target ) {
		steps.select( 1, { push: true } );
		setView( 'own' );
		renderNow();
		if ( target === 'heading' ) {
			const heading = document.getElementById( workspaceTitleId );
			scrollIntoViewSafe( heading );
			focusElement( heading );
			return;
		}
		focusCard( target );
	}

	/* ================================================================ Entry choice and views. */

	/**
	 * Whether the entry choice is shown: the visitor can see a pre-built protocol and no shared
	 * protocol is open or about to open (CHANGE-1.7.1 §2.4).
	 *
	 * @return {boolean} Shown.
	 */
	function entryShown() {
		return available && ! shared && ! sharePending;
	}

	/**
	 * The view shown: the requested one while the choice is shown, else "Make your own protocol"
	 * (the 1.6.0 layout).
	 *
	 * @return {'prebuilt'|'own'} View.
	 */
	function effectiveView() {
		return entryShown() ? view : 'own';
	}

	/**
	 * Whether focus is inside a part of the builder: the focused element, or — when the browser
	 * already reports <body> because it dropped focus from an element hidden in the same task — the
	 * last element focused inside the root, while that element is no longer rendered (no boxes). A
	 * visible element the visitor left by clicking elsewhere (focus on <body>) does not count.
	 *
	 * @param {HTMLElement} part Part.
	 * @return {boolean} Inside.
	 */
	function focusInside( part ) {
		const active = document.activeElement;
		if ( active && active !== document.body && active !== document.documentElement ) {
			return part.contains( active );
		}
		return !! lastFocus && part.contains( lastFocus ) && ( typeof lastFocus.getClientRects !== 'function' || lastFocus.getClientRects().length === 0 );
	}

	/**
	 * Shows the effective view (synchronous, idempotent; CHANGE-1.7.1 §2.5): the choice with the
	 * pressed button, one of the two views, the step fragment and the view recorded in the history
	 * entry. When a part is hidden that held focus, focus moves without scrolling to the section
	 * heading (pre-built view) or the selected step tab; nothing moves on a page load, where nothing
	 * is focused yet. Callers that focus something in the new view do so right afterwards.
	 *
	 * @return {boolean} The effective view changed.
	 */
	function applyView() {
		const shown = entryShown();
		const next = effectiveView();
		const changed = next !== shownView;
		// Parts hidden by this call: the view shown before, and the choice when it goes away.
		const hiding = [];
		if ( changed && shownView === 'prebuilt' ) {
			hiding.push( prebuiltView );
		}
		if ( changed && shownView === 'own' ) {
			hiding.push( ownView );
		}
		if ( choiceShown && ! shown ) {
			hiding.push( entry.el );
		}
		const hadFocus = hiding.some( ( part ) => focusInside( part ) );
		if ( ! hadFocus && lastFocus && hiding.some( ( part ) => part.contains( lastFocus ) ) ) {
			// The visitor had left that element (focus on <body>): once hidden it must not count later.
			lastFocus = null;
		}
		entry.update( { shown, view: next } );
		prebuiltView.hidden = next !== 'prebuilt';
		ownView.hidden = next !== 'own';
		shownView = next;
		choiceShown = shown;
		if ( changed || shown ) {
			syncStepHash();
		}
		if ( hadFocus ) {
			const target = next === 'prebuilt' ? storeProtocols.el.querySelector( '.arp-sprotos__title' ) : ownView.querySelector( '[role="tab"][aria-selected="true"]' );
			// Moved without scrolling: the viewport guard never brings it back from outside the
			// viewport (Back and Forward keep the position the browser restored).
			viewportGuard.quiet( target );
			focusElement( target, { preventScroll: true } );
		}
		if ( ! changed ) {
			return false;
		}
		viewportGuard.update();
		// Charts measure their width: draw them once the steps are visible (as the steps' onChange).
		if ( next === 'own' && timeline ) {
			scheduleRender();
		}
		return true;
	}

	/**
	 * Keeps the step fragment and the view recorded in the current history entry true to what is
	 * shown (CHANGE-1.7.1 §2.10): only on a step fragment ('', '#', '#plan'; deep links are replaced
	 * by their handlers) and only on a difference, with one history.replaceState() — '#plan' when
	 * step 2 of the own view is shown, else no fragment; `arp_view` only while the choice is shown
	 * (without it nothing is recorded, as in 1.6.0). Switching views never adds a history entry.
	 */
	function syncStepHash() {
		const hash = window.location.hash;
		if ( ! isStepHash( hash ) ) {
			return;
		}
		const shown = entryShown();
		const current = effectiveView();
		const plan = current === 'own' && steps.current() === 1;
		const state = window.history.state;
		const base = state && typeof state === 'object' && Object.getPrototypeOf( state ) === Object.prototype ? state : {};
		const fragmentDiffers = ( hash === PLAN_HASH ) !== plan;
		const viewDiffers = shown && base.arp_view !== current;
		if ( ! fragmentDiffers && ! viewDiffers ) {
			return;
		}
		try {
			window.history.replaceState( shown ? { ...base, arp_view: current } : state, '', window.location.pathname + window.location.search + ( plan ? PLAN_HASH : '' ) );
		} catch ( e ) {
			// History is unavailable (sandboxed frame) or throttled: the view still changes.
		}
	}

	/**
	 * Requests a view (no history entry, never stored or announced; focus moves only through the
	 * focus rule of applyView()).
	 *
	 * @param {string} next 'prebuilt' | 'own' (anything else is ignored).
	 * @return {boolean} The effective view changed.
	 */
	function setView( next ) {
		if ( normalizeEntryView( next ) === null ) {
			return false;
		}
		view = next;
		return applyView();
	}

	/**
	 * A press of "Pre-built protocols" / "Make your own protocol": stops a pending pre-built link,
	 * remembers the choice on this device (a failing storage is ignored), switches the view, drops a
	 * pending protocol window when the view changed and announces the view on every press (also of
	 * the pressed button). Focus stays on the button; nothing scrolls.
	 *
	 * @param {string} next 'prebuilt' | 'own'.
	 */
	function chooseView( next ) {
		++linkSeq;
		drafts.setPref( ENTRY_VIEW_PREF, next );
		if ( setView( next ) ) {
			storeProtocols.cancelOpen();
		}
		announcer.announce( next === 'prebuilt' ? __( 'The pre-built protocols are shown below.' ) : __( 'The steps to make your own protocol are shown below.' ) );
	}

	/**
	 * Focuses the heading of the pre-built protocols and brings it to the top (instantly; the
	 * scroll-padding of the viewport guard keeps it clear of sticky headers). Only while the
	 * pre-built view is shown.
	 */
	function revealPrebuilt() {
		const title = storeProtocols.el.querySelector( '.arp-sprotos__title' );
		if ( ! title || effectiveView() !== 'prebuilt' ) {
			return;
		}
		focusElement( title, { preventScroll: true } );
		if ( typeof title.scrollIntoView === 'function' ) {
			title.scrollIntoView( { block: 'start' } );
		}
	}

	/**
	 * The list decides whether the visitor can see a pre-built protocol (CHANGE-1.7.1 §2.7; called
	 * by onAvailability). Turning false removes the choice and the pre-built view (S52 is announced
	 * when the visitor saw that view or had focus in it, unless the pending link's own toast says
	 * it, so it is heard once); turning true shows the choice with the requested view, which is
	 * "Make your own protocol" unless a pre-built link waits for the list.
	 */
	function refreshAvailability() {
		const known = storeProtocols.available();
		const next = known === null ? hint : known;
		if ( next === available ) {
			return;
		}
		const sawPrebuilt = shownView === 'prebuilt' || focusInside( entry.el ) || focusInside( prebuiltView );
		available = next;
		if ( ! next ) {
			view = 'own';
			applyView();
			if ( sawPrebuilt && ! ( noneLink !== 0 && noneLink === linkSeq ) ) {
				announcer.announce( __( 'There are no pre-built protocols at the moment.' ) );
			}
			return;
		}
		applyView();
	}

	/* ================================================================ Focus not obscured. */

	/**
	 * Keeps the focused control clear of everything fixed to the viewport edges (WCAG 2.4.11):
	 * the phone basket bar, toasts, theme bottom toolbars (Storefront handheld bar, WoodMart
	 * toolbar…) and sticky theme headers.
	 *
	 * - Theme bottom toolbars are measured and the summary bar is lifted above them through
	 *   `--arp-bottom-offset` on the planner wrapper (a theme can also set it in its CSS).
	 * - `scroll-padding` on <html> makes the browser's own scrolling (Tab, anchors) leave room for
	 *   the bars and the visible toast stack.
	 * - On focus (and when a toast appears), a control that is still covered is scrolled clear;
	 *   the check runs again once the browser's own reveal scroll has settled (WebKit scrolls
	 *   after focusin, or not at all), and a control left entirely outside the viewport is
	 *   brought into view — except the element a view switch focused without scrolling
	 *   (`quiet( el )`, until focus moves elsewhere).
	 *
	 * @return {{update: Function, check: Function, quiet: Function}} Guard.
	 */
	function createViewportGuard() {
		const html = document.documentElement;
		const original = { top: html.style.scrollPaddingTop, bottom: html.style.scrollPaddingBottom };
		const isSheet = () => !! ( window.matchMedia && ! window.matchMedia( '(min-width: 1024px)' ).matches );
		const box = ( rect, edge ) => ( { top: rect.top, bottom: rect.bottom, left: rect.left, right: rect.right, edge } );

		/**
		 * Nearest fixed or sticky ancestor-or-self that is not part of the planner.
		 *
		 * @param {Element} el Element.
		 * @return {Element|null} Element.
		 */
		const fixedAncestor = ( el ) => {
			for ( let node = el; node && node !== document.body && node !== html; node = node.parentElement ) {
				if ( scope.contains( node ) || ( node.classList && node.classList.contains( 'arp-modal-host' ) ) ) {
					return null;
				}
				const position = window.getComputedStyle( node ).position;
				if ( position === 'fixed' || position === 'sticky' ) {
					return node;
				}
			}
			return null;
		};

		/**
		 * Theme elements fixed along one edge of the viewport.
		 *
		 * @param {string} edge top | bottom.
		 * @return {Array<Object>} Boxes.
		 */
		const themeBars = ( edge ) => {
			if ( typeof document.elementsFromPoint !== 'function' ) {
				return [];
			}
			const y = edge === 'top' ? 1 : window.innerHeight - 2;
			const found = new Set();
			[ 8, Math.round( window.innerWidth / 2 ), window.innerWidth - 8 ].forEach( ( x ) => {
				document.elementsFromPoint( x, y ).forEach( ( el ) => {
					const bar = fixedAncestor( el );
					if ( bar ) {
						found.add( bar );
					}
				} );
			} );
			return [ ...found ]
				.map( ( el ) => el.getBoundingClientRect() )
				.filter( ( r ) => r.width > 0 && r.height > 0 && r.height < window.innerHeight * 0.4 && ( edge === 'top' ? r.top <= 2 : r.bottom >= window.innerHeight - 2 ) )
				.map( ( r ) => box( r, edge ) );
		};

		// Last measured heights of theme toolbars (bottom: lifts the summary bar; top: sticky headers).
		const measured = { bottom: 0, top: 0 };

		/**
		 * Measures theme toolbars. Skipped while a modal dialog makes the rest of the page inert:
		 * inert elements are not hit-testable, so elementsFromPoint() would not find the toolbars and
		 * the summary bar would drop behind them. The previous measurement is kept instead.
		 */
		const measure = () => {
			if ( document.body && document.body.querySelector( ':scope > [inert]' ) ) {
				return;
			}
			let bottom = 0;
			let top = 0;
			if ( isSheet() ) {
				themeBars( 'bottom' ).forEach( ( bar ) => {
					bottom = Math.max( bottom, Math.ceil( window.innerHeight - bar.top ) );
				} );
			}
			themeBars( 'top' ).forEach( ( bar ) => {
				top = Math.max( top, Math.ceil( bar.bottom ) );
			} );
			measured.bottom = bottom;
			measured.top = top;
		};

		/** Lifts the summary bar above theme toolbars and sets the scroll padding. */
		const update = () => {
			measure();
			const offset = isSheet() ? measured.bottom : 0;
			const top = measured.top;
			let bottom = 0;
			if ( isSheet() ) {
				scope.style.setProperty( '--arp-bottom-offset', offset + 'px' );
				const fixed = summary.fixedArea();
				bottom = offset + ( fixed ? Math.ceil( fixed.getBoundingClientRect().height ) : 0 );
			} else {
				scope.style.removeProperty( '--arp-bottom-offset' );
			}
			// Visible toasts sit above the summary bar: keep browser reveals clear of them too.
			toaster.el.querySelectorAll( '.arp-toast' ).forEach( ( toast ) => {
				const rect = toast.getBoundingClientRect();
				if ( rect.height > 0 && rect.top < window.innerHeight ) {
					bottom = Math.max( bottom, Math.ceil( window.innerHeight - rect.top ) );
				}
			} );
			html.style.scrollPaddingBottom = bottom > 0 ? bottom + 16 + 'px' : original.bottom;
			html.style.scrollPaddingTop = top > 0 ? top + 16 + 'px' : original.top;
		};

		// The element the focus rule of applyView() focused without scrolling (CHANGE-1.7.1 §2.5),
		// while it keeps focus: never brought back from outside the viewport (null: none).
		let quiet = null;

		/**
		 * Scrolls the focused planner control clear of fixed bars when it is covered.
		 *
		 * @param {Element|null} target Focused element (default: the active element).
		 */
		const check = ( target = null ) => {
			const el = target || document.activeElement;
			if ( ! el || el === document.body || ! scope.contains( el ) || summary.bar.contains( el ) || toaster.el.contains( el ) ) {
				return;
			}
			const rect = el.getBoundingClientRect();
			// Back / Forward: the browser restores the scroll position after the view switched, so
			// the moved focus may lie entirely outside the viewport; bars still clear it on screen.
			if ( el === quiet && ( rect.bottom <= 0 || rect.top >= window.innerHeight ) ) {
				return;
			}
			const bars = [ ...themeBars( 'top' ), ...themeBars( 'bottom' ) ];
			const fixed = summary.fixedArea();
			if ( fixed ) {
				bars.push( box( fixed.getBoundingClientRect(), 'bottom' ) );
			}
			toaster.el.querySelectorAll( '.arp-toast' ).forEach( ( toast ) => bars.push( box( toast.getBoundingClientRect(), 'bottom' ) ) );
			const delta = clearanceScroll( rect, bars, window.innerHeight );
			if ( delta !== 0 ) {
				window.scrollBy( { top: delta, left: 0, behavior: 'auto' } );
			}
		};

		scope.addEventListener( 'focusin', ( event ) => {
			const target = event.target;
			// Any other focus ends the exemption of the focus rule's element.
			if ( target !== quiet ) {
				quiet = null;
			}
			const settle = () => {
				if ( document.activeElement === target ) {
					check( target );
				}
			};
			check( target );
			// The browser's own reveal (smooth) scroll may still be running, or start only after
			// focusin (WebKit): check again once it settled.
			window.requestAnimationFrame( settle );
			window.setTimeout( settle, 100 );
			window.setTimeout( settle, 250 );
			if ( 'onscrollend' in window ) {
				window.addEventListener( 'scrollend', settle, { once: true } );
				window.setTimeout( () => window.removeEventListener( 'scrollend', settle ), 1000 );
			}
		} );
		let resizeTimer = null;
		window.addEventListener( 'resize', () => {
			clearTimeout( resizeTimer );
			resizeTimer = setTimeout( update, 150 );
		} );
		window.addEventListener( 'load', update );
		const bar = summary.bar;
		if ( typeof ResizeObserver === 'function' && bar ) {
			// The phone bar grows when its text wraps or a warning appears (not shown on wide screens).
			// update() moves the bar, so it runs in the next frame: changing an observed element's
			// layout inside the callback raises "ResizeObserver loop completed with undelivered
			// notifications" as a page error.
			let frame = 0;
			new ResizeObserver( () => {
				if ( ! frame ) {
					frame = window.requestAnimationFrame( () => {
						frame = 0;
						update();
					} );
				}
			} ).observe( bar );
		}
		return {
			update,
			check,
			quiet: ( el ) => {
				quiet = el || null;
			},
		};
	}

	/* ================================================================ Units and results. */

	/**
	 * Applies live fields from a /calculate `product` entry over the catalogue unit.
	 *
	 * @param {Object} raw SellableUnit public array.
	 */
	function mergeLive( raw ) {
		const fresh = normalizeSellable( raw );
		if ( ! fresh ) {
			return;
		}
		const has = ( key ) => raw && Object.prototype.hasOwnProperty.call( raw, key );
		const patch = {};
		if ( has( 'price' ) ) {
			patch.price = fresh.price;
		}
		if ( has( 'stock_status' ) ) {
			patch.stockStatus = fresh.stockStatus;
		}
		if ( has( 'stock_quantity' ) ) {
			patch.stockQuantity = fresh.stockQuantity;
		}
		if ( has( 'backorders_allowed' ) ) {
			patch.backordersAllowed = fresh.backordersAllowed;
		}
		if ( has( 'is_purchasable' ) ) {
			patch.purchasable = fresh.purchasable;
		}
		if ( has( 'readiness' ) ) {
			patch.readiness = fresh.readiness;
			patch.readinessMessage = fresh.readinessMessage;
		}
		if ( has( 'fetched_at' ) ) {
			patch.fetchedAt = fresh.fetchedAt;
		}
		liveUnits.set( fresh.key, patch );
	}

	/**
	 * The unit a line refers to (catalogue data with the latest live fields), or null.
	 *
	 * @param {Object} line Line.
	 * @return {Object|null} Unit.
	 */
	function unitOfLine( line ) {
		const entry = products.get( line.product_id );
		const product = entry && entry.product;
		if ( ! product ) {
			return null;
		}
		let unit = null;
		if ( product.type !== 'variable' ) {
			unit = unitById( product, 0 );
		} else if ( line.variation_id > 0 ) {
			unit = unitById( product, line.variation_id );
		}
		if ( ! unit ) {
			return null;
		}
		const live = liveUnits.get( unit.key );
		return live ? { ...unit, ...live } : unit;
	}

	const coverageMap = ( state ) => bundleCoverage( state.lines, unitOfLine, { planStart: state.start_date, priceDecimals: currency.decimals, showPrices: showPrices(), limits } );
	const signature = ( line, start, covered ) => JSON.stringify( [ toLineInput( line ), start, covered ] );

	/**
	 * Everything besides the line inputs that a preview depends on.
	 *
	 * @param {Object|null} unit Unit.
	 * @return {string} Signature.
	 */
	function previewSignature( unit ) {
		return JSON.stringify( [
			unit ? [ unit.key, unit.readiness, unit.price, unit.capacities, unit.packCount, unit.modes, unit.compatibleUnits ] : null,
			currency.decimals,
			showPrices(),
			limits,
		] );
	}

	/** Recomputes local previews for every line whose server result is out of date. */
	function refreshPreviews() {
		const state = store.getState();
		const coverage = coverageMap( state );
		const ids = new Set();
		state.lines.forEach( ( line ) => {
			ids.add( line.id );
			const covered = coverage.get( line.id ) || 0;
			const sig = signature( line, state.start_date, covered );
			const current = results.get( line.id );
			const unit = unitOfLine( line );
			const previewKey = previewSignature( unit );
			// Up to date (server result, or a preview of the same inputs and unit data): skip.
			if ( current && current.sig === sig && ( current.source === 'server' || current.previewKey === previewKey ) ) {
				return;
			}
			const preview = previewLine( line, unit, { planStart: state.start_date, priceDecimals: currency.decimals, covered, showPrices: showPrices(), limits } );
			results.set( line.id, { ...preview, source: 'preview', sig, previewKey } );
		} );
		for ( const id of results.keys() ) {
			if ( ! ids.has( id ) ) {
				results.delete( id );
			}
		}
	}

	/**
	 * Result state from a /calculate line entry.
	 *
	 * @param {Object} entry Entry { id, ok, errors, product, result, timeline }.
	 * @param {Object} line  Line.
	 * @param {string} sig   Signature.
	 * @param {string} start Plan start.
	 * @return {Object} Result state.
	 */
	function serverState( entry, line, sig, start ) {
		const base = { source: 'server', sig, result: null, timeline: null, errors: [], code: '', message: '' };
		if ( entry.ok && entry.result && typeof entry.result === 'object' ) {
			let tl = entry.timeline && typeof entry.timeline === 'object' ? entry.timeline : null;
			if ( ! tl && entry.result.mode === 'schedule' ) {
				try {
					tl = buildTimeline( toLineInput( line ), entry.result, start );
				} catch ( e ) {
					tl = null;
				}
			}
			return { ...base, status: 'ok', result: entry.result, timeline: tl };
		}
		const errors = Array.isArray( entry.errors ) ? entry.errors.filter( ( e ) => e && typeof e === 'object' ) : [];
		const first = errors[ 0 ] || { code: 'invalid', message: '' };
		if ( READINESS_CODES.includes( first.code ) ) {
			return { ...base, status: 'blocked', code: first.code, message: first.message || '', errors };
		}
		if ( CODES.calculation.includes( first.code ) ) {
			return { ...base, status: 'error', code: first.code, message: first.message || '', errors };
		}
		return { ...base, status: 'invalid', errors };
	}

	const calcDebounced = debounce( () => runCalculate(), 400 );

	/**
	 * Sends the whole plan to POST /calculate (authoritative).
	 *
	 * @return {Promise<boolean>} Whether the store calculated the current plan (false on failure).
	 */
	async function runCalculate() {
		clearTimeout( retryTimer );
		const state = store.getState();
		const coverage = coverageMap( state );
		const lines = state.lines.filter( ( line ) => {
			const unit = unitOfLine( line );
			return unit && isPlannable( unit ) && isComplete( line ) && validateLine( toLineInput( line ), limits ).ok;
		} );
		const seq = ++calc.seq;
		if ( lines.length === 0 ) {
			calc = { ...calc, pending: false, error: '', totals: null };
			scheduleRender();
			return true;
		}
		const sigs = new Map( lines.map( ( line ) => [ line.id, signature( line, state.start_date, coverage.get( line.id ) || 0 ) ] ) );
		calc = { ...calc, pending: true };
		scheduleRender();
		try {
			const body = { lines: lines.map( toLineInput ) };
			if ( state.start_date ) {
				body.start_date = state.start_date;
			}
			const data = await api.calculate( body );
			if ( seq !== calc.seq ) {
				return calc.error === '';
			}
			const now = store.getState();
			const nowCoverage = coverageMap( now );
			( data && Array.isArray( data.lines ) ? data.lines : [] ).forEach( ( entry ) => {
				if ( entry && entry.product ) {
					mergeLive( entry.product );
				}
			} );
			( data && Array.isArray( data.lines ) ? data.lines : [] ).forEach( ( entry ) => {
				const line = entry && now.lines.find( ( l ) => l.id === entry.id );
				if ( ! line ) {
					return;
				}
				const sig = signature( line, now.start_date, nowCoverage.get( line.id ) || 0 );
				if ( sig !== sigs.get( line.id ) ) {
					return;
				}
				results.set( line.id, serverState( entry, line, sig, now.start_date ) );
			} );
			calc = {
				...calc,
				pending: false,
				error: '',
				calculatedAt: data && typeof data.calculated_at === 'string' ? data.calculated_at : new Date().toISOString(),
				calculatedLocal: Date.now(),
				totals: data && data.totals ? data.totals : null,
			};
			stale = false;
			refreshPreviews();
		} catch ( e ) {
			if ( seq !== calc.seq ) {
				return false;
			}
			const hadError = calc.error !== '';
			calc = { ...calc, pending: false, error: __( 'The store could not confirm the calculation right now. The results shown are an instant preview from your browser.' ) };
			if ( ! hadError ) {
				// The notice is drawn in the summary (a closed bottom sheet on phones): announce it too.
				announcer.announce( calc.error );
			}
			if ( e.status === 429 && e.retryAfter > 0 ) {
				retryTimer = setTimeout( () => runCalculate(), Math.min( 60, e.retryAfter ) * 1000 );
			}
		}
		scheduleRender();
		return calc.error === '';
	}

	/**
	 * Waits for an authoritative calculation of the current plan.
	 *
	 * @return {Promise<boolean>} Whether the store confirmed it.
	 */
	async function flushCalculation() {
		calcDebounced.cancel();
		return runCalculate();
	}

	/** Re-reads product data and prices, then recalculates. */
	async function refreshPrices() {
		const ids = [ ...new Set( store.getState().lines.map( ( line ) => line.product_id ) ) ];
		liveUnits.clear();
		await Promise.all( ids.map( ( id ) => loadProduct( id, true ) ) );
		await flushCalculation();
		announcer.announce( __( 'Prices and stock were refreshed.' ) );
	}

	/* ================================================================ Products. */

	/**
	 * Loads GET /product/{id} once (or again with force).
	 *
	 * @param {number}  id    Product ID.
	 * @param {boolean} force Reload.
	 * @return {Promise<Object|null>} Product.
	 */
	function loadProduct( id, force = false ) {
		const existing = products.get( id );
		if ( existing && ! force && ( existing.status === 'ready' || existing.status === 'loading' ) ) {
			return existing.promise;
		}
		const entry = { status: 'loading', product: existing ? existing.product : null, promise: null };
		products.set( id, entry );
		entry.promise = api
			.product( id )
			.then( ( data ) => {
				const product = normalizeProduct( data );
				if ( ! product ) {
					throw new Error( 'invalid product' );
				}
				entry.status = 'ready';
				entry.product = product;
				onProductLoaded( id );
				return product;
			} )
			.catch( ( e ) => {
				entry.status = e && ( e.status === 404 || e.code === 'arp_not_found' || e.code === 'product_not_found' || e.code === 'rest_no_route' ) ? 'missing' : 'error';
				onProductLoaded( id );
				return null;
			} );
		scheduleRender();
		return entry.promise;
	}

	/**
	 * After a product loads: resolve units of its lines, refresh previews and recalculate.
	 *
	 * Stored lines are adapted with adaptLine(): a unit the product no longer offers is converted
	 * exactly or the amount is cleared, with a notice on the card — never relabelled. A shared plan
	 * is read-only: its lines are shown exactly as shared (the preview reports what no longer fits).
	 *
	 * A line from a store protocol loses its tag only when the adaptation changed one of its values
	 * (a notice, or another variation, mode, unit or amount): an unchanged line keeps it, so tags
	 * survive every reload (CHANGE-1.7.0 §6.7).
	 *
	 * @param {number} id Product ID.
	 */
	function onProductLoaded( id ) {
		const entry = products.get( id );
		if ( entry && entry.product && ! shared ) {
			store.getState().lines.forEach( ( line ) => {
				if ( line.product_id !== id ) {
					return;
				}
				const product = entry.product;
				let unit = null;
				if ( product.type !== 'variable' ) {
					unit = unitById( product, 0 );
				} else if ( line.variation_id > 0 ) {
					unit = unitById( product, line.variation_id );
				} else {
					unit = resolveUnit( product, line.variation_attributes );
				}
				if ( unit && isPlannable( unit ) ) {
					const adapted = adaptLine( line, unit );
					// A line without values of the visitor is set up like a new one (weekly or quantity).
					const next = hasUserValues( line ) ? adapted.line : prepareNewLine( adapted.line, unit );
					store.dispatch( { type: 'line/update', id: line.id, changes: { variation_id: next.variation_id, mode: next.mode, unit: next.unit, amount: next.amount, period_unit: next.period_unit, manual_quantity: next.manual_quantity } } );
					showLineNotice( line.id, adapted.notice );
					if ( adapted.notice !== null || next.variation_id !== line.variation_id || next.mode !== line.mode || next.unit !== line.unit || next.amount !== line.amount ) {
						untag( line.id );
					}
				}
			} );
		}
		refreshPreviews();
		calcDebounced();
		scheduleRender();
	}

	/**
	 * Text explaining what a unit or mode change did to the values of a line.
	 *
	 * @param {Object} notice Notice from adaptLine() / changeUnit().
	 * @return {string} Text.
	 */
	function lineNoticeText( notice ) {
		const amount = ( value, unit ) => amountText( { value, unit }, currency );
		if ( notice.type === 'converted' ) {
			/* translators: 1: amount before the change (e.g. 250 mg), 2: the same amount in the new unit (e.g. 250,000 mcg). */
			return sprintf( __( 'The amount was converted from %1$s to %2$s.' ), amount( notice.amount, notice.from ), amount( notice.converted, notice.to ) );
		}
		if ( notice.type === 'cleared' ) {
			return notice.reason === 'inexact'
				? sprintf(
					/* translators: 1: amount entered (e.g. 0.5 mcg), 2: new unit (e.g. g). */
					__( '%1$s cannot be written in %2$s with at most 4 decimal places, so the amount was cleared. Enter the amount in %2$s.' ),
					amount( notice.amount, notice.from ),
					unitName( notice.to )
				)
				: sprintf(
					/* translators: 1: amount entered (e.g. 4 mg), 2: new unit (e.g. IU). */
					__( '%1$s cannot be converted to %2$s: different kinds of units are never converted into each other, so the amount was cleared. Enter the amount in %2$s.' ),
					amount( notice.amount, notice.from ),
					unitName( notice.to )
				);
		}
		/* translators: 1: previous calculation mode, 2: calculation mode now used. */
		return sprintf( __( '"%1$s" is not available for this product, so this line now uses "%2$s". Check its values.' ), modeLabel( notice.from ), modeLabel( notice.to ) );
	}

	/**
	 * Shows (and announces) the explanation of a unit / mode change on a line card.
	 *
	 * @param {string}      id     Line ID.
	 * @param {Object|null} notice Notice (null: nothing changed).
	 */
	function showLineNotice( id, notice ) {
		if ( ! notice ) {
			return;
		}
		const text = lineNoticeText( notice );
		lineNotices.set( id, text );
		announcer.announce( text );
		scheduleRender();
	}

	/** Loads every product referenced by the workspace. */
	function ensureProducts() {
		store.getState().lines.forEach( ( line ) => {
			if ( ! products.has( line.product_id ) ) {
				loadProduct( line.product_id );
			}
		} );
	}

	/**
	 * Message when the protocol is full.
	 *
	 * @return {string} Message.
	 */
	const fullMessage = () =>
		/* translators: %d: maximum number of items. */
		sprintf( __( 'A protocol can contain up to %d items. Remove an item to add another.' ), maxLines );

	/**
	 * A new line for a loaded product (amounts empty; weekly or quantity-only set-up).
	 *
	 * @param {Object} product   Product.
	 * @param {Object} selection Attribute choices.
	 * @param {Object} unit      Resolved unit (or null).
	 * @return {Object} Line.
	 */
	function newLine( product, selection, unit ) {
		const plannable = isPlannable( unit ) ? unit : null;
		return prepareNewLine( createLine( { productId: product.id, unit: plannable, selection, defaults } ), plannable );
	}

	/**
	 * Adds a product as a new line.
	 *
	 * @param {number} productId Product ID.
	 * @param {Object} options   { focus }.
	 * @return {Promise<boolean>} Added.
	 */
	async function addProduct( productId, options = {} ) {
		if ( shared ) {
			toaster.show( __( 'Close the shared protocol to edit your own workspace.' ), { tone: 'info' } );
			return false;
		}
		if ( store.getState().lines.length >= maxLines ) {
			toaster.show( fullMessage(), { tone: 'error' } );
			announcer.announce( fullMessage(), true );
			return false;
		}
		const product = await loadProduct( productId );
		if ( ! product ) {
			toaster.show( __( 'This product could not be loaded. Please try again.' ), { tone: 'error' } );
			return false;
		}
		if ( ! product.units.some( isPlannable ) ) {
			/* translators: %s: product name. */
			toaster.show( sprintf( __( '%s cannot be planned yet because the store has not verified its data.' ), product.name ), { tone: 'error' } );
			return false;
		}
		if ( store.getState().lines.length >= maxLines ) {
			return false;
		}
		const selection = initialSelection( product );
		const line = newLine( product, selection, resolveUnit( product, selection ) );
		store.dispatch( { type: 'line/add', line, max: maxLines } );
		/* translators: %s: product name. */
		const message = sprintf( __( '%s was added to your protocol.' ), product.name );
		toaster.show( message, { tone: 'success', action: { label: __( 'Go to item' ), onClick: () => goToStep2( line.id ) } } );
		if ( options.focus ) {
			setTimeout( () => goToStep2( line.id ), 0 );
		}
		return true;
	}

	/**
	 * Removes every line of a product ("Remove" on its card in step 1). Each line leaves its Undo
	 * placeholder in step 2; focus stays on the card's button.
	 *
	 * @param {number} productId Product ID.
	 * @param {string} name      Product name.
	 */
	function removeProduct( productId, name ) {
		if ( shared ) {
			return;
		}
		const ids = store.getState().lines.filter( ( line ) => line.product_id === productId ).map( ( line ) => line.id );
		ids.forEach( ( id ) => {
			store.dispatch( { type: 'line/remove', id } );
			cartErrors.delete( id );
			lineNotices.delete( id );
			spareLines.delete( id );
		} );
		if ( ids.length > 0 ) {
			/* translators: %s: product name. */
			const message = sprintf( __( '%s was removed from your protocol.' ), name );
			toaster.show( message, { tone: 'info', action: { label: __( 'Undo' ), onClick: () => ids.forEach( ( id ) => store.dispatch( { type: 'line/restore', id, max: maxLines } ) ) } } );
			announcer.announce( message );
		}
	}

	/**
	 * "+ Add all" of a popular combination: one line per product that is not in the protocol yet,
	 * with the configured variation (or the first plannable variation in stock, else the first on
	 * backorder). Amounts stay empty.
	 *
	 * @param {Object} combo Combination.
	 * @return {Promise<void>} Settles when the products were added.
	 */
	async function addCombination( combo ) {
		if ( shared ) {
			toaster.show( __( 'Close the shared protocol to edit your own workspace.' ), { tone: 'info' } );
			return;
		}
		const additions = comboAdditions( combo, store.getState().lines );
		if ( additions.length === 0 ) {
			return;
		}
		if ( store.getState().lines.length + additions.length > maxLines ) {
			toaster.show( fullMessage(), { tone: 'error' } );
			announcer.announce( fullMessage(), true );
			return;
		}
		const loaded = await Promise.all( additions.map( ( item ) => loadProduct( item.productId ) ) );
		const added = [];
		let skipped = 0;
		additions.forEach( ( item, i ) => {
			const product = loaded[ i ];
			if ( ! product || ! product.units.some( isPlannable ) || store.getState().lines.some( ( line ) => line.product_id === item.productId ) ) {
				skipped += product ? 0 : 1;
				return;
			}
			const choice = comboSelection( product, item.variationId );
			const line = newLine( product, choice.selection, choice.unit );
			store.dispatch( { type: 'line/add', line, max: maxLines } );
			if ( findLine( line.id ) ) {
				added.push( line.id );
			}
		} );
		if ( added.length > 0 ) {
			/* translators: %d: number of products. */
			const message = sprintf( _n( '%d product was added to your protocol.', '%d products were added to your protocol.', added.length ), added.length );
			toaster.show( message, { tone: 'success', action: { label: __( 'Plan quantities' ), onClick: () => goToStep2( added[ 0 ] ) } } );
			announcer.announce( message );
		}
		if ( skipped > 0 ) {
			toaster.show( __( 'Some products could not be loaded. Please try again.' ), { tone: 'error' } );
		}
	}

	/* ================================================================ Line handlers. */

	const findLine = ( id ) => store.getState().lines.find( ( line ) => line.id === id ) || null;

	/**
	 * Focuses a product block (heading) in step 2 and scrolls it into view.
	 *
	 * @param {string} id Line ID.
	 */
	function focusCard( id ) {
		steps.select( 1, { push: true } );
		setView( 'own' );
		renderNow();
		const card = cards.get( id );
		if ( card ) {
			scrollIntoViewSafe( card.el );
			card.focus( 'heading' );
		}
	}

	/**
	 * Current result of a line (null unless calculated).
	 *
	 * @param {string} id Line ID.
	 * @return {Object|null} Result.
	 */
	const resultOf = ( id ) => {
		const current = results.get( id );
		return current && current.status === 'ok' && current.result ? current.result : null;
	};

	/**
	 * Override that keeps "+1 spare" after a change of the calculated quantity: the line is previewed
	 * with the change (engine.js mirrors the server exactly) and the spare follows the new quantity.
	 *
	 * @param {Object} line    Line before the change.
	 * @param {Object} changes Changes.
	 * @return {number|null} override_quantity.
	 */
	function followSpare( line, changes ) {
		const candidate = { ...line, ...changes, override_quantity: null };
		const state = store.getState();
		const coverage = coverageMap( { ...state, lines: state.lines.map( ( l ) => ( l.id === line.id ? candidate : l ) ) } );
		const preview = previewLine( candidate, unitOfLine( candidate ), { planStart: state.start_date, priceDecimals: currency.decimals, covered: coverage.get( line.id ) || 0, showPrices: showPrices(), limits, withTimeline: false } );
		return preview.status === 'ok' && preview.result ? spareOverride( true, preview.result, limits.max_quantity ) : null;
	}

	/**
	 * A customer edit of a line: applies the changes (applyLineUpdate()) and, when the line changed,
	 * removes its "From a pre-built protocol" tag (CHANGE-1.7.0 §6.7). Every card handler that edits
	 * values (onChange, onStep, onQuantity, onSpare) goes through here; onSelect decides itself.
	 *
	 * @param {string} id      Line ID.
	 * @param {Object} changes Changes.
	 */
	function updateLine( id, changes ) {
		if ( applyLineUpdate( id, changes ) ) {
			untag( id );
		}
	}

	/**
	 * Applies changes to a line: a line saved with an older setting is converted first (CHANGE-1.1.0
	 * §2), a unit change converts or clears the amount, and a checked "+1 spare" follows the new
	 * calculated quantity.
	 *
	 * @param {string} id      Line ID.
	 * @param {Object} changes Changes.
	 * @return {boolean} The line changed.
	 */
	function applyLineUpdate( id, changes ) {
		if ( shared ) {
			return false;
		}
		const line = findLine( id );
		if ( ! line ) {
			return false;
		}
		const unit = unitOfLine( line );
		let next = { ...changes };
		const onlyLabel = Object.keys( changes ).every( ( key ) => key === 'label' );
		if ( ! onlyLabel && isLegacyLine( line, unit ) ) {
			const current = resultOf( id );
			next = { ...modernizeLine( line, unit, { defaultWeeks: config.default_periods, quantity: current ? current.quantity : null, limits } ), ...next };
			lineNotices.delete( id );
			announcer.announce( lineKind( unit ) === 'quantity' ? __( 'This item now uses a quantity.' ) : __( 'This item now uses weekly values. Check times per week and the duration.' ) );
		}
		if ( Object.prototype.hasOwnProperty.call( changes, 'unit' ) && changes.unit !== line.unit ) {
			// Never keep the number under a new unit: convert exactly, or clear it and explain.
			const switched = changeUnit( { ...line, ...next, unit: line.unit }, changes.unit );
			next = { ...next, ...switched.changes };
			lineNotices.delete( id );
			showLineNotice( id, switched.notice );
		} else if ( Object.prototype.hasOwnProperty.call( changes, 'amount' ) && changes.amount !== null ) {
			lineNotices.delete( id );
		}
		if ( ! Object.prototype.hasOwnProperty.call( changes, 'override_quantity' ) && touchesCalculation( next ) && ( spareLines.has( id ) || spareChecked( line, resultOf( id ) ) ) ) {
			spareLines.add( id );
			next.override_quantity = followSpare( line, next );
		}
		store.dispatch( { type: 'line/update', id, changes: next } );
		return findLine( id ) !== line;
	}

	const cardHandlers = {
		onChange: ( id, changes ) => updateLine( id, changes ),
		onDismissNotice( id ) {
			lineNotices.delete( id );
			renderNow();
		},
		onSelect( id, key, slug ) {
			const line = findLine( id );
			const entry = line && products.get( line.product_id );
			if ( ! line || ! entry || ! entry.product || shared ) {
				return;
			}
			const selection = { ...line.variation_attributes, [ key ]: slug };
			const unit = resolveUnit( entry.product, selection );
			const plannable = unit && isPlannable( unit ) ? unit : null;
			const fresh = ! hasUserValues( line );
			const adapted = adaptLine( { ...line, variation_attributes: selection }, plannable, { fresh } );
			const next = fresh ? prepareNewLine( adapted.line, plannable ) : adapted.line;
			// Not updateLine(): choosing the option of a store protocol line decides its tag itself.
			const changed = applyLineUpdate( id, {
				variation_attributes: selection,
				variation_id: unit ? unit.variationId : 0,
				mode: next.mode,
				unit: next.unit,
				amount: next.amount,
				period_unit: next.period_unit,
				manual_quantity: next.manual_quantity,
			} );
			showLineNotice( id, adapted.notice );
			// A converted or cleared value ends the customer's pick ("Option of your choice"), also on a
			// line a value edit already untagged. A line whose option the customer picks keeps its tag
			// otherwise; on a line whose option the store fixed, choosing another option is an edit.
			if ( changed && storeOrigin ) {
				if ( adapted.notice !== null ) {
					storeOrigin.picks.delete( id );
				}
				if ( ! storeOrigin.picks.has( id ) ) {
					untag( id );
				}
			}
		},
		onStep( id, delta, which ) {
			const line = findLine( id );
			if ( ! line || shared ) {
				return;
			}
			if ( which === 'manual' ) {
				// Step from the quantity the field shows (for a line saved with an older setting: the
				// quantity its conversion uses).
				const current = resultOf( id );
				const base = manualStepBase( line, unitOfLine( line ), current ? current.quantity : null );
				updateLine( id, { manual_quantity: Math.max( 1, Math.min( limits.max_quantity, base + ( delta < 0 ? -1 : 1 ) ) ) } );
				return;
			}
			spareLines.delete( id );
			updateLine( id, { override_quantity: stepOverride( line, resultOf( id ), delta, limits.max_quantity ) } );
		},
		onQuantity( id, value, which ) {
			const line = findLine( id );
			if ( ! line || shared ) {
				return;
			}
			if ( which === 'manual' ) {
				if ( value !== null && value >= 1 ) {
					updateLine( id, { manual_quantity: Math.min( limits.max_quantity, value ) } );
				}
				return;
			}
			spareLines.delete( id );
			updateLine( id, { override_quantity: value === null ? null : quantityOverride( value, resultOf( id ), limits.max_quantity ) } );
		},
		onSpare( id, checked ) {
			const line = findLine( id );
			if ( ! line || shared ) {
				return;
			}
			if ( checked ) {
				spareLines.add( id );
			} else {
				spareLines.delete( id );
			}
			updateLine( id, { override_quantity: spareOverride( checked, resultOf( id ), limits.max_quantity ) } );
			const current = findLine( id );
			/* translators: %s: quantity. */
			announcer.announce( checked && current && current.override_quantity !== null ? sprintf( __( 'Quantity set to %s, including one spare.' ), String( current.override_quantity ) ) : __( 'The calculated quantity is used again.' ) );
		},
		onDuplicate( id ) {
			const newId = newLineId();
			store.dispatch( { type: 'line/duplicate', id, newId, max: maxLines } );
			if ( findLine( newId ) ) {
				announcer.announce( __( 'Item duplicated.' ) );
				setTimeout( () => focusCard( newId ), 0 );
			}
		},
		onMove( id, delta ) {
			store.dispatch( { type: 'line/move', id, delta } );
			renderNow();
			const card = cards.get( id );
			if ( card ) {
				card.focus( delta < 0 ? 'up' : 'down' );
			}
			const lines = store.getState().lines;
			/* translators: 1: position, 2: number of items. */
			announcer.announce( sprintf( __( 'Moved to position %1$s of %2$s.' ), String( lines.findIndex( ( l ) => l.id === id ) + 1 ), String( lines.length ) ) );
		},
		onRemove( id ) {
			const lines = store.getState().lines;
			const index = lines.findIndex( ( l ) => l.id === id );
			if ( index < 0 ) {
				return;
			}
			store.dispatch( { type: 'line/remove', id } );
			cartErrors.delete( id );
			lineNotices.delete( id );
			spareLines.delete( id );
			renderNow();
			// The card is replaced by an inline "… was removed · Undo" placeholder at the same place:
			// focus moves to it, so Undo is the next Tab stop and stays available without a time limit.
			const placeholder = removedViews.get( id );
			if ( placeholder ) {
				placeholder.focus();
			} else {
				focusElement( document.getElementById( workspaceTitleId ) );
			}
		},
		onRetry( id ) {
			const line = findLine( id );
			if ( line ) {
				loadProduct( line.product_id, true );
			}
		},
		onExplain( id ) {
			const line = findLine( id );
			const current = results.get( id );
			if ( line && current && current.result ) {
				openFormulaDialog( { title: lineTitle( line ), result: current.result, currency, showPrices: showPrices(), source: current.source, unit: unitOfLine( line ), locale, calculatedAt: calc.calculatedAt } );
			}
		},
	};

	/**
	 * Restores a removed line (inline Undo).
	 *
	 * @param {string} id Line ID.
	 */
	function undoRemove( id ) {
		store.dispatch( { type: 'line/restore', id, max: maxLines } );
		if ( findLine( id ) ) {
			announcer.announce( __( 'Item restored.' ) );
			focusCard( id );
			return;
		}
		/* translators: %d: maximum number of items. */
		announcer.announce( sprintf( __( 'A protocol can contain up to %d items. Remove an item to add another.' ), maxLines ), true );
	}

	/**
	 * Drops the Undo placeholder of a removed line; focus moves to what now takes its place.
	 *
	 * @param {string} id Line ID.
	 */
	function dismissRemoved( id ) {
		const view = removedViews.get( id );
		const next = view ? view.el.nextElementSibling || view.el.previousElementSibling : null;
		store.dispatch( { type: 'line/forget-removed', id } );
		renderNow();
		const card = next ? [ ...cards.values() ].find( ( c ) => c.el === next ) : null;
		if ( card ) {
			card.focus( 'heading' );
		} else if ( next && removedViews.size > 0 ) {
			const other = [ ...removedViews.values() ].find( ( v ) => v.el === next );
			if ( other ) {
				other.focus();
				return;
			}
			focusElement( document.getElementById( workspaceTitleId ) );
		} else {
			focusElement( document.getElementById( workspaceTitleId ) );
		}
	}

	/**
	 * Inline placeholder of a removed line: "{name} was removed from your plan." + Undo + Dismiss.
	 * Stays until it is used or dismissed (no time limit), at the position of the removed card.
	 *
	 * @param {Object} entry Removed entry { line, index }.
	 * @return {{el: HTMLElement, focus: Function}} View.
	 */
	function removedView( entry ) {
		const id = entry.line.id;
		let view = removedViews.get( id );
		if ( view ) {
			return view;
		}
		const textId = uid( 'removed' );
		const name = lineTitle( entry.line ) || __( 'Item' );
		/* translators: %s: product name. */
		const text = h( 'p', { class: 'arp-removed__text', id: textId, tabindex: '-1' }, icon( 'trash' ), h( 'span', null, sprintf( __( '%s was removed from your protocol.' ), name ) ) );
		const undo = button( { label: __( 'Undo' ), iconName: 'undo', size: 'sm', attrs: { 'aria-describedby': textId }, onClick: () => undoRemove( id ) } );
		const dismiss = button( { label: __( 'Dismiss' ), iconName: 'close', variant: 'ghost', size: 'sm', iconOnly: true, attrs: { 'aria-describedby': textId }, onClick: () => dismissRemoved( id ) } );
		const el = h( 'div', { class: 'arp-removed', role: 'group', 'aria-labelledby': textId, dataset: { removed: id } }, text, h( 'div', { class: 'arp-removed__actions' }, undo, dismiss ) );
		view = { el, focus: () => focusElement( text, { preventScroll: false } ) };
		removedViews.set( id, view );
		return view;
	}

	/**
	 * Display name and variant of a line.
	 *
	 * @param {Object} line Line.
	 * @return {{name: string, variant: string}} Names.
	 */
	function lineNames( line ) {
		const entry = products.get( line.product_id );
		const product = entry && entry.product;
		return { name: product ? product.name : '', variant: product ? variantLabel( product, line.variation_attributes ) : '' };
	}

	/**
	 * "Name — Variant".
	 *
	 * @param {Object} line Line.
	 * @return {string} Title.
	 */
	function lineTitle( line ) {
		const { name, variant } = lineNames( line );
		return variant ? name + ' — ' + variant : name;
	}

	/* ================================================================ Cart. */

	/**
	 * Lines ready for the cart.
	 *
	 * @return {Array<Object>} Items.
	 */
	function cartItems() {
		return store
			.getState()
			.lines.map( ( line ) => {
				const current = results.get( line.id );
				const unit = unitOfLine( line );
				if ( ! current || current.status !== 'ok' || ! current.result || current.result.quantity <= 0 || ! unit || ! unit.purchasable ) {
					return null;
				}
				const { name, variant } = lineNames( line );
				return {
					lineId: line.id,
					name,
					variant,
					product_id: line.product_id,
					variation_id: line.variation_id || 0,
					variation_attributes: line.variation_attributes,
					quantity: current.result.quantity,
					// The cart flow refuses anything the server has not calculated (never preview quantities).
					source: current.source,
				};
			} )
			.filter( Boolean );
	}

	/* ================================================================ Plans, sharing, reset. */

	/**
	 * Plan document for the store (exports, saving): a plan document needs a title (ARCHITECTURE
	 * §6.1), so an untitled workspace is sent as "Untitled research plan", the default the Plans
	 * dialog also saves with. The workspace itself keeps its empty title.
	 *
	 * @return {Object} Plan document.
	 */
	function titledPlan() {
		const plan = planDocument( store.getState() );
		const title = plan.title.trim();
		return { ...plan, title: title !== '' ? title : __( 'Untitled research protocol' ) };
	}

	/**
	 * Loads a plan into the workspace. The store protocol origin is replaced by `origin` (a store
	 * protocol that was used) or cleared (a draft, an account protocol, a file…; CHANGE-1.7.0 §6.7).
	 * A loaded plan is shown in "Make your own protocol" (CHANGE-1.7.1 §2.8).
	 *
	 * @param {Object}      plan    Plan (any source; sanitized here).
	 * @param {Object}      newMeta Meta.
	 * @param {Object|null} origin  Store protocol origin { protocols, lines, picks }, or null.
	 */
	function loadPlan( plan, newMeta, origin = null ) {
		const clean = sanitizePlan( plan, maxLines );
		autoStart = false;
		clearedWeeks = new Map();
		spareLines.clear();
		results.clear();
		cartErrors.clear();
		lineNotices.clear();
		cartState = { phase: 'idle' };
		store.dispatch( { type: 'workspace/load', plan: clean } );
		storeOrigin = origin ? normalizeStoreOrigin( origin, clean.lines.map( ( line ) => line.id ) ) : null;
		setMeta( newMeta );
		if ( clean.dropped > 0 ) {
			/* translators: %d: number of items. */
			toaster.show( sprintf( _n( '%d item could not be loaded and was skipped.', '%d items could not be loaded and were skipped.', clean.dropped ), clean.dropped ), { tone: 'info' } );
		}
		setView( 'own' );
	}

	/**
	 * Replaces the plan metadata (draft / account link).
	 *
	 * @param {Object} next Meta.
	 */
	function setMeta( next ) {
		meta = { ...next, dirty: false };
		savedRevision = store.getState().revision;
		autosave();
		scheduleRender();
	}

	/**
	 * Empties the workspace for a new protocol, whose start date starts at today (site time zone;
	 * the customer can change or clear it).
	 */
	function newProtocol() {
		clearedWeeks = new Map();
		spareLines.clear();
		storeOrigin = null;
		store.dispatch( { type: 'workspace/reset', title: '', start_date: siteToday } );
		autoStart = true;
	}

	/**
	 * Sets the protocol start date: lines that start in a later week keep their week (Start week).
	 * Clearing the date disables Start week; the weeks are remembered meanwhile, so a date set again
	 * (e.g. retyped) puts every line back into its week.
	 *
	 * Clearing it also removes the store protocol tag of every line that starts after week 1: its
	 * week is remembered only in memory (not autosaved), so after a reload it would run from week 1
	 * while still claiming the store's values (CHANGE-1.7.0 §6.7). Lines in week 1 keep their tag.
	 *
	 * @param {string|null} startDate Y-m-d or null.
	 */
	function setStartDate( startDate ) {
		if ( shared ) {
			return;
		}
		autoStart = false;
		const state = store.getState();
		let lines;
		if ( startDate === null ) {
			if ( state.start_date ) {
				clearedWeeks = lineWeeks( state.lines, state.start_date );
				clearedWeeks.forEach( ( week, id ) => {
					if ( week > 1 ) {
						untag( id );
					}
				} );
			}
			lines = shiftLineStarts( state.lines, state.start_date, null );
		} else if ( ! state.start_date ) {
			lines = restoreLineWeeks( state.lines, clearedWeeks, startDate );
			clearedWeeks = new Map();
		} else {
			lines = shiftLineStarts( state.lines, state.start_date, startDate );
		}
		store.dispatch( { type: 'workspace/start', start_date: startDate, lines: lines !== state.lines ? lines : undefined } );
	}

	/** Empties the workspace (after confirmation). */
	async function resetWorkspace() {
		const state = store.getState();
		if ( state.lines.length > 0 ) {
			const ok = await confirmDialog( {
				title: __( 'Start a new protocol?' ),
				message: __( 'All items and values in the current workspace will be removed. Saved protocols are not affected.' ),
				confirmLabel: __( 'New protocol' ),
				danger: true,
			} );
			if ( ! ok ) {
				return;
			}
		}
		results.clear();
		cartErrors.clear();
		lineNotices.clear();
		cartState = { phase: 'idle' };
		newProtocol();
		setMeta( { kind: 'local' } );
		announcer.announce( __( 'The workspace is empty.' ) );
	}

	/**
	 * Opens the Plans dialog — once the visitor's session is known, so a signed-in customer opening
	 * it right after the page loaded never sees the guest version. While the session is still
	 * loading the Plans button is busy and further calls (double clicks) return the pending one, so
	 * exactly one dialog opens.
	 *
	 * @return {Promise<void>} Settles once the dialog is open.
	 */
	function openPlans() {
		if ( plansOpening ) {
			return plansOpening;
		}
		if ( sessionKnown ) {
			showPlansDialog();
			return Promise.resolve();
		}
		toolbar.setPlansBusy( true );
		announcer.announce( __( 'Loading your protocols…' ) );
		plansOpening = sessionSettled.then( () => {
			toolbar.setPlansBusy( false );
			plansOpening = null;
			showPlansDialog();
		} );
		return plansOpening;
	}

	/**
	 * Opens the Plans dialog for the known session.
	 */
	function showPlansDialog() {
		openPlansDialog( {
			api,
			drafts,
			locale,
			maxLines,
			maxPlans: config.max_plans_per_user,
			features,
			urls,
			loggedIn,
			getPlan: () => planDocument( store.getState() ),
			getMeta: () => meta,
			lineCount: () => store.getState().lines.length,
			loadPlan,
			resetPlan: () => {
				results.clear();
				lineNotices.clear();
				newProtocol();
				setMeta( { kind: 'local' } );
			},
			setMeta: ( next ) => {
				if ( next.kind === 'account' && next.title && next.title !== store.getState().title ) {
					store.dispatch( { type: 'workspace/title', title: next.title } );
				}
				setMeta( next );
			},
			toast: ( message, tone ) => toaster.show( message, { tone } ),
			clearLocal: () => {
				results.clear();
				lineNotices.clear();
				newProtocol();
				meta = { kind: 'local' };
				autosave.cancel();
				drafts.clearAll();
				autosaveResult = { ok: true, code: null };
				toaster.show( __( 'Planner data stored in this browser was deleted.' ), { tone: 'success' } );
			},
			// Store managers: "Publish as pre-built protocol" (CHANGE-1.7.0 §6.10).
			canPublish: canPublish && ! shared,
			getStoreOrigin: () => storeOrigin,
			publishStoreProtocol: ( request ) => publishStoreProtocol( request ),
		} );
	}

	/**
	 * Publishes the workspace as a store protocol (store managers, CHANGE-1.7.0 §4.6, §6.10): a new
	 * one (POST, saved switched off) or an update of the newest origin protocol (PUT with the
	 * `updated_at` the builder knows; another manager's change in between answers 409 arp_conflict).
	 * Afterwards every line of the workspace equals the store protocol, so all of them are tagged and
	 * the origin holds the protocol's new `updated_at` (a later update sends it).
	 *
	 * @param {Object}      request        Request.
	 * @param {boolean}     request.create Create a new store protocol.
	 * @param {string|null} request.id     Store protocol to update.
	 * @param {string}      request.name   Name of the new store protocol.
	 * @return {Promise<Object>} normalizePublishResult() result; rejects with the ApiError.
	 */
	async function publishStoreProtocol( request ) {
		const create = !! ( request && request.create );
		const id = create ? null : storeProtocolId( request && request.id );
		const entry = id && storeOrigin ? storeOrigin.protocols.find( ( item ) => item.id === id ) : null;
		if ( ! create && id === null ) {
			throw new Error( '' );
		}
		const updatedAt = entry ? entry.updatedAt : '';
		const body = publishBody( { plan: titledPlan(), origin: storeOrigin, name: create && typeof request.name === 'string' ? request.name : '', updatedAt: create ? '' : updatedAt } );
		const data = create ? await api.createStoreProtocol( body ) : await api.updateStoreProtocol( id, body );
		const result = normalizePublishResult( data );
		if ( ! result ) {
			throw new Error( '' );
		}
		const lineIds = store.getState().lines.map( ( line ) => line.id );
		storeOrigin = normalizeStoreOrigin( { protocols: [ { id: result.id, name: result.name, updatedAt: result.updatedAt } ], lines: lineIds, picks: storeOrigin ? storeOrigin.picks : [] }, lineIds );
		autosave();
		scheduleRender();
		return result;
	}

	/**
	 * Saves the workspace over its account plan (PATCH with optimistic concurrency), used by the
	 * Share dialog before a link is created.
	 *
	 * @return {Promise<{ok: boolean, message: string}>} Result.
	 */
	async function saveAccountChanges() {
		if ( meta.kind !== 'account' || ! meta.uuid ) {
			return { ok: false, message: '' };
		}
		const plan = titledPlan();
		const title = plan.title;
		try {
			const record = await api.updatePlan( meta.uuid, { title, plan: { ...plan, title }, if_unmodified_since: meta.updated_at || undefined } );
			setMeta( {
				kind: 'account',
				uuid: meta.uuid,
				updated_at: record && typeof record.updated_at === 'string' ? record.updated_at : meta.updated_at,
				title: record && typeof record.title === 'string' ? record.title : title,
			} );
			return { ok: true, message: '' };
		} catch ( e ) {
			return {
				ok: false,
				message:
					e && e.code === 'arp_conflict'
						? __( 'This protocol was changed in another tab or on another device, so your changes were not saved and no link was created. Open My protocols to load the saved version or save your changes as a new protocol.' )
						: ( e && e.message ) || '',
			};
		}
	}

	/** Opens the Share dialog. */
	function openShare() {
		openShareDialog( {
			api,
			locale,
			defaultDays: config.share_default_days,
			maxDays: config.share_max_days,
			getMeta: () => meta,
			onSaveFirst: () => openPlans(),
			saveChanges: saveAccountChanges,
		} );
	}

	/**
	 * Opens a shared plan read-only (#share=token).
	 *
	 * @param {string} token Token.
	 */
	async function openShared( token ) {
		if ( ! SHARE_TOKEN.test( token ) ) {
			sharePending = false;
			toaster.show( __( 'This share link is not valid.' ), { tone: 'error', timeout: 0 } );
			scheduleRender();
			return;
		}
		// From here on `shared` keeps the choice hidden (set in the same task, nothing is painted between).
		shared = { token, status: 'loading', title: '' };
		sharePending = false;
		scheduleRender();
		try {
			const data = await api.shared( token );
			const plan = sanitizePlan( data && data.plan ? data.plan : {}, 100 );
			shared = {
				token,
				status: 'ready',
				title: data && typeof data.title === 'string' && data.title !== '' ? data.title : plan.title,
				scope: data && data.scope === 'full' ? 'full' : 'quantities',
				expires_at: data && typeof data.expires_at === 'string' ? data.expires_at : '',
			};
			results.clear();
			lineNotices.clear();
			store.dispatch( { type: 'workspace/load', plan: { ...plan, title: shared.title } } );
			steps.select( 1, { replace: true } );
			announcer.announce( __( 'Shared protocol opened in read-only mode.' ) );
		} catch ( e ) {
			shared = null;
			toaster.show( e.code === 'arp_share_invalid' || e.status === 404 || e.status === 403 ? __( 'This share link is invalid, has expired or was revoked.' ) : e.message, { tone: 'error', timeout: 0 } );
		}
		scheduleRender();
	}

	/** Leaves the shared view and restores the visitor's own workspace. */
	function closeShared() {
		shared = null;
		results.clear();
		lineNotices.clear();
		restoreWorkspace();
		scheduleRender();
	}

	/** Copies the shared plan into the visitor's own (editable) workspace. */
	async function copyShared() {
		const previous = drafts.loadWorkspace();
		if ( previous && previous.plan && Array.isArray( previous.plan.lines ) && previous.plan.lines.length > 0 ) {
			const ok = await confirmDialog( {
				title: __( 'Replace your workspace?' ),
				message: __( 'Your own workspace on this device will be replaced by a copy of the shared protocol. Save it in My protocols first if you want to keep it.' ),
				confirmLabel: __( 'Replace' ),
			} );
			if ( ! ok ) {
				return;
			}
		}
		shared = null;
		// The copy is the shared protocol's lines, not the previous workspace: no store protocol origin.
		storeOrigin = null;
		setMeta( { kind: 'local' } );
		announcer.announce( __( 'The shared protocol was copied into your workspace.' ) );
		// Lines shown read-only were never adapted: adapt them now that they are the visitor's own.
		new Set( store.getState().lines.map( ( line ) => line.product_id ) ).forEach( ( productId ) => {
			if ( products.has( productId ) && products.get( productId ).product ) {
				onProductLoaded( productId );
			}
		} );
		scheduleRender();
	}

	/* ================================================================ Store protocols. */

	/**
	 * Removes the "From a pre-built protocol" tag of a line: the customer changed one of the values
	 * the store wrote (CHANGE-1.7.0 §6.7). The line stays in `picks` (only onSelect with a notice
	 * removes it there), so publishing keeps "Option of your choice" for it.
	 *
	 * @param {string} id Line ID.
	 */
	function untag( id ) {
		if ( ! storeOrigin || ! storeOrigin.lines.has( id ) ) {
			return;
		}
		storeOrigin.lines.delete( id );
		autosave();
		scheduleRender();
	}

	/**
	 * "Use this protocol" (CHANGE-1.7.0 §6.6; `mode` 'use', the onUse callback of the store protocol
	 * dialog) and "Edit in builder" (`mode` 'edit', §6.8). Copies the store's values into the
	 * workspace — replacing it or adding to it — lands in step 2 of "Make your own protocol" and lets
	 * the store subscription load the products and calculate; every value stays editable and nothing
	 * reaches the cart without "Add all to cart". Step 2 is pushed before the view switches, so Back
	 * returns to the pre-built protocols; "Use this protocol" is remembered as the visitor's choice
	 * "Make your own protocol" (CHANGE-1.7.1 §2.5, §2.10).
	 *
	 * While the protocol dialog is open the planner root is inert (the toaster and the announcer live
	 * in it): refusals go to `ctx.showError()` (the dialog's inline alert), and the dialog is closed
	 * with `ctx.close()` before the workspace changes, step 2 takes focus or anything is announced.
	 *
	 * @param {Object} detail Store protocol (normalizeStoreProtocol()).
	 * @param {Object} ctx    { opener, close(), showError( message ) }.
	 * @param {string} mode   'use' | 'edit'.
	 * @return {Promise<boolean>} The workspace was changed.
	 */
	async function useStoreProtocol( detail, ctx, mode = 'use' ) {
		const edit = mode === 'edit';
		// 1. Guards (nothing changes).
		if ( shared ) {
			ctx.showError( __( 'Close the shared protocol to edit your own workspace.' ) );
			return false;
		}
		// A page served from a page cache may carry an older max_lines than the server, and
		// sanitizePlan() would cut the protocol silently: refuse it instead.
		if ( detail.lineCount > maxLines ) {
			ctx.showError(
				edit
					? sprintf( /* translators: %d: maximum number of items in a protocol. */ __( 'This pre-built protocol has more items than the builder allows (%d). Edit it on the Pre-built protocols tab.' ), maxLines )
					: __( 'This pre-built protocol has more items than the builder allows right now, so it cannot be used.' )
			);
			return false;
		}

		// 2. Products: customers need a unit every line can use now; the edit path only needs the
		// products (the builder's own notices show what has to be fixed).
		const ids = [ ...new Set( detail.lines.map( ( line ) => line.productId ) ) ];
		const loaded = await Promise.all( ids.map( ( id ) => loadProduct( id ) ) );
		if ( ctx.opener && ! ctx.opener.isConnected ) {
			// The customer closed the protocol dialog while its products loaded: nothing is applied.
			return false;
		}
		const catalogue = new Map();
		ids.forEach( ( id, i ) => {
			if ( loaded[ i ] ) {
				catalogue.set( id, loaded[ i ] );
			}
		} );
		const build = ( planStart, usedIds ) => buildTemplateLines( { protocol: detail, products: catalogue, planStart, usedIds, newId: newLineId, strict: mode !== 'edit' } );
		const check = build( siteToday, new Set() );
		if ( check.missing.length > 0 ) {
			const first = check.missing[ 0 ];
			ctx.showError(
				edit
					? sprintf( /* translators: %d: product ID. */ __( 'This pre-built protocol cannot be opened in the builder because product #%d could not be loaded. Fix it on the Pre-built protocols tab.' ), first.productId )
					: sprintf( /* translators: %s: product name. */ __( 'This pre-built protocol cannot be used right now because %s is not available.' ), first.name || '#' + first.productId )
			);
			return false;
		}

		// 3. Replace or add: an untouched workspace is replaced without asking.
		const state = store.getState();
		const untouched = isUntouchedWorkspace( planDocument( state ), { kind: meta.kind, auto_start: autoStart } );
		let choice = 'replace';
		if ( ! untouched && edit ) {
			const ok = await confirmDialog( {
				title: __( 'Replace the current workspace?' ),
				message: __( 'The protocol you are working on will be replaced. Save it first if you want to keep it.' ),
				confirmLabel: __( 'Replace' ),
			} );
			if ( ! ok ) {
				return false;
			}
		} else if ( ! untouched ) {
			choice = await chooseApplyMode( { canAdd: state.lines.length + detail.lineCount <= maxLines, maxLines, hasItems: state.lines.length > 0 } );
			if ( choice !== 'replace' && choice !== 'add' ) {
				return false;
			}
		}

		// 4. The protocol dialog closes first (focus goes back to its opener, the root is no longer
		// inert); only then is the workspace changed.
		ctx.close();

		let message;
		let target = 'heading';
		if ( choice === 'replace' ) {
			// 5. Replace: the protocol starts today (site time zone), titled with the protocol's name,
			// without notes; the account or draft link of the previous workspace is dropped. Step 2 is
			// pushed first: loadPlan() switches to "Make your own protocol", and the history entry left
			// behind keeps the view it showed (Back returns to the pre-built protocols).
			steps.select( 1, { push: true } );
			const built = build( siteToday, new Set() );
			loadPlan(
				{ schema: 'arp-plan', version: 1, title: detail.name, start_date: siteToday, notes: '', lines: built.lines },
				{ kind: 'local' },
				{ protocols: [ { id: detail.id, name: detail.name, updatedAt: edit && detail.edit ? detail.edit.updatedAt : '' } ], lines: built.tagged, picks: built.picks }
			);
			/* translators: %s: pre-built protocol name. */
			message = sprintf( __( '"%s" was loaded into your protocol. Check every value before you order.' ), detail.name );
		} else {
			// 6. Add: week 1 of the store protocol is the workspace's protocol start (set to today when a
			// later week needs one); title, notes, start date and meta stay. goToStep2() pushes step 2,
			// then switches the view.
			if ( needsStartDate( detail ) && ! store.getState().start_date ) {
				setStartDate( siteToday );
			}
			const current = store.getState();
			const built = build( current.start_date, new Set( current.lines.map( ( line ) => line.id ) ) );
			built.lines.forEach( ( line ) => store.dispatch( { type: 'line/add', line, max: maxLines } ) );
			const added = new Set( built.lines.map( ( line ) => line.id ).filter( ( id ) => findLine( id ) !== null ) );
			// The protocol moves to the end of the origin (no duplicates, the oldest beyond 5 dropped).
			const protocols = ( storeOrigin ? storeOrigin.protocols : [] ).filter( ( entry ) => entry.id !== detail.id );
			protocols.push( { id: detail.id, name: detail.name, updatedAt: '' } );
			storeOrigin = {
				protocols: protocols.slice( -MAX_ORIGIN_PROTOCOLS ),
				lines: new Set( [ ...( storeOrigin ? storeOrigin.lines : [] ), ...built.tagged.filter( ( id ) => added.has( id ) ) ] ),
				picks: new Set( [ ...( storeOrigin ? storeOrigin.picks : [] ), ...built.picks.filter( ( id ) => added.has( id ) ) ] ),
			};
			autosave();
			const first = built.lines.find( ( line ) => added.has( line.id ) );
			target = first ? first.id : 'heading';
			/* translators: %s: pre-built protocol name. */
			message = sprintf( __( 'The items of "%s" were added to your protocol. Check every value before you order.' ), detail.name );
		}

		// 7. Step 2 (heading after replace, the first new item after add); the products load and the
		// quantities are calculated through the store subscription. A used protocol is the visitor's
		// own from now on: the next visit opens "Make your own protocol" (the result is ignored:
		// storage may be unavailable or full).
		if ( ! edit ) {
			drafts.setPref( ENTRY_VIEW_PREF, 'own' );
		}
		goToStep2( target );
		toaster.show( message, { tone: 'success' } );
		announcer.announce( message );
		return true;
	}

	/**
	 * Opens a store protocol link (CHANGE-1.7.0 §6.8, CHANGE-1.7.1 §2.8): #store-protocol=<id> opens
	 * its dialog, #store-protocols=product:<id> / group:<key> / anything else shows the section
	 * (filtered) — both in the "Pre-built protocols" view, after the list has answered when the page
	 * did not expect protocols — and #store-protocol-edit=<id> (managers, "Edit in builder") loads any
	 * store protocol into the workspace of "Make your own protocol". The fragment is always replaced,
	 * so IDs never linger. A press of an entry button while a pre-built link is pending stops it.
	 *
	 * @param {Object} link parseStoreLink() result.
	 * @return {Promise<void>} Settles when handled.
	 */
	async function openStoreLink( link ) {
		const seq = ++linkSeq;
		await sessionSettled;
		if ( shared ) {
			closeShared();
		}
		steps.select( 0, { replace: true } );
		if ( link.kind !== 'edit' && seq !== linkSeq ) {
			return; // A button was pressed meanwhile.
		}
		setView( link.kind === 'edit' ? 'own' : 'prebuilt' );
		if ( link.kind !== 'edit' ) {
			if ( ! available && storeProtocolsRequested ) {
				await storeProtocols.ready; // Settle availability before opening or filtering anything.
				refreshAvailability();
				if ( seq !== linkSeq ) {
					return;
				}
			}
			if ( ! available ) {
				// No section: #store-protocol= opens its dialog without one, as in 1.7.0. A product or
				// group link keeps asking for the pre-built view: its own filtered list may be the first
				// to report protocols, which then shows that view before the section is revealed.
				if ( link.kind !== 'product' && link.kind !== 'group' ) {
					setView( 'own' );
				}
			} else if ( link.kind !== 'protocol' ) {
				revealPrebuilt();
			}
		}
		// The section takes focus and scrolls for this link only while no button was pressed since.
		const wanted = () => seq === linkSeq;
		const none = () => {
			if ( seq !== linkSeq ) {
				return;
			}
			// No first view has loaded: the section shows "could not be loaded" + "Try again" instead.
			if ( effectiveView() === 'prebuilt' && storeProtocols.available() === null ) {
				focusElement( storeProtocols.el.querySelector( '.arp-sprotos__title' ) );
				return;
			}
			toaster.show( __( 'There are no pre-built protocols at the moment.' ), { tone: 'info' } );
		};
		// After a product, group or section link's list: S52 may be announced again by later changes,
		// and a link whose list found nothing leaves no hidden request for the pre-built view.
		const done = () => {
			if ( noneLink === seq ) {
				noneLink = 0;
			}
			if ( seq === linkSeq && ! available ) {
				setView( 'own' );
			}
		};
		switch ( link.kind ) {
			case 'protocol':
				if ( ( await storeProtocols.open( link.id ) ) === 'unavailable' ) {
					showStoreProtocolUnavailable();
				}
				return;
			case 'edit':
				await openStoreProtocolForEdit( link.id );
				return;
			case 'product':
				noneLink = seq;
				if ( ! ( await storeProtocols.showProduct( link.productId, '', { wanted } ) ) ) {
					none();
				}
				done();
				return;
			case 'group':
				noneLink = seq;
				if ( ! ( await storeProtocols.showGroup( link.key, { wanted } ) ) ) {
					none();
				}
				done();
				return;
			default:
				noneLink = seq;
				if ( storeProtocolsRequested ) {
					await storeProtocols.ready;
					if ( seq !== linkSeq ) {
						done();
						return;
					}
				}
				if ( ! storeProtocols.hasAny() ) {
					none();
					done();
					return;
				}
				done();
				scrollIntoViewSafe( storeProtocols.el );
				focusElement( storeProtocols.el.querySelector( '.arp-sprotos__title' ) );
		}
	}

	/** Shows that a store protocol is not available (unknown, switched off, hidden or members only). */
	function showStoreProtocolUnavailable() {
		toaster.show( __( 'This pre-built protocol is not available.' ), { tone: 'error' } );
	}

	/**
	 * "Edit in builder" (#store-protocol-edit=<id>, store managers only): loads any stored protocol —
	 * also one that customers do not see — so its items and the builder's own notices show what to
	 * fix; afterwards, for a protocol customers do not see, a lasting toast names the first reason.
	 *
	 * @param {string} value Store protocol ID as given.
	 * @return {Promise<void>} Settles when handled.
	 */
	async function openStoreProtocolForEdit( value ) {
		const id = storeProtocolId( value );
		if ( ! canPublish || id === null ) {
			showStoreProtocolUnavailable();
			return;
		}
		let detail = null;
		try {
			detail = normalizeStoreProtocol( await api.storeProtocolForEdit( id ) );
		} catch ( e ) {
			if ( e && ( e.status === 404 || e.status === 401 || e.status === 403 || e.code === 'arp_not_found' ) ) {
				showStoreProtocolUnavailable();
			} else {
				toaster.show( __( 'This pre-built protocol could not be loaded. Please try again.' ), { tone: 'error' } );
			}
			return;
		}
		if ( ! detail || detail.id !== id ) {
			showStoreProtocolUnavailable();
			return;
		}
		const used = await useStoreProtocol( detail, { opener: null, close() {}, showError: ( text ) => toaster.show( text, { tone: 'error' } ) }, 'edit' );
		if ( used && detail.edit && ! detail.edit.visible ) {
			const problem = detail.edit.problems.find( ( entry ) => entry.message !== '' );
			if ( problem ) {
				/* translators: %s: the first reason why customers do not see the pre-built protocol. */
				toaster.show( sprintf( __( 'Customers do not see this pre-built protocol at the moment: %s' ), problem.message ), { tone: 'info', timeout: 0 } );
			}
		}
	}

	/* ================================================================ Persistence. */

	const autosave = debounce( () => {
		if ( shared ) {
			return;
		}
		// auto_start: the start date is still the pre-filled "today" of a new protocol (restore).
		// store_origin: the store protocols the workspace started from and the tagged lines (§6.7).
		const storedMeta = { kind: meta.kind, draftId: meta.draftId || null, uuid: meta.uuid || null, updated_at: meta.updated_at || null, title: meta.title || null, dirty: !! meta.dirty, auto_start: autoStart, store_origin: storeOriginForSave( storeOrigin ) };
		autosaveResult = drafts.saveWorkspace( planDocument( store.getState() ), storedMeta );
		scheduleRender();
	}, 500 );

	/**
	 * Restores the autosaved workspace (if any). An untouched new protocol (no items, name or notes,
	 * its start date still the pre-filled one) starts again as a new protocol, so its date is today
	 * and not the day it was first opened (CHANGE-1.1.0 §9.4); everything else keeps its date.
	 * The store protocol origin is restored for every kind of workspace (CHANGE-1.7.0 §6.7).
	 */
	function restoreWorkspace() {
		const saved = drafts.loadWorkspace();
		if ( saved && saved.plan && isUntouchedWorkspace( sanitizePlan( saved.plan, maxLines ), saved.meta ) ) {
			newProtocol();
			meta = { kind: 'local' };
			savedRevision = store.getState().revision;
			return;
		}
		if ( saved && saved.plan ) {
			const clean = sanitizePlan( saved.plan, maxLines );
			store.dispatch( { type: 'workspace/load', plan: clean } );
			autoStart = false;
			const stored = saved.meta || {};
			meta = [ 'draft', 'account' ].includes( stored.kind ) ? { kind: stored.kind, draftId: stored.draftId || undefined, uuid: stored.uuid || undefined, updated_at: stored.updated_at || undefined, title: stored.title || undefined, dirty: !! stored.dirty } : { kind: 'local' };
			storeOrigin = normalizeStoreOrigin( stored.store_origin, clean.lines.map( ( line ) => line.id ) );
			savedRevision = meta.dirty ? -1 : store.getState().revision;
		} else {
			newProtocol();
			meta = { kind: 'local' };
			savedRevision = store.getState().revision;
		}
	}

	/* ================================================================ Store subscription. */

	store.subscribe( ( state, previous ) => {
		if ( state.lines !== previous.lines || state.start_date !== previous.start_date ) {
			const before = new Map( previous.lines.map( ( line ) => [ line.id, line ] ) );
			state.lines.forEach( ( line ) => {
				if ( before.get( line.id ) !== line ) {
					cartErrors.delete( line.id );
				}
			} );
			const ids = new Set( state.lines.map( ( line ) => line.id ) );
			for ( const id of lineNotices.keys() ) {
				if ( ! ids.has( id ) ) {
					lineNotices.delete( id );
				}
			}
			for ( const id of spareLines ) {
				if ( ! ids.has( id ) && ! ( state.removed || [] ).some( ( entry ) => entry.line.id === id ) ) {
					spareLines.delete( id );
				}
			}
			// "In protocol" states of the product cards and combinations follow every change of the
			// protocol's products (add, remove, undo, duplicate, reset, opening or importing…), in place.
			const planned = state.lines.map( ( line ) => line.product_id ).sort().join( ',' );
			if ( planned !== plannedSignature ) {
				plannedSignature = planned;
				picker.refreshPlanned();
				combos.refresh();
			}
			if ( cartState.phase === 'done' || cartState.phase === 'error' ) {
				cartState = { phase: 'idle' };
			}
			ensureProducts();
			refreshPreviews();
			calcDebounced();
		}
		// A removed line keeps its store protocol tag for Undo; once forgotten (dismissed, or beyond
		// the undo history) it leaves the origin. A shared protocol shown read-only never touches it.
		if ( storeOrigin && ! shared && ( state.lines !== previous.lines || state.removed !== previous.removed ) ) {
			const known = new Set( [ ...state.lines.map( ( line ) => line.id ), ...( state.removed || [] ).map( ( entry ) => entry.line.id ) ] );
			[ storeOrigin.lines, storeOrigin.picks ].forEach( ( set ) => {
				for ( const id of [ ...set ] ) {
					if ( ! known.has( id ) ) {
						set.delete( id );
					}
				}
			} );
		}
		if ( meta.kind === 'account' ) {
			meta = { ...meta, dirty: state.revision !== savedRevision };
		}
		if ( ! shared ) {
			autosave();
		}
		scheduleRender();
	} );

	/* ================================================================ Rendering. */

	/**
	 * Save status line.
	 *
	 * @return {{text: string, tone: string}} Status.
	 */
	function saveStatus() {
		if ( shared ) {
			return { text: '', tone: '' };
		}
		if ( meta.kind === 'account' ) {
			return meta.dirty
				? { text: __( 'Changes not yet saved to your account' ), tone: 'warning' }
				: { text: __( 'Saved to your account' ), tone: 'success' };
		}
		if ( ! drafts.available ) {
			return { text: __( 'Not saved: browser storage is unavailable' ), tone: 'warning' };
		}
		if ( ! autosaveResult.ok ) {
			return { text: __( 'Not saved: browser storage is full' ), tone: 'warning' };
		}
		return { text: __( 'Saved on this device' ), tone: 'success' };
	}

	/** Renders the banners (shared plan, boot errors) when they change. */
	function renderBanners() {
		const signature = JSON.stringify( [ bootError, shared ? [ shared.status, shared.title, shared.scope, shared.expires_at ] : null, features.exports ] );
		if ( signature === bannerSignature ) {
			return;
		}
		bannerSignature = signature;
		const nodes = [];
		if ( bootError ) {
			nodes.push(
				h(
					'div',
					{ class: 'arp-notice arp-notice--error', role: 'alert' },
					h( 'p', { class: 'arp-notice__title' }, __( 'The planner could not connect to the store' ) ),
					h( 'p', null, bootError ),
					button( { label: __( 'Try again' ), iconName: 'refresh', size: 'sm', onClick: () => boot() } )
				)
			);
		}
		if ( shared ) {
			nodes.push(
				h(
					'div',
					{ class: 'arp-banner arp-banner--shared', role: 'region', 'aria-label': __( 'Shared protocol' ) },
					h(
						'div',
						{ class: 'arp-banner__text' },
						h( 'p', { class: 'arp-banner__title' }, icon( 'link' ), __( 'Shared protocol (read only)' ) ),
						shared.status === 'loading'
							? h( 'p', { role: 'status' }, __( 'Opening the shared protocol…' ) )
							: h(
								'p',
								null,
								[
									shared.title,
									shared.scope === 'full' ? __( 'Full protocol' ) : __( 'Quantities only' ),
									/* translators: %s: date. */
									shared.expires_at ? sprintf( __( 'link expires %s' ), formatDate( shared.expires_at.slice( 0, 10 ), locale ) ) : '',
								]
									.filter( Boolean )
									.join( ' · ' )
							)
					),
					shared.status === 'ready'
						? h(
							'div',
							{ class: 'arp-banner__actions' },
							button( { label: __( 'Copy into my workspace' ), iconName: 'copy', variant: 'primary', size: 'sm', onClick: copyShared } ),
							features.exports !== false
								? button( {
									label: __( 'Print' ),
									iconName: 'print',
									size: 'sm',
									onClick: () => exportsMenu.print(),
								} )
								: null,
							button( { label: __( 'Close shared protocol' ), iconName: 'close', variant: 'ghost', size: 'sm', onClick: closeShared } )
						)
						: null
				)
			);
		}
		render( banners, ...nodes );
	}

	/**
	 * View model of one line card.
	 *
	 * @param {Object}  line     Line.
	 * @param {number}  index    Index.
	 * @param {number}  count    Number of lines.
	 * @param {Object}  state    Workspace.
	 * @return {Object} View.
	 */
	function lineView( line, index, count, state ) {
		const entry = products.get( line.product_id );
		const { name, variant } = lineNames( line );
		const current = results.get( line.id ) || null;
		const unit = unitOfLine( line );
		const legacyLine = isLegacyLine( line, unit );
		return {
			line,
			index,
			count,
			atMax: count >= maxLines,
			readOnly: !! shared,
			productState: entry ? { status: entry.status, product: entry.product } : { status: 'loading', product: null },
			unit,
			kind: lineKind( unit ) || ( unit ? '' : productKind( entry && entry.product ) ),
			// Saved with an older setting (the first edit converts it: updateLine()). Its fields, in
			// read-only views too, show only exact equivalents of the stored values: no default duration
			// is filled in before that first edit.
			legacyShown: legacyLine,
			legacyPreview: legacyLine ? modernizeLine( line, unit, { defaultWeeks: null, quantity: current && current.result ? current.result.quantity : null, limits } ) : null,
			calc: current,
			pending: calc.pending && !! current && current.source === 'preview' && current.status === 'ok',
			cartErrors: cartErrors.get( line.id ) || [],
			currency,
			showPrices: showPrices(),
			showImages,
			locale,
			limits,
			planStart: state.start_date,
			name: name || ( entry && entry.status !== 'loading' ? __( 'Unavailable product' ) : '' ),
			variant,
			unitNotice: lineNotices.get( line.id ) || '',
			// "From a pre-built protocol" (CHANGE-1.7.0 §6.7); never on a shared protocol shown read-only.
			storeTag: ! shared && !! storeOrigin && storeOrigin.lines.has( line.id ),
		};
	}

	/** Renders every component now. */
	function renderNow() {
		renderQueued = false;
		const state = store.getState();
		const readOnly = !! shared;
		const status = saveStatus();
		renderBanners();
		toolbar.update( {
			title: state.title,
			start_date: state.start_date,
			status: status.text,
			statusTone: status.tone,
			readOnly,
			canReset: state.lines.length > 0 || state.title !== '' || state.start_date !== siteToday,
		} );
		exportsMenu.update( { enabled: features.exports !== false, hasLines: state.lines.length > 0, hasStartDate: hasStartDate( state ) } );
		picker.el.hidden = readOnly;
		combos.el.classList.toggle( 'is-readonly', readOnly );
		storeProtocols.setReadOnly( readOnly );
		applyView();
		// While the app cannot start, the expected section shows no loading state (CHANGE-1.7.1 §2.7).
		storeProtocols.setStalled( bootError !== '' );
		steps.setCount( state.lines.length );

		// Lines, with the Undo placeholders of removed lines at the positions they were removed from.
		const ids = new Set( state.lines.map( ( line ) => line.id ) );
		for ( const [ id, card ] of cards ) {
			if ( ! ids.has( id ) ) {
				card.el.remove();
				cards.delete( id );
			}
		}
		const removed = readOnly ? [] : ( state.removed || [] ).map( ( entry, order ) => ( { entry, order } ) ).sort( ( a, b ) => a.entry.index - b.entry.index || a.order - b.order );
		const removedIds = new Set( removed.map( ( item ) => item.entry.line.id ) );
		for ( const [ id, view ] of removedViews ) {
			if ( ! removedIds.has( id ) ) {
				view.el.remove();
				removedViews.delete( id );
			}
		}
		const nodes = [];
		let r = 0;
		state.lines.forEach( ( line, index ) => {
			while ( r < removed.length && removed[ r ].entry.index <= index ) {
				nodes.push( removedView( removed[ r++ ].entry ).el );
			}
			let card = cards.get( line.id );
			if ( ! card ) {
				card = createLineCard( cardHandlers, line.id );
				cards.set( line.id, card );
			}
			card.update( lineView( line, index, state.lines.length, state ) );
			nodes.push( card.el );
		} );
		while ( r < removed.length ) {
			nodes.push( removedView( removed[ r++ ].entry ).el );
		}
		nodes.forEach( ( node, index ) => {
			const at = lineList.children[ index ];
			if ( at !== node ) {
				lineList.insertBefore( node, at || null );
			}
		} );
		workspaceEmpty.hidden = state.lines.length > 0;
		/* translators: 1: number of items, 2: maximum. */
		workspaceCount.textContent = state.lines.length > 0 ? sprintf( _n( '%1$s of %2$s item', '%1$s of %2$s items', maxLines ), String( state.lines.length ), String( maxLines ) ) : '';
		maxNotice.hidden = state.lines.length < maxLines || readOnly;
		/* translators: %d: maximum number of items. */
		maxNotice.textContent = sprintf( __( 'This protocol has reached the maximum of %d items. Remove an item to add another, or start a second protocol.' ), maxLines );

		// Timeline.
		if ( timeline ) {
			const rows = state.lines
				.map( ( line ) => {
					const current = results.get( line.id );
					if ( ! current || current.status !== 'ok' || ! current.result || current.result.mode !== 'schedule' || ! current.timeline ) {
						return null;
					}
					const unit = unitOfLine( line );
					return { id: line.id, name: lineTitle( line ) || __( 'Item' ), format: unit ? unit.containerType : '', result: current.result, timeline: current.timeline };
				} )
				.filter( Boolean );
			timeline.update( { rows, currency, locale } );
			timeline.el.hidden = state.lines.length === 0;
		}

		// Summary.
		const items = state.lines.map( ( line ) => {
			const current = results.get( line.id );
			const { name, variant } = lineNames( line );
			let itemStatus = 'incomplete';
			if ( current && current.status === 'ok' && current.result ) {
				itemStatus = 'ok';
			} else if ( current && ( current.status === 'blocked' || current.status === 'error' ) ) {
				itemStatus = 'blocked';
			}
			return {
				id: line.id,
				name: name || __( 'Item' ),
				variant,
				status: itemStatus,
				quantity: itemStatus === 'ok' ? current.result.quantity : 0,
				estimate: itemStatus === 'ok' ? current.result.estimate : null,
			};
		} );
		const ready = items.filter( ( item ) => item.status === 'ok' );
		const allServer = state.lines.every( ( line ) => ( results.get( line.id ) || {} ).source === 'server' );
		if ( stale && ! staleAnnounced && showPrices() && ready.length > 0 ) {
			// The warning is drawn in the summary (a closed bottom sheet on phones): announce it once.
			staleAnnounced = true;
			announcer.announce( __( 'Prices may have changed since they were last checked. Refresh prices before adding to your cart.' ) );
		} else if ( ! stale ) {
			staleAnnounced = false;
		}
		let subtotal = null;
		if ( ready.length > 0 ) {
			if ( allServer && calc.totals && typeof calc.totals.estimate === 'string' && ! calc.pending ) {
				subtotal = calc.totals.estimate;
			} else {
				try {
					subtotal = priceSum( ready.map( ( item ) => item.estimate ), currency.decimals );
				} catch ( e ) {
					subtotal = null;
				}
			}
		}
		const waItems = ready.filter( ( item ) => item.quantity > 0 ).map( ( item ) => ( { quantity: item.quantity, name: item.name, variant: item.variant } ) );
		const shownSubtotal = ready.some( ( item ) => item.estimate !== null ) ? subtotal : null;

		// Step 1 bar: "{n} products · est. {price}" (hidden while the protocol is empty).
		stepBar.hidden = state.lines.length === 0 || readOnly;
		const productCount = sprintf( /* translators: %s: number of products. */ _n( '%s product', '%s products', state.lines.length ), String( state.lines.length ) );
		const barText = showPrices() && shownSubtotal ? sprintf( /* translators: 1: number of products (e.g. 3 products), 2: estimated price. */ __( '%1$s · est. %2$s' ), productCount, money( shownSubtotal, currency ) ) : productCount;
		if ( stepBarText.textContent !== barText ) {
			stepBarText.textContent = barText;
		}

		summary.update( {
			items,
			subtotal: shownSubtotal,
			showPrices: showPrices(),
			currency,
			stale,
			calcError: calc.error,
			pending: calc.pending,
			cart: cartState,
			readOnly,
			sticky: config.sticky_summary !== false,
			urls,
			showShare: !! ( features.sharing && features.account_plans && loggedIn && ! readOnly ),
			exports: features.exports !== false,
			hasStartDate: hasStartDate( state ),
			whatsapp: {
				enabled: !! features.whatsapp && typeof config.whatsapp_number === 'string' && config.whatsapp_number !== '',
				url: whatsappUrl( config.whatsapp_number, buildWhatsAppMessage( config.whatsapp_template, waItems ) ),
			},
		} );
	}

	/**
	 * Batches renders: every change made in the same task renders once, before the next paint
	 * (a microtask, so rendering also continues in background tabs where animation frames pause).
	 */
	function scheduleRender() {
		if ( renderQueued ) {
			return;
		}
		renderQueued = true;
		Promise.resolve().then( () => {
			if ( renderQueued ) {
				renderNow();
			}
		} );
	}

	/* ================================================================ Hash routing. */

	/**
	 * Parses #add=… / #share=… / #protocol=… / the pre-built protocol links from the URL fragment.
	 *
	 * @return {{add: string|null, share: string|null, protocol: string|null, store: Object|null}} Hash.
	 */
	function parseHash() {
		return parseDeepLink( window.location.hash || '' );
	}

	/**
	 * Replaces #add / #share / #protocol in the address bar (tokens must not linger) with #plan: deep
	 * links open step 2 (CHANGE-1.1.0 §9.1) of "Make your own protocol" (CHANGE-1.7.1 §2.8).
	 */
	function clearHash() {
		setView( 'own' );
		steps.select( 1, { replace: true } );
	}

	/** Shows the not-found message of a saved protocol (the one My protocols uses). */
	function showProtocolNotFound() {
		toaster.show( planErrorMessage( { code: 'arp_not_found' } ), { tone: 'error', timeout: 0 } );
	}

	/**
	 * Opens a protocol saved in the customer's account from #protocol=<uuid> (CHANGE-1.2.0 §8: the
	 * account area's "Open in Protocol Builder") exactly as My protocols → Open does: the same
	 * request, the same confirmation before a workspace with items is replaced, and a copy on this
	 * device while saving to the account is turned off. Logged out, a malformed ID or a protocol that
	 * is not found (unknown or another customer's) shows the not-found message.
	 *
	 * @param {string} value #protocol= value.
	 */
	async function openAccountProtocol( value ) {
		await sessionSettled;
		const uuid = protocolId( value );
		if ( ! uuid || ! loggedIn ) {
			showProtocolNotFound();
			return;
		}
		if ( shared ) {
			closeShared();
		}
		const current = meta.kind === 'account' && meta.uuid === uuid && ! meta.dirty;
		if ( store.getState().lines.length > 0 && ! current ) {
			const ok = await confirmDialog( {
				title: __( 'Replace the current workspace?' ),
				message: __( 'The protocol you are working on will be replaced. Save it first if you want to keep it.' ),
				confirmLabel: __( 'Replace' ),
			} );
			if ( ! ok ) {
				return;
			}
		}
		let record;
		try {
			record = normalizeAccountPlan( await api.getPlan( uuid ) );
		} catch ( e ) {
			if ( isMissingProtocol( e ) ) {
				showProtocolNotFound();
			} else {
				toaster.show( e && e.code ? planErrorMessage( e ) : ( e && e.message ) || __( 'The protocol could not be opened.' ), { tone: 'error', timeout: 0 } );
			}
			return;
		}
		if ( ! record || ! record.plan ) {
			toaster.show( __( 'The protocol could not be opened.' ), { tone: 'error', timeout: 0 } );
			return;
		}
		// While saving to the account is turned off, the protocol opens as a copy on this device.
		const accountMeta = features.account_plans ? { kind: 'account', uuid: record.uuid, updated_at: record.updated_at, title: record.title } : { kind: 'local' };
		loadPlan( { ...record.plan, title: record.title || record.plan.title }, accountMeta );
	}

	/**
	 * Handles #add / #share / #protocol and, after them, the store protocol links (CHANGE-1.7.0 §6.8).
	 *
	 * @param {Object} hash Parsed hash.
	 * @return {Promise<boolean>} Handled.
	 */
	async function handleHash( hash ) {
		if ( hash.share ) {
			clearHash();
			await openShared( hash.share );
			return true;
		}
		if ( hash.add ) {
			clearHash();
			if ( /^[1-9]\d{0,15}$/.test( hash.add ) ) {
				await addProduct( Number( hash.add ), { focus: true } );
			}
			return true;
		}
		if ( typeof hash.protocol === 'string' ) {
			clearHash();
			await openAccountProtocol( hash.protocol );
			return true;
		}
		if ( hash.store ) {
			await openStoreLink( hash.store );
			return true;
		}
		return false;
	}

	/* ================================================================ Boot. */

	/** Boots (or retries booting) the app. */
	async function boot() {
		if ( ! booted ) {
			booted = true;
			enhanceHero( scope );
			restoreWorkspace();
			window.addEventListener( 'hashchange', () => {
				const hash = parseHash();
				if ( isDeepLink( hash ) ) {
					handleHash( hash );
					return;
				}
				steps.sync();
				// #plan is step 2 of "Make your own protocol".
				if ( stepFromHash( window.location.hash ) === 1 ) {
					setView( 'own' );
				}
			} );
			// Back / forward between the steps (#plan is pushed by the tabs) and the views: an entry shows
			// the view it recorded (never stored or announced; CHANGE-1.7.1 §2.10).
			window.addEventListener( 'popstate', () => {
				if ( ! isDeepLink( parseHash() ) ) {
					steps.sync();
					const stamped = normalizeEntryView( window.history.state && window.history.state.arp_view );
					setView( stepFromHash( window.location.hash ) === 1 ? 'own' : ( ( entryShown() && stamped ) || view ) );
				}
			} );
			if ( stepFromHash( window.location.hash ) === 1 ) {
				steps.select( 1 );
			}
			// A #share= link opens the shared protocol read-only once the session answered: no choice
			// meanwhile, so the row does not appear and disappear (§2.4: no buttons while shared).
			sharePending = !! parseHash().share;
			// Start view (CHANGE-1.7.1 §2.6), before the first paint: deep links and #plan first, then
			// preselected products, the visitor's last choice and whether the workspace is untouched.
			const preselected = config.preselect && Array.isArray( config.preselect.products ) ? config.preselect.products.filter( ( id ) => Number.isSafeInteger( id ) && id > 0 ).length : 0;
			view = startView( {
				available,
				deep: parseHash(),
				step: stepFromHash( window.location.hash ),
				preselect: preselected,
				hasLines: store.getState().lines.length > 0,
				untouched: isUntouchedWorkspace( planDocument( store.getState() ), { kind: meta.kind, auto_start: autoStart } ),
				remembered: normalizeEntryView( drafts.pref( ENTRY_VIEW_PREF, null ) ),
			} );
			setInterval( () => {
				if ( calc.calculatedLocal > 0 && ! stale && Date.now() - calc.calculatedLocal > stalePriceMs ) {
					stale = true;
					scheduleRender();
				}
			}, 30000 );
		}
		bootError = '';
		renderNow();
		viewportGuard.update();
		let session;
		try {
			session = await api.session( true );
		} catch ( e ) {
			bootError = e.message;
			settleSession();
			renderNow();
			return;
		}
		features = { ...features, ...( session.features && typeof session.features === 'object' ? session.features : {} ) };
		loggedIn = !! ( session.user && session.user.logged_in );
		canPublish = !! ( session.store_protocols && typeof session.store_protocols === 'object' && session.store_protocols.can_publish === true );
		if ( session.limits && typeof session.limits === 'object' ) {
			limits = effectiveLimits( session.limits );
		}
		if ( session.urls && typeof session.urls === 'object' ) {
			for ( const [ key, value ] of Object.entries( session.urls ) ) {
				if ( typeof value === 'string' && value !== '' ) {
					urls[ key ] = value;
				}
			}
		}
		if ( session.currency && typeof session.currency === 'object' ) {
			currency = normalizeCurrency( { ...( config.currency || {} ), ...session.currency } );
			picker.setCurrency( currency );
			combos.setCurrency( currency );
			storeProtocols.setCurrency( currency );
		}
		if ( typeof session.today === 'string' && dateError( session.today ) === null ) {
			siteToday = session.today;
			// A new protocol starts today in the store's time zone (the browser's guess may differ).
			if ( autoStart && ! shared && store.getState().start_date !== siteToday ) {
				setStartDate( siteToday );
				autoStart = true;
			}
		}
		settleSession();
		picker.load();
		combos.load();
		// After the session settled: the REST nonce is sent, so signed-in visitors get the
		// members-only store protocols too.
		storeProtocols.load();
		storeProtocolsRequested = true;
		ensureProducts();
		refreshPreviews();
		calcDebounced();
		// The fragment changed while the session loaded: a #share= link no longer waits (openShared()
		// ends the wait itself when it handles one).
		if ( sharePending && ! parseHash().share ) {
			sharePending = false;
			applyView();
		}
		const handled = await handleHash( parseHash() );
		const preselect = config.preselect && Array.isArray( config.preselect.products ) ? config.preselect.products : [];
		if ( ! handled && store.getState().lines.length === 0 && preselect.length > 0 ) {
			for ( const id of preselect.slice( 0, maxLines ) ) {
				if ( Number.isSafeInteger( id ) && id > 0 ) {
					// eslint-disable-next-line no-await-in-loop
					await addProduct( id );
				}
			}
		}
		renderNow();
	}

	return {
		boot,
		addProduct: ( id ) => addProduct( id, { focus: true } ),
	};
}
