/**
 * "Your basket" at the end of step 2 (CHANGE-1.1.0 §9.6, replacing the desktop sticky sidebar):
 * price note, a table Item / Qty / Price with the estimated total, and the button row "Add all to
 * cart →", "Save to my account", "Add reminders to calendar", "Copy protocol link", the Export menu
 * and the optional WhatsApp handoff. Cart progress, errors and the WooCommerce totals after adding
 * are shown below the buttons. On phones a compact bar fixed to the bottom of the viewport shows
 * the total and "Review & add to cart", which opens the basket.
 *
 * "Add all to cart" is never natively disabled: while it cannot be used it carries
 * aria-disabled="true" (plus a description), so the button keeps keyboard focus while the cart is
 * checked and a dialog opened from it can return focus to it.
 *
 * @module components/summary
 */

import { h, uid, icon, button, render } from '../app/dom.js';
import { __, _n, _x, sprintf } from '../app/i18n.js';
import { money, formatNumber } from '../app/format.js';
import { infoTip } from './tooltip.js';

/**
 * Creates the basket and the phone bar.
 *
 * @param {Object}      handlers         { onAddAll, onRetryCart, onSkipErrors, onRefresh, onFocusLine, onSave, onCalendar, onShare, onReview, onLayout }.
 * @param {HTMLElement} exportsEl        Export menu element.
 * @return {{el: HTMLElement, bar: HTMLElement, update: Function, focusResult: Function, returnTarget: Function, fixedArea: Function, focusHeading: Function}} Basket.
 */
export function createSummary( handlers, exportsEl = null ) {
	const titleId = uid( 'sum-title' );
	const barText = h( 'span', { class: 'arp-summary__bar-text' } );
	const barAlertText = h( 'span', null );
	const barAlert = h( 'span', { class: 'arp-summary__bar-alert', hidden: true }, icon( 'alert' ), barAlertText );
	const barButton = h(
		'button',
		{ type: 'button', class: 'arp-summary__toggle', onClick: () => handlers.onReview() },
		h( 'span', { class: 'arp-summary__bar-info' }, barText, barAlert ),
		h( 'span', { class: 'arp-summary__toggle-label' }, __( 'Review & add to cart' ) ),
		icon( 'down', 'arp-summary__chevron' )
	);
	const bar = h( 'div', { class: 'arp-summary__bar', hidden: true }, barButton );

	const table = h( 'div', { class: 'arp-basket__table-wrap' } );
	const notices = h( 'div', { class: 'arp-summary__notices' } );
	const addButton = button( {
		label: __( 'Add all to cart' ),
		iconName: 'cart',
		variant: 'primary',
		cls: 'arp-summary__add',
		onClick: () => {
			if ( addButton.getAttribute( 'aria-disabled' ) !== 'true' ) {
				handlers.onAddAll();
			}
		},
	} );
	addButton.querySelector( '.arp-btn__label' ).appendChild( h( 'span', { 'aria-hidden': 'true' }, ' →' ) );
	const addHelp = h( 'p', { class: 'arp-field__help arp-summary__add-help', id: uid( 'add-help' ) } );
	addButton.setAttribute( 'aria-describedby', addHelp.id );
	const saveButton = button( { label: __( 'Save to my account' ), iconName: 'folder', attrs: { 'aria-haspopup': 'dialog' }, onClick: () => handlers.onSave() } );
	const calendarHelp = h( 'p', { class: 'arp-field__help', id: uid( 'cal-help' ), hidden: true } );
	const calendarButton = button( {
		label: __( 'Add reminders to calendar' ),
		iconName: 'calendar',
		attrs: { 'aria-describedby': calendarHelp.id },
		onClick: () => {
			if ( calendarButton.getAttribute( 'aria-disabled' ) !== 'true' ) {
				handlers.onCalendar();
			}
		},
	} );
	const shareButton = button( { label: __( 'Copy protocol link' ), iconName: 'link', attrs: { 'aria-haspopup': 'dialog' }, onClick: () => handlers.onShare() } );
	const cartArea = h( 'div', { class: 'arp-summary__cart', tabindex: '-1' } );
	const whatsapp = h( 'div', { class: 'arp-summary__whatsapp' } );
	const priceNote = h( 'p', { class: 'arp-summary__note' }, __( 'Estimates use current store prices and exclude shipping, taxes and discounts. WooCommerce calculates the final total in your cart and at checkout.' ) );
	const heading = h( 'h2', { class: 'arp-section-head__title', id: titleId, tabindex: '-1' }, __( 'Your basket' ) );

	const el = h(
		'section',
		{ class: 'arp-card arp-summary arp-basket', 'aria-labelledby': titleId },
		h( 'div', { class: 'arp-section-head' }, heading ),
		priceNote,
		notices,
		table,
		h( 'div', { class: 'arp-basket__actions' }, addButton, saveButton, calendarButton, shareButton, exportsEl ),
		addHelp,
		calendarHelp,
		cartArea,
		whatsapp
	);

	const isPhone = () => !! ( window.matchMedia && ! window.matchMedia( '(min-width: 1024px)' ).matches );

	const cartContent = ( cart, view ) => {
		if ( ! cart || cart.phase === 'idle' ) {
			return [];
		}
		if ( cart.phase === 'checking' || cart.phase === 'adding' ) {
			return [
				h(
					'div',
					{ class: 'arp-progress', role: 'status' },
					h( 'span', { class: 'arp-spinner', 'aria-hidden': 'true' } ),
					cart.phase === 'checking' ? __( 'Checking your cart…' ) : __( 'Adding to your cart…' )
				),
			];
		}
		if ( cart.phase === 'error' ) {
			return [
				h(
					'div',
					{ class: 'arp-notice arp-notice--error', role: 'alert' },
					h( 'p', { class: 'arp-notice__title' }, cart.title || __( 'Nothing was added to your cart' ) ),
					cart.message ? h( 'p', null, cart.message ) : null,
					cart.lines && cart.lines.length > 0
						? h(
							'ul',
							null,
							cart.lines.map( ( line ) =>
								h( 'li', null, h( 'button', { type: 'button', class: 'arp-linkish', onClick: () => handlers.onFocusLine( line.id ) }, line.name ), ': ', line.messages.join( ' ' ) )
							)
						)
						: null,
					h(
						'div',
						{ class: 'arp-notice__actions' },
						cart.canRetry ? button( { label: __( 'Try again' ), iconName: 'refresh', size: 'sm', onClick: () => handlers.onRetryCart() } ) : null,
						cart.canSkipErrors ? button( { label: cart.skipLabel, size: 'sm', onClick: () => handlers.onSkipErrors() } ) : null
					)
				),
			];
		}
		if ( cart.phase === 'done' ) {
			const summary = cart.cart || {};
			const rows = [];
			const add = ( label, value ) => {
				if ( typeof value === 'string' && value !== '' ) {
					rows.push( h( 'dt', null, label ), h( 'dd', null, value ) );
				}
			};
			add( __( 'Cart subtotal' ), summary.subtotal );
			if ( typeof summary.discount === 'string' && /[1-9]/.test( summary.discount ) ) {
				add( __( 'Discounts' ), summary.discount );
			}
			add( __( 'Cart total' ), summary.total );
			const coupons = Array.isArray( summary.coupons ) ? summary.coupons.map( ( c ) => ( typeof c === 'string' ? c : c && ( c.code || c.label ) ) ).filter( Boolean ) : [];
			return [
				h(
					'div',
					{ class: 'arp-success', role: 'status' },
					h( 'p', { class: 'arp-success__title' }, icon( 'check' ), cart.title ),
					cart.details && cart.details.length > 0 ? h( 'ul', { class: 'arp-success__list' }, cart.details.map( ( d ) => h( 'li', null, d ) ) ) : null,
					rows.length > 0 ? h( 'dl', { class: 'arp-success__totals' }, rows ) : null,
					coupons.length > 0 ? h( 'p', { class: 'arp-success__coupons' }, sprintf( /* translators: %s: coupon codes. */ __( 'Coupons applied: %s' ), coupons.join( ', ' ) ) ) : null,
					h( 'p', { class: 'arp-success__note' }, typeof summary.totals_note === 'string' && summary.totals_note !== '' ? summary.totals_note : __( 'These totals come from your WooCommerce cart and are authoritative. Shipping and taxes are calculated at checkout.' ) ),
					h(
						'div',
						{ class: 'arp-success__actions' },
						h( 'a', { class: 'arp-btn arp-btn--secondary', href: summary.cart_url || view.urls.cart }, __( 'View cart' ) ),
						h( 'a', { class: 'arp-btn arp-btn--primary', href: summary.checkout_url || view.urls.checkout }, __( 'Checkout' ) )
					)
				),
			];
		}
		return [];
	};

	/**
	 * Basket table.
	 *
	 * @param {Object} view View.
	 * @return {Array<HTMLElement>} Nodes.
	 */
	const tableContent = ( view ) => {
		if ( view.items.length === 0 ) {
			return [ h( 'p', { class: 'arp-summary__empty' }, __( 'Your protocol is empty. Add products to see the quantities to buy.' ) ) ];
		}
		const rows = view.items.map( ( item ) => {
			let qty = '—';
			let price = '—';
			if ( item.status === 'ok' ) {
				qty = formatNumber( String( item.quantity ), view.currency );
				price = item.estimate !== null ? money( item.estimate, view.currency ) : __( 'No price' );
			} else if ( item.status === 'blocked' ) {
				price = __( 'Needs verification' );
			} else {
				price = __( 'Needs input' );
			}
			return h(
				'tr',
				{ class: item.status !== 'ok' ? 'is-pending' : '' },
				h(
					'th',
					{ scope: 'row' },
					h( 'button', { type: 'button', class: 'arp-linkish', onClick: () => handlers.onFocusLine( item.id ) }, item.name ),
					/* translators: %s: chosen variant (e.g. strength or pen format), shown after a product name. */
					item.variant ? h( 'span', { class: 'arp-summary__variant' }, ' ' + sprintf( _x( '(%s)', 'variant after a product name' ), item.variant ) ) : null
				),
				h( 'td', { class: 'arp-basket__qty' }, qty ),
				view.showPrices ? h( 'td', { class: 'arp-basket__price' }, price ) : null
			);
		} );
		return [
			h(
				'table',
				{ class: 'arp-table arp-basket__table' },
				h( 'caption', { class: 'arp-sr-only' }, __( 'Products in your protocol' ) ),
				h(
					'thead',
					null,
					h(
						'tr',
						null,
						h( 'th', { scope: 'col' }, __( 'Item' ) ),
						h( 'th', { scope: 'col', class: 'arp-basket__qty' }, __( 'Qty' ) ),
						view.showPrices ? h( 'th', { scope: 'col', class: 'arp-basket__price' }, __( 'Price' ) ) : null
					)
				),
				h( 'tbody', null, rows ),
				view.showPrices
					? h(
						'tfoot',
						null,
						h(
							'tr',
							null,
							h( 'th', { scope: 'row', colspan: '2' }, __( 'Estimated total' ), view.pending ? h( 'span', { class: 'arp-summary__updating' }, ' ' + __( 'Updating…' ) ) : null ),
							h( 'td', { class: 'arp-basket__price' }, h( 'strong', null, view.subtotal ? money( view.subtotal, view.currency ) : '—' ) )
						)
					)
					: null
			),
		];
	};

	const signatures = new Map();
	/**
	 * Re-renders a region only when its inputs changed (keeps focus inside stable regions).
	 *
	 * @param {HTMLElement} region Region.
	 * @param {Array}       inputs Values the content depends on (compared by identity / JSON).
	 * @param {Function}    build  () => nodes.
	 */
	const patch = ( region, inputs, build ) => {
		const signature = inputs.map( ( v ) => ( v && typeof v === 'object' ? v : JSON.stringify( v ) ) );
		const previous = signatures.get( region );
		if ( previous && previous.length === signature.length && previous.every( ( v, i ) => v === signature[ i ] ) ) {
			return;
		}
		signatures.set( region, signature );
		const keepFocus = region.contains( document.activeElement ) ? document.activeElement.textContent : null;
		render( region, ...build() );
		if ( keepFocus !== null ) {
			// A re-render replaced the focused row button: focus the row button with the same text.
			const again = Array.from( region.querySelectorAll( 'button' ) ).find( ( b ) => b.textContent === keepFocus );
			if ( again ) {
				again.focus();
			}
		}
	};

	return {
		el,
		bar,
		/**
		 * Updates the basket.
		 *
		 * @param {Object} view View model.
		 */
		update( view ) {
			const ready = view.items.filter( ( item ) => item.status === 'ok' && item.quantity > 0 );
			const units = ready.reduce( ( sum, item ) => sum + item.quantity, 0 );
			const counts =
				/* translators: %s: number of purchase units. */
				sprintf( _n( '%s unit', '%s units', units ), formatNumber( String( units ), view.currency ) ) +
				' · ' +
				/* translators: %s: number of protocol items. */
				sprintf( _n( '%s item', '%s items', view.items.length ), formatNumber( String( view.items.length ), view.currency ) );
			const barValue = view.showPrices && view.subtotal ? counts + ' · ' + money( view.subtotal, view.currency ) : counts;
			if ( barText.textContent !== barValue ) {
				barText.textContent = barValue;
			}
			let alertText = '';
			if ( view.calcError ) {
				alertText = __( 'Not confirmed by the store yet' );
			} else if ( view.stale && view.showPrices ) {
				alertText = __( 'Prices may have changed' );
			}
			barAlertText.textContent = alertText;
			barAlert.hidden = alertText === '';
			bar.hidden = ! view.sticky || view.readOnly || view.items.length === 0;

			patch( notices, [ view.stale, view.calcError ], () => [
				view.stale
					? h(
						'div',
						{ class: 'arp-notice arp-notice--warning' },
						h( 'p', null, __( 'Prices may have changed since they were last checked.' ) ),
						button( { label: __( 'Refresh prices' ), iconName: 'refresh', size: 'sm', onClick: () => handlers.onRefresh() } )
					)
					: null,
				view.calcError
					? h(
						'div',
						{ class: 'arp-notice arp-notice--warning' },
						h( 'p', null, view.calcError ),
						button( { label: __( 'Try again' ), iconName: 'refresh', size: 'sm', onClick: () => handlers.onRefresh() } )
					)
					: null,
			] );

			patch( table, [ JSON.stringify( view.items ), view.showPrices, view.currency, view.subtotal, view.pending ], () => tableContent( view ) );
			priceNote.hidden = ! view.showPrices;

			const busy = view.cart && ( view.cart.phase === 'checking' || view.cart.phase === 'adding' );
			// aria-disabled, never `disabled`: disabling the focused button would drop focus to <body>.
			addButton.disabled = false;
			addButton.setAttribute( 'aria-disabled', ready.length === 0 || busy || view.readOnly ? 'true' : 'false' );
			addButton.setAttribute( 'aria-busy', busy ? 'true' : 'false' );
			addButton.hidden = !! view.readOnly;
			saveButton.hidden = !! view.readOnly;
			shareButton.hidden = ! view.showShare || !! view.readOnly;
			calendarButton.hidden = ! view.exports || !! view.readOnly;
			calendarButton.setAttribute( 'aria-disabled', view.items.length === 0 || ! view.hasStartDate ? 'true' : 'false' );
			let calendarText = '';
			if ( ! calendarButton.hidden && view.items.length > 0 && ! view.hasStartDate ) {
				calendarText = __( 'Add a protocol start date to export review dates.' );
			}
			if ( calendarHelp.textContent !== calendarText ) {
				calendarHelp.textContent = calendarText;
			}
			calendarHelp.hidden = calendarText === '';
			let help = '';
			if ( view.readOnly ) {
				help = __( 'Copy this shared protocol into your workspace to add it to your cart.' );
			} else if ( view.items.length === 0 ) {
				help = __( 'Add products to your protocol first.' );
			} else if ( ready.length === 0 ) {
				help = __( 'Enter your amounts to calculate the units to buy.' );
			} else if ( view.calcError ) {
				help = __( 'The store has not confirmed these quantities yet. Adding to the cart first asks the store to calculate them again; nothing is added until it does.' );
			} else if ( ready.length < view.items.length ) {
				/* translators: %d: number of items without a result. */
				help = sprintf( _n( '%d item without a result will not be added.', '%d items without a result will not be added.', view.items.length - ready.length ), view.items.length - ready.length );
			}
			if ( addHelp.textContent !== help ) {
				addHelp.textContent = help;
			}
			addHelp.hidden = help === '';

			patch( cartArea, [ view.cart ], () => cartContent( view.cart, view ) );

			if ( view.whatsapp && view.whatsapp.enabled && ! view.readOnly ) {
				patch( whatsapp, [ view.whatsapp.url, ready.length ], () => [
					h(
						'div',
						{ class: 'arp-summary__wa' },
						h(
							'a',
							{
								class: [ 'arp-btn', 'arp-btn--secondary', ready.length === 0 ? 'is-disabled' : '' ],
								href: ready.length === 0 ? null : view.whatsapp.url,
								target: '_blank',
								rel: 'noopener noreferrer',
								'aria-disabled': ready.length === 0 ? 'true' : null,
								onClick: ( event ) => {
									if ( ready.length === 0 ) {
										event.preventDefault();
									}
								},
							},
							icon( 'chat' ),
							h( 'span', null, __( 'Ask about these items on WhatsApp' ) )
						),
						infoTip(
							__( 'Opens WhatsApp with product names and quantities only. Your research inputs are never included.' ),
							__( 'What is sent to WhatsApp?' )
						)
					),
				] );
			} else {
				patch( whatsapp, [ 'off' ], () => [] );
			}
		},
		/** Focuses the cart result area (after adding). */
		focusResult() {
			cartArea.focus( { preventScroll: false } );
		},
		/** Focuses the basket heading (the phone bar's "Review & add to cart"). */
		focusHeading() {
			heading.focus( { preventScroll: false } );
		},
		/**
		 * Where focus returns after a dialog opened by the cart flow: the add button when it is
		 * shown, else the cart status area.
		 *
		 * @return {HTMLElement} Element.
		 */
		returnTarget() {
			return ! addButton.hidden && addButton.isConnected ? addButton : cartArea;
		},
		/**
		 * The part fixed at the bottom of the viewport on phones (the bar); null on wide screens.
		 *
		 * @return {HTMLElement|null} Element.
		 */
		fixedArea() {
			return isPhone() && ! bar.hidden ? bar : null;
		},
	};
}
