/**
 * Observable workspace state with pure reducers (undo for line removal).
 *
 * The workspace holds only what the user typed or chose (protocol title, start date, notes and
 * the canonical LineInput-shaped lines). Calculation results, product data and session data live
 * in the app controller, never here, so drafts and plan files stay small and private.
 *
 * @module store
 */

/** Maximum plan title length (PlanSerializer::MAX_TITLE_LENGTH: the server refuses longer titles). */
export const MAX_TITLE_LENGTH = 120;

/** Maximum notes length (PlanSerializer::MAX_NOTES_LENGTH). */
export const MAX_NOTES_LENGTH = 1000;

/** Number of removed lines kept for undo (each one is offered until it is restored or dismissed). */
export const MAX_REMOVED = 5;

/**
 * Minimal observable store.
 *
 * @param {Function} reducer      ( state, action ) => state.
 * @param {*}        initialState Initial state.
 * @return {{getState: Function, dispatch: Function, subscribe: Function}} Store.
 */
export function createStore( reducer, initialState ) {
	let state = initialState;
	const listeners = new Set();
	return {
		getState: () => state,
		dispatch( action ) {
			const next = reducer( state, action );
			if ( next !== state ) {
				const previous = state;
				state = next;
				listeners.forEach( ( listener ) => listener( state, previous, action ) );
			}
			return action;
		},
		subscribe( listener ) {
			listeners.add( listener );
			return () => listeners.delete( listener );
		},
	};
}

/**
 * Empty workspace.
 *
 * @param {string} title Default title.
 * @return {Object} Workspace.
 */
export function initialWorkspace( title = '' ) {
	return { title: cleanText( title, MAX_TITLE_LENGTH ), start_date: null, notes: '', lines: [], removed: [], revision: 0 };
}

/**
 * Removed-line entries shifted after `lines` changed at position `at`: entries placed after that
 * position move by `delta` (+1 when a line was inserted, -1 when one was removed). An entry's
 * `index` is the number of current lines in front of it, so it is shown where the line was.
 *
 * @param {Array<{line: Object, index: number}>} removed Entries.
 * @param {number}                               at      Position of the change.
 * @param {number}                               delta   +1 or -1.
 * @return {Array<{line: Object, index: number}>} Entries.
 */
function shiftRemoved( removed, at, delta ) {
	return removed.map( ( entry ) => ( entry.index > at ? { ...entry, index: Math.max( 0, entry.index + delta ) } : entry ) );
}

/**
 * Plain single-line text without control characters.
 *
 * @param {*}      value Value.
 * @param {number} max   Maximum length.
 * @return {string} Text.
 */
export function cleanText( value, max ) {
	return String( value === null || value === undefined ? '' : value ).replace( /[\u0000-\u001F\u007F]/g, ' ' ).slice( 0, max );
}

/**
 * Deep copy of a line (plain JSON data).
 *
 * @param {Object} line Line.
 * @return {Object} Copy.
 */
function copyLine( line ) {
	return { ...line, variation_attributes: { ...( line.variation_attributes || {} ) } };
}

/**
 * Next state with an incremented revision.
 *
 * @param {Object} state   State.
 * @param {Object} changes Changes.
 * @return {Object} State.
 */
function bump( state, changes ) {
	return { ...state, ...changes, revision: state.revision + 1 };
}

/**
 * Workspace reducer.
 *
 * Actions:
 *  - workspace/load { plan }           replace everything (title, start_date, notes, lines)
 *  - workspace/reset { title, start_date } empty protocol (start_date: Y-m-d or null)
 *  - workspace/title { title }
 *  - workspace/start { start_date, lines? } Y-m-d or null; optional lines with their start dates
 *                                      moved along (Start week, see weeks.js shiftLineStarts())
 *  - workspace/notes { notes }
 *  - line/add { line, max }            ignored when the plan already has `max` lines
 *  - line/update { id, changes }
 *  - line/remove { id }                remembers the line (up to MAX_REMOVED) for line/restore
 *  - line/restore { id, max }          undo the removal of that exact line, at its old position
 *  - line/duplicate { id, newId, max }
 *  - line/move { id, delta }           -1 = up, +1 = down
 *  - line/forget-removed { id? }       drops the undo information of one line (or of all)
 *
 * @param {Object} state  State.
 * @param {Object} action Action.
 * @return {Object} New state (same object when nothing changed).
 */
export function workspaceReducer( state, action ) {
	const lines = state.lines;
	const index = ( id ) => lines.findIndex( ( line ) => line.id === id );

	switch ( action.type ) {
		case 'workspace/load': {
			const plan = action.plan || {};
			return bump( state, {
				title: cleanText( plan.title, MAX_TITLE_LENGTH ),
				start_date: typeof plan.start_date === 'string' && plan.start_date !== '' ? plan.start_date : null,
				notes: cleanText( plan.notes, MAX_NOTES_LENGTH ),
				lines: Array.isArray( plan.lines ) ? plan.lines.map( copyLine ) : [],
				removed: [],
			} );
		}
		case 'workspace/reset': {
			const start = typeof action.start_date === 'string' && action.start_date !== '' ? action.start_date : null;
			return bump( state, { ...initialWorkspace( action.title ), start_date: start, revision: state.revision } );
		}
		case 'workspace/title': {
			const title = cleanText( action.title, MAX_TITLE_LENGTH );
			return title === state.title ? state : bump( state, { title } );
		}
		case 'workspace/start': {
			const start = typeof action.start_date === 'string' && action.start_date !== '' ? action.start_date : null;
			if ( start === state.start_date ) {
				return state;
			}
			return bump( state, Array.isArray( action.lines ) ? { start_date: start, lines: action.lines.map( copyLine ) } : { start_date: start } );
		}
		case 'workspace/notes': {
			const notes = cleanText( action.notes, MAX_NOTES_LENGTH );
			return notes === state.notes ? state : bump( state, { notes } );
		}
		case 'line/add':
			if ( ! action.line || lines.length >= ( action.max ?? Infinity ) || index( action.line.id ) >= 0 ) {
				return state;
			}
			return bump( state, { lines: [ ...lines, copyLine( action.line ) ] } );
		case 'line/update': {
			const i = index( action.id );
			if ( i < 0 ) {
				return state;
			}
			const current = lines[ i ];
			const changes = action.changes || {};
			const changed = Object.keys( changes ).some( ( key ) => JSON.stringify( current[ key ] ) !== JSON.stringify( changes[ key ] ) );
			if ( ! changed ) {
				return state;
			}
			const next = lines.slice();
			next[ i ] = { ...current, ...changes, id: current.id };
			return bump( state, { lines: next } );
		}
		case 'line/remove': {
			const i = index( action.id );
			if ( i < 0 ) {
				return state;
			}
			const removed = [ ...shiftRemoved( state.removed || [], i, -1 ).filter( ( entry ) => entry.line.id !== action.id ), { line: lines[ i ], index: i } ];
			return bump( state, { lines: lines.filter( ( line ) => line.id !== action.id ), removed: removed.slice( -MAX_REMOVED ) } );
		}
		case 'line/restore': {
			const list = state.removed || [];
			const k = list.findIndex( ( entry ) => entry.line.id === action.id );
			if ( k < 0 || lines.length >= ( action.max ?? Infinity ) || index( action.id ) >= 0 ) {
				return state;
			}
			const entry = list[ k ];
			const at = Math.min( entry.index, lines.length );
			const next = lines.slice();
			next.splice( at, 0, entry.line );
			// Entries shown after the restored line move one position down; entries at the same
			// position that were removed earlier stay in front of it.
			const removed = list
				.filter( ( _, j ) => j !== k )
				.map( ( other ) => ( other.index > at || ( other.index === at && list.indexOf( other ) > k ) ? { ...other, index: other.index + 1 } : other ) );
			return bump( state, { lines: next, removed } );
		}
		case 'line/forget-removed': {
			const list = state.removed || [];
			const removed = action.id ? list.filter( ( entry ) => entry.line.id !== action.id ) : [];
			return removed.length === list.length ? state : { ...state, removed };
		}
		case 'line/duplicate': {
			const i = index( action.id );
			if ( i < 0 || ! action.newId || lines.length >= ( action.max ?? Infinity ) || index( action.newId ) >= 0 ) {
				return state;
			}
			const next = lines.slice();
			next.splice( i + 1, 0, { ...copyLine( lines[ i ] ), id: action.newId } );
			return bump( state, { lines: next, removed: shiftRemoved( state.removed || [], i, 1 ) } );
		}
		case 'line/move': {
			const i = index( action.id );
			const j = i + ( action.delta < 0 ? -1 : 1 );
			if ( i < 0 || j < 0 || j >= lines.length ) {
				return state;
			}
			const next = lines.slice();
			[ next[ i ], next[ j ] ] = [ next[ j ], next[ i ] ];
			return bump( state, { lines: next } );
		}
		default:
			return state;
	}
}
