/**
 * Product block of step 2 ("Plan & quantities"): one product of the protocol with plain labels
 * (CHANGE-1.1.0 §2, §9.3).
 *
 * - Weekly items: Vial size (variant selects) · Amount per use [unit] · Times per week (+ quick
 *   choices) · Duration (weeks) (+ quick choices) · Start week. The amount always starts EMPTY.
 * - Quantity-only items (supplies, bundles, add-ons): the variant selects and a Quantity stepper.
 * - Result strip: total required, how long each container lasts, run-out, and the highlighted
 *   purchase cell with the quantity stepper ("calculated" / "changed"), the price per week of
 *   supply and the "+1 spare" box. One "How it works" link opens the formula dialog.
 * - Lines saved with older settings show a notice; the first edit converts them (app.js).
 * - Lines copied from a store protocol show "From a pre-built protocol" in the header until the
 *   customer edits them (view.storeTag, CHANGE-1.7.0 §6.7, CHANGE-1.7.1 §3).
 *
 * Inputs are created once and patched on update (focus and caret are never lost while typing);
 * text that cannot be parsed stays in the input with an inline error linked via aria-describedby.
 *
 * @module components/line-card
 */

import { h, uid, icon, button, render } from '../app/dom.js';
import { __, _n, sprintf } from '../app/i18n.js';
import { parseDecimalInput, parseIntegerInput, toInputText, money, formatNumber, formatDate } from '../app/format.js';
import { DEFAULT_LIMITS } from '../app/engine.js';
import { validationText, calculationText, readinessText, noticeText } from '../app/messages.js';
import { sizeLabel, containerLabel, spareLabel, quantityHeadline, lastsCaption, perMgPrice, massCapacity, purchaseFormat, stepperLabels, containerNoun } from '../app/catalog.js';
import { TIMES_PER_WEEK_CHOICES, DURATION_CHOICES, MAX_START_WEEK, weekOfStart, startForWeek, containerLasts, runOut, supplyTo, coveredWeeks, perWeekPrice } from '../app/weeks.js';
import { spareChecked, stepperQuantity, quantityStatus, productFormat } from '../app/protocol.js';
import { createVariantPicker } from './variant-picker.js';
import { amountText, unitName, periodName } from './explain.js';

const VERIFY_CODES = [ 'needs_mapping', 'disabled', 'unverified', 'stale_mapping', 'invalid', 'no_capacity', 'invalid_pack_count' ];

/**
 * Old calculation-mode names (used to explain an adapted line saved with an older setting).
 *
 * @param {string} mode Mode.
 * @return {string} Label.
 */
export function modeLabel( mode ) {
	switch ( mode ) {
		case 'direct':
			return __( 'Total quantity' );
		case 'manual':
			return __( 'Quantity only' );
		default:
			return __( 'Weekly use' );
	}
}

/**
 * Label of a "times per week" quick choice.
 *
 * @param {number} n Times per week.
 * @return {string} Label.
 */
export function timesLabel( n ) {
	if ( n === 7 ) {
		return __( 'Daily' );
	}
	if ( n === 1 ) {
		return __( 'Weekly' );
	}
	/* translators: %s: number of times per week (quick choice button, e.g. "3×"). */
	return sprintf( __( '%s×' ), String( n ) );
}

/**
 * Old setting of a legacy line in words ("1 use per day for 30 days").
 *
 * @param {Object} line Line.
 * @return {string} Text ('' when nothing describes it).
 */
function legacySetting( line ) {
	if ( line.mode === 'direct' ) {
		return __( 'a total amount' );
	}
	if ( line.mode === 'manual' ) {
		return __( 'a quantity only' );
	}
	if ( line.events_per_period === null || line.periods === null ) {
		return '';
	}
	return sprintf(
		/* translators: 1: number of uses, 2: period (day, month), 3: number of periods, 4: period name (plural). */
		__( '%1$s per %2$s for %3$s %4$s' ),
		/* translators: %s: number of uses per period. */
		sprintf( _n( '%s use', '%s uses', line.events_per_period ), String( line.events_per_period ) ),
		periodName( line.period_unit, 1 ),
		String( line.periods ),
		periodName( line.period_unit, line.periods )
	);
}

/**
 * Short date ("20 Oct"; with the year when it is not the current year).
 *
 * @param {string} ymd    Y-m-d.
 * @param {string} locale Locale.
 * @return {string} Date.
 */
export function shortDate( ymd, locale ) {
	if ( typeof ymd !== 'string' || ymd === '' ) {
		return '';
	}
	const sameYear = ymd.slice( 0, 4 ) === String( new Date().getFullYear() );
	return formatDate( ymd, locale, sameYear ? { day: 'numeric', month: 'short' } : { day: 'numeric', month: 'short', year: 'numeric' } );
}

/**
 * Text read by screen readers instead of a visible abbreviation ("5.7 wks" → "5.7 weeks").
 *
 * @param {string} visible Visible text.
 * @param {string} spoken  Spoken text.
 * @return {Array<HTMLElement>} Nodes.
 */
function spokenAs( visible, spoken ) {
	return [ h( 'span', { 'aria-hidden': 'true' }, visible ), h( 'span', { class: 'arp-sr-only' }, spoken ) ];
}

/**
 * A labelled form field with help and error text.
 *
 * @param {Object} options { label, control, help, suffix, after, cls }.
 * @return {Object} Field { wrap, control, label, help, setError, hasError, setHelp }.
 */
function field( options ) {
	const id = options.control.id || uid( 'f' );
	options.control.id = id;
	const helpId = uid( 'help' );
	const errorId = uid( 'err' );
	const error = h( 'p', { id: errorId, class: 'arp-field__error', hidden: true } );
	const label = h( 'label', { class: 'arp-label', id: uid( 'label' ), for: id }, options.label );
	const helpEl = h( 'p', { id: helpId, class: 'arp-field__help', hidden: ! options.help }, options.help || '' );
	const describe = ( withError ) => {
		const ids = [ helpEl.hidden ? null : helpId, withError ? errorId : null ].filter( Boolean ).join( ' ' );
		if ( ids ) {
			options.control.setAttribute( 'aria-describedby', ids );
		} else {
			options.control.removeAttribute( 'aria-describedby' );
		}
	};
	describe( false );
	const control = options.suffix ? h( 'div', { class: 'arp-input-group' }, options.control, options.suffix ) : options.control;
	const wrap = h( 'div', { class: [ 'arp-field', options.cls ] }, label, control, options.after || null, helpEl, error );
	return {
		wrap,
		control: options.control,
		label,
		help: helpEl,
		/**
		 * Shows or clears the error (no DOM writes when nothing changed: it runs on every render).
		 *
		 * @param {string} message Message ('' clears).
		 */
		setError( message ) {
			const has = !! message;
			if ( has === ! error.hidden && error.textContent === ( message || '' ) ) {
				return;
			}
			error.textContent = message || '';
			error.hidden = ! has;
			if ( has ) {
				options.control.setAttribute( 'aria-invalid', 'true' );
			} else {
				options.control.removeAttribute( 'aria-invalid' );
			}
			describe( has );
		},
		/**
		 * Replaces the help text ('' hides it).
		 *
		 * @param {string} text Text.
		 */
		setHelp( text ) {
			if ( helpEl.textContent === text && helpEl.hidden === ( text === '' ) ) {
				return;
			}
			helpEl.textContent = text;
			helpEl.hidden = text === '';
			describe( ! error.hidden );
		},
		hasError: () => ! error.hidden,
	};
}

/**
 * Accessible name of a "Times per week" quick choice: one whole translatable string that contains
 * the visible label ("3× per week"); '' for Daily and Weekly, whose visible text is the full name.
 *
 * @param {number} n Times per week.
 * @return {string} Name.
 */
export function timesName( n ) {
	if ( n === 7 || n === 1 ) {
		return '';
	}
	/* translators: %s: number of times per week (quick choice button, e.g. "3" in "3× per week"). */
	return sprintf( __( '%s× per week' ), String( n ) );
}

/**
 * Accessible name of a "Duration (weeks)" quick choice ("8 weeks"), in the plural form of the count.
 *
 * @param {number} n Weeks.
 * @return {string} Name.
 */
export function weeksName( n ) {
	/* translators: %s: number of weeks. */
	return sprintf( _n( '%s week', '%s weeks', n ), String( n ) );
}

/**
 * A duration in the period unit of a result ("30 days", "8 weeks", "2 months").
 *
 * @param {string} period day | week | month.
 * @param {number} n      Number of periods.
 * @param {string} count  Formatted number.
 * @return {string} Text.
 */
export function durationText( period, n, count ) {
	switch ( period ) {
		case 'day':
			/* translators: %s: number of days. */
			return sprintf( _n( '%s day', '%s days', n ), count );
		case 'month':
			/* translators: %s: number of months. */
			return sprintf( _n( '%s month', '%s months', n ), count );
		default:
			/* translators: %s: number of weeks. */
			return sprintf( _n( '%s week', '%s weeks', n ), count );
	}
}

/**
 * Group of quick-choice buttons (aria-pressed) for a number field.
 *
 * @param {Object}   options          Options.
 * @param {number[]} options.values   Values.
 * @param {Function} options.label    ( value ) => visible label.
 * @param {Function} options.name     ( value ) => full accessible name containing the visible label
 *                                    ('' when the visible label is the full name).
 * @param {string}   options.groupBy  ID of the field label (names the group).
 * @param {Function} options.onPick   ( value ) => void.
 * @return {{el: HTMLElement, update: Function}} Quick choices.
 */
function quickChoices( { values, label, name, groupBy, onPick } ) {
	const buttons = values.map( ( value ) => {
		const full = name( value );
		return h(
			'button',
			{ type: 'button', class: 'arp-quick__btn', 'aria-pressed': 'false', 'aria-label': full || null, 'data-value': String( value ), onClick: () => onPick( value ) },
			label( value )
		);
	} );
	const el = h( 'div', { class: 'arp-quick', role: 'group', 'aria-labelledby': groupBy }, buttons );
	return {
		el,
		/**
		 * Marks the button of the current value as pressed.
		 *
		 * @param {number|null} current Current value.
		 * @param {boolean}     disabled Disabled.
		 */
		update( current, disabled ) {
			buttons.forEach( ( btn ) => {
				const pressed = btn.getAttribute( 'data-value' ) === String( current );
				if ( btn.getAttribute( 'aria-pressed' ) !== String( pressed ) ) {
					btn.setAttribute( 'aria-pressed', pressed ? 'true' : 'false' );
				}
				btn.disabled = !! disabled;
			} );
		},
	};
}

/**
 * Disables a stepper button without ever dropping keyboard focus: at a bound (or while the stepper
 * cannot be used) it is aria-disabled and ignores activation; it is natively disabled only while it
 * does not have focus and the stepper cannot be used at all (read-only, nothing calculated).
 *
 * @param {HTMLButtonElement} btn      Button.
 * @param {boolean}           unusable The stepper cannot be used.
 * @param {boolean}           atLimit  The value is at this button's bound.
 */
export function setStepperButton( btn, unusable, atLimit ) {
	const off = unusable || atLimit;
	if ( btn.getAttribute( 'aria-disabled' ) !== ( off ? 'true' : 'false' ) ) {
		btn.setAttribute( 'aria-disabled', off ? 'true' : 'false' );
	}
	btn.disabled = unusable && document.activeElement !== btn;
}

/**
 * Number stepper [ − n + ] with an editable value.
 *
 * The value shown follows the stored quantity, also while the input has focus (ArrowUp/ArrowDown,
 * − and + change it), except while the customer has typed text that is not applied yet (Enter or
 * leaving the field applies it) or the text is invalid.
 *
 * @param {Object}   options          Options.
 * @param {string}   options.cls      Extra class.
 * @param {Function} options.onStep   ( delta ) => void.
 * @param {Function} options.onInput  ( value|null ) => void (null = empty).
 * @return {Object} Stepper { el, input, label, status, minus, plus, error, isTyping }.
 */
function stepper( { cls, onStep, onInput } ) {
	const input = h( 'input', { class: 'arp-input arp-stepper__input', type: 'text', inputmode: 'numeric', autocomplete: 'off', id: uid( 'qty' ) } );
	const label = h( 'label', { class: 'arp-label', for: input.id } );
	// aria-disabled (never `disabled` on the focused button: that would drop focus to <body>).
	const press = ( btn, delta ) => () => {
		if ( btn.getAttribute( 'aria-disabled' ) !== 'true' ) {
			onStep( delta );
		}
	};
	const minus = h( 'button', { type: 'button', class: 'arp-stepper__btn', 'aria-controls': input.id, 'aria-disabled': 'false' }, icon( 'minus' ) );
	const plus = h( 'button', { type: 'button', class: 'arp-stepper__btn', 'aria-controls': input.id, 'aria-disabled': 'false' }, icon( 'plus' ) );
	minus.addEventListener( 'click', press( minus, -1 ) );
	plus.addEventListener( 'click', press( plus, 1 ) );
	const status = h( 'span', { class: 'arp-stepper__status', id: uid( 'qty-status' ) } );
	const error = h( 'p', { class: 'arp-field__error', id: uid( 'qty-err' ), hidden: true } );
	input.setAttribute( 'aria-describedby', status.id );
	// Text typed into the field that is not applied yet: renders never overwrite it.
	let typing = false;
	const apply = ( showError ) => {
		typing = false;
		const text = input.value.trim();
		if ( text === '' ) {
			error.hidden = true;
			input.removeAttribute( 'aria-invalid' );
			onInput( null );
			return;
		}
		const parsed = parseIntegerInput( text, { min: 0, max: DEFAULT_LIMITS.max_quantity } );
		if ( parsed.ok ) {
			error.hidden = true;
			input.removeAttribute( 'aria-invalid' );
			input.setAttribute( 'aria-describedby', status.id );
			onInput( parsed.value );
		} else if ( showError ) {
			error.textContent = parsed.message;
			error.hidden = false;
			input.setAttribute( 'aria-invalid', 'true' );
			input.setAttribute( 'aria-describedby', status.id + ' ' + error.id );
		}
	};
	input.addEventListener( 'input', () => {
		typing = true;
	} );
	input.addEventListener( 'change', () => apply( true ) );
	input.addEventListener( 'blur', () => {
		typing = false;
	} );
	input.addEventListener( 'keydown', ( event ) => {
		if ( event.key === 'ArrowUp' || event.key === 'ArrowDown' ) {
			event.preventDefault();
			if ( typing ) {
				// Typed text first, then the step from it.
				apply( false );
			}
			onStep( event.key === 'ArrowUp' ? 1 : -1 );
		} else if ( event.key === 'Enter' ) {
			apply( true );
		}
	} );
	const el = h( 'div', { class: [ 'arp-stepper', cls ] }, label, h( 'div', { class: 'arp-stepper__row' }, minus, input, plus, status ), error );
	return { el, input, label, status, minus, plus, error, isTyping: () => typing };
}

/**
 * Writes a stepper's value from state unless the customer is typing in it or it holds invalid text.
 *
 * @param {Object} s     Stepper.
 * @param {string} text  Text.
 */
function syncStepper( s, text ) {
	if ( s.isTyping() || s.input.getAttribute( 'aria-invalid' ) === 'true' ) {
		return;
	}
	if ( s.input.value !== text ) {
		s.input.value = text;
	}
}

/**
 * Creates a product block.
 *
 * @param {Object} handlers { onChange, onSelect, onDuplicate, onMove, onRemove, onRetry, onExplain,
 *                          onDismissNotice, onStep, onQuantity, onSpare }.
 * @param {string} lineId   Line ID.
 * @return {{el: HTMLElement, update: Function, focus: Function}} Block.
 */
export function createLineCard( handlers, lineId ) {
	let view = null;
	const titleId = uid( 'line-title' );
	const parseErrors = new Map();
	const touched = new Set();

	/* ---------------------------------------------------------------- Header. */

	const media = h( 'div', { class: 'arp-line__media' } );
	const title = h( 'h3', { class: 'arp-line__title', id: titleId } );
	// Shown while the line still carries the values of a store protocol the customer used
	// (view.storeTag, CHANGE-1.7.0 §6.7).
	const origin = h( 'span', { class: 'arp-line__origin', hidden: true }, __( 'From a pre-built protocol' ) );
	const meta = h( 'p', { class: 'arp-line__meta' } );
	const dupButton = button( { label: __( 'Duplicate' ), iconName: 'copy', variant: 'ghost', iconOnly: true, size: 'sm', onClick: () => handlers.onDuplicate( lineId ) } );
	const upButton = button( { label: __( 'Move up' ), iconName: 'up', variant: 'ghost', iconOnly: true, size: 'sm', onClick: () => handlers.onMove( lineId, -1 ) } );
	const downButton = button( { label: __( 'Move down' ), iconName: 'down', variant: 'ghost', iconOnly: true, size: 'sm', onClick: () => handlers.onMove( lineId, 1 ) } );
	const removeButton = h( 'button', { type: 'button', class: 'arp-btn arp-btn--link arp-btn--sm arp-line__remove', 'aria-describedby': titleId, onClick: () => handlers.onRemove( lineId ) }, __( 'Remove' ) );
	const actions = h( 'div', { class: 'arp-line__actions', role: 'group', 'aria-label': __( 'Item actions' ) }, dupButton, upButton, downButton, removeButton );

	/* ---------------------------------------------------------------- Notices. */

	const notice = h( 'div', { class: 'arp-line__notice', hidden: true } );
	const legacyText = h( 'p', null );
	const legacy = h( 'div', { class: 'arp-notice arp-notice--info arp-line__legacy', hidden: true }, legacyText );
	const unitNoticeText = h( 'p', { class: 'arp-line__unit-notice-text' } );
	const unitNotice = h(
		'div',
		{ class: 'arp-notice arp-notice--info arp-line__unit-notice', hidden: true },
		icon( 'info' ),
		unitNoticeText,
		button( {
			label: __( 'Dismiss message' ),
			iconName: 'close',
			variant: 'ghost',
			size: 'sm',
			iconOnly: true,
			onClick: () => {
				const restore = unitNotice.contains( document.activeElement );
				handlers.onDismissNotice( lineId );
				if ( restore ) {
					amountInput.focus();
				}
			},
		} )
	);

	/* ---------------------------------------------------------------- Fields. */

	const sizeLegendId = uid( 'size' );
	const variants = createVariantPicker( ( key, slug ) => handlers.onSelect( lineId, key, slug ) );
	const sizeStatic = h( 'p', { class: 'arp-line__size-value' } );
	const sizeGroup = h( 'div', { class: 'arp-field arp-line__size', role: 'group', 'aria-labelledby': sizeLegendId }, h( 'p', { class: 'arp-label', id: sizeLegendId } ), variants.el, sizeStatic );

	const amountInput = h( 'input', { class: 'arp-input', type: 'text', inputmode: 'decimal', autocomplete: 'off', placeholder: '' } );
	const unitSelect = h( 'select', { class: 'arp-select arp-select--unit', 'aria-label': __( 'Unit' ) } );
	const amountField = field( { label: __( 'Amount per use' ), control: amountInput, suffix: unitSelect, cls: 'arp-field--amount' } );

	const eventsInput = h( 'input', { class: 'arp-input arp-input--num', type: 'text', inputmode: 'numeric', autocomplete: 'off' } );
	const eventsField = field( { label: __( 'Times per week' ), control: eventsInput, cls: 'arp-field--times' } );
	const timesQuick = quickChoices( {
		values: TIMES_PER_WEEK_CHOICES,
		label: timesLabel,
		name: timesName,
		groupBy: eventsField.label.id,
		onPick: ( n ) => pick( eventsInput, eventsField, 'events_per_period', n ),
	} );
	eventsField.wrap.insertBefore( timesQuick.el, eventsField.help );

	const periodsInput = h( 'input', { class: 'arp-input arp-input--num', type: 'text', inputmode: 'numeric', autocomplete: 'off' } );
	const periodsField = field( { label: __( 'Duration (weeks)' ), control: periodsInput, cls: 'arp-field--weeks' } );
	const weeksQuick = quickChoices( {
		values: DURATION_CHOICES,
		label: ( n ) => String( n ),
		name: weeksName,
		groupBy: periodsField.label.id,
		onPick: ( n ) => pick( periodsInput, periodsField, 'periods', n ),
	} );
	periodsField.wrap.insertBefore( weeksQuick.el, periodsField.help );

	const weekInput = h( 'input', { class: 'arp-input arp-input--num', type: 'text', inputmode: 'numeric', autocomplete: 'off' } );
	const weekField = field( { label: __( 'Start week' ), control: weekInput, cls: 'arp-field--start-week' } );

	const manual = stepper( {
		cls: 'arp-stepper--manual',
		onStep: ( delta ) => handlers.onStep( lineId, delta, 'manual' ),
		onInput: ( value ) => handlers.onQuantity( lineId, value, 'manual' ),
	} );
	manual.label.textContent = __( 'Quantity' );

	const weeklyFields = h( 'div', { class: 'arp-line__weekly' }, amountField.wrap, eventsField.wrap, periodsField.wrap, weekField.wrap );
	const fields = h( 'div', { class: 'arp-line__fields' }, sizeGroup, weeklyFields, manual.el );

	const labelInput = h( 'input', { class: 'arp-input', type: 'text', maxlength: '80', autocomplete: 'off' } );
	const labelField = field( { label: __( 'Line label (optional)' ), control: labelInput, help: __( 'A short name for this line, for example "Batch A". Included in exports and shared protocols.' ) } );
	const morePanelId = uid( 'more' );
	const moreToggle = h(
		'button',
		{ type: 'button', class: 'arp-disclosure', 'aria-expanded': 'false', 'aria-controls': morePanelId },
		icon( 'chevron', 'arp-disclosure__icon' ),
		h( 'span', null, __( 'More options' ) )
	);
	const morePanel = h( 'div', { id: morePanelId, class: 'arp-disclosure__panel', hidden: true }, labelField.wrap );
	const toggle = ( trigger, panel, open ) => {
		trigger.setAttribute( 'aria-expanded', open ? 'true' : 'false' );
		panel.hidden = ! open;
	};
	moreToggle.addEventListener( 'click', () => toggle( moreToggle, morePanel, morePanel.hidden ) );

	/* ---------------------------------------------------------------- Result. */

	const headline = h( 'p', { class: 'arp-result__headline', 'aria-live': 'polite', 'aria-atomic': 'true' } );
	const updating = h( 'span', { class: 'arp-result__updating', hidden: true }, __( 'Updating…' ) );
	const cells = [ 0, 1, 2 ].map( () => {
		const value = h( 'p', { class: 'arp-strip__value' } );
		const caption = h( 'p', { class: 'arp-strip__caption' } );
		return { el: h( 'div', { class: 'arp-strip__cell' }, value, caption ), value, caption };
	} );
	const buyCaption = h( 'p', { class: 'arp-strip__caption arp-strip__caption--buy' } );
	const buy = stepper( {
		cls: 'arp-stepper--buy',
		onStep: ( delta ) => handlers.onStep( lineId, delta, 'override' ),
		onInput: ( value ) => handlers.onQuantity( lineId, value, 'override' ),
	} );
	const perWeek = h( 'p', { class: 'arp-strip__per-week' } );
	const spareBox = h( 'input', { type: 'checkbox', onChange: () => handlers.onSpare( lineId, spareBox.checked ) } );
	const spareText = h( 'span' );
	const spare = h( 'label', { class: 'arp-check arp-strip__spare' }, spareBox, spareText );
	// Empty state of the purchase cell (§9.3: "—" with "enter values above", like cells 1–3).
	const buyEmpty = h( 'div', { class: 'arp-strip__empty', hidden: true }, h( 'p', { class: 'arp-strip__value' }, '—' ), h( 'p', { class: 'arp-strip__caption' }, __( 'enter values above' ) ) );
	const buyCell = h( 'div', { class: 'arp-strip__cell arp-strip__cell--buy' }, buyEmpty, buyCaption, buy.el, perWeek, spare );
	const strip = h( 'div', { class: 'arp-strip' }, cells.map( ( c ) => c.el ), buyCell );
	const resultBody = h( 'div', { class: 'arp-result__body' } );
	const howButton = button( { label: __( 'How it works' ), iconName: 'help', variant: 'link', size: 'sm', attrs: { 'aria-haspopup': 'dialog' }, onClick: () => handlers.onExplain( lineId ) } );
	const result = h( 'div', { class: 'arp-result' }, h( 'div', { class: 'arp-result__top' }, headline, updating ), strip, resultBody, h( 'div', { class: 'arp-result__links' }, howButton ) );

	const el = h(
		'article',
		{ class: 'arp-card arp-line', 'aria-labelledby': titleId, dataset: { line: lineId } },
		h( 'header', { class: 'arp-line__head' }, media, h( 'div', { class: 'arp-line__heading' }, title, origin, meta ), actions ),
		notice,
		legacy,
		unitNotice,
		fields,
		result,
		h( 'div', { class: 'arp-line__extra' }, moreToggle, morePanel )
	);

	/* ---------------------------------------------------------------- Input wiring. */

	const limits = () => ( view && view.limits ? view.limits : DEFAULT_LIMITS );
	const seps = () => ( { decimalSeparator: view.currency.decimalSeparator, thousandSeparator: view.currency.thousandSeparator } );

	/**
	 * Wires a text input to a parser.
	 *
	 * @param {HTMLInputElement} input      Input.
	 * @param {Object}           f          Field.
	 * @param {string}           key        Line key.
	 * @param {Function}         parse      ( text ) => { ok, value, message, empty }.
	 * @param {Function}         toChanges  ( value|null, invalid ) => line changes, or null to change nothing.
	 */
	const wire = ( input, f, key, parse, toChanges = ( value ) => ( { [ key ]: value } ) ) => {
		// Text of the field when it got focus: leaving it without typing changes nothing (a no-op
		// submit would convert a line saved with an older setting or re-align its start date).
		let focusText = null;
		const submit = ( changes ) => {
			if ( changes && Object.keys( changes ).length > 0 ) {
				handlers.onChange( lineId, changes );
			}
		};
		const apply = ( showError, send = true ) => {
			const parsed = parse( input.value );
			if ( parsed.ok ) {
				parseErrors.delete( key );
				f.setError( serverError( key ) );
				if ( send ) {
					submit( toChanges( parsed.value, false ) );
				}
				return;
			}
			if ( parsed.empty ) {
				parseErrors.delete( key );
				f.setError( ! touched.has( key ) || parsed.allowEmpty ? '' : parsed.message );
				if ( send ) {
					submit( toChanges( null, false ) );
				}
				return;
			}
			parseErrors.set( key, parsed.message );
			if ( showError || f.hasError() ) {
				f.setError( parsed.message );
			}
			if ( send ) {
				submit( toChanges( null, true ) );
			}
		};
		input.addEventListener( 'focus', () => {
			focusText = input.value;
		} );
		input.addEventListener( 'input', () => apply( false ) );
		input.addEventListener( 'blur', () => {
			touched.add( key );
			const typed = focusText === null || input.value !== focusText;
			focusText = null;
			// Messages are shown either way (an empty required field says so once left).
			apply( true, typed );
		} );
	};

	/**
	 * Applies a quick choice: the field shows and submits the value.
	 *
	 * @param {HTMLInputElement} input Input.
	 * @param {Object}           f     Field.
	 * @param {string}           key   Line key.
	 * @param {number}           value Value.
	 */
	const pick = ( input, f, key, value ) => {
		input.value = String( value );
		parseErrors.delete( key );
		f.setError( '' );
		handlers.onChange( lineId, { [ key ]: value } );
	};

	/**
	 * Whole number of times per week (decimals are rejected with their own message).
	 *
	 * @param {string} text Text.
	 * @return {Object} Parse result.
	 */
	const parseTimes = ( text ) => {
		if ( /^\s*\d*[.,]\d+\s*$/.test( String( text ) ) ) {
			return { ok: false, value: null, empty: false, message: __( 'Enter how many times per week as a whole number, for example 3. Decimals are not accepted.' ) };
		}
		return parseIntegerInput( text, { min: 1, max: limits().max_events_per_period } );
	};

	wire( amountInput, amountField, 'amount', ( text ) => parseDecimalInput( text, seps() ) );
	wire( eventsInput, eventsField, 'events_per_period', parseTimes );
	wire( periodsInput, periodsField, 'periods', ( text ) => parseIntegerInput( text, { min: 1, max: limits().max_periods_week } ) );
	wire(
		weekInput,
		weekField,
		'start_week',
		( text ) => {
			if ( String( text ).trim() === '' ) {
				return { ok: false, empty: true, allowEmpty: true, value: null, message: '' };
			}
			return parseIntegerInput( text, { min: 1, max: MAX_START_WEEK } );
		},
		( week, invalid ) => {
			if ( invalid || ! view.planStart ) {
				return null;
			}
			// The week the line already starts in: keep its date (an older protocol's date inside
			// that week is not moved to the first day of the week).
			if ( week !== null && week === weekOfStart( view.line.start_date, view.planStart ).week ) {
				return null;
			}
			const target = startForWeek( view.planStart, week === null ? 1 : week );
			return target.ok && target.date !== ( view.line.start_date || null ) ? { start_date: target.date } : null;
		}
	);
	labelInput.addEventListener( 'input', () => handlers.onChange( lineId, { label: labelInput.value.replace( /[\u0000-\u001F\u007F]/g, ' ' ).slice( 0, 80 ) } ) );
	unitSelect.addEventListener( 'change', () => handlers.onChange( lineId, { unit: unitSelect.value } ) );

	/**
	 * Validation message for a field from the preview/server result ('' when none).
	 *
	 * @param {string} key Field.
	 * @return {string} Message.
	 */
	function serverError( key ) {
		if ( ! view || ! view.calc || ! Array.isArray( view.calc.errors ) ) {
			return '';
		}
		const entry = view.calc.errors.find( ( e ) => e.field === key );
		if ( ! entry ) {
			return '';
		}
		return view.calc.source === 'server' && entry.message ? entry.message : validationText( entry.code );
	}

	/**
	 * Sets an input's text from state unless the user is editing it or it holds unparsed text.
	 *
	 * @param {HTMLInputElement} input Input.
	 * @param {string}           key   Line key.
	 * @param {string}           text  Text.
	 */
	const sync = ( input, key, text ) => {
		if ( document.activeElement === input || parseErrors.has( key ) ) {
			return;
		}
		if ( input.value !== text ) {
			input.value = text;
		}
	};

	const setText = ( node, text ) => {
		if ( node.textContent !== text ) {
			node.textContent = text;
		}
	};

	/* ---------------------------------------------------------------- Result rendering. */

	const displayName = () => ( view.variant ? view.variant : view.name );

	/**
	 * Headline and extra nodes for states without a calculated result.
	 *
	 * @return {{head: string, nodes: Array, ok: boolean}} Content.
	 */
	const resultContent = () => {
		const calc = view.calc || { status: 'incomplete' };
		const product = view.productState;
		const nodes = [];

		if ( view.cartErrors && view.cartErrors.length > 0 ) {
			nodes.push( h( 'div', { class: 'arp-notice arp-notice--error' }, h( 'p', { class: 'arp-notice__title' }, __( 'Could not be added to the cart' ) ), h( 'ul', null, view.cartErrors.map( ( m ) => h( 'li', null, m ) ) ) ) );
		}
		if ( ! product || product.status === 'loading' ) {
			return { ok: false, head: __( 'Loading product…' ), nodes: [ ...nodes, h( 'div', { class: 'arp-sk arp-sk--result', 'aria-hidden': 'true' } ) ] };
		}
		if ( product.status === 'error' || ! product.product ) {
			return {
				ok: false,
				head: product.status === 'missing' ? __( 'Product not available' ) : __( 'Product could not be loaded' ),
				nodes: [
					...nodes,
					h( 'p', null, product.status === 'missing' ? __( 'This product is no longer available in the builder. You can remove it.' ) : __( 'Check your connection and try again.' ) ),
					product.status === 'missing' ? null : button( { label: __( 'Try again' ), iconName: 'refresh', size: 'sm', onClick: () => handlers.onRetry( lineId ) } ),
				],
			};
		}
		if ( calc.status === 'blocked' ) {
			const verify = VERIFY_CODES.includes( calc.code );
			return {
				ok: false,
				head: verify ? __( 'Needs store verification' ) : readinessText( calc.code ),
				nodes: [ ...nodes, h( 'p', null, verify ? __( 'The store has not verified the capacity data of this option yet, so it cannot be calculated. Choose another option or check back later.' ) : calc.message || readinessText( calc.code ) ) ],
			};
		}
		if ( ! view.unit ) {
			if ( view.line.variation_id > 0 ) {
				return { ok: false, head: __( 'Option no longer available' ), nodes: [ ...nodes, h( 'p', null, __( 'The option chosen earlier is no longer offered. Choose the product options again.' ) ) ] };
			}
			return { ok: false, head: __( 'Choose the product options' ), nodes: [ ...nodes, h( 'p', { class: 'arp-result__hint' }, __( 'Select every option above to see the exact item and its price.' ) ) ] };
		}
		if ( calc.status === 'incomplete' ) {
			return { ok: false, head: '', nodes };
		}
		if ( calc.status === 'invalid' ) {
			const visible = [ 'amount', 'unit', 'events_per_period', 'period_unit', 'periods', 'manual_quantity', 'override_quantity', 'start_date', 'label' ];
			const other = ( calc.errors || [] ).filter( ( e ) => ! visible.includes( e.field ) );
			return {
				ok: false,
				head: __( 'Check the highlighted values' ),
				nodes: [ ...nodes, other.length > 0 ? h( 'ul', { class: 'arp-result__errors' }, other.map( ( e ) => h( 'li', null, calc.source === 'server' && e.message ? e.message : validationText( e.code ) ) ) ) : null ],
			};
		}
		if ( calc.status === 'error' ) {
			const verify = VERIFY_CODES.includes( calc.code );
			return {
				ok: false,
				head: verify ? __( 'Needs store verification' ) : __( 'Cannot calculate this item' ),
				nodes: [ ...nodes, h( 'p', null, calc.source === 'server' && calc.message ? calc.message : calculationText( calc.code ) ) ],
			};
		}
		return { ok: true, head: '', nodes };
	};

	/**
	 * Details under the strip of a calculated line: vial size, left over / shortfall, price and
	 * the result's warnings.
	 *
	 * @param {Object} r Result.
	 * @return {Array<HTMLElement>} Nodes.
	 */
	const resultDetails = ( r ) => {
		const c = view.currency;
		const format = view.unit ? view.unit.containerType : '';
		const rows = [];
		const row = ( label, value, cls = '' ) => rows.push( h( 'div', { class: [ 'arp-result__item', cls ] }, h( 'dt', null, label ), h( 'dd', null, value ) ) );
		if ( r.mode !== 'manual' ) {
			row(
				sizeLabel( format ),
				r.pack_count > 1
					? sprintf( /* translators: 1: capacity per purchase unit, 2: containers, 3: capacity per container. */ __( '%1$s (%2$s × %3$s)' ), amountText( r.capacity_per_unit, c ), String( r.pack_count ), amountText( { value: r.capacity.amount, unit: r.capacity.unit }, c ) )
					: amountText( r.capacity_per_unit, c )
			);
			if ( r.shortfall ) {
				row( __( 'Shortfall' ), h( 'span', { class: 'arp-shortfall' }, icon( 'alert' ), amountText( r.shortfall, c ) ), 'is-shortfall' );
			} else {
				row( __( 'Left over' ), amountText( r.surplus, c ) );
			}
			if ( r.bundle_covered_units > 0 ) {
				row( __( 'Supplied by a bundle' ), formatNumber( String( r.bundle_covered_units ), c ) );
			}
		}
		if ( view.showPrices ) {
			row( __( 'Price' ), r.estimate !== null ? money( r.estimate, c ) : __( 'Price unavailable' ), 'is-estimate' );
		}
		const nodes = [ h( 'dl', { class: 'arp-result__details' }, rows ) ];
		const warnings = ( r.warnings || [] ).filter( ( w ) => w.code !== 'price_hidden' && ( view.showPrices || w.code !== 'price_unavailable' ) );
		if ( warnings.length > 0 ) {
			nodes.push(
				h(
					'ul',
					{ class: 'arp-result__warnings' },
					warnings.map( ( w ) => h( 'li', { class: w.code === 'override_shortfall' ? 'is-danger' : '' }, icon( w.code === 'override_shortfall' ? 'alert' : 'info' ), h( 'span', null, view.calc.source === 'server' && w.message ? w.message : noticeText( w.code, w.message ) ) ) )
				)
			);
		}
		return nodes;
	};

	/**
	 * Patches the three information cells of the strip.
	 *
	 * @param {Object|null} r  Result (null: empty state).
	 * @param {Object|null} tl Timeline.
	 */
	const renderCells = ( r, tl ) => {
		const c = view.currency;
		const dash = [ '—', __( 'enter values above' ) ];
		let texts = [ dash, dash, dash ];
		if ( r && r.mode !== 'manual' ) {
			const totalCaption = r.event_count !== null
				? sprintf( /* translators: %s: number of uses. */ _n( 'Total required (%s use)', 'Total required (%s uses)', r.event_count ), formatNumber( String( r.event_count ), c ) )
				: __( 'Total required' );
			const lasts = containerLasts( r );
			const format = view.unit ? view.unit.containerType : '';
			const period = r.period_unit || 'week';
			let lastsCell = dash;
			if ( lasts ) {
				lastsCell = [
					spokenAs(
						sprintf( /* translators: %s: number of weeks (one decimal), abbreviated. */ __( '%s wks' ), formatNumber( lasts.weeks, c ) ),
						sprintf( /* translators: %s: number of weeks (one decimal). */ __( '%s weeks' ), formatNumber( lasts.weeks, c ) )
					),
					lastsCaption( format, amountText( { value: r.capacity.amount, unit: r.capacity.unit }, c ), lasts.uses, formatNumber( String( lasts.uses ), c ) ),
				];
			} else if ( r.mode === 'direct' || period !== 'week' ) {
				// A line saved with an older setting: values are entered, but not per week.
				lastsCell = [ '—', __( 'shown for weekly values' ) ];
			}
			const out = runOut( r, tl );
			let runCell;
			if ( out ) {
				let after = sprintf( /* translators: %s: week number. */ __( 'after week %s' ), formatNumber( String( out.afterWeek ), c ) );
				if ( period !== 'week' ) {
					/* translators: %s: a duration in days or months (e.g. "12 days"). */
					after = sprintf( __( 'after %s' ), durationText( period, out.afterWeek, formatNumber( String( out.afterWeek ), c ) ) );
				}
				runCell = [ out.date ? shortDate( out.date, view.locale ) : after, __( 'Supply runs out' ) ];
			} else if ( r.mode === 'schedule' ) {
				runCell = [
					tl && tl.last_day ? shortDate( tl.last_day, view.locale ) : durationText( period, r.periods, formatNumber( String( r.periods ), c ) ),
					__( 'Covers the full duration' ),
				];
			} else {
				runCell = r.shortfall ? [ '—', __( 'Supply runs out' ) ] : [ '✓', __( 'Covers the full duration' ) ];
			}
			texts = [ [ amountText( r.total_required, c ), totalCaption ], lastsCell, runCell ];
		}
		texts.forEach( ( [ value, caption ], i ) => {
			const cell = cells[ i ];
			const key = JSON.stringify( [ Array.isArray( value ) ? value.map( ( n ) => n.textContent ) : value, caption ] );
			if ( cell.el.dataset.key !== key ) {
				cell.el.dataset.key = key;
				render( cell.value, value );
				cell.caption.textContent = caption;
			}
		} );
	};

	/**
	 * Patches the highlighted purchase cell (persistent controls: focus is never lost). Without a
	 * result it shows the empty state ("—", "enter values above") like the other cells, unless the
	 * customer is working in the cell (focus or an invalid typed quantity).
	 *
	 * @param {Object|null} r        Result.
	 * @param {Object|null} tl       Timeline.
	 * @param {boolean}     readOnly Read-only.
	 * @param {string}      format   Format of the purchase-quantity nouns (purchaseFormat(): the
	 *                               product's format until an option is chosen; "pack" for packs).
	 */
	const renderBuy = ( r, tl, readOnly, format ) => {
		const c = view.currency;
		const line = view.line;
		const keep = buyCell.contains( document.activeElement ) || buy.input.getAttribute( 'aria-invalid' ) === 'true';
		const empty = ! r && ! keep;
		buyEmpty.hidden = ! empty;
		buyCaption.hidden = empty;
		buy.el.hidden = empty;
		spare.hidden = empty;
		const nouns = containerLabel( format );
		let caption = nouns;
		if ( r && r.mode === 'schedule' ) {
			const to = supplyTo( r, tl );
			const weeks = coveredWeeks( r );
			if ( to ) {
				/* translators: 1: container noun (e.g. Vials), 2: date. */
				caption = sprintf( __( '%1$s · supply to %2$s' ), nouns, shortDate( to, view.locale ) );
			} else if ( weeks !== null && weeks > 0 ) {
				/* translators: 1: container noun (e.g. Vials), 2: number of weeks. */
				caption = sprintf( _n( '%1$s · supply for %2$s week', '%1$s · supply for %2$s weeks', weeks ), nouns, formatNumber( String( weeks ), c ) );
			}
		}
		setText( buyCaption, caption );
		setText( buy.label, nouns );
		const quantity = stepperQuantity( line, r );
		// Also while the input has focus: ArrowUp / ArrowDown change the quantity in place.
		syncStepper( buy, quantity === null ? '' : String( quantity ) );
		const usable = !! r && ! readOnly;
		buy.input.disabled = ! usable && document.activeElement !== buy.input;
		setStepperButton( buy.minus, ! usable, quantity === null || quantity <= 0 );
		setStepperButton( buy.plus, ! usable, quantity === null || quantity >= limits().max_quantity );
		const names = stepperLabels( format );
		buy.minus.setAttribute( 'aria-label', names.fewer );
		buy.plus.setAttribute( 'aria-label', names.more );
		const status = r ? ( quantityStatus( line ) === 'changed' ? __( 'changed' ) : __( 'calculated' ) ) : '';
		setText( buy.status, status );
		buy.status.classList.toggle( 'is-changed', !! r && quantityStatus( line ) === 'changed' );

		let weekPrice = '';
		if ( r && view.showPrices && r.mode === 'schedule' && r.period_unit === 'week' ) {
			const price = perWeekPrice( r.estimate, r.periods, c.decimals );
			/* translators: %s: price. */
			weekPrice = price !== null ? sprintf( __( '≈ %s per week of supply' ), money( price, c ) ) : '';
		}
		setText( perWeek, weekPrice );
		perWeek.hidden = weekPrice === '';

		setText( spareText, spareLabel( format ) );
		spareBox.checked = spareChecked( line, r );
		spareBox.disabled = ! usable;
	};

	/* ---------------------------------------------------------------- Update. */

	const stockBadge = ( unit ) => {
		if ( ! unit ) {
			return null;
		}
		if ( unit.stockStatus === 'outofstock' ) {
			return h( 'span', { class: 'arp-badge arp-badge--muted' }, __( 'Out of stock' ) );
		}
		if ( unit.stockStatus === 'onbackorder' ) {
			return h( 'span', { class: 'arp-badge arp-badge--warning' }, __( 'On backorder' ) );
		}
		return null;
	};

	let lastMediaSrc = null;
	let resultSignature = '';
	let metaSignature = '';
	let labelName = null;

	return {
		el,
		/**
		 * Updates the block.
		 *
		 * @param {Object} next View model (see app.js lineView()).
		 */
		update( next ) {
			view = next;
			const line = view.line;
			const unit = view.unit;
			const product = view.productState && view.productState.product;
			const readOnly = !! view.readOnly;
			const kind = view.kind;
			// A line saved with an older setting shows only values that mean exactly what is being
			// calculated (n per day = 7n per week; days only when they are whole weeks); the rest stays
			// empty until the first edit converts the line (app.js updateLine()).
			const shown = view.legacyShown ? { ...line, ...view.legacyPreview } : line;

			// Header.
			setText( title, view.name || __( 'Loading product…' ) );
			origin.hidden = ! view.storeTag;
			const image = view.showImages ? ( unit && unit.image ) || ( product && product.image ) : null;
			const src = image ? image.src : '';
			if ( src !== lastMediaSrc ) {
				lastMediaSrc = src;
				render( media, image ? h( 'img', { src: image.src, alt: '', width: '56', height: '56', loading: 'lazy', decoding: 'async' } ) : h( 'span', { class: 'arp-line__placeholder' }, icon( 'box' ) ) );
				media.hidden = ! view.showImages;
			}
			// Price of one purchase unit over the capacity it buys (containers × pack count).
			const perMg = view.showPrices && unit ? perMgPrice( unit.price, massCapacity( unit ), view.currency.decimals, unit.packCount ) : null;
			const nextMeta = JSON.stringify( [ perMg, unit && unit.stockStatus, view.currency.symbol, view.currency.decimals ] );
			if ( nextMeta !== metaSignature ) {
				metaSignature = nextMeta;
				render(
					meta,
					perMg !== null
						? h(
							'span',
							{ class: 'arp-line__unit-price' },
							spokenAs(
								/* translators: %s: price per milligram. */
								sprintf( __( '%s/mg' ), money( perMg, view.currency ) ),
								/* translators: %s: price per milligram. */
								sprintf( __( '%s per mg' ), money( perMg, view.currency ) )
							)
						)
						: null,
					stockBadge( unit )
				);
				meta.hidden = meta.childNodes.length === 0;
			}
			if ( labelName !== view.name ) {
				labelName = view.name;
				dupButton.setAttribute( 'aria-label', sprintf( /* translators: %s: product name. */ __( 'Duplicate %s' ), view.name ) );
				upButton.setAttribute( 'aria-label', sprintf( /* translators: %s: name of the item that is moved (product, product type, category or combination). */ __( 'Move %s up' ), view.name ) );
				downButton.setAttribute( 'aria-label', sprintf( /* translators: %s: name of the item that is moved (product, product type, category or combination). */ __( 'Move %s down' ), view.name ) );
			}
			dupButton.disabled = view.atMax;
			dupButton.title = view.atMax ? __( 'The protocol has reached the maximum number of items.' ) : '';
			upButton.disabled = view.index === 0;
			downButton.disabled = view.index >= view.count - 1;
			actions.hidden = readOnly;

			// Size (variant selects, or the single option of a simple product).
			// Until an option is chosen, the format of the product's first plannable unit.
			const format = unit ? unit.containerType : productFormat( product );
			// Nouns of the purchase quantity ("3 vials", "Packs" for a pack of several vials).
			const nounFormat = purchaseFormat( unit, format );
			setText( sizeGroup.querySelector( '.arp-label' ), sizeLabel( format ) );
			variants.update( product || null, line.variation_attributes, readOnly );
			const simple = ! product || product.type !== 'variable';
			const cap = unit && unit.capacities.length > 0 ? unit.capacities[ 0 ] : null;
			setText( sizeStatic, simple && cap ? amountText( { value: cap.amount, unit: cap.unit }, view.currency ) : '' );
			sizeStatic.hidden = ! simple || ! cap;
			sizeGroup.hidden = simple && ! cap;

			// Fields of the item kind.
			weeklyFields.hidden = kind !== 'weekly';
			manual.el.hidden = kind !== 'quantity';
			strip.hidden = kind !== 'weekly';
			// Until the option (vial size…) is chosen the fields are shown but cannot be used yet.
			const usable = kind !== '' && ! readOnly && !! unit;

			const units = unit ? unit.compatibleUnits : [];
			const unitSignature = units.join( ',' );
			if ( unitSelect.dataset.units !== unitSignature ) {
				unitSelect.dataset.units = unitSignature;
				unitSelect.replaceChildren( ...units.map( ( u ) => h( 'option', { value: u }, unitName( u ) ) ) );
			}
			if ( shown.unit && unitSelect.value !== shown.unit ) {
				unitSelect.value = shown.unit;
			}

			sync( amountInput, 'amount', toInputText( shown.amount, view.currency.decimalSeparator ) );
			sync( eventsInput, 'events_per_period', shown.events_per_period === null ? '' : String( shown.events_per_period ) );
			sync( periodsInput, 'periods', shown.periods === null ? '' : String( shown.periods ) );
			timesQuick.update( shown.events_per_period, ! usable );
			weeksQuick.update( shown.periods, ! usable );

			const week = weekOfStart( line.start_date, view.planStart );
			sync( weekInput, 'start_week', view.planStart && week.week !== null ? String( week.week ) : '' );
			let weekHelp = '';
			if ( ! view.planStart ) {
				weekHelp = line.start_date
					? sprintf( /* translators: %s: date. */ __( 'Starts on %s. Set a protocol start date to start this item in a later week.' ), formatDate( line.start_date, view.locale ) )
					: __( 'Set a protocol start date to start this item in a later week.' );
			} else if ( line.start_date ) {
				/* translators: %s: date. */
				weekHelp = sprintf( __( 'Starts on %s.' ), formatDate( line.start_date, view.locale ) );
			}
			weekField.setHelp( weekHelp );

			const manualValue = kind === 'quantity' ? ( view.legacyShown ? view.legacyPreview.manual_quantity ?? null : line.manual_quantity ) : null;
			// Also while the input has focus: ArrowUp / ArrowDown change the quantity in place.
			syncStepper( manual, manualValue === null ? '' : String( manualValue ) );
			manual.input.disabled = ! usable && document.activeElement !== manual.input;
			setStepperButton( manual.minus, ! usable, manualValue === null || manualValue <= 1 );
			setStepperButton( manual.plus, ! usable, manualValue !== null && manualValue >= limits().max_quantity );
			manual.minus.setAttribute( 'aria-label', __( 'Decrease quantity' ) );
			manual.plus.setAttribute( 'aria-label', __( 'Increase quantity' ) );
			setText( manual.status, containerNoun( nounFormat, manualValue ?? 2 ) );

			if ( document.activeElement !== labelInput && labelInput.value !== ( line.label || '' ) ) {
				labelInput.value = line.label || '';
			}
			[ amountInput, unitSelect, eventsInput, periodsInput, labelInput ].forEach( ( input ) => {
				input.disabled = ! usable;
			} );
			weekInput.disabled = ! usable || ! view.planStart;
			moreToggle.hidden = kind === '';
			if ( moreToggle.hidden ) {
				morePanel.hidden = true;
			} else if ( line.label && morePanel.hidden && ! moreToggle.dataset.touched ) {
				moreToggle.dataset.touched = '1';
				toggle( moreToggle, morePanel, true );
			}

			// Field errors (parse errors first, then preview/server validation errors).
			[
				[ amountField, 'amount', 'unit' ],
				[ eventsField, 'events_per_period', 'period_unit' ],
				[ periodsField, 'periods' ],
				[ weekField, 'start_week', 'start_date' ],
				[ labelField, 'label' ],
			].forEach( ( [ f, key, extra ] ) => {
				const parseMessage = parseErrors.has( key ) && ( touched.has( key ) || f.hasError() ) ? parseErrors.get( key ) : '';
				const editing = document.activeElement === f.control && parseErrors.has( key ) && ! parseMessage;
				f.setError( parseMessage || ( editing ? '' : serverError( key ) || ( extra ? serverError( extra ) : '' ) ) );
			} );

			// Notices: older setting, unit / option change, blocked option.
			let legacyMessage = '';
			if ( view.legacyShown ) {
				const old = legacySetting( line );
				if ( readOnly ) {
					// A shared protocol: the recipient cannot convert it, so only say why fields are empty.
					legacyMessage = old
						? sprintf( /* translators: %s: the older setting, e.g. "1 use per day for 30 days". */ __( 'Saved with an older setting (%s).' ), old )
						: __( 'Saved with an older setting.' );
				} else if ( kind === 'quantity' ) {
					legacyMessage = __( 'This item uses an older setting; change the quantity to switch to the current one.' );
				} else {
					legacyMessage = old
						? sprintf( /* translators: %s: the older setting, e.g. "1 use per day for 30 days". */ __( 'This item uses an older setting (%s); change any field to switch to weekly.' ), old )
						: __( 'This item uses an older setting; change any field to switch to weekly.' );
				}
			}
			setText( legacyText, legacyMessage );
			legacy.hidden = legacyMessage === '';
			const unitText = view.unitNotice || '';
			setText( unitNoticeText, unitText );
			unitNotice.hidden = unitText === '';
			const blocked = view.calc && view.calc.status === 'blocked';
			notice.hidden = ! blocked;
			if ( blocked ) {
				render( notice, h( 'p', null, VERIFY_CODES.includes( view.calc.code ) ? __( 'This option needs store verification before it can be calculated.' ) : readinessText( view.calc.code ) ) );
			}

			// Result.
			const calc = view.calc || {};
			const signature = JSON.stringify( [
				calc.status,
				calc.source,
				calc.code,
				calc.message,
				calc.result,
				calc.errors,
				calc.timeline && [ calc.timeline.start_date, calc.timeline.last_day, calc.timeline.run_out ],
				view.cartErrors,
				view.productState && view.productState.status,
				!! unit,
				unit && unit.containerType,
				nounFormat,
				line.variation_id,
				line.override_quantity,
				view.name,
				view.variant,
				view.showPrices,
				view.locale,
				kind,
			] );
			const content = signature !== resultSignature ? resultContent() : null;
			const r = calc.status === 'ok' && calc.result ? calc.result : null;
			if ( content ) {
				resultSignature = signature;
				let head = content.head;
				if ( content.ok && r ) {
					head = quantityHeadline( nounFormat, r.quantity, formatNumber( String( r.quantity ), view.currency ), displayName() );
				}
				setText( headline, head );
				headline.hidden = head === '';
				render( resultBody, ...content.nodes, ...( content.ok && r ? resultDetails( r ) : [] ) );
				renderCells( content.ok ? r : null, calc.timeline || null );
				howButton.hidden = ! ( content.ok && r );
			}
			renderBuy( r, calc.timeline || null, readOnly, nounFormat );
			result.classList.toggle( 'is-ok', calc.status === 'ok' );
			result.classList.toggle( 'is-shortfall', !! ( r && r.shortfall ) );
			updating.hidden = ! view.pending;
			el.classList.toggle( 'is-readonly', readOnly );
		},
		/**
		 * Focuses part of the block.
		 *
		 * @param {string} which heading | up | down | amount.
		 */
		focus( which ) {
			const target = { up: upButton, down: downButton, amount: amountInput }[ which ];
			if ( target && ! target.disabled && ! target.closest( '[hidden]' ) ) {
				target.focus();
				return;
			}
			title.setAttribute( 'tabindex', '-1' );
			title.focus();
		},
	};
}
