/**
 * WhatsApp handoff message: product names, variants and whole-unit quantities ONLY.
 *
 * Research inputs (amounts, units, events, periods, dates, notes, labels) are never included,
 * whatever the caller passes in: the builder reads exactly three fields per item.
 *
 * @module whatsapp
 */

import { __, sprintf } from './i18n.js';

/**
 * Single-line plain text (no control characters, collapsed whitespace, ≤ 200 characters).
 *
 * @param {*} value Value.
 * @return {string} Text.
 */
function plain( value ) {
	return String( typeof value === 'string' ? value : '' )
		.replace( /[\u0000-\u001F\u007F-\u009F]/g, ' ' )
		.replace( /\s+/g, ' ' )
		.trim()
		.slice( 0, 200 );
}

/**
 * Message items from arbitrary objects (only quantity, name and variant are read).
 *
 * @param {Array<Object>} entries Entries.
 * @return {Array<{quantity: number, name: string, variant: string}>} Items.
 */
export function whatsappItems( entries ) {
	return ( Array.isArray( entries ) ? entries : [] )
		.map( ( entry ) => ( {
			quantity: entry && Number.isSafeInteger( entry.quantity ) ? entry.quantity : 0,
			name: plain( entry && entry.name ),
			variant: plain( entry && entry.variant ),
		} ) )
		.filter( ( item ) => item.quantity > 0 && item.name !== '' );
}

/**
 * Builds the message from the store template ({items} placeholder).
 *
 * @param {string}        template Template from the settings.
 * @param {Array<Object>} entries  Entries ({ quantity, name, variant }).
 * @return {string} Message.
 */
export function buildWhatsAppMessage( template, entries ) {
	const list = whatsappItems( entries )
		/* translators: 1: product name, 2: chosen variant (e.g. strength or pen format). */
		.map( ( item ) => '- ' + item.quantity + ' × ' + ( item.variant !== '' ? sprintf( __( '%1$s (%2$s)' ), item.name, item.variant ) : item.name ) )
		.join( '\n' );
	const text = typeof template === 'string' && template.includes( '{items}' ) ? template : '{items}';
	return text.split( '{items}' ).join( list === '' ? '' : '\n' + list ).trim();
}

/**
 * wa.me URL for a number (digits only, E.164 without +) and a message.
 *
 * @param {string} number  Number.
 * @param {string} message Message.
 * @return {string} URL ('' when the number is invalid).
 */
export function whatsappUrl( number, message ) {
	const digits = String( number || '' ).replace( /\D/g, '' );
	if ( ! /^\d{8,15}$/.test( digits ) ) {
		return '';
	}
	return 'https://wa.me/' + digits + '?text=' + encodeURIComponent( message );
}
