/**
 * Tiny DOM helpers (no innerHTML anywhere: all text goes through textContent / text nodes).
 *
 * @module dom
 */

const SVG_NS = 'http://www.w3.org/2000/svg';
const PROPERTIES = new Set( [ 'value', 'checked', 'selected', 'disabled', 'hidden', 'readOnly', 'indeterminate', 'open' ] );

let counter = 0;

/**
 * Unique element ID.
 *
 * @param {string} prefix Prefix.
 * @return {string} ID.
 */
export function uid( prefix = 'el' ) {
	counter += 1;
	return 'arp-' + prefix + '-' + counter;
}

/**
 * Appends children (strings, numbers, nodes, arrays; null/false skipped).
 *
 * @param {Node}  parent   Parent.
 * @param {Array} children Children.
 */
export function append( parent, children ) {
	for ( const child of children ) {
		if ( child === null || child === undefined || child === false || child === true ) {
			continue;
		}
		if ( Array.isArray( child ) ) {
			append( parent, child );
		} else if ( typeof child === 'object' && child.nodeType ) {
			parent.appendChild( child );
		} else {
			parent.appendChild( document.createTextNode( String( child ) ) );
		}
	}
}

/**
 * Applies props to an element.
 *
 * @param {Element} el    Element.
 * @param {Object}  props Props.
 */
function applyProps( el, props ) {
	for ( const [ key, value ] of Object.entries( props || {} ) ) {
		if ( value === null || value === undefined || value === false ) {
			if ( PROPERTIES.has( key ) && value === false ) {
				el[ key ] = false;
			}
			continue;
		}
		if ( key === 'class' || key === 'className' ) {
			const names = Array.isArray( value ) ? value.filter( Boolean ).join( ' ' ) : String( value );
			if ( el instanceof SVGElement ) {
				el.setAttribute( 'class', names );
			} else {
				el.className = names;
			}
		} else if ( key === 'text' ) {
			el.textContent = String( value );
		} else if ( key === 'style' && typeof value === 'object' ) {
			for ( const [ prop, v ] of Object.entries( value ) ) {
				if ( prop.startsWith( '--' ) ) {
					el.style.setProperty( prop, String( v ) );
				} else {
					el.style[ prop ] = v;
				}
			}
		} else if ( key === 'dataset' && typeof value === 'object' ) {
			Object.assign( el.dataset, value );
		} else if ( key.length > 2 && key.startsWith( 'on' ) && typeof value === 'function' ) {
			el.addEventListener( key.slice( 2 ).toLowerCase(), value );
		} else if ( PROPERTIES.has( key ) ) {
			el[ key ] = value;
		} else if ( key === 'for' ) {
			el.setAttribute( 'for', String( value ) );
		} else {
			el.setAttribute( key, value === true ? '' : String( value ) );
		}
	}
}

/**
 * Creates an HTML element.
 *
 * @param {string} tag      Tag name.
 * @param {Object} props    Props (class, text, style, dataset, on*, attributes).
 * @param {...*}   children Children.
 * @return {HTMLElement} Element.
 */
export function h( tag, props = null, ...children ) {
	const el = document.createElement( tag );
	applyProps( el, props );
	append( el, children );
	return el;
}

/**
 * Creates an SVG element.
 *
 * @param {string} tag      Tag name.
 * @param {Object} attrs    Attributes.
 * @param {...*}   children Children.
 * @return {SVGElement} Element.
 */
export function s( tag, attrs = null, ...children ) {
	const el = document.createElementNS( SVG_NS, tag );
	applyProps( el, attrs );
	append( el, children );
	return el;
}

/**
 * Removes all children.
 *
 * @param {Node} el Element.
 * @return {Node} Element.
 */
export function clear( el ) {
	while ( el.firstChild ) {
		el.removeChild( el.firstChild );
	}
	return el;
}

/**
 * Replaces all children.
 *
 * @param {Node} el       Element.
 * @param {...*} children Children.
 * @return {Node} Element.
 */
export function render( el, ...children ) {
	clear( el );
	append( el, children );
	return el;
}

/**
 * Debounces a function (with cancel() and flush()).
 *
 * @param {Function} fn Function.
 * @param {number}   ms Delay.
 * @return {Function} Debounced function.
 */
export function debounce( fn, ms ) {
	let timer = null;
	let lastArgs = [];
	const debounced = ( ...args ) => {
		lastArgs = args;
		clearTimeout( timer );
		timer = setTimeout( () => {
			timer = null;
			fn( ...lastArgs );
		}, ms );
	};
	debounced.cancel = () => {
		clearTimeout( timer );
		timer = null;
	};
	debounced.flush = () => {
		if ( timer !== null ) {
			debounced.cancel();
			fn( ...lastArgs );
		}
	};
	debounced.pending = () => timer !== null;
	return debounced;
}

