/**
 * Decorative inline SVG icon (hidden from assistive technology).
 *
 * @param {string} name Icon name.
 * @param {string} cls  Extra class.
 * @return {SVGElement} Icon.
 */
export function icon( name, cls = '' ) {
	return s(
		'svg',
		{
			class: [ 'arp-icon', cls ],
			viewBox: '0 0 24 24',
			width: '20',
			height: '20',
			'aria-hidden': 'true',
			focusable: 'false',
			fill: 'none',
			stroke: 'currentColor',
			'stroke-width': '2',
			'stroke-linecap': 'round',
			'stroke-linejoin': 'round',
		},
		s( 'path', { d: ICONS[ name ] || ICONS.info } )
	);
}

/**
 * Button helper.
 *
 * @param {Object} options Options: label, icon, variant (primary|secondary|ghost|danger|link), size (sm), onClick, attrs, iconOnly.
 * @return {HTMLButtonElement} Button.
 */
export function button( options ) {
	const { label, iconName, variant = 'secondary', size = '', onClick, attrs = {}, iconOnly = false, cls = '' } = options;
	const props = {
		type: 'button',
		class: [ 'arp-btn', 'arp-btn--' + variant, size ? 'arp-btn--' + size : '', iconOnly ? 'arp-btn--icon' : '', cls ],
		onClick,
		...attrs,
	};
	if ( iconOnly ) {
		props[ 'aria-label' ] = label;
		return h( 'button', props, iconName ? icon( iconName ) : null );
	}
	return h( 'button', props, iconName ? icon( iconName ) : null, h( 'span', { class: 'arp-btn__label' }, label ) );
}

/**
 * Triggers a file download for a Blob.
 *
 * @param {Blob}   blob     Data.
 * @param {string} filename File name.
 */
export function downloadBlob( blob, filename ) {
	const url = URL.createObjectURL( blob );
	const link = h( 'a', { href: url, download: filename, hidden: true } );
	document.body.appendChild( link );
	link.click();
	link.remove();
	setTimeout( () => URL.revokeObjectURL( url ), 30000 );
}
