/**
 * Local (device-only) persistence: autosave of the current workspace and up to 20 named drafts.
 *
 * Data is stored in localStorage under versioned keys and never leaves the browser. When storage
 * is unavailable (private mode, disabled, sandboxed) everything still works in memory and
 * `available` is false; quota errors are reported instead of thrown.
 *
 * @module drafts
 */

import { MAX_TITLE_LENGTH } from './store.js';

/** Storage format version. */
export const STORAGE_VERSION = 1;

/** Maximum number of named drafts. */
export const MAX_DRAFTS = 20;

/** Keys. */
export const KEYS = Object.freeze( {
	workspace: 'arp.v1.workspace',
	drafts: 'arp.v1.drafts',
	prefs: 'arp.v1.prefs',
} );

/**
 * Preference (in KEYS.prefs) holding the visitor's last choice of the entry buttons: 'prebuilt' or
 * 'own' (CHANGE-1.7.1 §2.5). Written by a press of "Pre-built protocols" / "Make your own protocol"
 * and by "Use this protocol" ('own'); read once at start; removed with clearAll().
 */
export const ENTRY_VIEW_PREF = 'entry_view';

const PREFIX = 'arp.v';

/**
 * In-memory Storage replacement.
 *
 * @return {Object} Storage-like object.
 */
export function memoryStorage() {
	const map = new Map();
	return {
		getItem: ( key ) => ( map.has( key ) ? map.get( key ) : null ),
		setItem: ( key, value ) => {
			map.set( key, String( value ) );
		},
		removeItem: ( key ) => {
			map.delete( key );
		},
		key: ( index ) => Array.from( map.keys() )[ index ] ?? null,
		get length() {
			return map.size;
		},
	};
}

/**
 * window.localStorage when it is usable, else null.
 *
 * @return {Storage|null} Storage.
 */
export function browserStorage() {
	try {
		const storage = typeof window !== 'undefined' ? window.localStorage : null;
		if ( ! storage ) {
			return null;
		}
		const probe = PREFIX + 'probe';
		storage.setItem( probe, '1' );
		storage.removeItem( probe );
		return storage;
	} catch ( e ) {
		return null;
	}
}

/**
 * Whether an exception is a storage quota error.
 *
 * @param {*} error Error.
 * @return {boolean} Quota exceeded.
 */
function isQuotaError( error ) {
	return !! error && ( error.name === 'QuotaExceededError' || error.name === 'NS_ERROR_DOM_QUOTA_REACHED' || error.code === 22 || error.code === 1014 );
}

/**
 * Random draft ID.
 *
 * @return {string} ID.
 */
function randomId() {
	const bytes = new Uint8Array( 8 );
	if ( typeof crypto !== 'undefined' && crypto.getRandomValues ) {
		crypto.getRandomValues( bytes );
	} else {
		for ( let i = 0; i < bytes.length; i++ ) {
			bytes[ i ] = Math.floor( Math.random() * 256 );
		}
	}
	return 'd_' + Array.from( bytes, ( b ) => b.toString( 16 ).padStart( 2, '0' ) ).join( '' );
}

/**
 * Plain-text draft title (at most MAX_TITLE_LENGTH characters, the limit of saved plans).
 *
 * @param {*} title Title.
 * @return {string} Title.
 */
function cleanTitle( title ) {
	return String( title === null || title === undefined ? '' : title ).replace( /[\u0000-\u001F\u007F]/g, ' ' ).trim().slice( 0, MAX_TITLE_LENGTH );
}

/**
 * Whether an autosaved workspace is a new protocol nobody worked on: no items, no name, no notes,
 * not linked to a draft or an account protocol, and its start date is still the pre-filled "today"
 * (`meta.auto_start` true; a workspace saved before the flag existed counts as untouched when it
 * is empty). Such a workspace starts again as a new protocol with today's date (CHANGE-1.1.0 §9.4);
 * a start date the customer chose or cleared (`auto_start` false) is kept.
 *
 * @param {Object} plan Sanitized plan document (plan.js sanitizePlan()).
 * @param {Object} meta Stored workspace metadata.
 * @return {boolean} Untouched.
 */
export function isUntouchedWorkspace( plan, meta ) {
	const p = plan && typeof plan === 'object' ? plan : null;
	const m = meta && typeof meta === 'object' ? meta : {};
	if ( ! p || ( Array.isArray( p.lines ) && p.lines.length > 0 ) ) {
		return false;
	}
	if ( String( p.title || '' ).trim() !== '' || String( p.notes || '' ).trim() !== '' ) {
		return false;
	}
	if ( m.kind === 'draft' || m.kind === 'account' ) {
		return false;
	}
	return m.auto_start !== false;
}

/**
 * Creates the drafts store.
 *
 * @param {Object}   options         Options.
 * @param {Storage}  options.storage Storage (default: localStorage, else memory).
 * @param {Function} options.now     Clock returning an ISO timestamp.
 * @param {Function} options.id      Draft ID generator.
 * @return {Object} Drafts API.
 */
export function createDrafts( options = {} ) {
	const provided = Object.prototype.hasOwnProperty.call( options, 'storage' ) ? options.storage : browserStorage();
	const available = !! provided;
	const storage = provided || memoryStorage();
	const now = typeof options.now === 'function' ? options.now : () => new Date().toISOString();
	const makeId = typeof options.id === 'function' ? options.id : randomId;

	const read = ( key ) => {
		try {
			const raw = storage.getItem( key );
			if ( raw === null || raw === undefined || raw === '' ) {
				return null;
			}
			const data = JSON.parse( raw );
			return data && typeof data === 'object' && data.v === STORAGE_VERSION ? data : null;
		} catch ( e ) {
			return null;
		}
	};
	const write = ( key, data ) => {
		try {
			storage.setItem( key, JSON.stringify( { ...data, v: STORAGE_VERSION } ) );
			return { ok: true, code: null };
		} catch ( e ) {
			return { ok: false, code: isQuotaError( e ) ? 'quota' : 'unavailable' };
		}
	};
	const items = () => {
		const data = read( KEYS.drafts );
		return data && Array.isArray( data.items )
			? data.items.filter( ( item ) => item && typeof item.id === 'string' && item.plan && typeof item.plan === 'object' )
			: [];
	};
	const writeItems = ( list ) => write( KEYS.drafts, { items: list } );
	const lineCount = ( plan ) => ( plan && Array.isArray( plan.lines ) ? plan.lines.length : 0 );

	return {
		available,

		/**
		 * Autosaved workspace.
		 *
		 * @return {{plan: Object, saved_at: string, meta: Object}|null} Workspace.
		 */
		loadWorkspace() {
			const data = read( KEYS.workspace );
			return data && data.plan && typeof data.plan === 'object'
				? { plan: data.plan, saved_at: String( data.saved_at || '' ), meta: data.meta && typeof data.meta === 'object' ? data.meta : {} }
				: null;
		},

		/**
		 * Autosaves the workspace.
		 *
		 * @param {Object} plan Plan document.
		 * @param {Object} meta Small metadata (e.g. linked draft or account plan).
		 * @return {{ok: boolean, code: string|null}} Result.
		 */
		saveWorkspace( plan, meta = {} ) {
			return write( KEYS.workspace, { saved_at: now(), plan, meta } );
		},

		/** Removes the autosaved workspace. */
		clearWorkspace() {
			try {
				storage.removeItem( KEYS.workspace );
			} catch ( e ) {
				// Nothing to clear.
			}
		},

		/**
		 * Draft summaries, newest first.
		 *
		 * @return {Array<{id: string, title: string, updated_at: string, line_count: number}>} Drafts.
		 */
		list() {
			return items()
				.map( ( item ) => ( { id: item.id, title: cleanTitle( item.title ), updated_at: String( item.updated_at || '' ), line_count: lineCount( item.plan ) } ) )
				.sort( ( a, b ) => ( a.updated_at < b.updated_at ? 1 : -1 ) );
		},

		/**
		 * One draft.
		 *
		 * @param {string} id Draft ID.
		 * @return {Object|null} Draft { id, title, updated_at, plan }.
		 */
		get( id ) {
			return items().find( ( item ) => item.id === id ) || null;
		},

		/**
		 * Creates or updates a named draft.
		 *
		 * @param {{id?: string, title: string, plan: Object}} draft Draft.
		 * @return {{ok: boolean, code: string|null, draft: Object|null}} Result (code: limit|quota|unavailable).
		 */
		save( draft ) {
			const list = items();
			const title = cleanTitle( draft.title ) || cleanTitle( draft.plan && draft.plan.title );
			const record = { id: draft.id || makeId(), title, updated_at: now(), plan: draft.plan };
			const index = list.findIndex( ( item ) => item.id === record.id );
			if ( index >= 0 ) {
				list[ index ] = record;
			} else {
				if ( list.length >= MAX_DRAFTS ) {
					return { ok: false, code: 'limit', draft: null };
				}
				list.push( record );
			}
			const result = writeItems( list );
			return { ...result, draft: result.ok ? record : null };
		},

		/**
		 * Renames a draft.
		 *
		 * @param {string} id    Draft ID.
		 * @param {string} title Title.
		 * @return {{ok: boolean, code: string|null}} Result.
		 */
		rename( id, title ) {
			const list = items();
			const item = list.find( ( entry ) => entry.id === id );
			if ( ! item ) {
				return { ok: false, code: 'not_found' };
			}
			item.title = cleanTitle( title );
			item.plan = { ...item.plan, title: item.title };
			item.updated_at = now();
			return writeItems( list );
		},

		/**
		 * Duplicates a draft.
		 *
		 * @param {string}   id      Draft ID.
		 * @param {Function} titleOf ( title ) => title of the copy (translated by the caller, e.g.
		 *                           sprintf( __( '%s (copy)' ), title ) — word order differs by language).
		 * @return {{ok: boolean, code: string|null, draft: Object|null}} Result.
		 */
		duplicate( id, titleOf = ( title ) => title + ' (copy)' ) {
			const item = this.get( id );
			if ( ! item ) {
				return { ok: false, code: 'not_found', draft: null };
			}
			const title = cleanTitle( typeof titleOf === 'function' ? titleOf( item.title ) : item.title + String( titleOf ) );
			return this.save( { title, plan: { ...JSON.parse( JSON.stringify( item.plan ) ), title } } );
		},

		/**
		 * Deletes a draft.
		 *
		 * @param {string} id Draft ID.
		 * @return {{ok: boolean, code: string|null}} Result.
		 */
		remove( id ) {
			const list = items();
			const next = list.filter( ( item ) => item.id !== id );
			if ( next.length === list.length ) {
				return { ok: false, code: 'not_found' };
			}
			return writeItems( next );
		},

		/**
		 * Reads a small preference value.
		 *
		 * @param {string} key      Key.
		 * @param {*}      fallback Fallback.
		 * @return {*} Value.
		 */
		pref( key, fallback = null ) {
			const data = read( KEYS.prefs );
			return data && data.values && Object.prototype.hasOwnProperty.call( data.values, key ) ? data.values[ key ] : fallback;
		},

		/**
		 * Stores a small preference value.
		 *
		 * @param {string} key   Key.
		 * @param {*}      value Value (JSON).
		 * @return {{ok: boolean, code: string|null}} Result.
		 */
		setPref( key, value ) {
			const data = read( KEYS.prefs );
			const values = data && data.values && typeof data.values === 'object' ? { ...data.values } : {};
			values[ key ] = value;
			return write( KEYS.prefs, { values } );
		},

		/**
		 * Deletes every planner key (workspace, drafts, preferences, older versions).
		 *
		 * @return {number} Number of keys removed.
		 */
		clearAll() {
			const keys = [];
			try {
				for ( let i = 0; i < storage.length; i++ ) {
					const key = storage.key( i );
					if ( typeof key === 'string' && key.startsWith( PREFIX ) ) {
						keys.push( key );
					}
				}
				keys.forEach( ( key ) => storage.removeItem( key ) );
			} catch ( e ) {
				return 0;
			}
			return keys.length;
		},
	};
}
