/**
 * "Add all to cart" flow: POST /cart dry run → conflict dialog (Add to existing quantity / Replace
 * with planned quantity / Skip) → commit with a generated request_id (reused on retry, so a retry
 * can never add twice) → per-line results → WooCommerce cart totals and mini-cart refresh.
 *
 * The server validates everything and is atomic: either all lines are added or none. Only
 * quantities calculated by the server (POST /calculate) are sent: when the store could not confirm
 * the current plan, nothing is added and the visitor can try again.
 *
 * @module components/cart
 */

import { h, uid, button } from '../app/dom.js';
import { __, _n, sprintf } from '../app/i18n.js';
import { uuid4 } from '../app/plan.js';
import { openDialog } from './modal.js';

/**
 * Notifies the theme / WooCommerce mini carts (classic fragments + Blocks event).
 *
 * @param {Object} fragments Fragments from POST /cart.
 * @param {string} cartHash  Cart hash.
 */
export function notifyMiniCart( fragments, cartHash ) {
	const $ = typeof window !== 'undefined' ? window.jQuery : null;
	if ( typeof $ === 'function' ) {
		try {
			$( document.body ).trigger( 'added_to_cart', [ fragments && typeof fragments === 'object' ? fragments : {}, typeof cartHash === 'string' ? cartHash : '', null ] );
			$( document.body ).trigger( 'wc_fragment_refresh' );
		} catch ( e ) {
			// A theme handler failed; the cart itself was updated on the server.
		}
	}
	try {
		document.body.dispatchEvent( new CustomEvent( 'wc-blocks_added_to_cart', { bubbles: true, cancelable: true } ) );
	} catch ( e ) {
		// CustomEvent unsupported: nothing else to notify.
	}
}

/**
 * "Name (Variant)" of a cart item, translatable as a whole (word order and brackets vary by language).
 *
 * @param {Object} item Item { name, variant }.
 * @return {string} Name.
 */
export function itemName( item ) {
	if ( ! item ) {
		return '';
	}
	/* translators: 1: product name, 2: chosen variant (e.g. strength or pen format). */
	return item.variant ? sprintf( __( '%1$s (%2$s)' ), item.name, item.variant ) : item.name;
}

/**
 * Error messages of one result entry.
 *
 * @param {Object} result Result.
 * @return {string[]} Messages.
 */
function messagesOf( result ) {
	const list = Array.isArray( result && result.errors ) ? result.errors : [];
	const out = list.map( ( e ) => ( typeof e === 'string' ? e : e && ( e.message || e.code ) ) ).filter( Boolean );
	return out.length > 0 ? out : [ __( 'This item could not be added.' ) ];
}

/**
 * Conflict dialog: one choice per line that is already in the cart.
 *
 * @param {Array}    conflicts   Results with status conflict.
 * @param {Map}      items       line ID => item.
 * @param {Function} returnFocus () => element focused when the dialog closes (optional).
 * @return {Promise<Object|null>} line ID => increase|set|skip, or null when cancelled.
 */
export function conflictDialog( conflicts, items, returnFocus = null ) {
	return new Promise( ( resolve ) => {
		let answer = null;
		const groups = conflicts.map( ( conflict ) => {
			const item = items.get( conflict.line_id ) || { name: '', quantity: 0 };
			const before = Number.isInteger( conflict.quantity_before ) ? conflict.quantity_before : 0;
			const name = uid( 'conflict' );
			const legendId = uid( 'legend' );
			const option = ( value, label ) =>
				h( 'label', { class: 'arp-radio' }, h( 'input', { type: 'radio', name, value } ), h( 'span', null, label ) );
			return {
				lineId: conflict.line_id,
				name,
				el: h(
					'fieldset',
					{ class: 'arp-conflict', 'aria-labelledby': legendId },
					h( 'legend', { id: legendId, class: 'arp-conflict__legend' }, itemName( item ) ),
					h(
						'p',
						{ class: 'arp-conflict__text' },
						/* translators: 1: quantity already in the cart, 2: planned quantity. */
						sprintf( __( 'Your cart already contains %1$s. This protocol adds %2$s.' ), String( before ), String( item.quantity ) )
					),
					/* translators: 1: quantity in cart, 2: planned quantity, 3: sum. */
					option( 'increase', sprintf( __( 'Add to existing quantity (%1$s + %2$s = %3$s)' ), String( before ), String( item.quantity ), String( before + item.quantity ) ) ),
					/* translators: %s: planned quantity. */
					option( 'set', sprintf( __( 'Replace with planned quantity (%s)' ), String( item.quantity ) ) ),
					option( 'skip', __( 'Skip this item' ) )
				),
			};
		} );
		const error = h( 'p', { class: 'arp-field__error', role: 'alert', hidden: true } );
		const form = h(
			'form',
			{ class: 'arp-form' },
			h( 'p', null, __( 'Some items are already in your cart. Choose what to do with each one — nothing is changed until you continue.' ) ),
			...groups.map( ( g ) => g.el ),
			error
		);
		const submit = ( dlg ) => {
			const choices = {};
			let missing = null;
			groups.forEach( ( g ) => {
				const checked = g.el.querySelector( 'input:checked' );
				if ( checked ) {
					choices[ g.lineId ] = checked.value;
				} else if ( ! missing ) {
					missing = g.el.querySelector( 'input' );
				}
			} );
			if ( missing ) {
				error.textContent = __( 'Choose an option for every item.' );
				error.hidden = false;
				missing.focus();
				return;
			}
			answer = choices;
			dlg.close( choices );
		};
		form.addEventListener( 'submit', ( event ) => event.preventDefault() );
		openDialog( {
			title: __( 'Already in your cart' ),
			size: 'md',
			content: form,
			returnFocus,
			onClose: () => resolve( answer ),
			actions: ( dlg ) => [
				button( { label: __( 'Cancel' ), onClick: () => dlg.close( null ) } ),
				button( { label: __( 'Continue' ), variant: 'primary', onClick: () => submit( dlg ) } ),
			],
		} );
	} );
}

/**
 * Creates the cart flow controller.
 *
 * @param {Object}   deps                  Dependencies.
 * @param {Object}   deps.api              API client.
 * @param {Function} deps.getItems         () => [{ lineId, name, variant, product_id, variation_id, variation_attributes, quantity, source }].
 * @param {Function} deps.flush            async () => boolean — waits for the authoritative calculation;
 *                                         false when the store could not calculate the plan.
 * @param {Function} deps.setState         ( cartState ) => void.
 * @param {Function} deps.setLineErrors    ( Map lineId => string[] ) => void.
 * @param {Function} deps.announce         ( message, important ) => void.
 * @param {Function} deps.returnFocus      () => element that receives focus when a dialog of the flow closes.
 * @return {{start: Function, retry: Function, skipErrors: Function}} Flow.
 */
export function createCartFlow( deps ) {
	let retryAction = null;
	let skipAction = null;
	let running = false;

	const toLine = ( item, onExisting ) => ( {
		line_id: item.lineId,
		product_id: item.product_id,
		variation_id: item.variation_id || 0,
		variation_attributes: { ...( item.variation_attributes || {} ) },
		quantity: item.quantity,
		on_existing: onExisting,
	} );

	const lineErrors = ( results, items ) => {
		const errors = new Map();
		const lines = [];
		( results || [] )
			.filter( ( r ) => r && r.status === 'error' )
			.forEach( ( r ) => {
				const messages = messagesOf( r );
				errors.set( r.line_id, messages );
				const item = items.get( r.line_id );
				lines.push( { id: r.line_id, name: item ? item.name : r.line_id, messages } );
			} );
		return { errors, lines };
	};

	const commit = async ( request, items ) => {
		deps.setState( { phase: 'adding' } );
		let response;
		try {
			response = await deps.api.addToCart( request );
		} catch ( e ) {
			const data = e && e.data && typeof e.data === 'object' ? e.data : {};
			if ( Array.isArray( data.results ) ) {
				const { errors, lines } = lineErrors( data.results, items );
				deps.setLineErrors( errors );
				retryAction = () => start();
				deps.setState( { phase: 'error', message: e.message, lines, canRetry: true } );
			} else {
				// Same request_id on retry: the server answers a processed request from its log.
				retryAction = () => commit( request, items );
				deps.setState( { phase: 'error', message: e.message, canRetry: true } );
			}
			deps.announce( __( 'Nothing was added to your cart.' ), true );
			return;
		}
		if ( response && typeof response.nonce === 'string' ) {
			deps.api.setNonce( response.nonce );
		}
		if ( ! response || response.ok === false ) {
			const { errors, lines } = lineErrors( response && response.results, items );
			deps.setLineErrors( errors );
			retryAction = () => start();
			deps.setState( { phase: 'error', lines, canRetry: true, message: __( 'The store rejected the request. Your cart was not changed.' ) } );
			deps.announce( __( 'Nothing was added to your cart.' ), true );
			return;
		}

		retryAction = null;
		const details = [];
		let added = 0;
		( response.results || [] ).forEach( ( r ) => {
			const item = items.get( r.line_id );
			const name = itemName( item );
			if ( r.status === 'added' ) {
				added++;
				/* translators: 1: quantity, 2: product. */
				details.push( sprintf( __( '%1$s × %2$s added' ), String( item ? item.quantity : r.quantity_after ), name ) );
			} else if ( r.status === 'updated' ) {
				added++;
				/* translators: 1: product, 2: new quantity in the cart. */
				details.push( sprintf( __( '%1$s: quantity in your cart is now %2$s' ), name, String( r.quantity_after ) ) );
			} else if ( r.status === 'skipped' ) {
				/* translators: %s: product. */
				details.push( sprintf( __( '%s: skipped' ), name ) );
			}
		} );
		deps.setLineErrors( new Map() );
		const title = added > 0 ? __( 'Added to your cart' ) : __( 'Your cart was not changed' );
		deps.setState( { phase: 'done', title, details, cart: response.cart || {} } );
		if ( added > 0 ) {
			notifyMiniCart( response.fragments, response.cart_hash );
		}
		/* translators: %d: number of items. */
		deps.announce( added > 0 ? sprintf( _n( '%d item was added to your cart.', '%d items were added to your cart.', added ), added ) : title, false );
	};

	/**
	 * Starts the flow.
	 *
	 * @param {Set<string>} exclude Line IDs to leave out.
	 */
	const start = async ( exclude = new Set() ) => {
		if ( running ) {
			return;
		}
		running = true;
		try {
			deps.setState( { phase: 'checking' } );
			const calculated = await deps.flush();
			const list = deps.getItems().filter( ( item ) => ! exclude.has( item.lineId ) );
			const items = new Map( list.map( ( item ) => [ item.lineId, item ] ) );
			if ( calculated === false || list.some( ( item ) => item.source !== 'server' ) ) {
				// Never add browser-preview quantities the server has not confirmed.
				retryAction = () => start( exclude );
				skipAction = null;
				const message = __( 'The store could not confirm the quantities right now, so nothing was added to your cart. Please try again in a moment.' );
				deps.setState( { phase: 'error', title: __( 'Quantities not confirmed' ), message, canRetry: true } );
				deps.announce( message, true );
				return;
			}
			if ( list.length === 0 ) {
				deps.setState( { phase: 'error', title: __( 'Nothing to add yet' ), message: __( 'Enter your research quantities so the planner can calculate the units to buy.' ) } );
				return;
			}
			deps.setLineErrors( new Map() );

			let dry;
			try {
				dry = await deps.api.addToCart( { request_id: uuid4(), dry_run: true, lines: list.map( ( item ) => toLine( item, null ) ) } );
			} catch ( e ) {
				retryAction = () => start( exclude );
				const data = e && e.data && typeof e.data === 'object' ? e.data : {};
				const { errors, lines } = lineErrors( data.results, items );
				deps.setLineErrors( errors );
				deps.setState( { phase: 'error', message: e.message, lines, canRetry: true } );
				deps.announce( e.message, true );
				return;
			}
			if ( dry && typeof dry.nonce === 'string' ) {
				deps.api.setNonce( dry.nonce );
			}
			const results = dry && Array.isArray( dry.results ) ? dry.results : [];
			const { errors, lines } = lineErrors( results, items );
			if ( errors.size > 0 || ( dry && dry.ok === false && results.length === 0 ) ) {
				deps.setLineErrors( errors );
				const others = list.length - errors.size;
				skipAction = others > 0 ? () => start( new Set( [ ...exclude, ...errors.keys() ] ) ) : null;
				retryAction = () => start( exclude );
				deps.setState( {
					phase: 'error',
					title: __( 'Some items cannot be added' ),
					message: __( 'Nothing was added yet. Fix or remove these items, or add the others.' ),
					lines,
					canRetry: true,
					canSkipErrors: others > 0,
					/* translators: %d: number of items. */
					skipLabel: sprintf( _n( 'Add the other %d item', 'Add the other %d items', others ), others ),
				} );
				deps.announce( __( 'Some items cannot be added to your cart.' ), true );
				return;
			}

			let choices = {};
			const conflicts = results.filter( ( r ) => r.status === 'conflict' );
			if ( conflicts.length > 0 ) {
				deps.setState( { phase: 'idle' } );
				const answer = await conflictDialog( conflicts, items, typeof deps.returnFocus === 'function' ? deps.returnFocus : null );
				if ( ! answer ) {
					deps.announce( __( 'Nothing was added to your cart.' ), false );
					return;
				}
				choices = answer;
			}
			const request = {
				request_id: uuid4(),
				dry_run: false,
				lines: list.map( ( item ) => toLine( item, choices[ item.lineId ] || null ) ),
			};
			if ( request.lines.every( ( line ) => line.on_existing === 'skip' ) ) {
				deps.setState( { phase: 'done', title: __( 'Your cart was not changed' ), details: [], cart: {} } );
				return;
			}
			await commit( request, items );
		} finally {
			running = false;
		}
	};

	return {
		start: () => start(),
		retry: () => ( retryAction ? retryAction() : start() ),
		skipErrors: () => ( skipAction ? skipAction() : start() ),
	};
}
