/**
 * Accessible dialogs: role="dialog" + aria-modal, labelled by the title, focus trap, Escape to
 * close, focus restore and an inert background. Supports stacked dialogs.
 *
 * @module components/modal
 */

import { h, uid, button } from '../app/dom.js';
import { __ } from '../app/i18n.js';
import { trapTab, focusableIn, focusElement, inertOthers } from '../app/a11y.js';

let host = null;
const stack = [];
let restoreInert = null;
let documentKeysBound = false;

/**
 * The control the visitor activated last (click or tap), with the time. WebKit (Safari) does not
 * focus a clicked button, so `document.activeElement` is not the dialog's opener there; the last
 * activated control is used instead when it was activated just before the dialog opened.
 */
const lastActivation = { el: null, at: 0 };
if ( typeof document !== 'undefined' ) {
	document.addEventListener(
		'click',
		( event ) => {
			const target = event.target && typeof event.target.closest === 'function' ? event.target.closest( 'button, a[href], [role="button"], summary, input, select' ) : null;
			if ( target ) {
				lastActivation.el = target;
				lastActivation.at = Date.now();
			}
		},
		true
	);
}

/**
 * The element focus returns to when a dialog closes: the control just activated when there is one
 * (WebKit leaves focus on <body>, on an earlier field, or moves it to the nearest focusable
 * ancestor of the clicked button, such as a theme's `#content` with tabindex -1), else the focused
 * element.
 *
 * @return {Element|null} Opener.
 */
function currentOpener() {
	const active = document.activeElement;
	const recent = lastActivation.el && lastActivation.el.isConnected && Date.now() - lastActivation.at < 2000 ? lastActivation.el : null;
	if ( recent && active !== recent && ! ( active && recent.contains( active ) ) ) {
		return recent;
	}
	return active;
}

/**
 * Keeps Escape and Tab working for the top dialog when focus is outside it — for example after
 * the dialog re-rendered the focused button (it is detached and focus falls back to <body>).
 * Events inside the dialog are handled by the overlay's own listener.
 *
 * @param {KeyboardEvent} event keydown event.
 */
function onDocumentKeydown( event ) {
	const top = stack[ stack.length - 1 ];
	if ( ! top || top.overlay.contains( event.target ) ) {
		return;
	}
	if ( event.key === 'Escape' ) {
		event.preventDefault();
		top.close( null );
	} else if ( event.key === 'Tab' ) {
		trapTab( top.el, event );
	}
}

/**
 * Container for dialogs, appended to <body> and carrying the planner's design tokens.
 *
 * @param {HTMLElement|null} tokensFrom Element whose inline custom properties are copied.
 * @return {HTMLElement} Host.
 */
export function modalHost( tokensFrom = null ) {
	if ( host && host.isConnected ) {
		return host;
	}
	host = h( 'div', { class: 'arp-app arp-modal-host' } );
	const source = tokensFrom || document.querySelector( '.arp-planner' );
	if ( source && source.getAttribute( 'style' ) ) {
		host.setAttribute( 'style', source.getAttribute( 'style' ) );
	}
	document.body.appendChild( host );
	return host;
}

/**
 * Opens a dialog.
 *
 * @param {Object}             options              Options.
 * @param {string}             options.title        Title (labels the dialog).
 * @param {Node|Function}      options.content      Content node, or ( api ) => node.
 * @param {Array}              options.actions      Footer buttons (nodes) or ( api ) => nodes.
 * @param {string}             options.size         sm | md | lg.
 * @param {string}             options.role         dialog | alertdialog.
 * @param {Function}           options.onClose      Called after closing with the close value.
 * @param {HTMLElement|Function|null} options.returnFocus Element to focus after closing, or a
 *                                                  function returning it at close time (default: opener).
 * @param {string}             options.initialFocus Selector of the element to focus first.
 * @param {string}             options.description  Optional text that describes the dialog.
 * @param {string}             options.describedBy  ID of an element of the content that describes the
 *                                                  dialog (alert dialogs: the message).
 * @return {{close: Function, el: HTMLElement, body: HTMLElement}} Dialog API.
 */
export function openDialog( options ) {
	const opener = currentOpener();
	const titleId = uid( 'dlg-title' );
	const descId = options.description ? uid( 'dlg-desc' ) : null;
	const target = modalHost();
	let closed = false;

	const body = h( 'div', { class: 'arp-dialog__body' } );
	const footer = h( 'div', { class: 'arp-dialog__footer' } );
	const dialog = h(
		'div',
		{
			class: [ 'arp-dialog', 'arp-dialog--' + ( options.size || 'md' ) ],
			role: options.role || 'dialog',
			'aria-modal': 'true',
			'aria-labelledby': titleId,
			'aria-describedby': descId || options.describedBy || null,
			tabindex: '-1',
		},
		h(
			'div',
			{ class: 'arp-dialog__header' },
			h( 'h2', { class: 'arp-dialog__title', id: titleId }, options.title ),
			button( { label: __( 'Close' ), iconName: 'close', variant: 'ghost', iconOnly: true, onClick: () => api.close( null ), cls: 'arp-dialog__close' } )
		),
		descId ? h( 'p', { id: descId, class: 'arp-dialog__desc' }, options.description ) : null,
		body,
		footer
	);
	const overlay = h( 'div', { class: 'arp-modal' }, h( 'div', { class: 'arp-modal__backdrop', onClick: () => api.close( null ) } ), dialog );

	const api = {
		el: dialog,
		body,
		footer,
		/**
		 * Closes the dialog.
		 *
		 * @param {*} value Close value passed to onClose.
		 */
		close( value ) {
			if ( closed ) {
				return;
			}
			closed = true;
			overlay.remove();
			const index = stack.indexOf( api );
			if ( index >= 0 ) {
				stack.splice( index, 1 );
			}
			if ( stack.length > 0 ) {
				const top = stack[ stack.length - 1 ];
				top.overlay.removeAttribute( 'inert' );
			} else {
				if ( restoreInert ) {
					restoreInert();
					restoreInert = null;
				}
				document.documentElement.classList.remove( 'arp-modal-open' );
			}
			const preferred = typeof options.returnFocus === 'function' ? options.returnFocus() : options.returnFocus;
			const back = preferred && preferred.isConnected ? preferred : opener;
			if ( back && back.isConnected && typeof back.focus === 'function' && back !== document.body ) {
				focusElement( back, { preventScroll: true } );
			} else if ( stack.length > 0 ) {
				// The opener was re-rendered inside the dialog below: keep focus in that dialog.
				focusElement( stack[ stack.length - 1 ].el, { preventScroll: true } );
			}
			if ( typeof options.onClose === 'function' ) {
				options.onClose( value );
			}
		},
		/**
		 * Replaces the body content.
		 *
		 * @param {Node} node Content.
		 */
		setContent( node ) {
			body.replaceChildren( node );
		},
		/**
		 * Replaces the footer buttons.
		 *
		 * @param {Node[]} nodes Buttons.
		 */
		setActions( nodes ) {
			footer.replaceChildren( ...nodes.filter( Boolean ) );
			footer.hidden = footer.childNodes.length === 0;
		},
		overlay,
	};

	const content = typeof options.content === 'function' ? options.content( api ) : options.content;
	if ( content ) {
		body.appendChild( content );
	}
	const actions = typeof options.actions === 'function' ? options.actions( api ) : options.actions || [];
	api.setActions( actions );

	overlay.addEventListener( 'keydown', ( event ) => {
		if ( event.key === 'Escape' ) {
			event.stopPropagation();
			api.close( null );
			return;
		}
		trapTab( dialog, event );
	} );

	if ( ! documentKeysBound ) {
		documentKeysBound = true;
		document.addEventListener( 'keydown', onDocumentKeydown );
	}
	if ( stack.length > 0 ) {
		stack[ stack.length - 1 ].overlay.setAttribute( 'inert', '' );
	} else {
		restoreInert = inertOthers( target );
		document.documentElement.classList.add( 'arp-modal-open' );
	}
	stack.push( api );
	target.appendChild( overlay );

	const first = options.initialFocus ? dialog.querySelector( options.initialFocus ) : null;
	const items = focusableIn( body );
	focusElement( first || items[ 0 ] || dialog, { preventScroll: true } );
	return api;
}

/**
 * Confirmation dialog (alertdialog described by its message, so screen readers announce the
 * consequence together with the title; Cancel has the initial focus).
 *
 * @param {Object} options { title, message, confirmLabel, cancelLabel, danger, returnFocus }.
 * @return {Promise<boolean>} Confirmed.
 */
export function confirmDialog( options ) {
	return new Promise( ( resolve ) => {
		const messageId = uid( 'dlg-msg' );
		openDialog( {
			title: options.title,
			size: 'sm',
			role: 'alertdialog',
			content: h( 'p', { class: 'arp-dialog__text', id: messageId }, options.message ),
			describedBy: messageId,
			returnFocus: options.returnFocus || null,
			onClose: ( value ) => resolve( value === true ),
			initialFocus: '.arp-btn--confirm-cancel',
			actions: ( dlg ) => [
				button( { label: options.cancelLabel || __( 'Cancel' ), variant: 'secondary', cls: 'arp-btn--confirm-cancel', onClick: () => dlg.close( false ) } ),
				button( { label: options.confirmLabel || __( 'Confirm' ), variant: options.danger ? 'danger' : 'primary', onClick: () => dlg.close( true ) } ),
			],
		} );
	} );
}

/**
 * Single text field dialog (rename etc.).
 *
 * @param {Object} options { title, label, value, maxLength, confirmLabel }.
 * @return {Promise<string|null>} Value or null when cancelled.
 */
export function promptDialog( options ) {
	return new Promise( ( resolve ) => {
		const inputId = uid( 'prompt' );
		const input = h( 'input', { id: inputId, class: 'arp-input', type: 'text', value: options.value || '', maxlength: String( options.maxLength || 190 ), autocomplete: 'off' } );
		let result = null;
		const form = h(
			'form',
			{
				class: 'arp-form',
				onSubmit: ( event ) => {
					event.preventDefault();
					result = input.value.trim();
					dlg.close( result );
				},
			},
			h( 'label', { class: 'arp-label', for: inputId }, options.label ),
			input
		);
		const dlg = openDialog( {
			title: options.title,
			size: 'sm',
			content: form,
			onClose: () => resolve( result ),
			actions: ( d ) => [
				button( { label: __( 'Cancel' ), onClick: () => d.close( null ) } ),
				button( { label: options.confirmLabel || __( 'Save' ), variant: 'primary', onClick: () => form.requestSubmit ? form.requestSubmit() : form.dispatchEvent( new Event( 'submit', { cancelable: true } ) ) } ),
			],
		} );
		input.select();
	} );
}

/**
 * Small heading + paragraph helper for dialog content.
 *
 * @param {string} title Heading.
 * @param {...*}   body  Content.
 * @return {HTMLElement} Section.
 */
export function dialogSection( title, ...body ) {
	return h( 'section', { class: 'arp-dialog__section' }, title ? h( 'h3', { class: 'arp-dialog__subtitle' }, title ) : null, ...body );
}

