/**
 * Entry choice of the Protocol Builder (CHANGE-1.7.1 §2.2): two buttons between the protocol
 * toolbar and the step tabs, "Pre-built protocols" (the ready-made protocols written by the store)
 * and "Make your own protocol" (the two steps). Shown only while the visitor can see a pre-built
 * protocol and no shared protocol is open; app.js decides that, the view shown and the start view.
 *
 * Pattern: a labelled group of two toggle buttons (`aria-pressed`, exactly one pressed). Not a
 * tablist: the step tabs stay the only tablist, so there are no tabs inside tabs, no roving
 * tabindex and no arrow keys. The buttons are created once and patched in place, so a focused
 * button keeps focus. The component never moves focus, announces or stores anything itself.
 *
 * @module components/entry-choice
 */

import { h } from '../app/dom.js';
import { __ } from '../app/i18n.js';

/** The two views, in button order (also the Tab order). */
export const ENTRY_VIEWS = Object.freeze( [ 'prebuilt', 'own' ] );

/**
 * A view name, or null for anything else (exact strings only: a stored value of another shape
 * reads as no choice).
 *
 * @param {*} value Value.
 * @return {'prebuilt'|'own'|null} View.
 */
export function normalizeEntryView( value ) {
	return value === 'prebuilt' || value === 'own' ? value : null;
}

/**
 * View a page load starts on (CHANGE-1.7.1 §2.6), first match wins; the deep-link order mirrors
 * app.js handleHash():
 *
 * 1. no pre-built protocol to see → own (no buttons);
 * 2. #share= → own (no buttons while shared); 3. #add= → own; 4. #protocol= (even empty) → own;
 * 5. a pre-built protocol link → prebuilt, except #store-protocol-edit= (managers) → own;
 * 6. #plan → own;
 * 7. products preselected by the shortcode that will be added (the workspace has no items) → own;
 * 8. the visitor's remembered choice;
 * 9. an untouched workspace → prebuilt;
 * 10. otherwise (the workspace has content) → own.
 *
 * A shortcode category alone does not affect it.
 *
 * @param {Object}  input            Input.
 * @param {boolean} input.available  The visitor can see a pre-built protocol (provisional).
 * @param {Object}  input.deep       parseDeepLink() result { add, share, protocol, store }.
 * @param {number}  input.step       stepFromHash() of the address (1: #plan).
 * @param {number}  input.preselect  Number of products the shortcode preselects.
 * @param {boolean} input.hasLines   The workspace has items.
 * @param {boolean} input.untouched  isUntouchedWorkspace() of the workspace.
 * @param {*}       input.remembered Stored choice (normalizeEntryView() applied here as well).
 * @return {'prebuilt'|'own'} View.
 */
export function startView( input ) {
	const i = input && typeof input === 'object' ? input : {};
	const deep = i.deep && typeof i.deep === 'object' ? i.deep : {};
	if ( ! i.available ) {
		return 'own';
	}
	if ( deep.share || deep.add || typeof deep.protocol === 'string' ) {
		return 'own';
	}
	if ( deep.store ) {
		return deep.store.kind === 'edit' ? 'own' : 'prebuilt';
	}
	if ( i.step === 1 ) {
		return 'own';
	}
	if ( i.preselect > 0 && ! i.hasLines ) {
		return 'own';
	}
	const remembered = normalizeEntryView( i.remembered );
	if ( remembered !== null ) {
		return remembered;
	}
	return i.untouched ? 'prebuilt' : 'own';
}

/**
 * Creates the entry choice (hidden until app.js shows it).
 *
 * @param {Object}   options          Options.
 * @param {Object}   options.ids      { prebuilt, own }: IDs of the two view containers (aria-controls).
 * @param {Function} options.onSelect ( view ) => void, on every activation (also of the pressed button).
 * @return {{el: HTMLElement, update: Function}} Entry choice.
 */
export function createEntryChoice( options ) {
	const ids = options && options.ids && typeof options.ids === 'object' ? options.ids : {};
	const select = ( view ) => {
		if ( options && typeof options.onSelect === 'function' ) {
			options.onSelect( view );
		}
	};
	const labels = {
		prebuilt: __( 'Pre-built protocols' ),
		own: __( 'Make your own protocol' ),
	};
	const buttons = ENTRY_VIEWS.map( ( view ) =>
		h(
			'button',
			{
				type: 'button',
				class: 'arp-entry__btn',
				'data-view': view,
				'aria-pressed': view === 'own' ? 'true' : 'false',
				'aria-controls': typeof ids[ view ] === 'string' && ids[ view ] !== '' ? ids[ view ] : null,
				onClick: () => select( view ),
			},
			h( 'span', { class: 'arp-entry__label' }, labels[ view ] )
		)
	);
	const el = h( 'div', { class: 'arp-entry', role: 'group', 'aria-label': __( 'Choose how to build your protocol' ), hidden: true }, buttons );

	return {
		el,
		/**
		 * Shows or hides the choice and presses the button of `view`; nothing else changes.
		 *
		 * @param {Object}  state      State.
		 * @param {boolean} state.shown Show the choice.
		 * @param {string}  state.view  'prebuilt' | 'own'.
		 */
		update( { shown, view } ) {
			el.hidden = ! shown;
			buttons.forEach( ( btn, i ) => {
				const pressed = ENTRY_VIEWS[ i ] === view ? 'true' : 'false';
				if ( btn.getAttribute( 'aria-pressed' ) !== pressed ) {
					btn.setAttribute( 'aria-pressed', pressed );
				}
			} );
		},
	};
}
