/**
 * Accessibility helpers: live-region announcements, focus management, focus trap, inert background.
 *
 * @module a11y
 */

const FOCUSABLE = [
	'a[href]',
	'area[href]',
	'button:not([disabled])',
	'input:not([disabled]):not([type="hidden"])',
	'select:not([disabled])',
	'textarea:not([disabled])',
	'iframe',
	'summary',
	'[contenteditable="true"]',
	'[tabindex]:not([tabindex="-1"])',
].join( ',' );

/**
 * Creates polite and assertive live regions inside `host`.
 *
 * @param {HTMLElement} host Container.
 * @return {{announce: Function}} Announcer.
 */
export function createAnnouncer( host ) {
	const make = ( politeness ) => {
		const region = document.createElement( 'div' );
		region.className = 'arp-sr-only';
		region.setAttribute( 'aria-live', politeness );
		region.setAttribute( 'aria-atomic', 'true' );
		if ( politeness === 'assertive' ) {
			region.setAttribute( 'role', 'alert' );
		}
		host.appendChild( region );
		return region;
	};
	const polite = make( 'polite' );
	const assertive = make( 'assertive' );
	let timer = null;
	return {
		/**
		 * Announces a message (re-announces identical messages).
		 *
		 * @param {string}  message   Message.
		 * @param {boolean} important Use the assertive region.
		 */
		announce( message, important = false ) {
			const region = important ? assertive : polite;
			region.textContent = '';
			clearTimeout( timer );
			timer = setTimeout( () => {
				region.textContent = String( message || '' );
			}, 60 );
		},
	};
}

/**
 * Visible, focusable descendants in DOM order.
 *
 * @param {HTMLElement} container Container.
 * @return {HTMLElement[]} Elements.
 */
export function focusableIn( container ) {
	return Array.from( container.querySelectorAll( FOCUSABLE ) ).filter( ( el ) => {
		if ( el.closest( '[inert]' ) || el.getAttribute( 'aria-hidden' ) === 'true' ) {
			return false;
		}
		return el.getClientRects().length > 0;
	} );
}

/**
 * Moves focus to an element (makes it programmatically focusable when needed).
 *
 * @param {HTMLElement|null} el      Element.
 * @param {Object}           options Focus options.
 */
export function focusElement( el, options = { preventScroll: false } ) {
	if ( ! el || typeof el.focus !== 'function' ) {
		return;
	}
	if ( ! el.matches( FOCUSABLE ) && ! el.hasAttribute( 'tabindex' ) ) {
		el.setAttribute( 'tabindex', '-1' );
	}
	try {
		el.focus( options );
	} catch ( e ) {
		el.focus();
	}
}

/**
 * Keeps Tab / Shift+Tab inside a container.
 *
 * @param {HTMLElement}   container Container.
 * @param {KeyboardEvent} event     keydown event.
 */
export function trapTab( container, event ) {
	if ( event.key !== 'Tab' ) {
		return;
	}
	const items = focusableIn( container );
	if ( items.length === 0 ) {
		event.preventDefault();
		focusElement( container );
		return;
	}
	const first = items[ 0 ];
	const last = items[ items.length - 1 ];
	const active = container.ownerDocument.activeElement;
	if ( event.shiftKey && ( active === first || ! container.contains( active ) ) ) {
		event.preventDefault();
		last.focus();
	} else if ( ! event.shiftKey && ( active === last || ! container.contains( active ) ) ) {
		event.preventDefault();
		first.focus();
	}
}

/**
 * Makes every child of <body> except `keep` inert (and restores it).
 *
 * @param {HTMLElement} keep Element that stays interactive.
 * @return {Function} Restore function.
 */
export function inertOthers( keep ) {
	const changed = [];
	Array.from( document.body.children ).forEach( ( el ) => {
		if ( el === keep || el.contains( keep ) || el.hasAttribute( 'inert' ) || el.tagName === 'SCRIPT' || el.tagName === 'STYLE' ) {
			return;
		}
		el.setAttribute( 'inert', '' );
		changed.push( el );
	} );
	return () => changed.forEach( ( el ) => el.removeAttribute( 'inert' ) );
}

/**
 * How far to scroll the window so a focused element is not hidden behind bars fixed to the top or
 * bottom of the viewport (WCAG 2.4.11 Focus Not Obscured): the mobile summary bar, toasts, theme
 * toolbars and sticky headers. A focused element entirely outside the viewport (a browser that did
 * not reveal it) is brought into the free area too. Pure geometry, so it can be unit-tested.
 *
 * @param {{top: number, bottom: number, left: number, right: number}} rect Focused element.
 * @param {Array<{top: number, bottom: number, left: number, right: number, edge: string}>} bars
 *   Fixed areas; edge 'top' (covers the viewport from its top) or 'bottom'.
 * @param {number} viewport Viewport height.
 * @param {number} margin   Space kept between the element and a bar.
 * @return {number} Pixels for window.scrollBy() (positive = down; 0 when nothing covers it).
 */
export function clearanceScroll( rect, bars, viewport, margin = 12 ) {
	let topLimit = null;
	let bottomLimit = null;
	for ( const bar of bars ) {
		if ( ! bar || bar.right <= rect.left || bar.left >= rect.right || bar.bottom <= bar.top ) {
			continue;
		}
		if ( bar.edge === 'top' ) {
			topLimit = Math.max( topLimit ?? 0, bar.bottom );
		} else {
			bottomLimit = Math.min( bottomLimit ?? viewport, bar.top );
		}
	}
	const top = topLimit === null ? 0 : topLimit + margin;
	// Entirely below or above the viewport (a browser that did not reveal the focused control,
	// e.g. WebKit for some fields): bring it into the area left free by the bars.
	if ( rect.top >= viewport ) {
		const down = rect.bottom - ( bottomLimit ?? viewport ) + margin;
		return Math.max( 0, Math.ceil( Math.min( down, rect.top - top ) ) );
	}
	if ( rect.bottom <= 0 ) {
		return Math.floor( rect.top - top );
	}
	if ( bottomLimit !== null && rect.bottom > bottomLimit - margin && rect.top < viewport ) {
		const down = rect.bottom - bottomLimit + margin;
		// Never push the element's top under a top bar: tall elements keep their top visible.
		return Math.max( 0, Math.ceil( Math.min( down, rect.top - top ) ) );
	}
	if ( topLimit !== null && rect.top < top && rect.bottom > 0 ) {
		return Math.floor( rect.top - top );
	}
	return 0;
}

/**
 * Whether the user prefers reduced motion.
 *
 * @return {boolean} Reduced motion.
 */
export function prefersReducedMotion() {
	return typeof window !== 'undefined' && typeof window.matchMedia === 'function' && window.matchMedia( '(prefers-reduced-motion: reduce)' ).matches;
}

/**
 * Scrolls an element into view, respecting reduced motion.
 *
 * @param {HTMLElement} el Element.
 */
export function scrollIntoViewSafe( el ) {
	if ( el && typeof el.scrollIntoView === 'function' ) {
		el.scrollIntoView( { behavior: prefersReducedMotion() ? 'auto' : 'smooth', block: 'nearest' } );
	}
}
