/**
 * Formatting and parsing helpers.
 *
 * Money is formatted from canonical decimal STRINGS with the WooCommerce currency settings
 * (symbol, position, decimals, separators) using string arithmetic only — never binary floats and
 * never a hardcoded currency. Number inputs accept the site decimal separator and reject input that
 * contains a thousands separator (ambiguous: "1,500" could be 1500 or 1.5). Dates (Y-m-d) are
 * formatted with Intl in UTC so no time zone can shift a calendar date.
 *
 * @module format
 */

import { __, sprintf } from './i18n.js';
import { decimalError, canonicalAmount } from './units.js';
import { validationText } from './messages.js';

const DECIMAL_PATTERN = /^(\d+)(?:\.(\d+))?$/;
const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;
const POSITIONS = [ 'left', 'right', 'left_space', 'right_space' ];
const NBSP = ' ';

/**
 * Normalizes WooCommerce currency settings (snake_case from PHP or camelCase).
 *
 * @param {Object} raw Raw settings.
 * @return {{code: string, symbol: string, position: string, decimals: number, decimalSeparator: string, thousandSeparator: string}} Currency.
 */
export function normalizeCurrency( raw ) {
	const c = raw && typeof raw === 'object' ? raw : {};
	const decimalsRaw = Number( c.decimals );
	const decimals = Number.isInteger( decimalsRaw ) && decimalsRaw >= 0 && decimalsRaw <= 8 ? decimalsRaw : 2;
	const pick = ( a, b, fallback ) => {
		if ( typeof a === 'string' ) {
			return a;
		}
		return typeof b === 'string' ? b : fallback;
	};
	let decimalSeparator = pick( c.decimal_separator, c.decimalSeparator, '.' );
	if ( decimalSeparator === '' ) {
		decimalSeparator = '.';
	}
	let thousandSeparator = pick( c.thousand_separator, c.thousandSeparator, ',' );
	if ( thousandSeparator === decimalSeparator ) {
		thousandSeparator = '';
	}
	return {
		code: typeof c.code === 'string' ? c.code : '',
		symbol: typeof c.symbol === 'string' ? c.symbol : '',
		position: POSITIONS.includes( c.position ) ? c.position : 'left',
		decimals,
		decimalSeparator,
		thousandSeparator,
	};
}

/**
 * Adds one to a string of ASCII digits.
 *
 * @param {string} digits Digits.
 * @return {string} Incremented digits.
 */
function incrementDigits( digits ) {
	const out = digits.split( '' );
	for ( let i = out.length - 1; i >= 0; i-- ) {
		if ( out[ i ] === '9' ) {
			out[ i ] = '0';
		} else {
			out[ i ] = String.fromCharCode( out[ i ].charCodeAt( 0 ) + 1 );
			return out.join( '' );
		}
	}
	return '1' + out.join( '' );
}

/**
 * Rounds a non-negative canonical decimal string half-up to exactly `decimals` places.
 *
 * @param {string} amount   Canonical decimal ("1900000", "12.345").
 * @param {number} decimals Decimal places (0–8).
 * @return {{int: string, frac: string}} Rounded parts.
 */
export function roundDecimalString( amount, decimals ) {
	const text = typeof amount === 'number' && Number.isSafeInteger( amount ) && amount >= 0 ? String( amount ) : amount;
	const m = typeof text === 'string' ? DECIMAL_PATTERN.exec( text.trim() ) : null;
	if ( ! m ) {
		throw new RangeError( 'Amount must be a non-negative decimal string.' );
	}
	const places = Number.isInteger( decimals ) && decimals >= 0 && decimals <= 8 ? decimals : 2;
	let int = m[ 1 ].replace( /^0+(?=\d)/, '' );
	let frac = m[ 2 ] || '';
	if ( frac.length > places ) {
		const roundUp = frac.charCodeAt( places ) - 48 >= 5;
		frac = frac.slice( 0, places );
		if ( roundUp ) {
			const digits = incrementDigits( int + frac );
			int = places === 0 ? digits : digits.slice( 0, digits.length - places );
			frac = places === 0 ? '' : digits.slice( digits.length - places );
		}
	} else {
		frac = frac.padEnd( places, '0' );
	}
	return { int: int === '' ? '0' : int, frac };
}

/**
 * Inserts a thousands separator into a string of digits.
 *
 * @param {string} int       Integer digits.
 * @param {string} separator Separator ('' for none).
 * @return {string} Grouped digits.
 */
export function groupDigits( int, separator ) {
	if ( ! separator || int.length <= 3 ) {
		return int;
	}
	const head = int.length % 3;
	const groups = head > 0 ? [ int.slice( 0, head ) ] : [];
	for ( let i = head; i < int.length; i += 3 ) {
		groups.push( int.slice( i, i + 3 ) );
	}
	return groups.join( separator );
}

/**
 * Formats a money amount (decimal string) with the store currency settings.
 *
 * @param {string} amount   Canonical non-negative decimal string.
 * @param {Object} currency Currency settings (see normalizeCurrency()).
 * @return {string} Formatted amount, e.g. "Rp1,900,000.00".
 * @throws {RangeError} When the amount is not a non-negative decimal string.
 */
export function formatMoney( amount, currency ) {
	const c = currency && typeof currency.decimalSeparator === 'string' ? currency : normalizeCurrency( currency );
	const { int, frac } = roundDecimalString( amount, c.decimals );
	const number = groupDigits( int, c.thousandSeparator ) + ( c.decimals > 0 ? c.decimalSeparator + frac : '' );
	switch ( c.position ) {
		case 'right':
			return number + c.symbol;
		case 'left_space':
			return c.symbol + NBSP + number;
		case 'right_space':
			return number + NBSP + c.symbol;
		default:
			return c.symbol + number;
	}
}

/**
 * formatMoney() that never throws ('' for missing or invalid amounts).
 *
 * @param {string|null} amount   Amount.
 * @param {Object}      currency Currency.
 * @return {string} Formatted amount or ''.
 */
export function money( amount, currency ) {
	if ( amount === null || amount === undefined || amount === '' ) {
		return '';
	}
	try {
		return formatMoney( amount, currency );
	} catch ( e ) {
		return '';
	}
}

/**
 * Formats a canonical decimal quantity (no rounding) with the site separators.
 *
 * @param {string} value    Canonical decimal ("4000", "0.25").
 * @param {Object} currency Currency settings (separators).
 * @return {string} Formatted number.
 */
export function formatNumber( value, currency ) {
	const c = currency && typeof currency.decimalSeparator === 'string' ? currency : normalizeCurrency( currency );
	const text = typeof value === 'number' && Number.isFinite( value ) ? String( value ) : value;
	const m = typeof text === 'string' ? DECIMAL_PATTERN.exec( text ) : null;
	if ( ! m ) {
		return typeof text === 'string' ? text : '';
	}
	const int = groupDigits( m[ 1 ].replace( /^0+(?=\d)/, '' ), c.thousandSeparator );
	return m[ 2 ] ? int + c.decimalSeparator + m[ 2 ] : int;
}

/**
 * A canonical decimal string shown in an input with the site decimal separator (no grouping).
 *
 * @param {string|null} value            Canonical value.
 * @param {string}      decimalSeparator Separator.
 * @return {string} Input text.
 */
export function toInputText( value, decimalSeparator = '.' ) {
	if ( value === null || value === undefined ) {
		return '';
	}
	const text = String( value );
	return decimalSeparator === '.' ? text : text.replace( '.', decimalSeparator );
}

/**
 * Parses a decimal typed by the user.
 *
 * @param {string} text    Input text.
 * @param {Object} options { decimalSeparator, thousandSeparator }.
 * @return {{ok: boolean, value: string|null, code: string|null, message: string, empty: boolean}} Result.
 */
export function parseDecimalInput( text, options = {} ) {
	const ds = typeof options.decimalSeparator === 'string' && options.decimalSeparator !== '' ? options.decimalSeparator : '.';
	const ts = typeof options.thousandSeparator === 'string' && options.thousandSeparator !== ds ? options.thousandSeparator : '';
	const raw = String( text === null || text === undefined ? '' : text ).trim();
	const fail = ( code, message ) => ( { ok: false, value: null, code, message, empty: false } );

	if ( raw === '' ) {
		return { ok: false, value: null, code: 'required', message: __( 'Enter a value.' ), empty: true };
	}
	if ( /^[-−]/.test( raw ) ) {
		return fail( 'not_positive', validationText( 'not_positive' ) );
	}
	const example = '0' + ds + '5';
	if ( ( ts !== '' && ts.trim() !== '' && raw.includes( ts ) ) || /\s/.test( raw ) ) {
		return fail(
			'thousands_separator',
			sprintf(
				/* translators: 1: decimal separator, 2: example number such as 0.5. */
				__( 'Enter the number without thousands separators or spaces, using "%1$s" for decimals, for example 1500 or %2$s.' ),
				ds,
				example
			)
		);
	}
	const other = ds === '.' ? ',' : '.';
	if ( raw.includes( other ) ) {
		return fail(
			'decimal_separator',
			sprintf(
				/* translators: 1: decimal separator, 2: example number such as 0.5. */
				__( 'Use "%1$s" as the decimal separator, for example %2$s.' ),
				ds,
				example
			)
		);
	}
	const parts = raw.split( ds );
	if ( parts.length > 2 || ! /^\d*$/.test( parts[ 0 ] ) || ( parts.length === 2 && ! /^\d*$/.test( parts[ 1 ] ) ) ) {
		return fail( 'invalid_number', validationText( 'invalid_number' ) );
	}
	const int = parts[ 0 ] === '' ? '0' : parts[ 0 ];
	const frac = parts.length === 2 ? parts[ 1 ] : '';
	if ( parts[ 0 ] === '' && frac === '' ) {
		return fail( 'invalid_number', validationText( 'invalid_number' ) );
	}
	const canonical = frac === '' ? int : int + '.' + frac;
	const code = decimalError( canonical );
	if ( code !== null ) {
		return fail( code, validationText( code ) );
	}
	return { ok: true, value: canonicalAmount( canonical ), code: null, message: '', empty: false };
}

/**
 * Parses a whole number typed by the user.
 *
 * @param {string} text    Input text.
 * @param {Object} options { min, max, thousandSeparator }.
 * @return {{ok: boolean, value: number|null, code: string|null, message: string, empty: boolean}} Result.
 */
export function parseIntegerInput( text, options = {} ) {
	const min = Number.isSafeInteger( options.min ) ? options.min : 0;
	const max = Number.isSafeInteger( options.max ) ? options.max : Number.MAX_SAFE_INTEGER;
	const raw = String( text === null || text === undefined ? '' : text ).trim();
	const fail = ( code, message ) => ( { ok: false, value: null, code, message, empty: false } );
	if ( raw === '' ) {
		return { ok: false, value: null, code: 'required', message: __( 'Enter a whole number.' ), empty: true };
	}
	if ( /^[-−]/.test( raw ) ) {
		return fail( 'not_positive', validationText( 'not_positive' ) );
	}
	if ( ! /^\d+$/.test( raw ) ) {
		return fail(
			'integer_required',
			__( 'Enter a whole number using digits only, without separators.' )
		);
	}
	const digits = raw.replace( /^0+(?=\d)/, '' );
	const value = digits.length > 15 ? Number.MAX_SAFE_INTEGER : Number( digits );
	if ( value < min || value > max ) {
		return fail(
			'out_of_range',
			sprintf(
				/* translators: 1: minimum, 2: maximum. */
				__( 'Enter a whole number from %1$s to %2$s.' ),
				String( min ),
				String( max )
			)
		);
	}
	return { ok: true, value, code: null, message: '', empty: false };
}

/**
 * Parses a strict Y-m-d date string.
 *
 * @param {string} ymd Date.
 * @return {number[]|null} [year, month, day].
 */
function dateParts( ymd ) {
	const m = typeof ymd === 'string' ? DATE_PATTERN.exec( ymd ) : null;
	return m ? [ Number( m[ 1 ] ), Number( m[ 2 ] ), Number( m[ 3 ] ) ] : null;
}

const formatters = new Map();

/**
 * A cached Intl.DateTimeFormat (creating one costs far more than formatting with it; the timeline
 * formats hundreds of dates per render).
 *
 * @param {string} locale  BCP 47 locale ('' = browser default).
 * @param {Object} options Intl options.
 * @return {Intl.DateTimeFormat} Formatter.
 */
export function dateFormatter( locale, options ) {
	const key = ( locale || '' ) + '|' + JSON.stringify( options );
	let formatter = formatters.get( key );
	if ( ! formatter ) {
		formatter = new Intl.DateTimeFormat( locale || undefined, options );
		if ( formatters.size >= 32 ) {
			formatters.clear();
		}
		formatters.set( key, formatter );
	}
	return formatter;
}

/**
 * Formats a Y-m-d calendar date for display (UTC, so the date never shifts).
 *
 * @param {string} ymd    Date.
 * @param {string} locale BCP 47 locale.
 * @param {Object} format Intl options (default: medium date).
 * @return {string} Formatted date (the input when it cannot be formatted).
 */
export function formatDate( ymd, locale, format = { year: 'numeric', month: 'short', day: 'numeric' } ) {
	const parts = dateParts( ymd );
	if ( ! parts ) {
		return typeof ymd === 'string' ? ymd : '';
	}
	try {
		const date = new Date( Date.UTC( 2000, 0, 1 ) );
		date.setUTCFullYear( parts[ 0 ], parts[ 1 ] - 1, parts[ 2 ] );
		return dateFormatter( locale, { ...format, timeZone: 'UTC' } ).format( date );
	} catch ( e ) {
		return ymd;
	}
}

/**
 * Formats an ISO 8601 timestamp as a local time of day (for "updated at" notes).
 *
 * @param {string} iso    Timestamp.
 * @param {string} locale Locale.
 * @return {string} Time or ''.
 */
export function formatTime( iso, locale ) {
	const ms = Date.parse( iso );
	if ( Number.isNaN( ms ) ) {
		return '';
	}
	try {
		return dateFormatter( locale, { hour: '2-digit', minute: '2-digit' } ).format( new Date( ms ) );
	} catch ( e ) {
		return '';
	}
}

/**
 * Today's date (Y-m-d) in UTC (the store's site time zone is reported by GET /session).
 *
 * @param {Date} now Clock.
 * @return {string} Date.
 */
export function todayUtc( now = new Date() ) {
	return now.toISOString().slice( 0, 10 );
}

/**
 * Formats a percentage string such as "125.0" with the site decimal separator.
 *
 * @param {string} percent  Percent.
 * @param {Object} currency Currency settings (separators).
 * @return {string} e.g. "125.0%".
 */
export function formatPercent( percent, currency ) {
	return formatNumber( percent, currency ) + '%';
}
