/**
 * Protocol toolbar: editable protocol name, My protocols / New protocol and the save status (above
 * the two steps), plus the protocol start date field shown at the top of step 2 ("Plan &
 * quantities"). Sharing and exports live in the basket (CHANGE-1.1.0 §9.6).
 *
 * @module components/toolbar
 */

import { h, uid, button, debounce } from '../app/dom.js';
import { __ } from '../app/i18n.js';
import { dateError, MIN_DATE, MAX_DATE } from '../app/engine.js';
import { validationText } from '../app/messages.js';
import { MAX_TITLE_LENGTH } from '../app/store.js';

/**
 * Creates the toolbar.
 *
 * @param {Object}   options         Options.
 * @param {Function} options.onTitle ( title ) => void.
 * @param {Function} options.onStart ( Y-m-d|null ) => void.
 * @param {Function} options.onPlans () => void.
 * @param {Function} options.onReset () => void.
 * @return {{el: HTMLElement, startEl: HTMLElement, update: Function, setPlansBusy: Function}} Toolbar.
 */
export function createToolbar( options ) {
	const titleId = uid( 'plan-title' );
	const startId = uid( 'plan-start' );
	const startHelpId = uid( 'plan-start-help' );
	const startErrorId = uid( 'plan-start-error' );

	const title = h( 'input', {
		id: titleId,
		class: 'arp-input arp-toolbar__title-input',
		type: 'text',
		maxlength: String( MAX_TITLE_LENGTH ),
		autocomplete: 'off',
		placeholder: __( 'Untitled research protocol' ),
	} );
	const pushTitle = debounce( () => options.onTitle( title.value ), 300 );
	title.addEventListener( 'input', pushTitle );
	title.addEventListener( 'blur', () => pushTitle.flush() );

	const startError = h( 'p', { id: startErrorId, class: 'arp-field__error', hidden: true } );
	const start = h( 'input', {
		id: startId,
		class: 'arp-input arp-input--date',
		type: 'date',
		min: MIN_DATE,
		max: MAX_DATE,
		'aria-describedby': startHelpId,
	} );
	const onStartChange = () => {
		const value = start.value.trim();
		if ( value === '' && start.validity && start.validity.badInput ) {
			// Partly filled while the customer edits it (one segment cleared): no date yet, but not
			// a clear either. The stored date and the lines' start weeks stay until a full date is
			// entered or every segment is cleared.
			return;
		}
		if ( value === '' ) {
			startError.hidden = true;
			start.removeAttribute( 'aria-invalid' );
			start.setAttribute( 'aria-describedby', startHelpId );
			options.onStart( null );
			return;
		}
		const code = dateError( value );
		if ( code !== null ) {
			startError.textContent = validationText( code );
			startError.hidden = false;
			start.setAttribute( 'aria-invalid', 'true' );
			start.setAttribute( 'aria-describedby', startHelpId + ' ' + startErrorId );
			return;
		}
		startError.hidden = true;
		start.removeAttribute( 'aria-invalid' );
		start.setAttribute( 'aria-describedby', startHelpId );
		options.onStart( value );
	};
	start.addEventListener( 'change', onStartChange );
	// Left partly filled: show the stored date again (update() does not write into the focused field).
	let storedStart = '';
	start.addEventListener( 'blur', () => {
		if ( start.value === '' && start.validity && start.validity.badInput ) {
			start.value = storedStart;
		}
	} );

	const status = h( 'p', { class: 'arp-toolbar__status', role: 'status' } );
	const plansButton = button( { label: __( 'My protocols' ), iconName: 'folder', onClick: options.onPlans, attrs: { 'aria-haspopup': 'dialog' } } );
	// aria-disabled (not disabled) when there is nothing to reset: focus returns to this button after
	// the confirmation dialog, and a disabled button would drop it to <body>.
	const resetButton = button( {
		label: __( 'New protocol' ),
		iconName: 'plus',
		variant: 'ghost',
		onClick: () => {
			if ( resetButton.getAttribute( 'aria-disabled' ) !== 'true' ) {
				options.onReset();
			}
		},
	} );

	const el = h(
		'section',
		{ class: 'arp-card arp-toolbar', 'aria-label': __( 'Protocol details' ) },
		h( 'div', { class: 'arp-field arp-toolbar__title' }, h( 'label', { class: 'arp-label', for: titleId }, __( 'Protocol name' ) ), title ),
		h( 'div', { class: 'arp-toolbar__bar' }, status, h( 'div', { class: 'arp-toolbar__actions' }, plansButton, resetButton ) )
	);

	const startEl = h(
		'div',
		{ class: 'arp-field arp-start' },
		h( 'label', { class: 'arp-label', for: startId }, __( 'Protocol start date' ) ),
		start,
		h( 'p', { id: startHelpId, class: 'arp-field__help' }, __( 'Used for the timeline, run-out dates and calendar reminders. Each product can start in a later week.' ) ),
		startError
	);

	return {
		el,
		startEl,
		/**
		 * Marks My protocols as busy while its dialog waits for the visitor's session (aria-busy; the
		 * button stays focusable and further clicks are ignored by the caller).
		 *
		 * @param {boolean} busy Whether the dialog is being opened.
		 */
		setPlansBusy( busy ) {
			if ( busy ) {
				plansButton.setAttribute( 'aria-busy', 'true' );
			} else {
				plansButton.removeAttribute( 'aria-busy' );
			}
		},
		/**
		 * Updates the toolbar.
		 *
		 * @param {Object} view { title, start_date, status, statusTone, readOnly, canReset }.
		 */
		update( view ) {
			if ( document.activeElement !== title && title.value !== view.title ) {
				title.value = view.title;
			}
			storedStart = view.start_date || '';
			if ( document.activeElement !== start && start.value !== ( view.start_date || '' ) && start.getAttribute( 'aria-invalid' ) !== 'true' ) {
				start.value = view.start_date || '';
			}
			title.disabled = !! view.readOnly;
			start.disabled = !! view.readOnly;
			// Live region: only real changes are written (rewriting identical text re-announces it).
			if ( status.textContent !== ( view.status || '' ) ) {
				status.textContent = view.status || '';
			}
			const statusClass = 'arp-toolbar__status' + ( view.statusTone ? ' is-' + view.statusTone : '' );
			if ( status.className !== statusClass ) {
				status.className = statusClass;
			}
			plansButton.hidden = !! view.readOnly;
			resetButton.hidden = !! view.readOnly;
			resetButton.setAttribute( 'aria-disabled', view.canReset ? 'false' : 'true' );
		},
	};
}
