/**
 * Enhances the server-rendered hero: "Read the full disclaimer" opens an accessible dialog with
 * a copy of the server-rendered disclaimer (no HTML strings are parsed in the browser). Without
 * JavaScript the link simply jumps to the disclaimer section.
 *
 * @module components/hero
 */

import { h } from '../app/dom.js';
import { __ } from '../app/i18n.js';
import { openDialog } from './modal.js';

/**
 * Opens the disclaimer dialog.
 *
 * @param {HTMLElement} scope Planner wrapper (.arp-planner).
 */
export function openDisclaimer( scope ) {
	const source = scope ? scope.querySelector( '[data-arp-disclaimer-body]' ) : null;
	const body = h( 'div', { class: 'arp-disclaimer-dialog' } );
	if ( source ) {
		Array.from( source.childNodes ).forEach( ( node ) => body.appendChild( node.cloneNode( true ) ) );
	} else {
		body.appendChild( h( 'p', null, __( 'This planner is an arithmetic tool for laboratory inventory and procurement. It does not provide medical advice and does not recommend amounts, schedules or uses.' ) ) );
	}
	openDialog( { title: __( 'Disclaimer' ), size: 'md', content: body } );
}

/**
 * Wires the disclaimer triggers inside the planner wrapper.
 *
 * @param {HTMLElement} scope Planner wrapper.
 */
export function enhanceHero( scope ) {
	if ( ! scope ) {
		return;
	}
	scope.querySelectorAll( '[data-arp-disclaimer-trigger]' ).forEach( ( link ) => {
		link.setAttribute( 'role', 'button' );
		link.setAttribute( 'aria-haspopup', 'dialog' );
		link.addEventListener( 'click', ( event ) => {
			event.preventDefault();
			openDisclaimer( scope );
		} );
		link.addEventListener( 'keydown', ( event ) => {
			if ( event.key === ' ' ) {
				event.preventDefault();
				openDisclaimer( scope );
			}
		} );
	} );
}
