/**
 * "All products" of step 1 (CHANGE-1.1.0 §3, §9.1, §9.2): format tabs ("All" plus the allowed
 * formats in the configured order and labels), category chips under the Vials tab (chip groups of
 * GET /catalog/categories, filtering with `group=<key>`), the search-as-you-type combobox (ARIA 1.2
 * combobox + listbox, 250 ms debounce) and a paginated grid of product cards.
 *
 * A card shows the image, the builder category tag, the name, the available sizes, the price "from
 * …", a per-mg price only for a verified mass capacity, and "+ Add to protocol". Once the product is
 * in the protocol the card has a gold border, a "✓ In protocol" tag and the same button reads
 * "Remove" (patched in place, so keyboard focus stays on it). Out-of-stock products show a disabled
 * "Out of stock" button. Only plannable products are listed (the server filters).
 *
 * A product with store protocols gets "{n} pre-built protocols" under its price (CHANGE-1.7.0 §6.9,
 * CHANGE-1.7.1 §3), which shows the pre-built protocols of that product; the counts usually arrive
 * after the products, so the buttons are added, updated or removed in place (refreshProtocols()).
 *
 * @module components/picker
 */

import { h, uid, icon, button, debounce, render } from '../app/dom.js';
import { __, _n, sprintf } from '../app/i18n.js';
import { money } from '../app/format.js';
import { formatLabel, formatTabs, normalizeCatalogPage, normalizeCategories, normalizeCategoryGroups, categoryTag, catalogQuery, perMgPrice } from '../app/catalog.js';

const PER_PAGE = 12;
const SUGGESTIONS = 8;

/**
 * Creates the product list of step 1.
 *
 * @param {Object}        options                 Options.
 * @param {Object}        options.api             API client.
 * @param {Object}        options.currency        Currency settings.
 * @param {boolean}       options.showPrices      Show prices.
 * @param {boolean}       options.showImages      Show images.
 * @param {string[]|null} options.allowedFormats  Formats enabled in the settings.
 * @param {string[]|null} options.formatOrder     Configured tab order.
 * @param {Object|null}   options.formatLabels    Configured tab labels.
 * @param {*}             options.initialCategory Preselected category (ID or slug).
 * @param {Function}      options.onAdd           ( productId ) => Promise.
 * @param {Function}      options.onRemove        ( productId, name ) => void.
 * @param {Function}      options.plannedCount    ( productId ) => number.
 * @param {Function}      options.protocolCount   ( productId ) => number of store protocols shown for it.
 * @param {Function}      options.onShowProtocols ( productId, name ) => void (shows its store protocols).
 * @param {Function}      options.announce        ( message ) => void.
 * @return {{el: HTMLElement, load: Function, refreshPlanned: Function, refreshProtocols: Function, focus: Function, setCurrency: Function}} Picker.
 */
export function createPicker( options ) {
	const state = {
		query: '',
		itemsQuery: null,
		format: '',
		group: '',
		category: '',
		categoryName: '',
		page: 1,
		pages: 1,
		total: 0,
		items: [],
		status: 'loading',
		formats: null,
		groups: [],
		parents: new Map(),
		seq: 0,
		active: -1,
		open: false,
		loadingMore: false,
		suggestions: [],
		suggestQuery: null,
	};
	let currency = options.currency;
	const cards = new Map();

	const inputId = uid( 'search' );
	const listId = uid( 'suggest' );
	const hintId = uid( 'search-hint' );
	const titleId = uid( 'picker-title' );

	const input = h( 'input', {
		id: inputId,
		class: 'arp-input arp-combo__input',
		type: 'text',
		role: 'combobox',
		'aria-autocomplete': 'list',
		'aria-expanded': 'false',
		'aria-controls': listId,
		'aria-describedby': hintId,
		autocomplete: 'off',
		spellcheck: 'false',
		enterkeyhint: 'search',
		maxlength: '100',
		placeholder: __( 'Search by product name' ),
	} );
	const listbox = h( 'ul', { id: listId, class: 'arp-combo__list', role: 'listbox', 'aria-label': __( 'Matching products' ), hidden: true } );
	const clearButton = button( {
		label: __( 'Clear search' ),
		iconName: 'close',
		variant: 'ghost',
		size: 'sm',
		iconOnly: true,
		cls: 'arp-combo__clear',
		onClick: () => {
			input.value = '';
			search();
			input.focus();
		},
	} );
	clearButton.hidden = true;

	const tabs = h( 'div', { class: 'arp-formats', role: 'group', 'aria-label': __( 'Product type' ) } );
	const chips = h( 'div', { class: 'arp-chips arp-chips--categories', role: 'group', 'aria-label': __( 'Category' ), hidden: true } );
	const categoryFilter = h( 'div', { class: 'arp-picker__filter', hidden: true } );
	const count = h( 'p', { class: 'arp-picker__count', role: 'status', 'aria-live': 'polite' } );
	const grid = h( 'ul', { class: 'arp-products', 'aria-label': __( 'Products' ) } );
	const moreMessage = h( 'div', { class: 'arp-picker__message' } );
	let moreOrigin = null;
	const moreLabel = h( 'span', { class: 'arp-btn__label' }, __( 'Show more products' ) );
	// One persistent button (never re-created or disabled), so it keeps focus while loading.
	const moreButton = h(
		'button',
		{
			type: 'button',
			class: 'arp-btn arp-btn--secondary arp-picker__more-btn',
			hidden: true,
			onClick: () => {
				if ( ! state.loadingMore ) {
					// WebKit does not focus a clicked button: remember where focus was when the visitor
					// asked for more, so the new results still receive it.
					moreOrigin = document.activeElement;
					fetchPage( state.page + 1 );
				}
			},
		},
		moreLabel
	);
	const more = h( 'div', { class: 'arp-picker__more' }, moreMessage, moreButton );

	const el = h(
		'section',
		{ class: 'arp-picker', 'aria-labelledby': titleId },
		h(
			'div',
			{ class: 'arp-picker__head' },
			h( 'h2', { class: 'arp-section-head__title arp-picker__title', id: titleId }, __( 'All products' ) ),
			h(
				'div',
				{ class: 'arp-field arp-combo' },
				h( 'label', { class: 'arp-sr-only', for: inputId }, __( 'Search products' ) ),
				h( 'div', { class: 'arp-combo__field' }, icon( 'search', 'arp-combo__icon' ), input, clearButton ),
				h( 'p', { id: hintId, class: 'arp-sr-only' }, __( 'Type to search. Use the arrow keys to choose a product and Enter to add it to your protocol.' ) ),
				listbox
			)
		),
		tabs,
		chips,
		categoryFilter,
		count,
		grid,
		more
	);

	/* ---------------------------------------------------------------- Rendering. */

	/**
	 * Writes the live product count only when it changed (rewriting identical text re-announces it).
	 *
	 * @param {string} text Text.
	 */
	const setCount = ( text ) => {
		if ( count.textContent !== text ) {
			count.textContent = text;
		}
	};

	const priceText = ( item ) => {
		if ( ! options.showPrices || item.priceMin === '' ) {
			return '';
		}
		const min = money( item.priceMin, currency );
		if ( item.priceMax !== '' && item.priceMax !== item.priceMin ) {
			/* translators: %s: lowest price. */
			return sprintf( __( 'from %s' ), min );
		}
		return min;
	};

	/**
	 * Applies the "in protocol" state of a card: gold border, tag and the button label (patched in
	 * place so a focused button keeps focus).
	 *
	 * @param {Object} ref Card references { id, el, tag, addButton, addLabel, addIcon, planned, soldOut }.
	 */
	const applyPlanned = ( ref ) => {
		const planned = options.plannedCount( ref.id );
		if ( planned === ref.planned ) {
			return;
		}
		ref.planned = planned;
		ref.el.classList.toggle( 'is-added', planned > 0 );
		ref.tag.hidden = planned === 0;
		if ( ref.soldOut && planned === 0 ) {
			ref.addLabel.textContent = __( 'Out of stock' );
			// aria-disabled, never `disabled`: after "Remove" this button has focus, and disabling it
			// would drop focus to <body>. Activation is ignored (onClick).
			ref.addButton.setAttribute( 'aria-disabled', 'true' );
			ref.addIcon.hidden = true;
			ref.addButton.classList.remove( 'arp-product__add--remove' );
			return;
		}
		ref.addButton.setAttribute( 'aria-disabled', 'false' );
		ref.addLabel.textContent = planned > 0 ? __( 'Remove' ) : __( 'Add to protocol' );
		ref.addIcon.hidden = planned > 0;
		ref.addButton.classList.toggle( 'arp-product__add--remove', planned > 0 );
	};

	const protocolCount = ( id ) => {
		const n = typeof options.protocolCount === 'function' ? options.protocolCount( id ) : 0;
		return Number.isSafeInteger( n ) && n > 0 ? n : 0;
	};

	/**
	 * Adds, updates or removes the "{n} pre-built protocols" button of a card in place (§6.9). A focused
	 * button that goes away hands focus to the card's main button.
	 *
	 * @param {Object} ref Card references.
	 */
	const applyProtocols = ( ref ) => {
		const n = protocolCount( ref.id );
		if ( n === ref.protocols ) {
			return;
		}
		ref.protocols = n;
		if ( n === 0 ) {
			if ( ref.protocolsButton ) {
				const hadFocus = document.activeElement === ref.protocolsButton;
				ref.protocolsButton.remove();
				ref.protocolsButton = null;
				if ( hadFocus ) {
					ref.addButton.focus();
				}
			}
			return;
		}
		/* translators: %d: number of pre-built protocols of a product. */
		const label = sprintf( _n( '%d pre-built protocol', '%d pre-built protocols', n ), n );
		if ( ! ref.protocolsButton ) {
			ref.protocolsButton = h( 'button', {
				type: 'button',
				class: 'arp-product__protocols',
				'aria-describedby': ref.nameId,
				onClick: () => {
					if ( typeof options.onShowProtocols === 'function' ) {
						options.onShowProtocols( ref.id, ref.name );
					}
				},
			} );
			// Under the price (the last line of the card's text).
			ref.body.appendChild( ref.protocolsButton );
		}
		if ( ref.protocolsButton.textContent !== label ) {
			ref.protocolsButton.textContent = label;
		}
	};

	const productCard = ( item ) => {
		const nameId = uid( 'product-name' );
		const addIcon = h( 'span', { class: 'arp-product__plus', 'aria-hidden': 'true' }, '+' );
		const addLabel = h( 'span', { class: 'arp-btn__label' } );
		const addButton = h(
			'button',
			{
				type: 'button',
				class: 'arp-btn arp-product__add',
				'aria-describedby': nameId,
				'data-product': String( item.id ),
				onClick: async ( event ) => {
					const target = event.currentTarget;
					// aria-busy instead of disabled: disabling the focused button would drop keyboard focus.
					if ( target.getAttribute( 'aria-busy' ) === 'true' || target.getAttribute( 'aria-disabled' ) === 'true' ) {
						return;
					}
					if ( options.plannedCount( item.id ) > 0 ) {
						options.onRemove( item.id, item.name );
						return;
					}
					target.setAttribute( 'aria-busy', 'true' );
					target.classList.add( 'is-busy' );
					try {
						await options.onAdd( item.id, item.name );
					} finally {
						target.removeAttribute( 'aria-busy' );
						target.classList.remove( 'is-busy' );
					}
				},
			},
			addIcon,
			addLabel
		);
		const tag = h( 'span', { class: 'arp-product__in', hidden: true }, icon( 'check' ), __( 'In protocol' ) );
		const category = categoryTag( item.categoryIds, state.groups, state.parents );
		const perMg = options.showPrices ? perMgPrice( item.priceMin, item.cheapestCapacity, currency.decimals, item.cheapestPackCount ) : null;
		const price = priceText( item );
		const image =
			options.showImages && item.image
				? h( 'img', {
					class: 'arp-product__img',
					src: item.image.src,
					srcset: item.image.srcset || null,
					sizes: item.image.srcset ? '(min-width: 1024px) 220px, 45vw' : null,
					alt: '',
					width: String( item.image.width ),
					height: String( item.image.height ),
					loading: 'lazy',
					decoding: 'async',
				} )
				: null;
		const body = h(
			'div',
			{ class: 'arp-product__body' },
			category ? h( 'p', { class: 'arp-product__tag' }, category ) : null,
			h( 'h3', { class: 'arp-product__name', id: nameId }, item.name ),
			item.sizes.length > 0 ? h( 'p', { class: 'arp-product__sizes' }, item.sizes.join( ' · ' ) ) : null,
			price !== ''
				? h(
					'p',
					{ class: 'arp-product__price' },
					h( 'span', null, price ),
					perMg !== null
						? h(
							'span',
							{ class: 'arp-product__per-mg' },
							h( 'span', { 'aria-hidden': 'true' }, sprintf( /* translators: %s: price per milligram. */ __( '%s/mg' ), money( perMg, currency ) ) ),
							h( 'span', { class: 'arp-sr-only' }, sprintf( /* translators: %s: price per milligram. */ __( '%s per mg' ), money( perMg, currency ) ) )
						)
						: null
				)
				: null
		);
		const li = h(
			'li',
			{ class: 'arp-product' },
			options.showImages ? h( 'div', { class: 'arp-product__media' }, image || h( 'span', { class: 'arp-product__placeholder' }, icon( 'box' ) ), tag ) : tag,
			body,
			addButton
		);
		const ref = { id: item.id, name: item.name, nameId, el: li, body, tag, addButton, addLabel, addIcon, planned: -1, soldOut: item.stockStatus === 'outofstock', protocols: 0, protocolsButton: null };
		cards.set( item.id, ref );
		applyProtocols( ref );
		applyPlanned( ref );
		return li;
	};

	const skeletons = () => Array.from( { length: 6 }, () => h( 'li', { class: 'arp-product arp-product--skeleton', 'aria-hidden': 'true' }, h( 'span', { class: 'arp-sk arp-sk--product-inner' } ) ) );

	const filtersActive = () => state.query !== '' || state.format !== '' || state.category !== '' || state.group !== '';

	/**
	 * Toggle buttons (aria-pressed) whose pressed state is patched in place so the focused one keeps
	 * focus.
	 *
	 * @param {HTMLElement} container Group.
	 * @param {string}      attr      data-* attribute holding the value.
	 * @param {string}      current   Current value.
	 */
	const pressIn = ( container, attr, current ) => {
		Array.from( container.children ).forEach( ( node ) => {
			const pressed = node.getAttribute( attr ) === current;
			node.setAttribute( 'aria-pressed', pressed ? 'true' : 'false' );
			node.classList.toggle( 'is-active', pressed );
		} );
	};

	/**
	 * Renders a group of toggle buttons. When the buttons (values and labels) are the same as the ones
	 * shown, only their pressed state is patched, so a focused button is never replaced (choosing
	 * "All" re-renders the tabs when the unfiltered page arrives). A real rebuild moves focus from a
	 * removed button to the button with the same value, else to the pressed one.
	 *
	 * @param {HTMLElement}             container Group.
	 * @param {string}                  attr      data-* attribute holding the value.
	 * @param {string}                  current   Current value.
	 * @param {Array<[string, string]>} wanted    [value, label] pairs.
	 * @param {Function}                make      ( value, label ) => button.
	 */
	const renderToggles = ( container, attr, current, wanted, make ) => {
		const key = JSON.stringify( wanted );
		if ( container.dataset.key === key ) {
			pressIn( container, attr, current );
			return;
		}
		const active = document.activeElement;
		const focused = active && container.contains( active ) ? active.getAttribute( attr ) : null;
		container.dataset.key = key;
		render( container, wanted.map( ( [ value, label ] ) => make( value, label ) ) );
		if ( null !== focused ) {
			const target = Array.from( container.children ).find( ( b ) => b.getAttribute( attr ) === focused ) || container.querySelector( '[aria-pressed="true"]' );
			if ( target ) {
				target.focus();
			}
		}
	};

	const renderTabs = () => {
		const list = formatTabs( { allowed: options.allowedFormats, order: options.formatOrder, labels: options.formatLabels, available: state.formats, active: state.format } );
		const tab = ( value, label ) =>
			h(
				'button',
				{
					type: 'button',
					class: [ 'arp-format', state.format === value ? 'is-active' : '' ],
					'aria-pressed': state.format === value ? 'true' : 'false',
					'data-format': value,
					onClick: () => {
						if ( state.format !== value ) {
							state.format = value;
							state.group = '';
							pressIn( tabs, 'data-format', value );
							renderChips();
							fetchPage( 1 );
						}
					},
				},
				label
			);
		renderToggles( tabs, 'data-format', state.format, list.length > 1 ? [ [ '', __( 'All' ) ], ...list.map( ( t ) => [ t.format, t.label ] ) ] : [], tab );
		tabs.hidden = list.length <= 1;
	};

	const renderChips = () => {
		const show = state.format === 'vial' && state.groups.length > 0;
		chips.hidden = ! show;
		if ( ! show ) {
			delete chips.dataset.key;
			render( chips );
			return;
		}
		const chip = ( key, label ) =>
			h(
				'button',
				{
					type: 'button',
					class: [ 'arp-chip', state.group === key ? 'is-active' : '' ],
					'aria-pressed': state.group === key ? 'true' : 'false',
					'data-group': key,
					onClick: () => {
						if ( state.group !== key ) {
							state.group = key;
							pressIn( chips, 'data-group', key );
							fetchPage( 1 );
						}
					},
				},
				label
			);
		renderToggles( chips, 'data-group', state.group, [ [ '', __( 'All' ) ], ...state.groups.map( ( g ) => [ g.key, g.label ] ) ], chip );
	};

	/** Shows the preselected category (shortcode attribute) as a removable filter. */
	const renderCategoryFilter = () => {
		categoryFilter.hidden = state.category === '';
		if ( state.category === '' ) {
			render( categoryFilter );
			return;
		}
		render(
			categoryFilter,
			h( 'span', { class: 'arp-picker__filter-text' }, sprintf( /* translators: %s: category name. */ __( 'Category: %s' ), state.categoryName ) ),
			button( {
				label: sprintf( /* translators: %s: category name. */ __( 'Show all categories instead of %s' ), state.categoryName ),
				iconName: 'close',
				variant: 'ghost',
				size: 'sm',
				iconOnly: true,
				onClick: () => {
					state.category = '';
					renderCategoryFilter();
					fetchPage( 1 );
					tabs.querySelector( '[aria-pressed="true"]' )?.focus();
				},
			} )
		);
	};

	/** Shows or hides "Show more products" and its loading state. */
	const updateMoreButton = () => {
		const hasMore = state.status === 'ready' && state.items.length > 0 && state.page < state.pages;
		moreButton.hidden = ! hasMore;
		moreButton.setAttribute( 'aria-busy', state.loadingMore ? 'true' : 'false' );
		moreButton.classList.toggle( 'is-busy', state.loadingMore );
		moreLabel.textContent = state.loadingMore ? __( 'Loading more products…' ) : __( 'Show more products' );
	};

	const countText = () =>
		/* translators: 1: number of products shown, 2: number of products found. */
		sprintf( _n( 'Showing %1$s of %2$s product', 'Showing %1$s of %2$s products', state.total ), String( state.items.length ), String( state.total ) );

	const renderResults = () => {
		if ( state.status === 'loading' ) {
			cards.clear();
			render( grid, ...skeletons() );
			grid.setAttribute( 'aria-busy', 'true' );
			render( moreMessage );
			updateMoreButton();
			setCount( __( 'Loading products…' ) );
			return;
		}
		grid.removeAttribute( 'aria-busy' );
		if ( state.status === 'error' ) {
			cards.clear();
			render( grid );
			setCount( '' );
			updateMoreButton();
			render(
				moreMessage,
				h(
					'div',
					{ class: 'arp-empty arp-empty--error', role: 'alert' },
					h( 'p', null, __( 'Products could not be loaded. Check your connection and try again.' ) ),
					button( { label: __( 'Try again' ), iconName: 'refresh', onClick: () => fetchPage( 1 ) } )
				)
			);
			return;
		}
		if ( state.items.length === 0 ) {
			cards.clear();
			render( grid );
			setCount( '' );
			updateMoreButton();
			render(
				moreMessage,
				filtersActive()
					? h(
						'div',
						{ class: 'arp-empty' },
						h( 'p', { class: 'arp-empty__title' }, __( 'No products match your search.' ) ),
						h( 'p', null, __( 'Try another name or clear the filters.' ) ),
						button( { label: __( 'Clear filters' ), onClick: clearFilters } )
					)
					: h(
						'div',
						{ class: 'arp-empty' },
						h( 'p', { class: 'arp-empty__title' }, __( 'No products can be planned yet.' ) ),
						h( 'p', null, __( 'The store is still verifying product data for the builder. Please check back soon.' ) )
					)
			);
			return;
		}
		cards.clear();
		render( grid, ...state.items.map( productCard ) );
		render( moreMessage );
		setCount( countText() );
		updateMoreButton();
	};

	/**
	 * Appends products of a further page and moves focus to the first new one when focus was on
	 * "Show more products", was lost, or has not moved since the button was clicked (WebKit does not
	 * focus clicked buttons), so keyboard and pointer users continue with the new results.
	 *
	 * @param {Object[]} added New items.
	 */
	const appendResults = ( added ) => {
		const active = document.activeElement;
		const focusWasOnMore = active === moreButton || ! active || active === document.body || ( null !== moreOrigin && active === moreOrigin );
		moreOrigin = null;
		const nodes = added.map( productCard );
		nodes.forEach( ( node ) => grid.appendChild( node ) );
		setCount( countText() );
		updateMoreButton();
		if ( focusWasOnMore && nodes.length > 0 ) {
			const first = nodes[ 0 ].querySelector( '.arp-product__add:not([disabled]):not([aria-disabled="true"])' );
			if ( first ) {
				first.focus();
			}
		}
	};

	const setActive = ( index ) => {
		const optionsEls = Array.from( listbox.children );
		state.active = optionsEls.length === 0 ? -1 : ( index + optionsEls.length ) % optionsEls.length;
		optionsEls.forEach( ( opt, i ) => opt.setAttribute( 'aria-selected', i === state.active ? 'true' : 'false' ) );
		if ( state.active >= 0 ) {
			input.setAttribute( 'aria-activedescendant', optionsEls[ state.active ].id );
			optionsEls[ state.active ].scrollIntoView( { block: 'nearest' } );
		} else {
			input.removeAttribute( 'aria-activedescendant' );
		}
	};

	const setOpen = ( open ) => {
		state.open = open && listbox.children.length > 0;
		listbox.hidden = ! state.open;
		input.setAttribute( 'aria-expanded', state.open ? 'true' : 'false' );
		if ( ! state.open ) {
			state.active = -1;
			input.removeAttribute( 'aria-activedescendant' );
		}
	};

	/** The text the suggestions must belong to. */
	const currentQuery = () => input.value.trim().slice( 0, 100 );

	/** Whether the rendered suggestions belong to the text currently in the field. */
	const suggestionsCurrent = () => state.suggestQuery !== null && state.suggestQuery === currentQuery() && state.suggestions.length > 0;

	/**
	 * Rebuilds the listbox from the loaded results — only when they are the results of the text in
	 * the field. The highlight is always reset (old option IDs no longer exist).
	 */
	const renderSuggestions = () => {
		const query = currentQuery();
		const valid = state.status === 'ready' && query !== '' && state.itemsQuery === query;
		state.suggestions = valid ? state.items.slice( 0, SUGGESTIONS ) : [];
		state.suggestQuery = valid ? query : null;
		state.active = -1;
		input.removeAttribute( 'aria-activedescendant' );
		render(
			listbox,
			...state.suggestions.map( ( item ) =>
				h(
					'li',
					{
						id: uid( 'opt' ),
						class: 'arp-combo__option',
						role: 'option',
						'aria-selected': 'false',
						onMousedown: ( event ) => event.preventDefault(),
						onClick: () => choose( item ),
					},
					h( 'span', { class: 'arp-combo__option-name' }, item.name ),
					item.formats.length > 0 ? h( 'span', { class: 'arp-combo__option-meta' }, item.formats.map( formatLabel ).join( ', ' ) ) : null
				)
			)
		);
		setOpen( document.activeElement === input && state.suggestions.length > 0 );
	};

	/** Closes and empties the listbox (its options belong to a previous text). */
	const dropSuggestions = () => {
		state.suggestions = [];
		state.suggestQuery = null;
		setOpen( false );
		render( listbox );
	};

	/* ---------------------------------------------------------------- Data. */

	const fetchPage = async ( page ) => {
		const seq = ++state.seq;
		const query = state.query;
		if ( page === 1 ) {
			state.status = 'loading';
			state.loadingMore = false;
			renderResults();
		} else {
			state.loadingMore = true;
			updateMoreButton();
		}
		try {
			const data = normalizeCatalogPage( await options.api.catalog( catalogQuery( { query, category: state.category, format: state.format, group: state.group, page, perPage: PER_PAGE } ) ) );
			if ( seq !== state.seq ) {
				return;
			}
			const known = new Set( state.items.map( ( item ) => item.id ) );
			const added = page === 1 ? data.items : data.items.filter( ( item ) => ! known.has( item.id ) );
			state.items = page === 1 ? data.items : state.items.concat( added );
			state.itemsQuery = query;
			state.page = data.page;
			state.pages = data.pages;
			state.total = Math.max( data.total, state.items.length );
			state.status = 'ready';
			state.loadingMore = false;
			if ( data.formats && ! filtersActive() ) {
				state.formats = data.formats;
				renderTabs();
			} else if ( ! filtersActive() && page === 1 && data.pages <= 1 ) {
				// The unfiltered list is complete: only offer the formats that are actually present.
				state.formats = [ ...new Set( data.items.flatMap( ( item ) => item.formats ) ) ];
				renderTabs();
			}
			if ( page === 1 ) {
				renderResults();
				renderSuggestions();
			} else {
				appendResults( added );
				/* translators: %d: number of products loaded. */
				options.announce( sprintf( _n( '%d more product loaded.', '%d more products loaded.', added.length ), added.length ) );
			}
		} catch ( e ) {
			if ( seq !== state.seq ) {
				return;
			}
			state.loadingMore = false;
			if ( page === 1 ) {
				state.status = 'error';
				state.items = [];
				state.itemsQuery = null;
				renderResults();
				dropSuggestions();
			} else {
				updateMoreButton();
				options.announce( e.message || __( 'More products could not be loaded.' ) );
			}
		}
	};

	const search = () => {
		const query = currentQuery();
		clearButton.hidden = input.value === '';
		if ( query === state.query ) {
			// Same text as the loaded results (e.g. typed and deleted a character): show them again.
			if ( ! suggestionsCurrent() ) {
				renderSuggestions();
			}
			return;
		}
		state.query = query;
		fetchPage( 1 );
	};
	const searchDebounced = debounce( search, 250 );

	const choose = ( item ) => {
		setOpen( false );
		options.onAdd( item.id, item.name );
	};

	const clearFilters = () => {
		input.value = '';
		clearButton.hidden = true;
		state.query = '';
		state.format = '';
		state.group = '';
		state.category = '';
		dropSuggestions();
		renderTabs();
		renderChips();
		renderCategoryFilter();
		fetchPage( 1 );
	};

	input.addEventListener( 'input', () => {
		clearButton.hidden = input.value === '';
		if ( state.suggestQuery !== null && state.suggestQuery !== currentQuery() ) {
			dropSuggestions();
		}
		searchDebounced();
	} );
	input.addEventListener( 'focus', () => {
		if ( suggestionsCurrent() ) {
			setOpen( true );
		} else {
			renderSuggestions();
		}
	} );
	input.addEventListener( 'blur', () => setOpen( false ) );
	input.addEventListener( 'keydown', ( event ) => {
		switch ( event.key ) {
			case 'ArrowDown':
				event.preventDefault();
				if ( state.open ) {
					setActive( state.active + 1 );
				} else if ( suggestionsCurrent() ) {
					setOpen( true );
					setActive( event.altKey ? -1 : 0 );
				} else {
					// Results of this text are not loaded yet: search now; they open when they arrive.
					searchDebounced.flush();
				}
				break;
			case 'ArrowUp':
				if ( state.open ) {
					event.preventDefault();
					setActive( state.active - 1 );
				}
				break;
			case 'Enter':
				event.preventDefault();
				if ( state.open && state.active >= 0 && suggestionsCurrent() ) {
					const item = state.suggestions[ state.active ];
					if ( item ) {
						choose( item );
					}
				} else {
					searchDebounced.flush();
				}
				break;
			case 'Escape':
				if ( state.open ) {
					event.preventDefault();
					setOpen( false );
				} else if ( input.value !== '' ) {
					event.preventDefault();
					input.value = '';
					search();
				}
				break;
			default:
				break;
		}
	} );

	/**
	 * Loads the category tree (for the builder category tags) and the chip groups, and applies a
	 * preselected category.
	 */
	const loadCategories = async () => {
		try {
			const raw = await options.api.categories();
			const cats = normalizeCategories( raw );
			state.parents = new Map( cats.map( ( c ) => [ c.id, c.parent ] ) );
			state.groups = normalizeCategoryGroups( raw );
			renderChips();
			const initial = options.initialCategory;
			if ( initial !== '' && initial !== null && initial !== undefined ) {
				const match = cats.find( ( c ) => String( c.id ) === String( initial ) || c.slug === String( initial ) );
				if ( match ) {
					state.categoryName = match.name;
					if ( state.category !== String( match.id ) ) {
						state.category = String( match.id );
						fetchPage( 1 );
					}
					renderCategoryFilter();
					return;
				}
				state.category = '';
				renderCategoryFilter();
			}
			if ( state.status === 'ready' && state.groups.length > 0 ) {
				// Category tags need the groups: redraw the cards already shown.
				renderResults();
			}
		} catch ( e ) {
			state.groups = [];
			renderChips();
		}
	};

	renderTabs();
	renderResults();

	return {
		el,
		/** Loads categories and the first page. */
		load() {
			const initial = options.initialCategory;
			if ( typeof initial === 'number' && initial > 0 ) {
				state.category = String( initial );
			}
			loadCategories();
			fetchPage( 1 );
		},
		/** Updates the "in protocol" state of every card in place (focus is kept). */
		refreshPlanned() {
			cards.forEach( applyPlanned );
		},
		/** Adds, updates or removes the "{n} pre-built protocols" buttons in place (counts arrived or changed). */
		refreshProtocols() {
			cards.forEach( applyProtocols );
		},
		/**
		 * Uses the store's currency settings reported by GET /session.
		 *
		 * @param {Object} next Currency.
		 */
		setCurrency( next ) {
			currency = next;
		},
		/** Focuses the search input. */
		focus() {
			input.focus();
		},
	};
}
