/**
 * Weekly protocol helpers (pure, no DOM): the quick choices of the line card, the "Start week" date
 * maths tied to the protocol start date, and "Each vial lasts X weeks (Y uses)".
 *
 * Start week: a line that starts in week N of a protocol starting on S has the line start date
 * S + 7 × (N − 1) days. Week 1 is stored as "no line date" (null): the line then follows the
 * protocol start, which gives the same date and needs no update when the protocol start moves.
 * The week shown in the UI is always derived back from the stored date.
 *
 * Everything is exact integer / decimal arithmetic (engine.js helpers); no floating point.
 *
 * @module weeks
 */

import { parseDate, daysFromCivil, addDays, dateError, parseAmount, mulDivFloor, priceToMinor, priceFromMinor, DEFAULT_LIMITS } from './engine.js';

/** Quick choices for "Times per week": Daily (7), 5×, 3×, 2×, Weekly (1). */
export const TIMES_PER_WEEK_CHOICES = Object.freeze( [ 7, 5, 3, 2, 1 ] );

/** Quick choices for "Duration (weeks)". */
export const DURATION_CHOICES = Object.freeze( [ 4, 8, 12, 16 ] );

/** Largest start week accepted (the longest weekly duration of the engine limits). */
export const MAX_START_WEEK = DEFAULT_LIMITS.max_periods_week;

/**
 * Days since 1970-01-01 of a valid Y-m-d, or null.
 *
 * @param {*} ymd Date.
 * @return {number|null} Days.
 */
function dayNumber( ymd ) {
	const parts = parseDate( ymd );
	return parts === null ? null : daysFromCivil( parts[ 0 ], parts[ 1 ], parts[ 2 ] );
}

/**
 * Week of a line within the protocol, derived from the stored line start date.
 *
 * @param {string|null} lineStart Line start date (Y-m-d) or null (follows the protocol start).
 * @param {string|null} planStart Protocol start date (Y-m-d) or null.
 * @return {{week: number|null, aligned: boolean}} week: 1-based week (null when it cannot be derived:
 *   no protocol start, or a line date before it); aligned: the line date falls exactly on the
 *   first day of that week.
 */
export function weekOfStart( lineStart, planStart ) {
	if ( lineStart === null || lineStart === undefined || lineStart === '' ) {
		return { week: 1, aligned: true };
	}
	const start = dayNumber( planStart );
	const line = dayNumber( lineStart );
	if ( start === null || line === null || line < start ) {
		return { week: null, aligned: false };
	}
	const diff = line - start;
	return { week: Math.floor( diff / 7 ) + 1, aligned: diff % 7 === 0 };
}

/**
 * Line start date for a start week: protocol start + 7 × (week − 1) days; null for week 1 (the line
 * follows the protocol start).
 *
 * @param {string} planStart Protocol start date (Y-m-d).
 * @param {number} week      Start week (1-based integer).
 * @return {{ok: boolean, date: string|null}} ok false when there is no valid protocol start, the week
 *   is not a whole number from 1 to MAX_START_WEEK, or the date would leave the supported range.
 */
export function startForWeek( planStart, week ) {
	if ( dayNumber( planStart ) === null || ! Number.isSafeInteger( week ) || week < 1 || week > MAX_START_WEEK ) {
		return { ok: false, date: null };
	}
	if ( week === 1 ) {
		return { ok: true, date: null };
	}
	const date = addDays( planStart, 7 * ( week - 1 ) );
	return date !== null && dateError( date ) === null ? { ok: true, date } : { ok: false, date: null };
}

/**
 * Line start dates after the protocol start date changed: a line that starts in week N of the old
 * protocol starts in week N of the new one (week 1 lines store no date). When the protocol start is
 * cleared, dates derived from it (aligned to a week) are cleared too; dates the customer chose
 * independently (older protocols, not aligned to a week) are kept as they are.
 *
 * @param {Object[]}    lines    Lines.
 * @param {string|null} oldStart Previous protocol start.
 * @param {string|null} newStart New protocol start.
 * @return {Object[]} Lines (the same array when nothing changed; changed lines are new objects).
 */
export function shiftLineStarts( lines, oldStart, newStart ) {
	if ( ! Array.isArray( lines ) || oldStart === newStart || dayNumber( oldStart ) === null ) {
		return lines;
	}
	let changed = false;
	const next = lines.map( ( line ) => {
		if ( ! line || ! line.start_date ) {
			return line;
		}
		const { week, aligned } = weekOfStart( line.start_date, oldStart );
		if ( week === null || ! aligned ) {
			return line;
		}
		let date = null;
		if ( dayNumber( newStart ) !== null ) {
			const target = startForWeek( newStart, week );
			if ( ! target.ok ) {
				return line;
			}
			date = target.date;
		}
		if ( date === line.start_date ) {
			return line;
		}
		changed = true;
		return { ...line, start_date: date };
	} );
	return changed ? next : lines;
}

/**
 * Start weeks (> 1) of the lines whose start date is derived from the protocol start (on the first
 * day of a week), by line ID. Remembered while the protocol start date is cleared, so setting a
 * date again puts every line back into its week (restoreLineWeeks()).
 *
 * @param {Object[]}    lines     Lines.
 * @param {string|null} planStart Protocol start date.
 * @return {Map<string, number>} Line ID => week.
 */
export function lineWeeks( lines, planStart ) {
	const weeks = new Map();
	if ( ! Array.isArray( lines ) || dayNumber( planStart ) === null ) {
		return weeks;
	}
	lines.forEach( ( line ) => {
		if ( line && line.start_date ) {
			const { week, aligned } = weekOfStart( line.start_date, planStart );
			if ( week !== null && week > 1 && aligned ) {
				weeks.set( line.id, week );
			}
		}
	} );
	return weeks;
}

/**
 * Lines with remembered start weeks (lineWeeks()) applied to a new protocol start date. Lines that
 * have a date of their own meanwhile keep it.
 *
 * @param {Object[]}            lines     Lines.
 * @param {Map<string, number>} weeks     Line ID => week.
 * @param {string}              planStart New protocol start date.
 * @return {Object[]} Lines (the same array when nothing changed).
 */
export function restoreLineWeeks( lines, weeks, planStart ) {
	if ( ! Array.isArray( lines ) || ! ( weeks instanceof Map ) || weeks.size === 0 || dayNumber( planStart ) === null ) {
		return lines;
	}
	let changed = false;
	const next = lines.map( ( line ) => {
		const week = line && ! line.start_date ? weeks.get( line.id ) : undefined;
		if ( week === undefined ) {
			return line;
		}
		const target = startForWeek( planStart, week );
		if ( ! target.ok || target.date === null ) {
			return line;
		}
		changed = true;
		return { ...line, start_date: target.date };
	} );
	return changed ? next : lines;
}

/**
 * How long one container lasts at the entered weekly rate: capacity ÷ (amount × times per week).
 * Weeks are shown with one decimal, rounded down (like every other coverage figure, the planner
 * never overstates how long stock lasts); uses are whole uses, rounded down.
 *
 * @param {Object} result Line result (LineResult::to_array() shape).
 * @return {{weeks: string, uses: number}|null} Null when the result is not a weekly schedule.
 */
export function containerLasts( result ) {
	const r = result && typeof result === 'object' ? result : null;
	if ( ! r || r.mode !== 'schedule' || r.period_unit !== 'week' || ! r.capacity || ! r.per_event || ! Number.isSafeInteger( r.events_per_period ) || r.events_per_period < 1 ) {
		return null;
	}
	try {
		const capacity = parseAmount( String( r.capacity.amount ), r.capacity.unit );
		const perUse = parseAmount( String( r.per_event.value ), r.per_event.unit );
		if ( perUse <= 0n || capacity <= 0n ) {
			return null;
		}
		const uses = capacity / perUse;
		const tenths = mulDivFloor( capacity, 10n, perUse * BigInt( r.events_per_period ) );
		const whole = tenths / 10n;
		const decimal = tenths % 10n;
		if ( uses > BigInt( Number.MAX_SAFE_INTEGER ) ) {
			return null;
		}
		return { weeks: whole.toString() + '.' + decimal.toString(), uses: Number( uses ) };
	} catch ( e ) {
		return null;
	}
}

/**
 * When a weekly schedule runs out (only with a shortfall).
 *
 * @param {Object}      result   Line result.
 * @param {Object|null} timeline Timeline (InventoryTimeline::build() shape) or null.
 * @return {{date: string|null, afterWeek: number}|null} Null when the quantity covers the whole
 *   duration (or the line is not a schedule). afterWeek = number of whole weeks fully covered (the
 *   supply runs out during week afterWeek + 1); date = start of that week when the line is dated.
 */
export function runOut( result, timeline ) {
	const r = result && typeof result === 'object' ? result : null;
	if ( ! r || r.mode !== 'schedule' || ! r.shortfall ) {
		return null;
	}
	const fromTimeline = timeline && timeline.run_out && typeof timeline.run_out === 'object' ? timeline.run_out : null;
	if ( fromTimeline && Number.isSafeInteger( fromTimeline.period_index ) ) {
		return { date: typeof fromTimeline.date === 'string' ? fromTimeline.date : null, afterWeek: fromTimeline.period_index };
	}
	if ( Number.isSafeInteger( r.events_covered ) && Number.isSafeInteger( r.events_per_period ) && r.events_per_period > 0 ) {
		return { date: null, afterWeek: Math.floor( r.events_covered / r.events_per_period ) };
	}
	return null;
}

/**
 * Whole weeks the bought quantity lasts at the entered weekly rate: uses covered ÷ times per week,
 * rounded down (a week that is only partly covered is not counted).
 *
 * @param {Object} result Line result.
 * @return {number|null} Weeks (null when the result is not a weekly schedule).
 */
export function coveredWeeks( result ) {
	const r = result && typeof result === 'object' ? result : null;
	if ( ! r || r.mode !== 'schedule' || r.period_unit !== 'week' || ! Number.isSafeInteger( r.events_covered ) || ! Number.isSafeInteger( r.events_per_period ) || r.events_per_period < 1 ) {
		return null;
	}
	return Math.floor( r.events_covered / r.events_per_period );
}

/**
 * Last day the bought quantity lasts ("supply to"): the last day of the last week it fully covers,
 * counted from the line's start date. With a shortfall this is the day before the run-out date.
 *
 * @param {Object}      result   Line result.
 * @param {Object|null} timeline Timeline of the line (its start_date is the line start).
 * @return {string|null} Y-m-d, or null without a start date or when not even one week is covered.
 */
export function supplyTo( result, timeline ) {
	const weeks = coveredWeeks( result );
	const start = timeline && typeof timeline.start_date === 'string' ? timeline.start_date : null;
	if ( weeks === null || weeks < 1 || dayNumber( start ) === null ) {
		return null;
	}
	const date = addDays( start, 7 * weeks - 1 );
	return date !== null && dateError( date ) === null ? date : null;
}

/**
 * Price per week of supply for display: estimate ÷ duration in weeks, rounded half-up to the
 * currency decimals (display arithmetic on the store estimate; WooCommerce stays authoritative).
 *
 * @param {string|null} estimate Estimate (decimal string) or null.
 * @param {number}      weeks    Duration in weeks.
 * @param {number}      decimals Currency decimals.
 * @return {string|null} Decimal string, or null when it cannot be computed.
 */
export function perWeekPrice( estimate, weeks, decimals ) {
	if ( typeof estimate !== 'string' || estimate === '' || ! Number.isSafeInteger( weeks ) || weeks < 1 ) {
		return null;
	}
	try {
		const minor = priceToMinor( estimate, decimals );
		const w = BigInt( weeks );
		return priceFromMinor( ( minor * 2n + w ) / ( w * 2n ), decimals );
	} catch ( e ) {
		return null;
	}
}

/**
 * Today's date (Y-m-d) in the site time zone: an IANA name ("Asia/Makassar") or a UTC offset
 * ("+08:00", as wp_timezone_string() reports sites without a city). Falls back to the browser's
 * own calendar date when the zone is unknown. GET /session reports the authoritative `today`.
 *
 * @param {string} timezone Site time zone.
 * @param {Date}   now      Clock.
 * @return {string} Y-m-d.
 */
export function todayIn( timezone, now = new Date() ) {
	const pad = ( n ) => String( n ).padStart( 2, '0' );
	const zone = typeof timezone === 'string' ? timezone.trim() : '';
	const offset = /^([+-])(\d{2}):?(\d{2})$/.exec( zone );
	if ( offset || zone === 'UTC' || zone === 'Z' ) {
		const minutes = offset ? ( offset[ 1 ] === '-' ? -1 : 1 ) * ( Number( offset[ 2 ] ) * 60 + Number( offset[ 3 ] ) ) : 0;
		const shifted = new Date( now.getTime() + minutes * 60000 );
		return shifted.getUTCFullYear() + '-' + pad( shifted.getUTCMonth() + 1 ) + '-' + pad( shifted.getUTCDate() );
	}
	if ( zone !== '' && typeof Intl !== 'undefined' && typeof Intl.DateTimeFormat === 'function' ) {
		try {
			const parts = {};
			new Intl.DateTimeFormat( 'en-US', { timeZone: zone, year: 'numeric', month: '2-digit', day: '2-digit' } ).formatToParts( now ).forEach( ( part ) => {
				parts[ part.type ] = part.value;
			} );
			if ( /^\d{4}$/.test( parts.year ) && /^\d{2}$/.test( parts.month ) && /^\d{2}$/.test( parts.day ) ) {
				return parts.year + '-' + parts.month + '-' + parts.day;
			}
		} catch ( e ) {
			// Unknown zone: use the browser calendar below.
		}
	}
	return now.getFullYear() + '-' + pad( now.getMonth() + 1 ) + '-' + pad( now.getDate() );
}
