/**
 * Variant picker: one select per variation attribute, labelled by role ("Strength" for strength
 * attributes, "Pen format" for pa_pen-type, otherwise the attribute label). Options that cannot be
 * planned or bought are disabled with the reason in the option text. The choices resolve to the
 * EXACT variation ID (catalog.resolveUnit()).
 *
 * @module components/variant-picker
 */

import { h, uid } from '../app/dom.js';
import { __, sprintf } from '../app/i18n.js';
import { attributeLabel, optionStates } from '../app/catalog.js';

/**
 * Creates a variant picker.
 *
 * @param {Function} onChange ( key, slug ) => void.
 * @return {{el: HTMLElement, update: Function}} Picker.
 */
export function createVariantPicker( onChange ) {
	const el = h( 'div', { class: 'arp-variants' } );
	const fields = new Map();

	return {
		el,
		/**
		 * Updates the selects.
		 *
		 * @param {Object|null} product   Product (normalized).
		 * @param {Object}      selection Choices.
		 * @param {boolean}     disabled  Read-only.
		 */
		update( product, selection, disabled ) {
			const attributes = product && product.type === 'variable' ? product.attributes : [];
			el.hidden = attributes.length === 0;
			const keys = new Set( attributes.map( ( a ) => a.key ) );
			for ( const [ key, field ] of fields ) {
				if ( ! keys.has( key ) ) {
					field.wrap.remove();
					fields.delete( key );
				}
			}
			attributes.forEach( ( attribute, index ) => {
				let field = fields.get( attribute.key );
				if ( ! field ) {
					const id = uid( 'variant' );
					const select = h( 'select', { id, class: 'arp-select', onChange: () => onChange( attribute.key, select.value ) } );
					const wrap = h( 'div', { class: 'arp-field arp-variants__field' }, h( 'label', { class: 'arp-label', for: id }, attributeLabel( attribute ) ), select );
					field = { wrap, select, signature: '' };
					fields.set( attribute.key, field );
				}
				// Move the field only when it is not already in place: re-inserting a node that
				// contains the focused select would blur it after every keyboard change.
				if ( el.children[ index ] !== field.wrap ) {
					el.insertBefore( field.wrap, el.children[ index ] || null );
				}
				const states = optionStates( product, selection, attribute.key );
				const value = ( selection || {} )[ attribute.key ] || '';
				const signature = JSON.stringify( states ) + '|' + value;
				if ( signature !== field.signature ) {
					field.signature = signature;
					field.select.replaceChildren(
						h( 'option', { value: '' }, __( 'Choose an option' ) ),
						...states.map( ( option ) =>
							h(
								'option',
								{ value: option.slug, disabled: option.disabled && option.slug !== value },
								option.disabled
									? sprintf(
										/* translators: 1: name (product or option), 2: short explanation (review reason or why the option cannot be chosen). */
										__( '%1$s — %2$s' ),
										option.name,
										option.reason
									)
									: option.name
							)
						)
					);
				}
				if ( field.select.value !== value ) {
					field.select.value = value;
				}
				field.select.disabled = !! disabled;
			} );
		},
	};
}
