/**
 * Translation helpers: thin wrappers around window.wp.i18n with a safe English fallback.
 *
 * Call sites always pass the literal text domain so `wp i18n make-pot` extracts every string from
 * the sources. The production build (build/build.mjs) strips that trailing literal argument from
 * `__()` / `_n()` calls of the modules importing these helpers, which then fall back to DOMAIN:
 * the result is identical and the bundle does not repeat the literal hundreds of times.
 *
 * @module i18n
 */

/** Text domain of every planner string. */
export const DOMAIN = 'atlas-research-planner';

/**
 * The wp.i18n API when the script dependency is loaded.
 *
 * @return {Object|null} wp.i18n.
 */
function api() {
	const w = typeof window !== 'undefined' ? window : null;
	return w && w.wp && w.wp.i18n && typeof w.wp.i18n.__ === 'function' ? w.wp.i18n : null;
}

/**
 * Translates a string.
 *
 * @param {string} text   Text.
 * @param {string} domain Text domain (default DOMAIN).
 * @return {string} Translation.
 */
export function __( text, domain = DOMAIN ) {
	const i18n = api();
	return i18n ? i18n.__( text, domain ) : text;
}

/**
 * Translates a string with context.
 *
 * @param {string} text    Text.
 * @param {string} context Context.
 * @param {string} domain  Text domain (default DOMAIN).
 * @return {string} Translation.
 */
export function _x( text, context, domain = DOMAIN ) {
	const i18n = api();
	return i18n && typeof i18n._x === 'function' ? i18n._x( text, context, domain ) : text;
}

/**
 * Translates a singular/plural string.
 *
 * @param {string} single Singular.
 * @param {string} plural Plural.
 * @param {number} number Count.
 * @param {string} domain Text domain (default DOMAIN).
 * @return {string} Translation.
 */
export function _n( single, plural, number, domain = DOMAIN ) {
	const i18n = api();
	if ( i18n && typeof i18n._n === 'function' ) {
		return i18n._n( single, plural, number, domain );
	}
	return Number( number ) === 1 ? single : plural;
}

/**
 * sprintf with %s, %d and positional %1$s placeholders (wp.i18n.sprintf when available).
 *
 * @param {string} format Format.
 * @param {...*}   args   Arguments.
 * @return {string} Formatted string.
 */
export function sprintf( format, ...args ) {
	const i18n = api();
	if ( i18n && typeof i18n.sprintf === 'function' ) {
		return i18n.sprintf( format, ...args );
	}
	let next = 0;
	return String( format ).replace( /%(?:(\d+)\$)?([sd%])/g, ( match, position, type ) => {
		if ( type === '%' ) {
			return '%';
		}
		const index = position ? Number( position ) - 1 : next++;
		const value = args[ index ];
		if ( type === 'd' ) {
			const n = Number.parseInt( value, 10 );
			return Number.isNaN( n ) ? '0' : String( n );
		}
		return value === undefined || value === null ? '' : String( value );
	} );
}
