/**
 * REST client for the `atlas-planner/v1` namespace.
 *
 * - GET /session is always loaded first (without nonce headers, with `X-ARP-Session: 1`); its
 *   `nonce` (X-ARP-Nonce) and `rest_nonce` (X-WP-Nonce) are sent with every later request. Nonces
 *   are never embedded in the page HTML.
 * - Every request has a timeout. Network failures and timeouts are retried once for GET requests
 *   and for requests marked idempotent (calculate, cart with request_id, exports).
 * - On `arp_bad_nonce` / `rest_cookie_invalid_nonce` the session is refreshed once and the request
 *   retried. HTTP 429 becomes an ApiError with `retryAfter` (seconds).
 * - Errors are normalized to ApiError { code, message, status, data, retryAfter, network }.
 *
 * @module api
 */

import { __ } from './i18n.js';

/** Error codes that trigger one session refresh + retry. */
export const NONCE_CODES = Object.freeze( [ 'arp_bad_nonce', 'rest_cookie_invalid_nonce' ] );

/** Header carrying share tokens (never put in URLs). */
export const SHARE_HEADER = 'X-ARP-Share-Token';

/**
 * Header carrying the IDs of the store protocols a saved protocol started from, joined with ","
 * (GET /exports/{uuid}, CHANGE-1.7.0 §6.14, §7). Which store protocol a customer started from is
 * research data: it never goes into a URL (ARCHITECTURE §0).
 */
export const STORE_PROTOCOLS_HEADER = 'X-ARP-Store-Protocols';

/** Store protocol IDs sent with an export (StoreProtocolRules::ID_PATTERN; at most 5, §7). */
const STORE_PROTOCOL_ID = /^[a-z0-9-]{1,40}$/;

/**
 * Valid, distinct store protocol IDs (at most 5) of an export request.
 *
 * @param {*} ids IDs.
 * @return {string[]} IDs.
 */
export function storeProtocolIds( ids ) {
	return ( Array.isArray( ids ) ? ids : [] ).filter( ( id, i, all ) => typeof id === 'string' && STORE_PROTOCOL_ID.test( id ) && all.indexOf( id ) === i ).slice( 0, 5 );
}

/**
 * Query of GET /store-protocols (CHANGE-1.7.0 §4.2): only the known keys; empty values (and a
 * product filter of 0) are omitted.
 *
 * @param {Object} query { group, product, search, offset, limit }.
 * @return {Object} Query.
 */
export function storeProtocolsQuery( query ) {
	const q = query && typeof query === 'object' ? query : {};
	const out = {};
	if ( typeof q.group === 'string' && q.group !== '' ) {
		out.group = q.group;
	}
	if ( Number.isSafeInteger( q.product ) && q.product > 0 ) {
		out.product = q.product;
	}
	if ( typeof q.search === 'string' && q.search !== '' ) {
		out.search = q.search;
	}
	if ( Number.isSafeInteger( q.offset ) && q.offset >= 0 ) {
		out.offset = q.offset;
	}
	if ( Number.isSafeInteger( q.limit ) && q.limit > 0 ) {
		out.limit = q.limit;
	}
	return out;
}

/**
 * Header sent ("1") with GET /session (RequestGuard::SESSION_HEADER). The server resolves a
 * logged-in user from the login cookie only for a request proven to be same-origin; a custom header
 * cannot be sent cross-origin without CORS, so it proves this script even when a privacy setting or
 * proxy strips the Referer and fetch metadata.
 */
export const SESSION_HEADER = 'X-ARP-Session';

/**
 * Normalized API error.
 */
export class ApiError extends Error {
	/**
	 * @param {Object}  details            Details.
	 * @param {string}  details.code       Stable code.
	 * @param {string}  details.message    Human-readable message.
	 * @param {number}  details.status     HTTP status (0 for network errors).
	 * @param {*}       details.data       Error data from the server.
	 * @param {number}  details.retryAfter Seconds to wait (429).
	 * @param {boolean} details.network    Network failure or timeout.
	 */
	constructor( { code = 'error', message = '', status = 0, data = null, retryAfter = 0, network = false } = {} ) {
		super( message || defaultMessage( code, status ) );
		this.name = 'ApiError';
		this.code = code;
		this.status = status;
		this.data = data;
		this.retryAfter = retryAfter;
		this.network = network;
	}
}

/**
 * Generic, translated message for an error without a server message.
 *
 * @param {string} code   Code.
 * @param {number} status HTTP status.
 * @return {string} Message.
 */
export function defaultMessage( code, status = 0 ) {
	if ( code === 'timeout' ) {
		return __( 'The store took too long to respond. Please try again.' );
	}
	if ( code === 'network' ) {
		return __( 'The store could not be reached. Check your connection and try again.' );
	}
	if ( code === 'arp_rate_limited' || status === 429 ) {
		return __( 'Too many requests in a short time. Please wait a moment and try again.' );
	}
	if ( status >= 500 ) {
		return __( 'Something went wrong on the store side. Please try again.' );
	}
	return __( 'The request could not be completed. Please try again.' );
}

/**
 * Seconds from a Retry-After header (delta seconds or HTTP date).
 *
 * @param {string|null} value Header value.
 * @param {number}      now   Current time (ms).
 * @return {number} Seconds (0 when absent or invalid).
 */
export function parseRetryAfter( value, now = Date.now() ) {
	if ( value === null || value === undefined || value === '' ) {
		return 0;
	}
	if ( /^\d+$/.test( String( value ).trim() ) ) {
		return Math.min( 3600, Number( String( value ).trim() ) );
	}
	const at = Date.parse( value );
	return Number.isNaN( at ) ? 0 : Math.max( 0, Math.min( 3600, Math.ceil( ( at - now ) / 1000 ) ) );
}

/**
 * File name from a Content-Disposition header.
 *
 * @param {string|null} header Header.
 * @return {string} File name or ''.
 */
export function filenameFromDisposition( header ) {
	if ( ! header ) {
		return '';
	}
	const star = /filename\*\s*=\s*UTF-8''([^;]+)/i.exec( header );
	if ( star ) {
		try {
			return decodeURIComponent( star[ 1 ].trim().replace( /^"|"$/g, '' ) );
		} catch ( e ) {
			// Fall through to the plain parameter.
		}
	}
	const plain = /filename\s*=\s*"?([^";]+)"?/i.exec( header );
	return plain ? plain[ 1 ].trim() : '';
}

/**
 * Share link from a POST /plans/{uuid}/shares response.
 *
 * The server returns `url: null` when no published planner page is configured; the link is then
 * built from the current page (without its fragment) so the token still travels only in the
 * URL fragment (`#share=…`), never in a query string.
 *
 * @param {Object} data Response `{url, token}`.
 * @param {string} href Current page URL.
 * @return {string} Link ('' when the response has neither a URL nor a token).
 */
export function shareUrlFrom( data, href ) {
	const response = data && typeof data === 'object' ? data : {};
	if ( typeof response.url === 'string' && response.url !== '' ) {
		return response.url;
	}
	const token = typeof response.token === 'string' ? response.token : '';
	if ( ! /^[A-Za-z0-9_-]{1,128}$/.test( token ) ) {
		return '';
	}
	return String( href || '' ).split( '#' )[ 0 ] + '#share=' + token;
}

/**
 * Creates the API client.
 *
 * @param {Object}   options            Options.
 * @param {string}   options.root       REST root, e.g. https://example.com/wp-json/atlas-planner/v1/.
 * @param {Function} options.fetch      fetch implementation (default: global fetch).
 * @param {number}   options.timeout    Timeout per attempt in ms (default 20000).
 * @param {number}   options.retryDelay Delay before the network retry in ms (default 600).
 * @param {Function} options.sleep      Sleep implementation (tests).
 * @return {Object} Client.
 */
export function createApi( options = {} ) {
	const root = String( options.root || '' ).replace( /\/?$/, '/' );
	const fetchImpl = options.fetch || ( typeof fetch === 'function' ? ( ...args ) => fetch( ...args ) : null );
	const timeout = Number.isFinite( options.timeout ) ? options.timeout : 20000;
	const retryDelay = Number.isFinite( options.retryDelay ) ? options.retryDelay : 600;
	const sleep = options.sleep || ( ( ms ) => new Promise( ( resolve ) => setTimeout( resolve, ms ) ) );

	let session = null;
	let sessionPromise = null;
	const listeners = new Set();

	/**
	 * Full URL for a route and query.
	 *
	 * @param {string} path  Route relative to the namespace.
	 * @param {Object} query Query parameters.
	 * @return {string} URL.
	 */
	const buildUrl = ( path, query ) => {
		let url = root + String( path ).replace( /^\/+/, '' );
		const params = [];
		for ( const [ key, value ] of Object.entries( query || {} ) ) {
			if ( value === null || value === undefined || value === '' ) {
				continue;
			}
			params.push( encodeURIComponent( key ) + '=' + encodeURIComponent( String( value ) ) );
		}
		if ( params.length > 0 ) {
			url += ( url.includes( '?' ) ? '&' : '?' ) + params.join( '&' );
		}
		return url;
	};

	/**
	 * One HTTP attempt.
	 *
	 * @param {string} method Method.
	 * @param {string} path   Route.
	 * @param {Object} opts   Options.
	 * @return {Promise<*>} Parsed data, or { blob, filename, type } for raw requests.
	 */
	const attempt = async ( method, path, opts ) => {
		if ( ! fetchImpl ) {
			throw new ApiError( { code: 'network', network: true } );
		}
		const headers = { Accept: opts.raw ? '*/*' : 'application/json' };
		if ( ! opts.skipNonce && session ) {
			if ( typeof session.rest_nonce === 'string' && session.rest_nonce !== '' ) {
				headers[ 'X-WP-Nonce' ] = session.rest_nonce;
			}
			if ( typeof session.nonce === 'string' && session.nonce !== '' ) {
				headers[ 'X-ARP-Nonce' ] = session.nonce;
			}
		}
		Object.assign( headers, opts.headers || {} );
		// A function is evaluated per attempt, after the session has loaded (cache mode by login state).
		const cache = typeof opts.cache === 'function' ? opts.cache() : opts.cache;
		const init = { method, headers, credentials: 'same-origin', cache: cache || 'no-store' };
		if ( opts.body !== undefined ) {
			headers[ 'Content-Type' ] = 'application/json';
			init.body = JSON.stringify( opts.body );
		}

		const controller = typeof AbortController === 'function' ? new AbortController() : null;
		let timedOut = false;
		const timer = controller
			? setTimeout( () => {
				timedOut = true;
				controller.abort();
			}, timeout )
			: null;
		if ( controller ) {
			init.signal = controller.signal;
		}

		let response;
		try {
			response = await fetchImpl( buildUrl( path, opts.query ), init );
		} catch ( e ) {
			throw new ApiError( { code: timedOut ? 'timeout' : 'network', network: true } );
		} finally {
			if ( timer ) {
				clearTimeout( timer );
			}
		}

		const header = ( name ) => ( response.headers && typeof response.headers.get === 'function' ? response.headers.get( name ) : null );

		if ( response.ok && opts.raw ) {
			const blob = await response.blob();
			return { blob, filename: filenameFromDisposition( header( 'Content-Disposition' ) ), type: header( 'Content-Type' ) || blob.type || '' };
		}

		let data = null;
		let text = '';
		try {
			text = await response.text();
			data = text === '' ? null : JSON.parse( text );
		} catch ( e ) {
			if ( response.ok ) {
				throw new ApiError( { code: 'bad_response', status: response.status } );
			}
		}

		if ( ! response.ok ) {
			const code = data && typeof data.code === 'string' ? data.code : ( response.status === 429 ? 'arp_rate_limited' : 'http_' + response.status );
			throw new ApiError( {
				code,
				message: data && typeof data.message === 'string' ? data.message : '',
				status: response.status,
				data: data && data.data !== undefined ? data.data : null,
				retryAfter: parseRetryAfter( header( 'Retry-After' ) ),
			} );
		}
		return data;
	};

	/**
	 * Loads (or refreshes) the session.
	 *
	 * @param {boolean} force Refresh even when a session is loaded.
	 * @return {Promise<Object>} Session.
	 */
	const loadSession = ( force = false ) => {
		if ( session && ! force ) {
			return Promise.resolve( session );
		}
		if ( sessionPromise ) {
			return sessionPromise;
		}
		sessionPromise = request( 'GET', 'session', { skipNonce: true, headers: { [ SESSION_HEADER ]: '1' } } )
			.then( ( data ) => {
				if ( ! data || typeof data !== 'object' ) {
					throw new ApiError( { code: 'bad_response' } );
				}
				session = data;
				listeners.forEach( ( fn ) => fn( session ) );
				return session;
			} )
			.finally( () => {
				sessionPromise = null;
			} );
		return sessionPromise;
	};

	/**
	 * Request with session, network retry and nonce refresh.
	 *
	 * @param {string} method Method.
	 * @param {string} path   Route.
	 * @param {Object} opts   { query, body, headers, raw, idempotent, skipNonce, cache }.
	 * @return {Promise<*>} Data.
	 */
	async function request( method, path, opts = {} ) {
		if ( ! opts.skipNonce ) {
			await loadSession( false );
		}
		let networkRetried = false;
		let nonceRetried = false;
		for ( ;; ) {
			try {
				return await attempt( method, path, opts );
			} catch ( e ) {
				if ( ! ( e instanceof ApiError ) ) {
					throw e;
				}
				if ( e.network && ! networkRetried && ( method === 'GET' || opts.idempotent ) ) {
					networkRetried = true;
					await sleep( retryDelay );
					continue;
				}
				if ( ! opts.skipNonce && ! nonceRetried && NONCE_CODES.includes( e.code ) ) {
					nonceRetried = true;
					await loadSession( true );
					continue;
				}
				throw e;
			}
		}
	}

	const share = ( token ) => ( { [ SHARE_HEADER ]: String( token || '' ) } );
	const enc = encodeURIComponent;
	/**
	 * Cache mode of the public store protocol routes (CHANGE-1.7.0 §4.1): they answer differently by
	 * login state and send no Vary, so the browser cache is used only while the session is a guest's.
	 *
	 * @return {string} default | no-store.
	 */
	const storeCache = () => ( session && session.user && session.user.logged_in === true ? 'no-store' : 'default' );

	return {
		request,
		session: loadSession,
		currentSession: () => session,
		/**
		 * Replaces the public nonce (POST /cart returns a fresh one once the store session starts).
		 *
		 * @param {string} nonce Nonce.
		 */
		setNonce( nonce ) {
			if ( session && typeof nonce === 'string' && nonce !== '' ) {
				session = { ...session, nonce };
			}
		},
		onSession( fn ) {
			listeners.add( fn );
			return () => listeners.delete( fn );
		},
		catalog: ( query ) => request( 'GET', 'catalog', { query, cache: 'default' } ),
		categories: () => request( 'GET', 'catalog/categories', { cache: 'default' } ),
		combinations: () => request( 'GET', 'combinations', { cache: 'default' } ),
		product: ( id ) => request( 'GET', 'product/' + enc( id ) ),
		calculate: ( body ) => request( 'POST', 'calculate', { body, idempotent: true } ),
		cart: () => request( 'GET', 'cart' ),
		addToCart: ( body ) => request( 'POST', 'cart', { body, idempotent: true } ),
		listPlans: () => request( 'GET', 'plans' ),
		getPlan: ( uuid ) => request( 'GET', 'plans/' + enc( uuid ) ),
		createPlan: ( body ) => request( 'POST', 'plans', { body } ),
		updatePlan: ( uuid, body ) => request( 'PATCH', 'plans/' + enc( uuid ), { body } ),
		deletePlan: ( uuid ) => request( 'DELETE', 'plans/' + enc( uuid ) ),
		duplicatePlan: ( uuid ) => request( 'POST', 'plans/' + enc( uuid ) + '/duplicate', { body: {} } ),
		/**
		 * Withdraws the consent to store plans and deletes every plan (and share link) of the
		 * logged-in customer: DELETE /plans/consent { confirm: true }. Not retried automatically.
		 *
		 * @return {Promise<Object>} Response { deleted_plans, deleted_shares } on success.
		 */
		withdrawConsent: () => request( 'DELETE', 'plans/consent', { body: { confirm: true } } ),
		listShares: ( uuid ) => request( 'GET', 'plans/' + enc( uuid ) + '/shares' ),
		createShare: ( uuid, body ) => request( 'POST', 'plans/' + enc( uuid ) + '/shares', { body } ),
		revokeShare: ( uuid, id ) => request( 'DELETE', 'plans/' + enc( uuid ) + '/shares/' + enc( id ) ),
		shared: ( token ) => request( 'GET', 'shared', { headers: share( token ) } ),
		/**
		 * POST /exports; `store_protocols` (the IDs of the store protocols the workspace started from)
		 * is added only when there are any.
		 *
		 * @param {string}   format         Format.
		 * @param {Object}   plan           Protocol document.
		 * @param {string[]} storeProtocols Store protocol IDs.
		 * @return {Promise<Object>} { blob, filename, type }.
		 */
		exportPlan: ( format, plan, storeProtocols = [] ) => {
			const ids = storeProtocolIds( storeProtocols );
			const body = ids.length > 0 ? { format, plan, store_protocols: ids } : { format, plan };
			return request( 'POST', 'exports', { body, raw: true, idempotent: true } );
		},
		/**
		 * GET /exports/{uuid}; store protocol IDs travel in the X-ARP-Store-Protocols header (never in
		 * the query string), only when there are any.
		 *
		 * @param {string}   uuid           Saved protocol ID.
		 * @param {string}   format         Format.
		 * @param {string[]} storeProtocols Store protocol IDs.
		 * @return {Promise<Object>} { blob, filename, type }.
		 */
		exportSaved: ( uuid, format, storeProtocols = [] ) => {
			const ids = storeProtocolIds( storeProtocols );
			const opts = { query: { format }, raw: true };
			if ( ids.length > 0 ) {
				opts.headers = { [ STORE_PROTOCOLS_HEADER ]: ids.join( ',' ) };
			}
			return request( 'GET', 'exports/' + enc( uuid ), opts );
		},
		exportShared: ( token, format ) => request( 'GET', 'exports/shared', { query: { format }, headers: share( token ), raw: true } ),
		/**
		 * GET /store-protocols (filtered, paged cards). Browser cache only for guests.
		 *
		 * @param {Object} query { group, product, search, offset, limit }.
		 * @return {Promise<Object>} Page.
		 */
		storeProtocols: ( query ) => request( 'GET', 'store-protocols', { query: storeProtocolsQuery( query ), cache: storeCache } ),
		/**
		 * GET /store-protocols/{id} (one shown store protocol). Browser cache only for guests.
		 *
		 * @param {string} id Store protocol ID.
		 * @return {Promise<Object>} Detail.
		 */
		storeProtocol: ( id ) => request( 'GET', 'store-protocols/' + enc( id ), { cache: storeCache } ),
		/**
		 * GET /store-protocols/{id}/edit (managers: any stored protocol, never cached).
		 *
		 * @param {string} id Store protocol ID.
		 * @return {Promise<Object>} Detail with edit fields.
		 */
		storeProtocolForEdit: ( id ) => request( 'GET', 'store-protocols/' + enc( id ) + '/edit' ),
		/**
		 * POST /store-protocols (managers: publish the workspace as a new store protocol). Not retried.
		 *
		 * @param {Object} body { name, plan, customer_picks }.
		 * @return {Promise<Object>} Result.
		 */
		createStoreProtocol: ( body ) => request( 'POST', 'store-protocols', { body } ),
		/**
		 * PUT /store-protocols/{id} (managers: replace a store protocol's items). Not retried.
		 *
		 * @param {string} id   Store protocol ID.
		 * @param {Object} body { plan, customer_picks, updated_at }.
		 * @return {Promise<Object>} Result.
		 */
		updateStoreProtocol: ( id, body ) => request( 'PUT', 'store-protocols/' + enc( id ), { body } ),
	};
}
