/**
 * Entry point of the planner bundle (assets/dist/planner.js): reads the server-rendered
 * #arp-config (no nonces in it) and mounts the app into [data-arp-root].
 *
 * Exposes a minimal global `window.ArpPlanner` ({ version, addProduct( productId ) }).
 *
 * @module main
 */

import { createApp } from './app.js';
import { h, render } from './dom.js';
import { __ } from './i18n.js';

/**
 * Shows a fatal configuration error inside the root.
 *
 * @param {HTMLElement} root Root.
 */
function showConfigError( root ) {
	root.removeAttribute( 'aria-busy' );
	render(
		root,
		h(
			'div',
			{ class: 'arp-notice arp-notice--error', role: 'alert' },
			h( 'p', null, __( 'The planner could not start. Please reload the page.' ) )
		)
	);
}

/** Mounts the planner once. */
function mount() {
	const root = document.querySelector( '[data-arp-root]' );
	const configEl = document.getElementById( 'arp-config' );
	if ( ! root || root.dataset.arpMounted === '1' ) {
		return;
	}
	let config = null;
	try {
		config = configEl ? JSON.parse( configEl.textContent || '' ) : null;
	} catch ( e ) {
		config = null;
	}
	if ( ! config || typeof config !== 'object' || typeof config.rest_root !== 'string' || config.rest_root === '' ) {
		showConfigError( root );
		return;
	}
	root.dataset.arpMounted = '1';
	try {
		const app = createApp( root, config );
		window.ArpPlanner = Object.freeze( {
			version: typeof config.version === 'string' ? config.version : '',
			addProduct: ( productId ) => app.addProduct( Number( productId ) ),
		} );
		app.boot();
	} catch ( e ) {
		showConfigError( root );
	}
}

if ( document.readyState === 'loading' ) {
	document.addEventListener( 'DOMContentLoaded', mount );
} else {
	mount();
}
