/**
 * Two-step flow (CHANGE-1.1.0 §9.1): ARIA tabs "1 Choose products" and "2 Plan & quantities" (with a
 * count badge of the products in the protocol). Keyboard behaviour follows the ARIA tabs pattern
 * (Left/Right/Home/End move focus and select; automatic activation). The selected step is kept in
 * the URL hash (`#plan` for step 2), so the browser's back and forward buttons switch steps.
 *
 * @module components/steps
 */

import { h, uid } from '../app/dom.js';
import { __, _n, sprintf } from '../app/i18n.js';

/** Hash of step 2. */
export const PLAN_HASH = '#plan';

/**
 * Step index for a URL hash: 1 (step 2) for #plan, else 0.
 *
 * @param {string} hash location.hash.
 * @return {number} Index.
 */
export function stepFromHash( hash ) {
	return String( hash || '' ) === PLAN_HASH ? 1 : 0;
}

/**
 * Whether a URL hash belongs to the step tabs: '' (or a bare '#') for step 1, '#plan' for step 2.
 * Other fragments (a theme's "Skip to content" link, in-page anchors) never change the step.
 *
 * @param {string} hash location.hash.
 * @return {boolean} Owned by the tabs.
 */
export function isStepHash( hash ) {
	const value = String( hash || '' );
	return value === '' || value === '#' || value === PLAN_HASH;
}

/**
 * Creates the steps.
 *
 * @param {Object}        options          Options.
 * @param {HTMLElement[]} options.panels   Contents of step 1 and step 2.
 * @param {Function}      options.onChange ( index ) => void, after a step was shown.
 * @return {{el: HTMLElement, select: Function, current: Function, setCount: Function, sync: Function}} Steps.
 */
export function createSteps( options ) {
	const labels = [ __( 'Choose products' ), __( 'Plan & quantities' ) ];
	const badge = h( 'span', { class: 'arp-tab__badge', hidden: true } );
	const tabs = [];
	const panels = [];
	let index = 0;

	options.panels.forEach( ( content, i ) => {
		const tabId = uid( 'tab' );
		const panelId = uid( 'tabpanel' );
		const tab = h(
			'button',
			{
				type: 'button',
				role: 'tab',
				id: tabId,
				class: 'arp-tab',
				'aria-controls': panelId,
				'aria-selected': i === 0 ? 'true' : 'false',
				tabindex: i === 0 ? '0' : '-1',
				onClick: () => select( i, { push: true } ),
			},
			h( 'span', { class: 'arp-tab__step' }, String( i + 1 ) ),
			h( 'span', { class: 'arp-tab__label' }, ' ' + labels[ i ] ),
			i === 1 ? badge : null
		);
		const panel = h( 'div', { role: 'tabpanel', id: panelId, class: 'arp-tabpanel', 'aria-labelledby': tabId, hidden: i !== 0 }, content );
		tabs.push( tab );
		panels.push( panel );
	} );

	const list = h( 'div', { class: 'arp-tabs', role: 'tablist', 'aria-label': __( 'Protocol builder steps' ) }, tabs );
	list.addEventListener( 'keydown', ( event ) => {
		const at = tabs.indexOf( event.target );
		if ( at < 0 ) {
			return;
		}
		let next = -1;
		if ( event.key === 'ArrowRight' ) {
			next = ( at + 1 ) % tabs.length;
		} else if ( event.key === 'ArrowLeft' ) {
			next = ( at - 1 + tabs.length ) % tabs.length;
		} else if ( event.key === 'Home' ) {
			next = 0;
		} else if ( event.key === 'End' ) {
			next = tabs.length - 1;
		}
		if ( next >= 0 ) {
			event.preventDefault();
			select( next, { push: true } );
			tabs[ next ].focus();
		}
	} );

	/**
	 * Shows a step.
	 *
	 * @param {number}  i               Index (0 or 1).
	 * @param {Object}  opts            Options.
	 * @param {boolean} opts.push       Add a history entry (#plan for step 2).
	 * @param {boolean} opts.replace    Replace the current history entry instead.
	 * @return {boolean} Whether the step changed.
	 */
	function select( i, opts = {} ) {
		const next = i === 1 ? 1 : 0;
		if ( opts.push || opts.replace ) {
			const url = window.location.pathname + window.location.search + ( next === 1 ? PLAN_HASH : '' );
			const same = stepFromHash( window.location.hash ) === next && ( next === 1 || window.location.hash === '' );
			try {
				if ( opts.replace ) {
					window.history.replaceState( window.history.state, '', url );
				} else if ( ! same ) {
					window.history.pushState( window.history.state, '', url );
				}
			} catch ( e ) {
				// History is unavailable (sandboxed frame): the step still changes.
			}
		}
		if ( next === index ) {
			return false;
		}
		index = next;
		tabs.forEach( ( tab, k ) => {
			tab.setAttribute( 'aria-selected', k === index ? 'true' : 'false' );
			tab.setAttribute( 'tabindex', k === index ? '0' : '-1' );
		} );
		panels.forEach( ( panel, k ) => {
			panel.hidden = k !== index;
		} );
		if ( typeof options.onChange === 'function' ) {
			options.onChange( index );
		}
		return true;
	}

	return {
		el: h( 'div', { class: 'arp-stepper-tabs' }, list, panels ),
		select,
		current: () => index,
		/**
		 * Count badge of step 2 (number of products).
		 *
		 * @param {number} n Products.
		 */
		setCount( n ) {
			const text = n > 0 ? String( n ) : '';
			if ( badge.dataset.count !== text ) {
				badge.dataset.count = text;
				badge.replaceChildren( h( 'span', { 'aria-hidden': 'true' }, text ), h( 'span', { class: 'arp-sr-only' }, n > 0 ? sprintf( /* translators: %d: number of products. */ _n( '(%d product)', '(%d products)', n ), n ) : '' ) );
				badge.hidden = n === 0;
			}
		},
		/** Shows the step of the current URL hash (back / forward); other fragments are ignored. */
		sync() {
			if ( isStepHash( window.location.hash ) ) {
				select( stepFromHash( window.location.hash ) );
			}
		},
	};
}
