/**
 * "Pre-built protocols" section (CHANGE-1.7.0 §6.3–§6.5, §6.12, §6.14; CHANGE-1.7.1 §2.9): ready-made
 * protocols written by the store (internally "store protocols"), shown in the builder's "Pre-built
 * protocols" view (app.js). Group chips with counts, a text filter, a per-product filter, a capped
 * first view of cards with "Show more pre-built protocols", and a dialog per protocol with the
 * store's notice, its steps (week ranges, amount per use, times per week, daily and weekly totals),
 * the store's notes, shop links and "Use this protocol".
 *
 * Since 1.7.1 the section can be expected to have protocols (option `expected`, the page-config
 * hint): it is then shown from the first paint with a loading line and placeholder cards until the
 * first view settles. It reports whether the store shows any (`available()`, `onAvailability()`),
 * never takes focus, scrolls or speaks while its view is hidden (option `isShown`), and a dialog
 * that cannot return focus into it returns it to `focusFallback()`.
 *
 * The section never applies anything itself: "Use this protocol" calls `onUse( detail, ctx )`
 * (app.js), which closes the dialog through `ctx.close()` before it changes the workspace. Every
 * store-written text (names, group labels, descriptions, notes, line labels, product names) goes
 * into the page as text only and is marked `data-arp-merchant`.
 *
 * @module components/store-protocols
 */

import { h, uid, icon, button, debounce, render } from '../app/dom.js';
import { __, _n, sprintf } from '../app/i18n.js';
import { money, formatNumber } from '../app/format.js';
import { formatLabel } from '../app/catalog.js';
import { focusElement, scrollIntoViewSafe } from '../app/a11y.js';
import { buildWhatsAppMessage, whatsappUrl } from '../app/whatsapp.js';
import { normalizeStoreProtocolPage, normalizeStoreProtocol, lineFigures, storeProtocolId, storeWhatsAppEntries, STORE_GROUP_KEY } from '../app/store-templates.js';
import { openDialog } from './modal.js';
import { periodRangeLabel } from './timeline.js';
import { durationText } from './line-card.js';
import { amountText } from './explain.js';

/** Cards of the first view and of every reload (§6.3). */
export const FIRST_VIEW = 6;

/** Cards added by "Show more pre-built protocols" (§6.3). */
export const MORE_LIMIT = 12;

/**
 * Nodes of a translated format whose placeholders take values: a store-written value is inserted as
 * a span marked `data-arp-merchant` (the wording scans skip exactly the store's words), everything
 * else stays plain text. Supports %s, %d and positional %1$s / %2$d.
 *
 * @param {string}                                     format Translated format.
 * @param {Array<{text: string|number, merchant?: boolean}>} values Values.
 * @return {Array<string|Node>} Nodes.
 */
export function withMerchant( format, values ) {
	const out = [];
	const re = /%(?:(\d+)\$)?([sd%])/g;
	let next = 0;
	let last = 0;
	let m;
	const text = String( format );
	while ( ( m = re.exec( text ) ) ) {
		if ( m.index > last ) {
			out.push( text.slice( last, m.index ) );
		}
		last = re.lastIndex;
		if ( m[ 2 ] === '%' ) {
			out.push( '%' );
			continue;
		}
		const value = values[ m[ 1 ] ? Number( m[ 1 ] ) - 1 : next++ ];
		if ( value ) {
			out.push( value.merchant ? h( 'span', { 'data-arp-merchant': true }, String( value.text ) ) : String( value.text ) );
		}
	}
	if ( last < text.length ) {
		out.push( text.slice( last ) );
	}
	return out;
}

/**
 * Week range of a line: "Week 1", "Weeks 2–4".
 *
 * @param {number} startWeek Start week.
 * @param {number} weeks     Weeks.
 * @return {string} Label.
 */
function weekRange( startWeek, weeks ) {
	return periodRangeLabel( 'week', startWeek - 1, startWeek + weeks - 2 );
}

/**
 * Asks how to use a store protocol in a workspace that is not untouched (§6.6 step 3): a stacked
 * dialog with "Replace your items" (primary), "Add to your items" and "Cancel" (initial focus).
 * When the items would exceed the maximum, "Add to your items" is aria-disabled and described by
 * the limit text. Cancel or Escape resolve null; focus returns to the control that opened it.
 *
 * @param {Object}  options          Options.
 * @param {boolean} options.canAdd   Adding stays within the maximum number of items.
 * @param {number}  options.maxLines Maximum number of items.
 * @param {boolean} options.hasItems The workspace has items (message S27, else S27b).
 * @return {Promise<'replace'|'add'|null>} Choice.
 */
export function chooseApplyMode( { canAdd = true, maxLines = 0, hasItems = false } = {} ) {
	return new Promise( ( resolve ) => {
		const messageId = uid( 'sproto-choice' );
		const limitId = uid( 'sproto-limit' );
		const message = hasItems
			? __( 'Your protocol already has items. Replace them with this pre-built protocol, or add its items to your protocol. To keep your current protocol, save it in My protocols first.' )
			: __( 'Your protocol has a name, notes, a start date or a saved copy of its own. Replacing it with this pre-built protocol replaces them; adding its items keeps them. To keep your current protocol, save it in My protocols first.' );
		openDialog( {
			title: __( 'Use this pre-built protocol?' ),
			size: 'sm',
			role: 'dialog',
			content: h(
				'div',
				{ class: 'arp-sproto-choice' },
				h( 'p', { class: 'arp-dialog__text arp-sproto-choice__text', id: messageId }, message ),
				canAdd
					? null
					: h(
						'p',
						{ class: 'arp-sproto-choice__limit', id: limitId },
						/* translators: %d: maximum number of items in a protocol. */
						sprintf( __( 'A protocol can contain up to %d items, so this pre-built protocol can only replace your items.' ), maxLines )
					)
			),
			describedBy: messageId,
			initialFocus: '.arp-sproto-choice__cancel',
			onClose: ( value ) => resolve( value === 'replace' || value === 'add' ? value : null ),
			actions: ( dlg ) => [
				button( { label: __( 'Replace your items' ), variant: 'primary', cls: 'arp-sproto-choice__replace', onClick: () => dlg.close( 'replace' ) } ),
				button( {
					label: __( 'Add to your items' ),
					cls: 'arp-sproto-choice__add',
					attrs: canAdd ? {} : { 'aria-disabled': 'true', 'aria-describedby': limitId },
					onClick: () => {
						if ( canAdd ) {
							dlg.close( 'add' );
						}
					},
				} ),
				button( { label: __( 'Cancel' ), cls: 'arp-sproto-choice__cancel', onClick: () => dlg.close( null ) } ),
			],
		} );
	} );
}

/**
 * Creates the "Pre-built protocols" section.
 *
 * @param {Object}   options               Options.
 * @param {Object}   options.api           API client (storeProtocols(), storeProtocol()).
 * @param {Object}   options.currency      Currency settings (separators and money).
 * @param {boolean}  options.showPrices    Show "from" prices.
 * @param {boolean}  options.showImages    Show the first product's image on cards.
 * @param {string}   options.notice        The pre-built protocol notice (setting); '' = the default text.
 * @param {Function} options.whatsapp      () => ({ number, template }) | null.
 * @param {Function} options.onUse         ( detail, ctx ) => Promise<boolean>; ctx = { opener, close(), showError( message ) }.
 * @param {Function} options.announce      ( message ) => void.
 * @param {Function} options.toast         ( message, { tone } ) => void.
 * @param {boolean}  options.expected      The section is expected to have protocols (page-config
 *                                         hint, CHANGE-1.7.1 §2.9): shown with a loading state until
 *                                         the first view settles. Default false (hidden until the
 *                                         first successful load says there are protocols).
 * @param {Function} options.isShown       () => boolean: the visitor can see the section's view
 *                                         (default always). While false the section never takes
 *                                         focus, scrolls or announces counts.
 * @param {Function} options.focusFallback () => HTMLElement|null: where a dialog returns focus when
 *                                         the section is hidden, read-only or not shown (default null).
 * @return {Object} Section API (§6.14).
 */
export function createStoreProtocols( options ) {
	let currency = options.currency;
	const expected = options.expected === true;
	const isShown = () => ( typeof options.isShown === 'function' ? options.isShown() !== false : true );
	const focusFallback = () => ( typeof options.focusFallback === 'function' ? options.focusFallback() || null : null );
	const state = {
		group: '',
		product: 0,
		productName: '',
		search: '',
		items: [],
		total: 0,
		allCount: 0,
		groups: [],
		productCounts: new Map(),
		countsKey: '',
		nextOffset: 0,
		seq: 0,
		loading: false,
		loadingMore: false,
		any: false,
		/** A first-view request has succeeded at least once (`any` is known). */
		known: false,
		/** The latest, non-superseded first-view request has finished once (success or failure). */
		settled: false,
		/** The app could not start (boot error): no loading state meanwhile. */
		stalled: false,
		readOnly: false,
		retry: null,
	};
	const availabilityListeners = new Set();
	/** Labels of every group seen (the pressed chip keeps its label when a search empties it). */
	const groupLabels = new Map();
	/** Keys of every group seen, in group order. */
	let groupOrder = [];
	/** Card references by protocol ID: { el, view }. */
	const refs = new Map();
	const countListeners = new Set();
	let activeDialog = null;
	/** Latest detail request (View or open()): an older response opens nothing. */
	let detailSeq = 0;
	let moreOrigin = null;
	let chipKeys = null;
	/** Latest first-view request. */
	let latest = Promise.resolve( true );

	let settleReady = null;
	let readySettled = false;
	const ready = new Promise( ( resolve ) => {
		settleReady = () => {
			if ( ! readySettled ) {
				readySettled = true;
				resolve();
			}
		};
	} );

	const announce = ( message ) => {
		if ( typeof options.announce === 'function' && message ) {
			options.announce( message );
		}
	};
	const toast = ( message ) => {
		if ( typeof options.toast === 'function' ) {
			options.toast( message, { tone: 'error' } );
		}
	};
	const noticeText = () =>
		typeof options.notice === 'string' && options.notice.trim() !== ''
			? options.notice.trim()
			: __( 'Written by the store for research use. Check every value before you order. Not medical advice.' );
	const notAvailable = () => __( 'This pre-built protocol is not available.' );
	const loadFailed = () => __( 'This pre-built protocol could not be loaded. Please try again.' );

	/* ---------------------------------------------------------------- Layout. */

	const titleId = uid( 'sprotos-title' );
	const inputId = uid( 'sprotos-filter' );
	const heading = h( 'h2', { class: 'arp-section-head__title arp-sprotos__title', id: titleId, tabindex: '-1' }, __( 'Pre-built protocols' ) );
	const notice = h( 'p', { class: 'arp-sprotos__notice', role: 'note' }, noticeText() );
	// Loading line of an expected section (no live role: the heading, the notice and this line stay
	// readable while the list is busy).
	const loadingLine = h( 'p', { class: 'arp-sprotos__loading', hidden: true }, __( 'Loading pre-built protocols…' ) );
	const chips = h( 'div', { class: 'arp-chips arp-sprotos__chips', role: 'group', 'aria-label': __( 'Protocol groups' ), hidden: true } );
	const input = h( 'input', {
		id: inputId,
		class: 'arp-input arp-sprotos__search',
		type: 'search',
		placeholder: __( 'Protocol or product name' ),
		maxlength: '100',
		autocomplete: 'off',
		spellcheck: 'false',
		enterkeyhint: 'search',
	} );
	const filter = h( 'div', { class: 'arp-field arp-sprotos__filter' }, h( 'label', { class: 'arp-label', for: inputId }, __( 'Filter pre-built protocols' ) ), input );
	const pillText = h( 'span', { class: 'arp-sprotos__pill-text' } );
	const pill = h(
		'p',
		{ class: 'arp-sprotos__pill', hidden: true },
		pillText,
		button( { label: __( 'Show all pre-built protocols' ), variant: 'link', size: 'sm', cls: 'arp-sprotos__pill-clear', onClick: () => clearProduct() } )
	);
	const countEl = h( 'p', { class: 'arp-sprotos__count' } );
	const errorSlot = h( 'div', { class: 'arp-sprotos__error' } );
	const list = h( 'ul', { class: 'arp-sprotos__list' } );
	const empty = h(
		'div',
		{ class: 'arp-empty arp-sprotos__empty', hidden: true },
		h( 'p', { class: 'arp-empty__title' }, __( 'No pre-built protocols match your filter.' ) ),
		button( { label: __( 'Show all pre-built protocols' ), cls: 'arp-sprotos__empty-clear', onClick: () => clearAll() } )
	);
	// One persistent button (never re-created or disabled), so it keeps focus while loading.
	const moreButton = h(
		'button',
		{
			type: 'button',
			class: 'arp-btn arp-btn--secondary arp-sprotos__more',
			hidden: true,
			onClick: () => loadMore(),
		},
		h( 'span', { class: 'arp-btn__label' }, __( 'Show more pre-built protocols' ) )
	);
	const el = h( 'section', { class: 'arp-sprotos', 'aria-labelledby': titleId, hidden: true }, heading, notice, loadingLine, chips, filter, pill, countEl, errorSlot, list, empty, moreButton );

	/* ---------------------------------------------------------------- Rendering. */

	/** Visible while the store shows protocols, or before the first success while they are expected. */
	const renderVisibility = () => {
		el.hidden = ! ( state.known ? state.any : expected );
	};

	/** The first view is expected and has not settled yet (§2.9). */
	const firstPending = () => expected && ! state.settled;

	/** Placeholder cards of the loading state (as many as the first view shows). */
	let placeholders = null;

	/**
	 * Loading state of an expected section: the loading line, FIRST_VIEW placeholder cards and
	 * aria-busy on the list while the first view loads (not while stalled); the filter is hidden
	 * until the first view settled. Placeholders are removed when the state ends (the first
	 * renderList() replaces them anyway).
	 */
	const renderLoading = () => {
		const loading = firstPending() && ! state.stalled;
		loadingLine.hidden = ! loading;
		filter.hidden = firstPending();
		if ( loading ) {
			list.setAttribute( 'aria-busy', 'true' );
			if ( ! placeholders ) {
				placeholders = Array.from( { length: FIRST_VIEW }, () => h( 'li', { class: 'arp-sproto-card arp-sproto-card--skeleton', 'aria-hidden': 'true' }, h( 'span', { class: 'arp-sk' } ) ) );
				render( list, placeholders );
			}
			return;
		}
		list.removeAttribute( 'aria-busy' );
		if ( placeholders ) {
			placeholders.forEach( ( node ) => node.remove() );
			placeholders = null;
		}
	};

	const countText = () =>
		sprintf(
			/* translators: 1: number of pre-built protocols shown, 2: number of pre-built protocols found. */
			_n( 'Showing %1$d of %2$d pre-built protocol', 'Showing %1$d of %2$d pre-built protocols', state.total ),
			state.items.length,
			state.total
		);

	/** Writes the count only when it changed. */
	const renderCount = () => {
		const text = countText();
		if ( countEl.textContent !== text ) {
			countEl.textContent = text;
		}
	};

	const updateMore = () => {
		moreButton.hidden = state.loading || state.nextOffset >= state.total || state.items.length === 0;
		if ( state.loadingMore ) {
			moreButton.setAttribute( 'aria-busy', 'true' );
		} else {
			moreButton.removeAttribute( 'aria-busy' );
		}
	};

	const renderPill = () => {
		pill.hidden = state.product === 0;
		if ( state.product === 0 ) {
			render( pillText );
			return;
		}
		/* translators: %s: product name. */
		render( pillText, withMerchant( __( 'Pre-built protocols for %s' ), [ { text: state.productName || '#' + state.product, merchant: true } ] ) );
	};

	/**
	 * Chip entries: "All", every group of the response and, when the pressed group is not listed (a
	 * search left no match in it), that group with the count 0 at its usual place.
	 *
	 * @return {Array<{key: string, label: string, count: number}>} Entries.
	 */
	const chipEntries = () => {
		const entries = state.groups.map( ( g ) => ( { key: g.key, label: g.label, count: g.count } ) );
		if ( state.group !== '' && ! entries.some( ( g ) => g.key === state.group ) ) {
			const rank = ( key ) => {
				const i = groupOrder.indexOf( key );
				return i < 0 ? Number.MAX_SAFE_INTEGER : i;
			};
			const own = rank( state.group );
			const at = entries.findIndex( ( g ) => rank( g.key ) > own );
			const pressed = { key: state.group, label: groupLabels.get( state.group ) || state.group, count: 0 };
			entries.splice( at < 0 ? entries.length : at, 0, pressed );
		}
		return entries;
	};

	const chipContent = ( entry ) =>
		entry.key === ''
			? /* translators: %d: number of pre-built protocols. */ [ sprintf( __( 'All (%d)' ), entry.count ) ]
			: /* translators: 1: group name, 2: number of pre-built protocols. */ withMerchant( __( '%1$s (%2$d)' ), [ { text: entry.label, merchant: true }, { text: entry.count } ] );

	/**
	 * Renders the group chips. When the same groups are shown, labels and pressed states are patched
	 * in place (a focused chip keeps focus); otherwise the chips are rebuilt and focus moves to the
	 * chip with the same key, else to the pressed one.
	 */
	const renderChips = () => {
		const groups = chipEntries();
		if ( groups.length === 0 ) {
			chips.hidden = true;
			chipKeys = null;
			render( chips );
			return;
		}
		chips.hidden = false;
		const entries = [ { key: '', label: '', count: state.allCount }, ...groups ];
		const keys = entries.map( ( e ) => e.key ).join( '\n' );
		const patch = ( chip, entry ) => {
			chip.setAttribute( 'aria-pressed', entry.key === state.group ? 'true' : 'false' );
			chip.classList.toggle( 'is-active', entry.key === state.group );
			render( chip, chipContent( entry ) );
		};
		if ( keys === chipKeys ) {
			Array.from( chips.children ).forEach( ( chip, i ) => patch( chip, entries[ i ] ) );
			return;
		}
		const active = document.activeElement;
		const focused = active && chips.contains( active ) ? active.getAttribute( 'data-group' ) : null;
		chipKeys = keys;
		render(
			chips,
			entries.map( ( entry ) => {
				const chip = h( 'button', { type: 'button', class: 'arp-chip', 'data-group': entry.key, onClick: () => pressGroup( entry.key ) } );
				patch( chip, entry );
				return chip;
			} )
		);
		if ( focused !== null ) {
			const target = Array.from( chips.children ).find( ( c ) => c.getAttribute( 'data-group' ) === focused ) || chips.querySelector( '[aria-pressed="true"]' );
			if ( target ) {
				target.focus();
			}
		}
	};

	/**
	 * Definition list of figures.
	 *
	 * @param {string}                 cls     Class.
	 * @param {Object|null}            figures lineFigures() result.
	 * @param {Array<[string, string]>} extra  Further rows.
	 * @return {HTMLElement|null} List.
	 */
	const figureList = ( cls, figures, extra = [] ) => {
		const rows = [];
		if ( figures ) {
			rows.push( [ __( 'Amount per use' ), amountText( { value: figures.amount, unit: figures.unit }, currency ) ] );
			rows.push( [ __( 'Times per week' ), formatNumber( String( figures.timesPerWeek ), currency ) ] );
			if ( figures.dailyTotal !== null ) {
				rows.push( [ __( 'Daily total' ), amountText( { value: figures.dailyTotal, unit: figures.unit }, currency ) ] );
			}
			rows.push( [ __( 'Weekly total' ), amountText( { value: figures.weeklyTotal, unit: figures.unit }, currency ) ] );
		}
		rows.push( ...extra );
		return rows.length === 0 ? null : h( 'dl', { class: cls }, rows.map( ( [ term, value ] ) => h( 'div', null, h( 'dt', null, term ), h( 'dd', null, value ) ) ) );
	};

	const formatsOf = ( protocol ) => [ ...new Set( protocol.products.map( ( p ) => p.format ).filter( ( f ) => f !== '' ) ) ];

	const card = ( protocol ) => {
		const nameId = uid( 'sproto-name' );
		const tags = [
			...formatsOf( protocol ).map( ( f ) => h( 'span', { class: 'arp-badge arp-badge--muted' }, formatLabel( f ) ) ),
			protocol.group ? h( 'span', { class: 'arp-badge arp-badge--primary', 'data-arp-merchant': true }, protocol.group.label ) : null,
		].filter( Boolean );
		const lead = protocol.lead;
		const leadProduct = lead ? protocol.products.find( ( p ) => p.productId === lead.productId ) : null;
		const image = options.showImages && protocol.products[ 0 ] ? protocol.products[ 0 ].image : null;
		const extra = [];
		if ( protocol.totalWeeks > 0 ) {
			extra.push( [ __( 'Duration' ), durationText( 'week', protocol.totalWeeks, formatNumber( String( protocol.totalWeeks ), currency ) ) ] );
		}
		if ( protocol.lineCount > 1 ) {
			/* translators: %d: number of steps of a pre-built protocol. */
			extra.push( [ __( 'Steps' ), sprintf( _n( '%d step', '%d steps', protocol.lineCount ), protocol.lineCount ) ] );
		}
		const price = options.showPrices && protocol.fromPrice !== '' ? money( protocol.fromPrice, currency ) : '';
		const view = h(
			'button',
			{ type: 'button', class: 'arp-btn arp-btn--primary arp-sproto-card__view', 'aria-describedby': nameId, onClick: () => openFromCard( protocol.id, view ) },
			h( 'span', { class: 'arp-btn__label' }, __( 'View protocol' ) )
		);
		const li = h(
			'li',
			{ class: 'arp-sproto-card', 'data-protocol': protocol.id },
			tags.length > 0 ? h( 'p', { class: 'arp-sproto-card__tags' }, tags ) : null,
			h( 'h3', { class: 'arp-sproto-card__name', id: nameId, 'data-arp-merchant': true }, protocol.name ),
			h( 'p', { class: 'arp-sproto-card__products', 'data-arp-merchant': true }, protocol.products.map( ( p ) => p.name ).filter( Boolean ).join( ' + ' ) ),
			protocol.description !== '' ? h( 'p', { class: 'arp-sproto-card__desc', 'data-arp-merchant': true }, protocol.description ) : null,
			image
				? h(
					'div',
					{ class: 'arp-sproto-card__media' },
					h( 'img', {
						class: 'arp-sproto-card__img',
						src: image.src,
						srcset: image.srcset || null,
						sizes: image.srcset ? '(min-width: 1024px) 300px, 90vw' : null,
						alt: '',
						width: String( image.width ),
						height: String( image.height ),
						loading: 'lazy',
						decoding: 'async',
					} )
				)
				: null,
			lead && ( protocol.lineCount > 1 || protocol.products.length > 1 )
				? h(
					'p',
					{ class: 'arp-sproto-card__lead' },
					/* translators: 1: product name, 2: week range such as "Week 1". */
					withMerchant( __( 'First step: %1$s · %2$s' ), [ { text: leadProduct ? leadProduct.name : '', merchant: true }, { text: weekRange( lead.startWeek, lead.weeks ) } ] )
				)
				: null,
			figureList( 'arp-sproto-card__figures', lead ? lineFigures( lead ) : null, extra ),
			/* translators: %s: lowest total price of one unit of each product. */
			price !== '' ? h( 'p', { class: 'arp-sproto-card__price' }, sprintf( __( 'from %s' ), price ) ) : null,
			view
		);
		refs.set( protocol.id, { el: li, view } );
		return li;
	};

	/** Renders every card (keeps focus on the same View button when one had it). */
	const renderList = () => {
		const active = document.activeElement;
		const focusedId = Array.from( refs.entries() ).find( ( [ , ref ] ) => ref.view === active );
		refs.clear();
		render( list, state.items.map( card ) );
		if ( focusedId ) {
			const ref = refs.get( focusedId[ 0 ] );
			if ( ref ) {
				ref.view.focus();
			}
		}
		empty.hidden = state.items.length > 0 || ! state.any;
	};

	const renderAll = () => {
		renderVisibility();
		renderLoading();
		renderChips();
		renderPill();
		renderCount();
		renderList();
		updateMore();
	};

	/**
	 * Inline load error with "Try again" (the cards already shown stay).
	 *
	 * @param {Function} retry Action to repeat.
	 */
	const showLoadError = ( retry ) => {
		state.retry = retry;
		render(
			errorSlot,
			h(
				'div',
				{ class: 'arp-notice arp-notice--error', role: 'alert' },
				h( 'p', null, __( 'Pre-built protocols could not be loaded.' ) ),
				button( {
					label: __( 'Try again' ),
					iconName: 'refresh',
					size: 'sm',
					onClick: () => {
						const again = state.retry;
						if ( again ) {
							again();
						}
					},
				} )
			)
		);
	};

	const hideLoadError = () => {
		state.retry = null;
		if ( errorSlot.firstChild ) {
			// Focus on "Try again" would be lost with the message: keep it in the section.
			const hadFocus = errorSlot.contains( document.activeElement );
			render( errorSlot );
			if ( hadFocus ) {
				focusElement( heading, { preventScroll: true } );
			}
		}
	};

	/* ---------------------------------------------------------------- Data. */

	/**
	 * Updates the known group order from a response's groups (in the store's group order). Only a
	 * response without a text or product filter lists every group, so only it sets the whole order;
	 * a filtered one keeps the order of the known keys and inserts an unseen key right after its
	 * predecessor in the response (the first key: right before the first known key that follows it
	 * in the response, else at the start), so the pressed chip that a search emptied keeps its place.
	 *
	 * @param {string[]} keys     Group keys of the response.
	 * @param {boolean}  filtered The request had a text or product filter.
	 */
	const mergeGroupOrder = ( keys, filtered ) => {
		if ( ! filtered ) {
			groupOrder = [ ...keys, ...groupOrder.filter( ( key ) => ! keys.includes( key ) ) ];
			return;
		}
		keys.forEach( ( key, i ) => {
			if ( groupOrder.includes( key ) ) {
				return;
			}
			if ( i > 0 ) {
				groupOrder.splice( groupOrder.indexOf( keys[ i - 1 ] ) + 1, 0, key );
				return;
			}
			const next = keys.find( ( k ) => groupOrder.includes( k ) );
			groupOrder.splice( next ? groupOrder.indexOf( next ) : 0, 0, key );
		} );
	};

	/**
	 * Applies a page.
	 *
	 * @param {Object}  page    normalizeStoreProtocolPage() result.
	 * @param {boolean} append  Append to the cards shown ("Show more").
	 * @param {Object}  request query() of the request that returned the page.
	 * @return {Object[]} Cards added.
	 */
	const applyPage = ( page, append, request ) => {
		let added = page.items;
		if ( append ) {
			const known = new Set( state.items.map( ( item ) => item.id ) );
			added = page.items.filter( ( item ) => ! known.has( item.id ) );
			state.items = state.items.concat( added );
		} else {
			state.items = page.items;
		}
		state.total = Math.max( page.total, state.items.length );
		state.allCount = page.allCount;
		state.groups = page.groups;
		page.groups.forEach( ( g ) => groupLabels.set( g.key, g.label ) );
		mergeGroupOrder( page.groups.map( ( g ) => g.key ), request.search !== '' || request.product !== 0 );
		state.nextOffset = Math.min( state.total, page.offset + Math.max( page.limit, page.items.length ) );
		if ( state.nextOffset < state.items.length ) {
			state.nextOffset = state.items.length;
		}
		state.any = page.productCounts.size > 0 || page.total > 0 || page.allCount > 0;
		state.productCounts = page.productCounts;
		const countsKey = JSON.stringify( [ ...page.productCounts ] );
		if ( countsKey !== state.countsKey ) {
			state.countsKey = countsKey;
			countListeners.forEach( ( fn ) => fn() );
		}
		return added;
	};

	const query = ( offset, limit ) => ( { group: state.group, product: state.product, search: state.search, offset, limit } );

	/**
	 * Loads the first view of the current filters. A response that is not the latest request's is
	 * ignored; a pending "Show more" is cancelled.
	 *
	 * @param {boolean} speak Announce the new count (filter actions).
	 * @return {Promise<boolean>} Loaded (false when it failed or was superseded).
	 */
	const reload = ( speak ) => {
		const run = fetchFirstView( speak );
		latest = run;
		return run;
	};

	/**
	 * Waits until the latest list request has settled (a deep link's filter may be superseded by the
	 * start-up load, or the other way round).
	 *
	 * @return {Promise<void>} Settled.
	 */
	const whenSettled = async () => {
		let current;
		do {
			current = latest;
			await current;
		} while ( current !== latest );
	};

	/**
	 * One first-view request (see reload()).
	 *
	 * @param {boolean} speak Announce the new count.
	 * @return {Promise<boolean>} Loaded.
	 */
	const fetchFirstView = async ( speak ) => {
		const seq = ++state.seq;
		state.loading = true;
		state.loadingMore = false;
		updateMore();
		const request = query( 0, FIRST_VIEW );
		let page;
		try {
			page = normalizeStoreProtocolPage( await options.api.storeProtocols( request ) );
		} catch ( e ) {
			if ( seq !== state.seq ) {
				return false;
			}
			state.loading = false;
			// The first view settled: the loading line and the placeholders go before the error shows.
			state.settled = true;
			renderLoading();
			// The cards shown belong to the previous filters: no "Show more" at their offset with the
			// new filters until a first view of these has loaded.
			state.nextOffset = state.total;
			if ( state.any || ( ! state.known && expected ) ) {
				showLoadError( () => reload( speak ) );
			}
			updateMore();
			settleReady();
			return false;
		}
		if ( seq !== state.seq ) {
			return false;
		}
		state.loading = false;
		state.settled = true;
		const first = ! state.known;
		const hadAny = state.any;
		state.known = true;
		hideLoadError();
		applyPage( page, false, request );
		renderAll();
		// Availability (CHANGE-1.7.1 §2.9): after the cards were rendered, before `ready` settles and
		// before the filter announcement.
		if ( first || state.any !== hadAny ) {
			availabilityListeners.forEach( ( fn ) => fn() );
		}
		settleReady();
		if ( speak && isShown() ) {
			announce( countText() );
		}
		return true;
	};

	/** "Show more pre-built protocols": the next 12 cards of the same filters. */
	const loadMore = async () => {
		if ( state.loading || state.loadingMore || state.nextOffset >= state.total ) {
			return;
		}
		// WebKit does not focus a clicked button: remember where focus was when more were asked for.
		moreOrigin = document.activeElement;
		const seq = ++state.seq;
		state.loadingMore = true;
		updateMore();
		const request = query( state.nextOffset, MORE_LIMIT );
		let page;
		try {
			page = normalizeStoreProtocolPage( await options.api.storeProtocols( request ) );
		} catch ( e ) {
			if ( seq !== state.seq ) {
				return;
			}
			state.loadingMore = false;
			updateMore();
			showLoadError( loadMore );
			return;
		}
		if ( seq !== state.seq ) {
			return;
		}
		state.loadingMore = false;
		hideLoadError();
		const added = applyPage( page, true, request );
		const active = document.activeElement;
		const focusWasOnMore = active === moreButton || ! active || active === document.body || ( moreOrigin !== null && active === moreOrigin );
		moreOrigin = null;
		const nodes = added.map( card );
		nodes.forEach( ( node ) => list.appendChild( node ) );
		renderChips();
		renderCount();
		// A view the visitor turned away from meanwhile takes no focus and says nothing.
		const shown = isShown();
		if ( shown && focusWasOnMore && added.length > 0 ) {
			const ref = refs.get( added[ 0 ].id );
			if ( ref ) {
				focusElement( ref.view );
			}
		}
		updateMore();
		if ( shown ) {
			/* translators: %d: number of pre-built protocols added to the list. */
			announce( sprintf( _n( '%d more pre-built protocol loaded.', '%d more pre-built protocols loaded.', added.length ), added.length ) );
		}
	};

	const pressGroup = ( key ) => {
		if ( state.group === key ) {
			return;
		}
		state.group = key;
		renderChips();
		reload( true );
	};

	const onSearch = () => {
		const value = input.value.trim().slice( 0, 100 );
		if ( value === state.search ) {
			return;
		}
		state.search = value;
		reload( true );
	};
	const searchDebounced = debounce( onSearch, 250 );
	input.addEventListener( 'input', () => searchDebounced() );
	input.addEventListener( 'keydown', ( event ) => {
		if ( event.key === 'Enter' ) {
			event.preventDefault();
			searchDebounced.flush();
		}
	} );

	/** Pill "Show all pre-built protocols": clears the product filter, focus to the text filter. */
	const clearProduct = () => {
		state.product = 0;
		state.productName = '';
		renderPill();
		focusElement( input );
		reload( true );
	};

	/** Empty state "Show all pre-built protocols": clears group, text and product filters. */
	const clearAll = () => {
		searchDebounced.cancel();
		input.value = '';
		state.search = '';
		state.group = '';
		state.product = 0;
		state.productName = '';
		renderPill();
		renderChips();
		focusElement( input );
		reload( true );
	};

	/** Clears every filter without loading (deep links and the product entry start afresh). */
	const resetFilters = () => {
		searchDebounced.cancel();
		input.value = '';
		state.search = '';
		state.group = '';
		state.product = 0;
		state.productName = '';
	};

	/** Brings the section into view and focuses its heading (never while its view is hidden). */
	const revealSection = () => {
		if ( state.any && ! state.readOnly && isShown() ) {
			scrollIntoViewSafe( el );
			focusElement( heading );
		}
	};

	/* ---------------------------------------------------------------- Dialog. */

	/**
	 * Loads a protocol's detail.
	 *
	 * @param {*} id Protocol ID.
	 * @return {Promise<{status: string, detail?: Object}>} ok | unavailable | failed.
	 */
	const fetchDetail = async ( id ) => {
		const valid = storeProtocolId( id );
		if ( valid === null ) {
			return { status: 'unavailable' };
		}
		try {
			const detail = normalizeStoreProtocol( await options.api.storeProtocol( valid ) );
			return detail && detail.id === valid ? { status: 'ok', detail } : { status: 'unavailable' };
		} catch ( e ) {
			return e && ( e.status === 404 || e.code === 'arp_not_found' ) ? { status: 'unavailable' } : { status: 'failed' };
		}
	};

	/**
	 * WhatsApp link of a protocol (the protocol name only), or null when WhatsApp is not configured.
	 *
	 * @param {Object} detail Detail.
	 * @return {HTMLElement|null} Link.
	 */
	const whatsappLink = ( detail ) => {
		const conf = typeof options.whatsapp === 'function' ? options.whatsapp() : null;
		if ( ! conf || typeof conf.number !== 'string' || conf.number === '' ) {
			return null;
		}
		const url = whatsappUrl( conf.number, buildWhatsAppMessage( conf.template, storeWhatsAppEntries( detail ) ) );
		if ( url === '' ) {
			return null;
		}
		return h(
			'a',
			{ class: 'arp-btn arp-btn--secondary arp-sproto__whatsapp', href: url, target: '_blank', rel: 'noopener' },
			icon( 'chat' ),
			h( 'span', { class: 'arp-btn__label' }, __( 'Ask about this protocol on WhatsApp' ) )
		);
	};

	/**
	 * Dialog content of a protocol.
	 *
	 * @param {Object}      detail   Detail.
	 * @param {string}      noticeId ID of the notice (describes the dialog).
	 * @param {HTMLElement} errorEl  Inline error region.
	 * @return {HTMLElement} Content.
	 */
	const detailContent = ( detail, noticeId, errorEl ) => {
		const names = new Map( detail.products.map( ( p ) => [ p.productId, p.name ] ) );
		const formats = formatsOf( detail ).map( formatLabel ).join( ', ' );
		const meta = [];
		if ( formats !== '' ) {
			meta.push( formats );
		}
		if ( detail.group ) {
			if ( meta.length > 0 ) {
				meta.push( ' · ' );
			}
			meta.push( h( 'span', { 'data-arp-merchant': true }, detail.group.label ) );
		}
		const step = ( line ) => {
			let option = null;
			if ( line.variationId === 0 && line.defaultVariationId > 0 ) {
				option = h( 'p', { class: 'arp-sproto__step-option' }, __( 'Option of your choice' ) );
			} else if ( line.variationId > 0 && line.variationLabel !== '' ) {
				option = h( 'p', { class: 'arp-sproto__step-option', 'data-arp-merchant': true }, line.variationLabel );
			}
			return h(
				'li',
				{ class: 'arp-sproto__step' },
				h( 'p', { class: 'arp-sproto__step-title' }, weekRange( line.startWeek, line.weeks ), ' · ', h( 'span', { 'data-arp-merchant': true }, names.get( line.productId ) || '' ) ),
				option,
				line.label !== '' ? h( 'p', { class: 'arp-sproto__step-label', 'data-arp-merchant': true }, line.label ) : null,
				figureList( 'arp-sproto__figures', lineFigures( line ) )
			);
		};
		const linked = detail.products.filter( ( p ) => p.permalink !== '' );
		return h(
			'div',
			{ class: 'arp-sproto' },
			h( 'p', { class: 'arp-sproto__notice', role: 'note', id: noticeId }, noticeText() ),
			meta.length > 0 ? h( 'p', { class: 'arp-sproto__meta' }, meta ) : null,
			detail.description !== '' ? h( 'p', { class: 'arp-sproto__desc', 'data-arp-merchant': true }, detail.description ) : null,
			h( 'h3', { class: 'arp-dialog__subtitle arp-sproto__heading' }, __( 'Steps' ) ),
			h( 'ol', { class: 'arp-sproto__steps', role: 'list', 'aria-label': __( 'Steps of this pre-built protocol' ) }, detail.lines.map( step ) ),
			detail.notes !== '' ? h( 'h3', { class: 'arp-dialog__subtitle arp-sproto__heading' }, __( 'Notes from the store' ) ) : null,
			detail.notes !== '' ? h( 'p', { class: 'arp-sproto__notes', 'data-arp-merchant': true }, detail.notes ) : null,
			linked.length > 0 ? h( 'h3', { class: 'arp-dialog__subtitle arp-sproto__heading' }, __( 'Products in this protocol' ) ) : null,
			linked.length > 0
				? h(
					'ul',
					{ class: 'arp-sproto__links', role: 'list' },
					linked.map( ( p ) =>
						h(
							'li',
							null,
							/* translators: %s: product name. */
							h( 'a', { href: p.permalink }, withMerchant( __( 'View %s in the shop' ), [ { text: p.name, merchant: true } ] ) )
						)
					)
				)
				: null,
			errorEl
		);
	};

	/**
	 * Opens the dialog of a protocol.
	 *
	 * @param {Object}               detail      Detail.
	 * @param {HTMLElement|Function} returnFocus Return focus target (or a function returning it).
	 */
	const openDetail = ( detail, returnFocus ) => {
		if ( activeDialog ) {
			activeDialog.close( null );
		}
		const noticeId = uid( 'sproto-notice' );
		const errorEl = h( 'p', { class: 'arp-sproto__error', role: 'alert', hidden: true } );
		const price = options.showPrices && detail.fromPrice !== '' ? money( detail.fromPrice, currency ) : '';
		let busy = false;
		let isOpen = true;
		let dlg = null;

		const clearError = () => {
			errorEl.textContent = '';
			errorEl.hidden = true;
		};
		const showError = ( message ) => {
			if ( isOpen ) {
				errorEl.textContent = String( message || '' );
				errorEl.hidden = errorEl.textContent === '';
				// The message is the last node of the scrolling dialog: bring it above the sticky
				// footer, so the customer sees why Use did nothing (focus stays on Use).
				if ( ! errorEl.hidden && dlg ) {
					dlg.el.scrollTop = dlg.el.scrollHeight;
				}
			}
		};
		const useButton = h(
			'button',
			{
				type: 'button',
				class: 'arp-btn arp-btn--primary arp-sproto__use',
				onClick: async () => {
					if ( busy ) {
						return;
					}
					busy = true;
					useButton.setAttribute( 'aria-busy', 'true' );
					clearError();
					const ctx = {
						opener: useButton,
						close: () => {
							if ( dlg ) {
								dlg.close( null );
							}
						},
						showError,
					};
					try {
						await options.onUse( detail, ctx );
					} catch ( e ) {
						showError( loadFailed() );
					} finally {
						busy = false;
						useButton.removeAttribute( 'aria-busy' );
						if ( isOpen && dlg && ! dlg.el.contains( document.activeElement ) ) {
							focusElement( useButton, { preventScroll: true } );
						}
					}
				},
			},
			h(
				'span',
				{ class: 'arp-btn__label' },
				/* translators: %s: lowest total price of one unit of each product. */
				price !== '' ? sprintf( __( 'Use this protocol · from %s' ), price ) : __( 'Use this protocol' )
			)
		);
		dlg = openDialog( {
			title: detail.name,
			size: 'lg',
			content: detailContent( detail, noticeId, errorEl ),
			actions: [ useButton, whatsappLink( detail ) ],
			describedBy: noticeId,
			initialFocus: '.arp-dialog__title',
			returnFocus,
			onClose: () => {
				isOpen = false;
				if ( activeDialog === dlg ) {
					activeDialog = null;
				}
			},
		} );
		const title = dlg.el.querySelector( '.arp-dialog__title' );
		if ( title ) {
			title.setAttribute( 'data-arp-merchant', '' );
		}
		activeDialog = dlg;
	};

	/**
	 * View button of a card: loads the detail (aria-busy meanwhile, re-activation ignored) and opens
	 * the dialog; a protocol that is no longer available or a failed request shows a toast and focus
	 * stays on the button. A response superseded by a later View or open() request does nothing.
	 *
	 * @param {string}      id      Protocol ID.
	 * @param {HTMLElement} trigger View button.
	 */
	const openFromCard = async ( id, trigger ) => {
		if ( trigger.getAttribute( 'aria-busy' ) === 'true' ) {
			return;
		}
		trigger.setAttribute( 'aria-busy', 'true' );
		const seq = ++detailSeq;
		try {
			const result = await fetchDetail( id );
			if ( seq !== detailSeq ) {
				return;
			}
			if ( result.status === 'ok' ) {
				openDetail( result.detail, trigger );
			} else {
				toast( result.status === 'unavailable' ? notAvailable() : loadFailed() );
			}
		} finally {
			trigger.removeAttribute( 'aria-busy' );
		}
	};

	/* ---------------------------------------------------------------- API. */

	// An expected section shows its loading state from the first paint.
	renderVisibility();
	renderLoading();

	return {
		el,
		ready,
		/**
		 * Loads the first view (the section stays hidden when there are no protocols, and when they
		 * cannot be loaded unless they were expected: then it shows the inline error).
		 *
		 * @return {Promise<void>} Settled.
		 */
		async load() {
			await reload( false );
		},
		/**
		 * Uses the store's currency settings reported by GET /session.
		 *
		 * @param {Object} next Currency.
		 */
		setCurrency( next ) {
			currency = next;
			if ( state.items.length > 0 ) {
				renderList();
			}
		},
		/**
		 * Shared read-only mode hides the section.
		 *
		 * @param {boolean} readOnly Read only.
		 */
		setReadOnly( readOnly ) {
			state.readOnly = !! readOnly;
			el.classList.toggle( 'is-readonly', state.readOnly );
		},
		/**
		 * The app could not start (boot error, CHANGE-1.7.1 §2.7): while stalled the section shows its
		 * heading and notice only (no loading line, placeholders or aria-busy); `false` brings the
		 * loading state back while the first view has not settled.
		 *
		 * @param {boolean} stalled Stalled.
		 */
		setStalled( stalled ) {
			const next = !! stalled;
			if ( next !== state.stalled ) {
				state.stalled = next;
				renderLoading();
			}
		},
		/**
		 * Whether the store shows any pre-built protocol: null until a first-view request has
		 * succeeded, then the answer of the latest successful one.
		 *
		 * @return {boolean|null} Available.
		 */
		available() {
			return state.known ? state.any : null;
		},
		/**
		 * Calls `fn` after a successful first-view response was rendered when it is the first success
		 * or changed whether there are protocols (never on failures).
		 *
		 * @param {Function} fn Listener.
		 * @return {Function} Unsubscribe.
		 */
		onAvailability( fn ) {
			availabilityListeners.add( fn );
			return () => availabilityListeners.delete( fn );
		},
		/**
		 * Drops a pending detail request: a pending open() resolves 'superseded' and a pending View
		 * opens nothing (no dialog, no toast).
		 */
		cancelOpen() {
			detailSeq++;
		},
		/**
		 * Number of store protocols shown for a product (GET /store-protocols `product_counts`).
		 *
		 * @param {number} productId Parent product ID.
		 * @return {number} Count.
		 */
		productCount( productId ) {
			return state.productCounts.get( productId ) || 0;
		},
		/**
		 * Calls `fn` whenever the product counts change.
		 *
		 * @param {Function} fn Listener.
		 * @return {Function} Unsubscribe.
		 */
		onCounts( fn ) {
			countListeners.add( fn );
			return () => countListeners.delete( fn );
		},
		/**
		 * Shows the store protocols of one product (product cards, #store-protocols=product:<id>): other
		 * filters are cleared, the section is scrolled into view and its heading focused.
		 *
		 * @param {number}   productId      Parent product ID.
		 * @param {string}   name           Product name for the filter pill.
		 * @param {Object}   options        Options.
		 * @param {Function} options.wanted () => boolean: the caller still wants the section revealed
		 *                                  (focus and scroll) when the list arrives; false after a
		 *                                  press of an entry button stopped its link (default: always).
		 * @return {Promise<boolean>} The store has store protocols (false: none at all).
		 */
		async showProduct( productId, name = '', { wanted = () => true } = {} ) {
			const id = Number.isSafeInteger( productId ) && productId > 0 ? productId : 0;
			resetFilters();
			state.product = id;
			state.productName = typeof name === 'string' ? name.trim() : '';
			renderPill();
			renderChips();
			const loaded = await reload( true );
			await whenSettled();
			if ( ( loaded || state.product === id ) && id > 0 && state.productName === '' ) {
				const match = state.items.flatMap( ( item ) => item.products ).find( ( p ) => p.productId === id );
				state.productName = match ? match.name : '';
				renderPill();
			}
			if ( wanted() ) {
				revealSection();
			}
			return state.any;
		},
		/**
		 * Shows one group (#store-protocols=group:<key>); an unknown key shows "All".
		 *
		 * @param {string}   key            Group key.
		 * @param {Object}   options        Options.
		 * @param {Function} options.wanted () => boolean: reveal the section (focus and scroll) when
		 *                                  the list arrives (default: always; see showProduct()).
		 * @return {Promise<boolean>} The store has store protocols.
		 */
		async showGroup( key, { wanted = () => true } = {} ) {
			resetFilters();
			state.group = typeof key === 'string' && STORE_GROUP_KEY.test( key ) ? key : '';
			renderPill();
			renderChips();
			let loaded = await reload( false );
			await whenSettled();
			if ( loaded && state.group !== '' && ! state.groups.some( ( g ) => g.key === state.group ) ) {
				state.group = '';
				renderChips();
				loaded = await reload( false );
				await whenSettled();
			}
			if ( loaded && isShown() ) {
				announce( countText() );
			}
			if ( wanted() ) {
				revealSection();
			}
			return state.any;
		},
		/**
		 * Opens a protocol's dialog (deep link). Focus returns to the card's View button when that card
		 * is rendered, else to the section heading; while the section is hidden, read-only or its view
		 * is not shown, to focusFallback() (never into a hidden view).
		 *
		 * @param {string} id Protocol ID.
		 * @return {Promise<'opened'|'unavailable'|'failed'|'superseded'>} Result ('unavailable': no
		 *   UI, the caller shows the message; 'failed': a toast was shown; 'superseded': a later View
		 *   or open() request won, no UI).
		 */
		async open( id ) {
			const seq = ++detailSeq;
			const result = await fetchDetail( id );
			if ( seq !== detailSeq ) {
				return 'superseded';
			}
			if ( result.status === 'unavailable' ) {
				return 'unavailable';
			}
			if ( result.status !== 'ok' ) {
				toast( loadFailed() );
				return 'failed';
			}
			const protocolId = result.detail.id;
			openDetail( result.detail, () => {
				if ( el.hidden || state.readOnly || ! isShown() ) {
					return focusFallback();
				}
				const ref = refs.get( protocolId );
				return ref && ref.view.isConnected ? ref.view : heading;
			} );
			return 'opened';
		},
		/**
		 * Whether the store shows any store protocol.
		 *
		 * @return {boolean} Any.
		 */
		hasAny() {
			return state.any;
		},
	};
}
