/**
 * Tooltips that are not hover-only: a real button described by the tip (aria-describedby), shown
 * on focus, hover and click/tap, hidden with Escape or when focus leaves.
 *
 * @module components/tooltip
 */

import { h, uid, icon } from '../app/dom.js';

/**
 * Info button with a tooltip.
 *
 * @param {string} text  Tooltip text.
 * @param {string} label Accessible name of the button (what the tip is about).
 * @return {HTMLElement} Wrapper.
 */
export function infoTip( text, label ) {
	const id = uid( 'tip' );
	const tip = h( 'span', { class: 'arp-tip__bubble', id, role: 'tooltip' }, text );
	const trigger = h(
		'button',
		{ type: 'button', class: 'arp-tip__button', 'aria-label': label, 'aria-describedby': id },
		icon( 'info' )
	);
	const wrap = h( 'span', { class: 'arp-tip' }, trigger, tip );
	let pinned = false;
	const set = ( open ) => {
		wrap.classList.toggle( 'is-open', open );
	};
	trigger.addEventListener( 'click', () => {
		pinned = ! pinned;
		set( pinned );
	} );
	trigger.addEventListener( 'focus', () => set( true ) );
	trigger.addEventListener( 'blur', () => {
		pinned = false;
		set( false );
	} );
	wrap.addEventListener( 'mouseenter', () => set( true ) );
	wrap.addEventListener( 'mouseleave', () => set( pinned || document.activeElement === trigger ) );
	trigger.addEventListener( 'keydown', ( event ) => {
		if ( event.key === 'Escape' && wrap.classList.contains( 'is-open' ) ) {
			event.stopPropagation();
			pinned = false;
			set( false );
		}
	} );
	return wrap;
}
