/**
 * Product-line rules of the protocol builder (pure, no DOM): which fields a line shows, the weekly
 * mapping of the plain labels, conversion of lines saved with older settings, and the quantity
 * stepper / "+1 spare" semantics on top of `override_quantity`. The calculation itself is
 * unchanged (engine.js); these helpers only decide which LineInput values the UI writes.
 *
 * - "Times per week" = `events_per_period` with `period_unit = "week"`; "Duration (weeks)" =
 *   `periods` (week unit); "Amount per use" = `amount`.
 * - Units that allow the schedule mode always use it with weeks. Supplies and units whose only
 *   mode is manual are planned by quantity (manual mode) only.
 * - Lines saved with day or month periods, the direct mode, or a mode the new UI no longer offers
 *   still load and calculate; the first edit converts them (modernizeLine()).
 *
 * @module protocol
 */

import { modesFor, isPlannable } from './catalog.js';

/** Line fields whose change alters the calculated (recommended) quantity. */
export const CALCULATION_FIELDS = Object.freeze( [ 'variation_id', 'variation_attributes', 'mode', 'amount', 'unit', 'events_per_period', 'period_unit', 'periods' ] );

/**
 * How a line of this unit is entered.
 *
 * @param {Object|null} unit Unit.
 * @return {string} 'weekly' (amount per use × times per week × weeks), 'quantity' (quantity only)
 *   or '' (the unit cannot be planned).
 */
export function lineKind( unit ) {
	if ( ! isPlannable( unit ) ) {
		return '';
	}
	const modes = modesFor( unit );
	if ( modes.includes( 'schedule' ) && unit.containerType !== 'supply' ) {
		return 'weekly';
	}
	if ( modes.includes( 'manual' ) ) {
		return 'quantity';
	}
	return '';
}

/**
 * Whether a line was saved with a setting the builder no longer offers for its unit (day or month
 * periods, the direct mode, or a manual quantity on a weekly item; any calculated mode on a
 * quantity-only item).
 *
 * @param {Object}      line Line.
 * @param {Object|null} unit Unit.
 * @return {boolean} Legacy.
 */
export function isLegacyLine( line, unit ) {
	const kind = lineKind( unit );
	if ( kind === 'weekly' ) {
		return line.mode !== 'schedule' || ( line.period_unit || 'week' ) !== 'week';
	}
	if ( kind === 'quantity' ) {
		return line.mode !== 'manual';
	}
	return false;
}

/**
 * Changes that convert a legacy line to the current setting of its unit. Nothing is invented: a
 * value is carried over only when it means exactly the same thing in the new setting.
 *
 * Weekly items: the amount per use of a schedule line is kept; n times per day becomes 7n times
 * per week (exact; when ≤ the limit); a duration in days becomes weeks only when it is a whole
 * number of weeks; otherwise the field is left empty (times per week) or set to the store default
 * duration. The total amount of a direct line is NOT an amount per use and is cleared. A purchase
 * quantity override is kept (it is the customer's own choice of containers).
 *
 * Quantity-only items: the quantity becomes the line's manual quantity — its previous manual
 * quantity, else the given quantity (the last calculated one), else 1 (the purchase quantity every
 * new quantity-only line starts with).
 *
 * @param {Object}      line    Line.
 * @param {Object|null} unit    Unit.
 * @param {Object}      options { defaultWeeks: number|null, quantity: number|null, limits: Object }.
 * @return {Object} Changes ({} when the line is not legacy).
 */
export function modernizeLine( line, unit, options = {} ) {
	if ( ! isLegacyLine( line, unit ) ) {
		return {};
	}
	const limits = options.limits && typeof options.limits === 'object' ? options.limits : {};
	const maxEvents = Number.isSafeInteger( limits.max_events_per_period ) ? limits.max_events_per_period : 1000;
	const maxWeeks = Number.isSafeInteger( limits.max_periods_week ) ? limits.max_periods_week : 520;
	if ( lineKind( unit ) === 'quantity' ) {
		const fromOptions = Number.isSafeInteger( options.quantity ) && options.quantity > 0 ? options.quantity : null;
		return {
			mode: 'manual',
			manual_quantity: line.manual_quantity ?? fromOptions ?? 1,
			override_quantity: null,
		};
	}
	const schedule = line.mode === 'schedule';
	const unitOfPeriod = line.period_unit || 'week';
	let events = null;
	let weeks = null;
	if ( schedule && unitOfPeriod === 'week' ) {
		events = line.events_per_period;
		weeks = line.periods;
	} else if ( schedule && unitOfPeriod === 'day' ) {
		if ( Number.isSafeInteger( line.events_per_period ) && line.events_per_period * 7 <= maxEvents ) {
			events = line.events_per_period * 7;
		}
		if ( Number.isSafeInteger( line.periods ) && line.periods % 7 === 0 && line.periods / 7 <= maxWeeks ) {
			weeks = line.periods / 7;
		}
	}
	if ( weeks === null && Number.isSafeInteger( options.defaultWeeks ) && options.defaultWeeks > 0 && options.defaultWeeks <= maxWeeks ) {
		weeks = options.defaultWeeks;
	}
	return {
		mode: 'schedule',
		period_unit: 'week',
		amount: schedule ? line.amount : null,
		events_per_period: events,
		periods: weeks,
		manual_quantity: null,
		override_quantity: line.mode === 'manual' ? null : line.override_quantity,
	};
}

/**
 * Whether a change touches a value the recommended quantity depends on.
 *
 * @param {Object} changes Line changes.
 * @return {boolean} Touches.
 */
export function touchesCalculation( changes ) {
	return Object.keys( changes || {} ).some( ( key ) => CALCULATION_FIELDS.includes( key ) );
}

/**
 * Whether the "+1 spare" box is checked: the purchase quantity is the calculated one plus one.
 *
 * @param {Object}      line   Line.
 * @param {Object|null} result Line result (calculated mode).
 * @return {boolean} Checked.
 */
export function spareChecked( line, result ) {
	return !! result && result.mode !== 'manual' && Number.isSafeInteger( result.recommended_quantity ) && line.override_quantity !== null && line.override_quantity === result.recommended_quantity + 1;
}

/**
 * Override for the "+1 spare" box: recommended + 1 when checked, no override when cleared.
 *
 * @param {boolean}     checked Checked.
 * @param {Object|null} result  Line result.
 * @param {number}      max     Maximum quantity.
 * @return {number|null} override_quantity.
 */
export function spareOverride( checked, result, max = 9999 ) {
	if ( ! checked || ! result || ! Number.isSafeInteger( result.recommended_quantity ) ) {
		return null;
	}
	return Math.min( max, result.recommended_quantity + 1 );
}

/**
 * Quantity shown in the stepper: the customer's override, else the calculated quantity.
 *
 * @param {Object}      line   Line.
 * @param {Object|null} result Line result.
 * @return {number|null} Quantity (null before anything is calculated).
 */
export function stepperQuantity( line, result ) {
	if ( line.override_quantity !== null && line.override_quantity !== undefined ) {
		return line.override_quantity;
	}
	return result && Number.isSafeInteger( result.quantity ) ? result.quantity : null;
}

/**
 * Override after the customer set the stepper to `value`: the calculated quantity itself means "no
 * override" (status "calculated"); anything else is kept as the override (status "changed").
 *
 * @param {number}      value  Quantity chosen (whole number).
 * @param {Object|null} result Line result.
 * @param {number}      max    Maximum quantity.
 * @return {number|null} override_quantity.
 */
export function quantityOverride( value, result, max = 9999 ) {
	if ( ! Number.isSafeInteger( value ) ) {
		return null;
	}
	const next = Math.max( 0, Math.min( max, value ) );
	if ( result && Number.isSafeInteger( result.recommended_quantity ) && next === result.recommended_quantity ) {
		return null;
	}
	return next;
}

/**
 * Override after − or + on the stepper.
 *
 * @param {Object}      line   Line.
 * @param {Object|null} result Line result.
 * @param {number}      delta  -1 or +1.
 * @param {number}      max    Maximum quantity.
 * @return {number|null} override_quantity (unchanged when nothing is calculated yet).
 */
export function stepOverride( line, result, delta, max = 9999 ) {
	const current = stepperQuantity( line, result );
	if ( current === null ) {
		return line.override_quantity ?? null;
	}
	return quantityOverride( current + ( delta < 0 ? -1 : 1 ), result, max );
}

/**
 * Status word of the stepper.
 *
 * @param {Object} line Line.
 * @return {string} 'changed' with an override, else 'calculated'.
 */
export function quantityStatus( line ) {
	return line.override_quantity !== null && line.override_quantity !== undefined ? 'changed' : 'calculated';
}

/**
 * A NEW line set up for the builder: weekly items use the schedule mode with weeks; quantity-only
 * items use the manual mode and start at a purchase quantity of 1. Amounts stay empty.
 *
 * @param {Object}      line Line from plan.js createLine().
 * @param {Object|null} unit Unit (null until a variant is chosen).
 * @return {Object} Line (new object).
 */
export function prepareNewLine( line, unit ) {
	const kind = lineKind( unit );
	if ( kind === 'quantity' ) {
		return { ...line, mode: 'manual', manual_quantity: line.manual_quantity ?? 1, override_quantity: null };
	}
	return { ...line, mode: 'schedule', period_unit: 'week' };
}

/**
 * How the lines of a product are entered before its option is chosen: the kind of its first
 * plannable unit ('' when none can be planned). Used to show the fields (disabled) while the
 * customer still has to choose the vial size.
 *
 * @param {Object|null} product Product (normalized).
 * @return {string} 'weekly', 'quantity' or ''.
 */
export function productKind( product ) {
	const units = product && Array.isArray( product.units ) ? product.units : [];
	const first = units.find( ( u ) => lineKind( u ) !== '' );
	return first ? lineKind( first ) : '';
}

/**
 * Format (container type) of a product before its option is chosen: the format of its first
 * plannable unit (the unit productKind() uses), else of its first unit, else ''. Labels the option
 * group ("Vial size") and the quantity nouns ("Vials") while the customer still has to choose.
 *
 * @param {Object|null} product Product (normalized).
 * @return {string} Format.
 */
export function productFormat( product ) {
	const units = product && Array.isArray( product.units ) ? product.units : [];
	const first = units.find( ( u ) => lineKind( u ) !== '' ) || units[ 0 ];
	return first ? first.containerType : '';
}

/**
 * Quantity the "Quantity" stepper of a quantity-only line steps from: the quantity its field
 * shows. A line saved with an older setting shows the quantity its conversion will use
 * (modernizeLine(): its manual quantity, else the last calculated one, else 1); other lines their
 * manual quantity (0 when empty).
 *
 * @param {Object}      line     Line.
 * @param {Object|null} unit     Unit.
 * @param {number|null} quantity Last calculated quantity of the line.
 * @return {number} Base quantity.
 */
export function manualStepBase( line, unit, quantity = null ) {
	if ( isLegacyLine( line, unit ) && lineKind( unit ) === 'quantity' ) {
		return modernizeLine( line, unit, { quantity } ).manual_quantity ?? 0;
	}
	return line.manual_quantity ?? 0;
}
