/**
 * Export menu: CSV, calendar (.ics, "Research inventory review" dates; disabled with an explanation
 * when no start date exists), print / save as PDF (server HTML opened from a Blob URL, then print)
 * and the protocol file (.json). Files are generated on request and never stored.
 *
 * The IDs of the store protocols the workspace started from (CHANGE-1.7.0 §7) travel with the
 * export request (in the body, or in a header for a saved protocol; never in a URL), so the printed
 * protocol names them; a shared protocol never sends them.
 *
 * @module components/exports
 */

import { h, uid, icon, downloadBlob } from '../app/dom.js';
import { __ } from '../app/i18n.js';

/**
 * Default file name for a format.
 *
 * @param {string} format csv | ics | print | json.
 * @return {string} File name.
 */
export function exportFilename( format ) {
	const date = new Date().toISOString().slice( 0, 10 );
	const ext = { csv: 'csv', ics: 'ics', print: 'html', json: 'json' }[ format ] || 'txt';
	return 'research-protocol-' + date + '.' + ext;
}

/**
 * Opens printable HTML in the window opened during the click and starts printing.
 *
 * @param {Blob}        blob HTML.
 * @param {Window|null} win  Window opened synchronously by the click handler.
 * @return {boolean} Printed in a new window (false = popup blocked).
 */
export function openPrintWindow( blob, win ) {
	if ( ! win || win.closed ) {
		return false;
	}
	const url = URL.createObjectURL( new Blob( [ blob ], { type: 'text/html' } ) );
	win.location.href = url;
	const started = Date.now();
	const timer = setInterval( () => {
		try {
			if ( win.closed || Date.now() - started > 20000 ) {
				clearInterval( timer );
				return;
			}
			if ( win.location.href === url && win.document.readyState === 'complete' ) {
				clearInterval( timer );
				win.focus();
				win.print();
			}
		} catch ( e ) {
			// The window is still navigating.
		}
	}, 200 );
	setTimeout( () => URL.revokeObjectURL( url ), 120000 );
	return true;
}

/**
 * Creates the export menu (a disclosure with buttons).
 *
 * @param {Object} ctx { api, getPlan(), getMeta(), getShareToken(), getStoreProtocols() (store
 *                     protocol IDs of the workspace's origin, [] in shared mode), toast( message, tone ) }.
 * @return {{el: HTMLElement, update: Function}} Menu.
 */
export function createExportMenu( ctx ) {
	const panelId = uid( 'export' );
	const icsHelpId = uid( 'ics-help' );
	const trigger = h(
		'button',
		{ type: 'button', class: 'arp-btn arp-btn--secondary', 'aria-expanded': 'false', 'aria-controls': panelId },
		icon( 'download' ),
		h( 'span', { class: 'arp-btn__label' }, __( 'Export' ) )
	);
	const item = ( format, iconName, label, extra = {} ) =>
		h( 'button', { type: 'button', class: 'arp-menu__item', onClick: () => run( format ), ...extra }, icon( iconName ), h( 'span', null, label ) );
	const csv = item( 'csv', 'file', __( 'Spreadsheet (CSV)' ) );
	const ics = item( 'ics', 'calendar', __( 'Calendar of review dates (.ics)' ), { 'aria-describedby': icsHelpId } );
	const icsHelp = h( 'p', { id: icsHelpId, class: 'arp-menu__help' } );
	const print = item( 'print', 'print', __( 'Print / save as PDF' ) );
	const json = item( 'json', 'download', __( 'Protocol file (.json)' ) );
	const status = h( 'p', { class: 'arp-menu__status', role: 'status' } );
	const panel = h(
		'div',
		{ id: panelId, class: 'arp-menu', hidden: true },
		csv,
		ics,
		icsHelp,
		print,
		json,
		h( 'p', { class: 'arp-menu__note' }, __( 'Files are generated on request and are not stored.' ) ),
		status
	);
	const el = h( 'div', { class: 'arp-export' }, trigger, panel );
	let busy = false;

	const setOpen = ( open ) => {
		panel.hidden = ! open;
		trigger.setAttribute( 'aria-expanded', open ? 'true' : 'false' );
	};
	trigger.addEventListener( 'click', () => {
		setOpen( panel.hidden );
		if ( ! panel.hidden ) {
			const first = panel.querySelector( 'button:not([disabled])' );
			if ( first ) {
				first.focus();
			}
		}
	} );
	el.addEventListener( 'keydown', ( event ) => {
		if ( event.key === 'Escape' && ! panel.hidden ) {
			event.stopPropagation();
			setOpen( false );
			trigger.focus();
		}
	} );
	document.addEventListener( 'click', ( event ) => {
		if ( ! panel.hidden && ! el.contains( event.target ) ) {
			setOpen( false );
		}
	} );
	el.addEventListener( 'focusout', ( event ) => {
		// Focus moving to an ancestor is WebKit focusing the nearest focusable ancestor of a tapped
		// menu item (Safari does not focus buttons): keep the menu open so the tap still lands.
		if ( event.relatedTarget && ! el.contains( event.relatedTarget ) && ! event.relatedTarget.contains( el ) ) {
			setOpen( false );
		}
	} );

	/**
	 * Runs an export.
	 *
	 * @param {string} format Format.
	 */
	async function run( format ) {
		if ( busy ) {
			return;
		}
		if ( format === 'json' ) {
			downloadBlob( new Blob( [ JSON.stringify( ctx.getPlan(), null, 2 ) ], { type: 'application/json' } ), exportFilename( 'json' ) );
			setOpen( false );
			trigger.focus();
			return;
		}
		// Open the print window synchronously (inside the click) so popup blockers allow it.
		const win = format === 'print' ? window.open( '', '_blank' ) : null;
		busy = true;
		status.textContent = __( 'Preparing your file…' );
		try {
			const token = ctx.getShareToken();
			const meta = ctx.getMeta();
			const storeProtocols = typeof ctx.getStoreProtocols === 'function' ? ctx.getStoreProtocols() : [];
			let file;
			if ( token ) {
				// Shared protocols never send the store protocols of the visitor's own workspace.
				file = await ctx.api.exportShared( token, format );
			} else if ( meta.kind === 'account' && meta.uuid && ! meta.dirty ) {
				file = await ctx.api.exportSaved( meta.uuid, format, storeProtocols );
			} else {
				file = await ctx.api.exportPlan( format, ctx.getPlan(), storeProtocols );
			}
			if ( format === 'print' ) {
				if ( ! openPrintWindow( file.blob, win ) ) {
					downloadBlob( new Blob( [ file.blob ], { type: 'text/html' } ), file.filename || exportFilename( 'print' ) );
					ctx.toast( __( 'Your browser blocked the print window, so the printable protocol was downloaded instead. Open it and print it from your browser.' ), 'info' );
				}
			} else {
				downloadBlob( file.blob, file.filename || exportFilename( format ) );
			}
			status.textContent = '';
			setOpen( false );
			trigger.focus();
		} catch ( e ) {
			if ( win && ! win.closed ) {
				win.close();
			}
			status.textContent = '';
			ctx.toast( e.message || __( 'The file could not be created. Please try again.' ), 'error' );
		} finally {
			busy = false;
		}
	}

	return {
		el,
		/** Prints the protocol (call from a click handler so the print window may open). */
		print: () => run( 'print' ),
		/**
		 * Runs an export (call from a click handler).
		 *
		 * @param {string} format csv | ics | print | json.
		 * @return {Promise<void>} Settles when the file was created.
		 */
		run: ( format ) => run( format ),
		/**
		 * Updates availability.
		 *
		 * @param {Object} view { enabled, hasLines, hasStartDate }.
		 */
		update( view ) {
			el.hidden = ! view.enabled;
			[ csv, print, json ].forEach( ( b ) => {
				b.disabled = ! view.hasLines;
			} );
			ics.disabled = ! view.hasLines || ! view.hasStartDate;
			icsHelp.textContent = view.hasStartDate ? '' : __( 'Add a protocol start date to export review dates.' );
			icsHelp.hidden = view.hasStartDate;
		},
	};
}
