/**
 * Explanation dialog "How it works": step-by-step formula rendered from the result's
 * numbers, translated), the rounding rules and where the data comes from.
 *
 * @module components/explain
 */

import { h } from '../app/dom.js';
import { __, _n, sprintf } from '../app/i18n.js';
import { formatNumber, formatPercent, money, formatDate, formatTime } from '../app/format.js';
import { parseAmount, formatScaled } from '../app/engine.js';
import { noticeText } from '../app/messages.js';
import { formatLabel } from '../app/catalog.js';
import { openDialog, dialogSection } from './modal.js';

/**
 * Display name of a unit for a count.
 *
 * @param {string} unit  Unit.
 * @param {string} value Amount (decides singular/plural).
 * @return {string} Name.
 */
export function unitName( unit, value = '2' ) {
	const one = value === '1';
	switch ( unit ) {
		case 'actuation':
			return one ? __( 'actuation' ) : __( 'actuations' );
		case 'piece':
			return one ? __( 'piece' ) : __( 'pieces' );
		default:
			return unit;
	}
}

/**
 * Formatted amount object { value, unit }.
 *
 * @param {Object|null} amount   Amount.
 * @param {Object}      currency Separators.
 * @return {string} e.g. "4,000 mcg".
 */
export function amountText( amount, currency ) {
	if ( ! amount || typeof amount.value !== 'string' ) {
		return '—';
	}
	return ( amount.exact === false ? '≈' : '' ) + formatNumber( amount.value, currency ) + ' ' + unitName( amount.unit, amount.value );
}

/**
 * Converts an amount object to another unit of the same dimension (display only).
 *
 * @param {Object} amount { value, unit }.
 * @param {string} unit   Target unit.
 * @return {Object} { value, unit, exact }.
 */
export function convertAmount( amount, unit ) {
	if ( ! amount || amount.unit === unit ) {
		return amount;
	}
	try {
		const formatted = formatScaled( parseAmount( amount.value, amount.unit ), unit );
		return { value: formatted.value, unit, exact: formatted.exact };
	} catch ( e ) {
		return amount;
	}
}

/**
 * Period name for a count.
 *
 * @param {string} period day | week | month.
 * @param {number} n      Count.
 * @return {string} Name.
 */
export function periodName( period, n ) {
	switch ( period ) {
		case 'day':
			return _n( 'day', 'days', n );
		case 'month':
			return _n( 'month', 'months', n );
		default:
			return _n( 'week', 'weeks', n );
	}
}

/**
 * Translated formula steps for a result.
 *
 * @param {Object}  r          Result (LineResult::to_array() shape).
 * @param {Object}  currency   Currency settings.
 * @param {boolean} showPrices Show the price step.
 * @return {string[]} Steps.
 */
export function formulaSteps( r, currency, showPrices ) {
	const n = ( value ) => formatNumber( String( value ), currency );
	const units = ( count ) => sprintf( _n( '%s unit', '%s units', count ), n( count ) );
	const steps = [];
	if ( r.mode === 'manual' ) {
		/* translators: %s: number of units. */
		steps.push( sprintf( __( 'Quantity entered: %s' ), units( r.quantity ) ) );
	} else {
		const capUnit = convertAmount( r.capacity_per_unit, r.unit );
		if ( r.mode === 'schedule' ) {
			steps.push(
				sprintf(
					/* translators: 1: times per period, 2: period name, 3: number of periods, 4: period name (plural), 5: number of uses. */
					__( '%1$s times per %2$s × %3$s %4$s = %5$s uses' ),
					n( r.events_per_period ),
					periodName( r.period_unit, 1 ),
					n( r.periods ),
					periodName( r.period_unit, r.periods ),
					n( r.event_count )
				)
			);
			steps.push(
				sprintf(
					/* translators: 1: amount per use, 2: number of uses, 3: total required. */
					__( '%1$s per use × %2$s uses = %3$s total required' ),
					amountText( r.per_event, currency ),
					n( r.event_count ),
					amountText( r.total_required, currency )
				)
			);
		} else {
			/* translators: %s: total amount. */
			steps.push( sprintf( __( 'Total required (entered directly): %s' ), amountText( r.total_required, currency ) ) );
		}
		if ( r.pack_count > 1 ) {
			steps.push(
				sprintf(
					/* translators: 1: capacity per container, 2: containers per unit, 3: capacity per unit. */
					__( '%1$s per container × %2$s containers per unit = %3$s per unit' ),
					amountText( { value: r.capacity.amount, unit: r.capacity.unit }, currency ),
					n( r.pack_count ),
					amountText( r.capacity_per_unit, currency )
				)
			);
		} else {
			/* translators: %s: capacity per purchase unit. */
			steps.push( sprintf( __( 'Capacity per unit: %s' ), amountText( r.capacity_per_unit, currency ) ) );
		}
		steps.push(
			sprintf(
				/* translators: 1: total required, 2: capacity per unit, 3: number of units. */
				__( '%1$s ÷ %2$s per unit, rounded up to a whole number = %3$s' ),
				amountText( r.total_required, currency ),
				amountText( capUnit, currency ),
				units( r.required_units )
			)
		);
		if ( r.bundle_covered_units > 0 ) {
			steps.push(
				sprintf(
					/* translators: 1: units required, 2: units covered by a bundle, 3: units to buy. */
					__( '%1$s − %2$s supplied by a bundle in this protocol = %3$s' ),
					units( r.required_units ),
					units( r.bundle_covered_units ),
					units( r.recommended_quantity )
				)
			);
		}
		if ( r.is_override ) {
			steps.push(
				sprintf(
					/* translators: 1: chosen quantity, 2: calculated quantity. */
					__( 'Quantity changed: you chose %1$s (calculated: %2$s)' ),
					units( r.quantity ),
					units( r.recommended_quantity )
				)
			);
		}
		steps.push(
			sprintf(
				/* translators: 1: units in stock, 2: capacity per unit, 3: coverage, 4: coverage percentage. */
				__( '%1$s × %2$s = %3$s coverage (%4$s of the total required)' ),
				units( r.quantity + r.bundle_covered_units ),
				amountText( capUnit, currency ),
				amountText( r.coverage, currency ),
				formatPercent( r.coverage_percent || '0.0', currency )
			)
		);
		if ( r.shortfall ) {
			steps.push(
				sprintf(
					/* translators: 1: total required, 2: coverage, 3: shortfall. */
					__( 'Shortfall: %1$s − %2$s = %3$s' ),
					amountText( r.total_required, currency ),
					amountText( r.coverage, currency ),
					amountText( r.shortfall, currency )
				)
			);
		} else {
			steps.push(
				sprintf(
					/* translators: 1: coverage, 2: total required, 3: amount left over. */
					__( 'Left over: %1$s − %2$s = %3$s' ),
					amountText( r.coverage, currency ),
					amountText( r.total_required, currency ),
					amountText( r.surplus, currency )
				)
			);
		}
	}
	if ( r.pack_count > 1 ) {
		steps.push(
			sprintf(
				/* translators: 1: units, 2: containers per unit, 3: containers. */
				__( '%1$s × %2$s containers per unit = %3$s containers' ),
				units( r.quantity ),
				n( r.pack_count ),
				n( r.containers )
			)
		);
	}
	if ( showPrices && r.estimate !== null && r.unit_price !== null ) {
		steps.push(
			sprintf(
				/* translators: 1: units, 2: unit price, 3: estimate. */
				__( '%1$s × %2$s = %3$s (estimate)' ),
				units( r.quantity ),
				money( r.unit_price, currency ),
				money( r.estimate, currency )
			)
		);
	}
	return steps;
}

/**
 * Rounding rules (static list).
 *
 * @return {string[]} Rules.
 */
export function roundingRules() {
	return [
		__( 'Purchase quantities are always whole units, rounded up.' ),
		__( 'All arithmetic uses exact decimals; values accept up to 4 decimal places.' ),
		__( 'Displayed amounts are rounded half-up to 4 decimal places (marked ≈ when rounded); percentages are truncated to one decimal place.' ),
		__( 'Units are converted only within the same kind (mcg, mg, g). Mass, IU, mL, actuations and pieces are never converted into each other.' ),
		__( 'Estimates multiply the store price per unit by the quantity; WooCommerce calculates the final total.' ),
	];
}


/**
 * Label of a capacity basis.
 *
 * @param {string} basis Basis.
 * @return {string} Label.
 */
function basisLabel( basis ) {
	switch ( basis ) {
		case 'usable':
			return __( 'merchant-verified usable amount per container' );
		case 'fill_volume':
			return __( 'fill volume per container' );
		default:
			return __( 'labelled amount per container, treated as fully usable' );
	}
}

/**
 * Sections of "Where the data comes from" (product capacity, price and stock, calculation).
 *
 * @param {Object} view { unit, currency, locale, calculatedAt }.
 * @return {Array<HTMLElement>} Sections.
 */
export function originSections( view ) {
	const unit = view.unit;
	const verified = unit && unit.verifiedAt ? formatDate( unit.verifiedAt.slice( 0, 10 ), view.locale ) : '';
	const capacities = unit ? unit.capacities : [];
	const checked = view.calculatedAt ? formatTime( view.calculatedAt, view.locale ) : '';
	return [
		dialogSection(
			__( 'Where the product data comes from' ),
			capacities.length > 0
				? h(
					'ul',
					{ class: 'arp-explain__list' },
					capacities.map( ( c ) => h( 'li', null, amountText( { value: c.amount, unit: c.unit }, view.currency ) + ' — ' + basisLabel( c.basis ) ) ),
					unit.packCount > 1 ? h( 'li', null, sprintf( /* translators: %s: number of containers. */ __( '%s containers per purchase unit' ), String( unit.packCount ) ) ) : null,
					unit.containerType ? h( 'li', null, sprintf( /* translators: %s: format such as Vial. */ __( 'Format: %s' ), formatLabel( unit.containerType ) ) ) : null
				)
				: h( 'p', null, __( 'This item is planned by quantity only; no capacity is used.' ) ),
			h(
				'p',
				null,
				verified
					? sprintf( /* translators: %s: date. */ __( 'Source: merchant-verified product data, verified on %s. Values are never taken from product descriptions.' ), verified )
					: __( 'Source: merchant-verified product data. Values are never taken from product descriptions.' )
			),
			unit && unit.publicNote ? h( 'p', { class: 'arp-explain__note' }, unit.publicNote ) : null
		),
		dialogSection(
			__( 'Price and stock' ),
			h(
				'p',
				null,
				checked
					? sprintf( /* translators: %s: time. */ __( 'Live from the store (WooCommerce), last checked at %s. Taxes, shipping and discounts are calculated in the cart.' ), checked )
					: __( 'Live from the store (WooCommerce). Taxes, shipping and discounts are calculated in the cart.' )
			)
		),
		dialogSection(
			__( 'Calculation' ),
			h( 'p', null, __( 'Results appear instantly in your browser and are then confirmed by the store server, which is always authoritative. Products without verified data cannot be calculated.' ) )
		),
	];
}

/**
 * Opens "How it works": the step-by-step formula of a line, the rounding rules, its assumptions
 * and notes, and where the data comes from (CHANGE-1.1.0 §2: one link for both).
 *
 * @param {Object} view { title, result, currency, showPrices, source, unit, locale, calculatedAt }.
 */
export function openFormulaDialog( view ) {
	const r = view.result;
	const notices = ( list ) => ( Array.isArray( list ) ? list : [] ).map( ( item ) => h( 'li', null, view.source === 'server' && item.message ? item.message : noticeText( item.code, item.message || '' ) ) );
	openDialog( {
		title: __( 'How it works' ),
		size: 'lg',
		description: view.title,
		content: h(
			'div',
			{ class: 'arp-explain' },
			dialogSection( __( 'Step by step' ), h( 'ol', { class: 'arp-explain__steps' }, formulaSteps( r, view.currency, view.showPrices ).map( ( step ) => h( 'li', null, step ) ) ) ),
			dialogSection( __( 'Rounding rules' ), h( 'ul', { class: 'arp-explain__list' }, roundingRules().map( ( rule ) => h( 'li', null, rule ) ) ) ),
			r.assumptions && r.assumptions.length > 0 ? dialogSection( __( 'Assumptions' ), h( 'ul', { class: 'arp-explain__list' }, notices( r.assumptions ) ) ) : null,
			r.warnings && r.warnings.length > 0 ? dialogSection( __( 'Notes' ), h( 'ul', { class: 'arp-explain__list' }, notices( r.warnings ) ) ) : null,
			...originSections( view ),
			h( 'p', { class: 'arp-explain__foot' }, __( 'This is arithmetic on the values you entered. It is not a recommendation of amounts, schedules or uses.' ) )
		),
	} );
}
