/**
 * "Popular combinations" row of step 1 (CHANGE-1.1.0 §3, §9.1): merchant-curated product lists
 * from GET /combinations (products only — no amounts or schedules). Each card shows the name, the
 * products joined with " + " (or the merchant's blurb) and "+ Add all · from {price}"; once every
 * product is in the protocol the same button reads "✓ In your protocol" (aria-disabled, so a
 * focused button keeps focus). The row is hidden when there are no combinations or they cannot be
 * loaded.
 *
 * @module components/combos
 */

import { h, uid, render } from '../app/dom.js';
import { __, sprintf } from '../app/i18n.js';
import { money } from '../app/format.js';
import { normalizeCombinations } from '../app/catalog.js';

/**
 * Creates the combinations row.
 *
 * @param {Object}   options            Options.
 * @param {Object}   options.api        API client.
 * @param {Object}   options.currency   Currency settings.
 * @param {boolean}  options.showPrices Show prices.
 * @param {Function} options.onAddAll   ( combo ) => Promise.
 * @param {Function} options.inProtocol ( combo ) => boolean.
 * @return {{el: HTMLElement, load: Function, refresh: Function, setCurrency: Function}} Row.
 */
export function createCombos( options ) {
	const titleId = uid( 'combos-title' );
	const list = h( 'ul', { class: 'arp-combos__list' } );
	const el = h( 'section', { class: 'arp-combos', 'aria-labelledby': titleId, hidden: true }, h( 'h2', { class: 'arp-section-head__title arp-combos__title', id: titleId }, __( 'Popular combinations' ) ), list );
	let currency = options.currency;
	let combos = [];
	const refs = [];

	/**
	 * Applies the "in protocol" state of a card in place.
	 *
	 * @param {Object} ref Card references.
	 */
	const apply = ( ref ) => {
		const done = options.inProtocol( ref.combo );
		if ( done === ref.done ) {
			return;
		}
		ref.done = done;
		ref.el.classList.toggle( 'is-added', done );
		ref.button.setAttribute( 'aria-disabled', done ? 'true' : 'false' );
		if ( done ) {
			ref.label.textContent = __( '✓ In your protocol' );
			return;
		}
		ref.label.textContent =
			options.showPrices && ref.combo.fromPrice !== ''
				? sprintf( /* translators: %s: lowest total price of the products. */ __( '+ Add all · from %s' ), money( ref.combo.fromPrice, currency ) )
				: __( '+ Add all' );
	};

	const card = ( combo ) => {
		const nameId = uid( 'combo-name' );
		const itemsId = uid( 'combo-items' );
		const label = h( 'span', { class: 'arp-btn__label' } );
		const ref = { combo, el: null, button: null, label, done: null };
		ref.button = h(
			'button',
			{
				type: 'button',
				class: 'arp-btn arp-combo-card__add',
				'aria-describedby': nameId + ' ' + itemsId,
				onClick: async () => {
					if ( ref.button.getAttribute( 'aria-disabled' ) === 'true' || ref.button.getAttribute( 'aria-busy' ) === 'true' ) {
						return;
					}
					ref.button.setAttribute( 'aria-busy', 'true' );
					try {
						await options.onAddAll( combo );
					} finally {
						ref.button.removeAttribute( 'aria-busy' );
						apply( ref );
					}
				},
			},
			label
		);
		ref.el = h(
			'li',
			{ class: 'arp-combo-card' },
			h( 'h3', { class: 'arp-combo-card__name', id: nameId }, combo.name ),
			h( 'p', { class: 'arp-combo-card__items', id: itemsId }, combo.blurb ),
			ref.button
		);
		refs.push( ref );
		apply( ref );
		return ref.el;
	};

	return {
		el,
		/** Loads the combinations (the row stays hidden when there are none or on errors). */
		async load() {
			try {
				combos = normalizeCombinations( await options.api.combinations() );
			} catch ( e ) {
				combos = [];
			}
			refs.length = 0;
			render( list, combos.map( card ) );
			el.hidden = combos.length === 0;
		},
		/** Updates every card's "in protocol" state in place. */
		refresh() {
			refs.forEach( apply );
		},
		/**
		 * Uses the store's currency settings reported by GET /session.
		 *
		 * @param {Object} next Currency.
		 */
		setCurrency( next ) {
			currency = next;
			refs.forEach( ( ref ) => {
				ref.done = null;
				apply( ref );
			} );
		},
	};
}
