/**
 * Toast notifications in a polite ARIA live region (with an optional action such as "Go to item").
 *
 * Toasts with an action stay until they time out (paused while hovered or focused) or are
 * dismissed; the action is a real button reachable by keyboard. Toasts are never the only way to
 * do something: undoing a removal has a persistent inline control in the workspace.
 *
 * @module components/toast
 */

import { h, button } from '../app/dom.js';
import { __ } from '../app/i18n.js';

/**
 * Creates the toast region inside `parent`.
 *
 * @param {HTMLElement} parent  Parent element.
 * @param {Object}      config  { onChange: () => void } — called after a toast appeared or left
 *                              (the app keeps the focused control clear of the toasts).
 * @return {{show: Function, clear: Function, el: HTMLElement}} Toaster.
 */
export function createToaster( parent, config = {} ) {
	const changed = () => {
		if ( typeof config.onChange === 'function' ) {
			config.onChange();
		}
	};
	const region = h( 'div', { class: 'arp-toasts', role: 'region', 'aria-label': __( 'Notifications' ) } );
	const live = h( 'div', { class: 'arp-toasts__live', 'aria-live': 'polite', 'aria-atomic': 'false' } );
	region.appendChild( live );
	parent.appendChild( region );

	/**
	 * Shows a toast.
	 *
	 * @param {string} message           Message.
	 * @param {Object} options           Options.
	 * @param {string} options.tone      info | success | error.
	 * @param {Object} options.action    { label, onClick }.
	 * @param {number} options.timeout   Milliseconds (0 = until dismissed).
	 * @return {{dismiss: Function}} Handle.
	 */
	const show = ( message, options = {} ) => {
		const tone = options.tone || 'info';
		const timeout = options.timeout ?? ( options.action ? 9000 : 5000 );
		let timer = null;
		let remaining = timeout;
		let started = 0;

		const toast = h( 'div', { class: [ 'arp-toast', 'arp-toast--' + tone ], role: tone === 'error' ? 'alert' : 'status' } );
		const dismiss = () => {
			clearTimeout( timer );
			if ( toast.isConnected ) {
				toast.remove();
				changed();
			}
		};
		toast.appendChild( h( 'p', { class: 'arp-toast__text' }, message ) );
		if ( options.action ) {
			toast.appendChild(
				button( {
					label: options.action.label,
					variant: 'link',
					cls: 'arp-toast__action',
					onClick: () => {
						dismiss();
						options.action.onClick();
					},
				} )
			);
		}
		toast.appendChild( button( { label: __( 'Dismiss notification' ), iconName: 'close', variant: 'ghost', iconOnly: true, size: 'sm', onClick: dismiss } ) );

		const start = () => {
			if ( timeout > 0 ) {
				started = Date.now();
				timer = setTimeout( dismiss, remaining );
			}
		};
		const pause = () => {
			if ( timeout > 0 && timer !== null ) {
				clearTimeout( timer );
				timer = null;
				remaining = Math.max( 1500, remaining - ( Date.now() - started ) );
			}
		};
		toast.addEventListener( 'mouseenter', pause );
		toast.addEventListener( 'focusin', pause );
		toast.addEventListener( 'mouseleave', start );
		toast.addEventListener( 'focusout', ( event ) => {
			if ( ! toast.contains( event.relatedTarget ) ) {
				start();
			}
		} );

		live.appendChild( toast );
		while ( live.children.length > 3 ) {
			live.firstElementChild.remove();
		}
		start();
		changed();
		return { dismiss };
	};

	return {
		el: region,
		show,
		clear: () => live.replaceChildren(),
	};
}
