/**
 * Normalizers and pure helpers for catalogue data (GET /catalog, /catalog/categories, /product/{id}).
 *
 * The server is authoritative for IDs, attributes, prices, stock and readiness. These helpers only
 * shape the responses for the UI, resolve the exact variation for a set of attribute choices and
 * explain why an option cannot be chosen. Nothing here invents catalogue values: when a unit has no
 * merchant-verified capacity it is simply not calculable.
 *
 * @module catalog
 */

import { compatibleUnits, dimensionOf, normalizeUnit as canonicalUnit, parseAmount } from './units.js';
import { priceToMinor, priceFromMinor } from './engine.js';
import { __, _n, sprintf } from './i18n.js';
import { readinessText } from './messages.js';

/** Product formats (mapping container types). */
export const FORMATS = Object.freeze( [ 'vial', 'pen', 'nasal_spray', 'bundle', 'supply', 'other' ] );

/** Readiness codes that allow planning. */
export const PLANNABLE = Object.freeze( [ 'ready', 'manual_addon' ] );

const str = ( v ) => ( typeof v === 'string' ? v : '' );
const num = ( v, fallback = 0 ) => ( typeof v === 'number' && Number.isFinite( v ) ? v : fallback );
const intOf = ( v, fallback = 0 ) => {
	if ( typeof v === 'number' && Number.isSafeInteger( v ) ) {
		return v;
	}
	if ( typeof v === 'string' && /^\d{1,15}$/.test( v ) ) {
		return Number( v );
	}
	return fallback;
};
const decimal = ( v ) => {
	if ( typeof v === 'number' && Number.isFinite( v ) && v >= 0 ) {
		return String( v );
	}
	return typeof v === 'string' && /^\d+(\.\d+)?$/.test( v ) ? v : '';
};
const obj = ( v ) => ( v && typeof v === 'object' && ! Array.isArray( v ) ? v : {} );

/**
 * Plural label of a format.
 *
 * @param {string} format Format.
 * @return {string} Label for filter chips.
 */
export function formatPluralLabel( format ) {
	switch ( format ) {
		case 'vial':
			return __( 'Vials' );
		case 'pen':
			return __( 'Pens' );
		case 'nasal_spray':
			return __( 'Nasal sprays' );
		case 'bundle':
			return __( 'Kits & bundles' );
		case 'supply':
			return __( 'Supplies' );
		default:
			return __( 'Other' );
	}
}

/**
 * Singular label of a format (badges).
 *
 * @param {string} format Format.
 * @return {string} Label.
 */
export function formatLabel( format ) {
	switch ( format ) {
		case 'vial':
			return __( 'Vial' );
		case 'pen':
			return __( 'Pen' );
		case 'nasal_spray':
			return __( 'Nasal spray' );
		case 'bundle':
			return __( 'Kit / bundle' );
		case 'supply':
			return __( 'Supply' );
		default:
			return __( 'Other' );
	}
}

/**
 * Container kind of a format: the noun used on product lines ("3 vials", "+1 spare pen").
 *
 * @param {string} format Format (container type), or "pack" for a purchase unit that holds several
 *                        containers (purchaseFormat()).
 * @return {string} vial | pen | bottle | pack | item.
 */
export function containerKind( format ) {
	switch ( format ) {
		case 'vial':
			return 'vial';
		case 'pen':
			return 'pen';
		case 'nasal_spray':
			return 'bottle';
		case 'bundle':
		case 'supply':
		case 'pack':
			return 'pack';
		default:
			return 'item';
	}
}

/**
 * Format whose nouns count the PURCHASE units of a line (headline, quantity stepper, "+1 spare"):
 * the unit's container type, or "pack" when one purchase unit holds several containers (a mapping
 * with pack_count > 1, e.g. "10 mg × 5 vials"): the quantity counts packs, never single vials.
 *
 * @param {Object|null} unit     Unit (normalizeSellable()) or null.
 * @param {string}      fallback Format used without a unit (e.g. the product's first unit).
 * @return {string} Format.
 */
export function purchaseFormat( unit, fallback = '' ) {
	if ( ! unit ) {
		return fallback;
	}
	return Number.isSafeInteger( unit.packCount ) && unit.packCount > 1 ? 'pack' : unit.containerType;
}

/**
 * Accessible names of the − / + buttons of the quantity stepper ("Fewer vials" / "More vials"):
 * whole translatable strings per noun (translated nouns are never lower-cased or inserted).
 *
 * @param {string} format Format.
 * @return {{fewer: string, more: string}} Names.
 */
export function stepperLabels( format ) {
	switch ( containerKind( format ) ) {
		case 'vial':
			return { fewer: __( 'Fewer vials' ), more: __( 'More vials' ) };
		case 'pen':
			return { fewer: __( 'Fewer pens' ), more: __( 'More pens' ) };
		case 'bottle':
			return { fewer: __( 'Fewer bottles' ), more: __( 'More bottles' ) };
		case 'pack':
			return { fewer: __( 'Fewer packs' ), more: __( 'More packs' ) };
		default:
			return { fewer: __( 'Fewer items' ), more: __( 'More items' ) };
	}
}

/**
 * Container noun in running text after a number ("2 packs"), in the plural form of the count.
 *
 * @param {string} format Format.
 * @param {number} n      Count.
 * @return {string} Noun.
 */
export function containerNoun( format, n ) {
	switch ( containerKind( format ) ) {
		case 'vial':
			return _n( 'vial', 'vials', n );
		case 'pen':
			return _n( 'pen', 'pens', n );
		case 'bottle':
			return _n( 'bottle', 'bottles', n );
		case 'pack':
			return _n( 'pack', 'packs', n );
		default:
			return _n( 'item', 'items', n );
	}
}

