/**
 * Headline of a calculated line: "3 vials of 10 MG".
 *
 * @param {string} format Format.
 * @param {number} n      Quantity.
 * @param {string} count  Formatted quantity.
 * @param {string} what   Strength / option / product name.
 * @return {string} Headline.
 */
export function quantityHeadline( format, n, count, what ) {
	switch ( containerKind( format ) ) {
		case 'vial':
			/* translators: 1: number of vials, 2: strength, option or product name. */
			return sprintf( _n( '%1$s vial of %2$s', '%1$s vials of %2$s', n ), count, what );
		case 'pen':
			/* translators: 1: number of pens, 2: strength, option or product name. */
			return sprintf( _n( '%1$s pen of %2$s', '%1$s pens of %2$s', n ), count, what );
		case 'bottle':
			/* translators: 1: number of bottles, 2: strength, option or product name. */
			return sprintf( _n( '%1$s bottle of %2$s', '%1$s bottles of %2$s', n ), count, what );
		case 'pack':
			/* translators: 1: number of packs, 2: option or product name. */
			return sprintf( _n( '%1$s pack of %2$s', '%1$s packs of %2$s', n ), count, what );
		default:
			/* translators: 1: number of items, 2: option or product name. */
			return sprintf( _n( '%1$s item of %2$s', '%1$s items of %2$s', n ), count, what );
	}
}

/**
 * Caption of the "lasts" cell: "Each 10 mg vial lasts (40 uses)".
 *
 * @param {string} format   Format.
 * @param {string} strength Formatted container capacity ("10 mg").
 * @param {number} uses     Whole uses per container.
 * @param {string} count    Formatted uses.
 * @return {string} Caption.
 */
export function lastsCaption( format, strength, uses, count ) {
	switch ( containerKind( format ) ) {
		case 'vial':
			/* translators: 1: capacity of one vial (e.g. 10 mg), 2: number of uses. */
			return sprintf( _n( 'Each %1$s vial lasts (%2$s use)', 'Each %1$s vial lasts (%2$s uses)', uses ), strength, count );
		case 'pen':
			/* translators: 1: capacity of one pen (e.g. 10 mg), 2: number of uses. */
			return sprintf( _n( 'Each %1$s pen lasts (%2$s use)', 'Each %1$s pen lasts (%2$s uses)', uses ), strength, count );
		case 'bottle':
			/* translators: 1: capacity of one bottle (e.g. 10 mL), 2: number of uses. */
			return sprintf( _n( 'Each %1$s bottle lasts (%2$s use)', 'Each %1$s bottle lasts (%2$s uses)', uses ), strength, count );
		default:
			/* translators: 1: capacity of one container (e.g. 10 mg), 2: number of uses. */
			return sprintf( _n( 'Each %1$s container lasts (%2$s use)', 'Each %1$s container lasts (%2$s uses)', uses ), strength, count );
	}
}

/**
 * Format tabs of the picker: "All" is added by the caller; these are the formats allowed by the
 * settings that the catalogue currently offers, in the configured order, with their configured
 * labels (falling back to the built-in plural labels).
 *
 * @param {Object}        options           Options.
 * @param {string[]|null} options.allowed   Allowed formats (null: all).
 * @param {string[]|null} options.order     Configured order (unknown values dropped, missing appended).
 * @param {Object|null}   options.labels    format => label.
 * @param {string[]|null} options.available Formats present in the catalogue (null: unknown, all).
 * @param {string}        options.active    Active format (always kept so its tab does not vanish).
 * @return {Array<{format: string, label: string}>} Tabs.
 */
export function formatTabs( { allowed = null, order = null, labels = null, available = null, active = '' } = {} ) {
	const ordered = [ ...( Array.isArray( order ) ? order : [] ).filter( ( f, i, all ) => FORMATS.includes( f ) && all.indexOf( f ) === i ) ];
	FORMATS.forEach( ( f ) => {
		if ( ! ordered.includes( f ) ) {
			ordered.push( f );
		}
	} );
	const allowedList = Array.isArray( allowed ) ? allowed : FORMATS;
	const names = labels && typeof labels === 'object' && ! Array.isArray( labels ) ? labels : {};
	return ordered
		.filter( ( f ) => allowedList.includes( f ) && ( available === null || available.includes( f ) || f === active ) )
		.map( ( f ) => {
			const custom = typeof names[ f ] === 'string' ? names[ f ].trim().slice( 0, 40 ) : '';
			return { format: f, label: custom !== '' ? custom : formatPluralLabel( f ) };
		} );
}

/**
 * Chip groups of GET /catalog/categories (`groups`), in server order.
 *
 * @param {*} raw Response.
 * @return {Array<{key: string, label: string, termIds: number[], count: number}>} Groups.
 */
export function normalizeCategoryGroups( raw ) {
	const list = raw && typeof raw === 'object' && Array.isArray( raw.groups ) ? raw.groups : [];
	const seen = new Set();
	return list
		.map( ( g ) => {
			const group = obj( g );
			return {
				key: str( group.key ),
				label: str( group.label ).trim(),
				termIds: ( Array.isArray( group.term_ids ) ? group.term_ids : [] ).map( ( id ) => intOf( id, 0 ) ).filter( ( id ) => id > 0 ),
				count: intOf( group.count, 0 ),
			};
		} )
		.filter( ( g ) => {
			if ( ! /^[a-z0-9-]{1,60}$/.test( g.key ) || g.label === '' || seen.has( g.key ) ) {
				return false;
			}
			seen.add( g.key );
			return true;
		} );
}

/**
 * Builder category label of a catalogue item: the first chip group (in chip order) containing one
 * of the item's categories or one of their ancestors.
 *
 * @param {number[]} categoryIds Item category IDs.
 * @param {Array}    groups      normalizeCategoryGroups() result.
 * @param {Map}      parents     Category ID => parent ID (from GET /catalog/categories items).
 * @return {string} Label ('' when no group matches).
 */
export function categoryTag( categoryIds, groups, parents = new Map() ) {
	if ( ! Array.isArray( categoryIds ) || categoryIds.length === 0 || ! Array.isArray( groups ) || groups.length === 0 ) {
		return '';
	}
	const lineage = new Set();
	categoryIds.forEach( ( id ) => {
		let current = id;
		for ( let depth = 0; current > 0 && depth < 20 && ! lineage.has( current ); depth++ ) {
			lineage.add( current );
			current = parents.get( current ) || 0;
		}
	} );
	const match = groups.find( ( g ) => g.termIds.some( ( id ) => lineage.has( id ) ) );
	return match ? match.label : '';
}

/**
 * Normalized image or null.
 *
 * @param {*} raw Raw image.
 * @return {{src: string, srcset: string, sizes: string, alt: string, width: number, height: number}|null} Image.
 */
export function normalizeImage( raw ) {
	const image = obj( raw );
	const src = str( image.src ) || str( image.url ) || str( image.thumbnail );
	if ( ! /^https?:\/\//i.test( src ) && ! src.startsWith( '/' ) ) {
		return null;
	}
	return {
		src,
		srcset: str( image.srcset ),
		sizes: str( image.sizes ),
		alt: str( image.alt ),
		width: intOf( image.width, 0 ) || 300,
		height: intOf( image.height, 0 ) || 300,
	};
}

/**
 * Normalized stock status.
 *
 * @param {*} raw Raw status.
 * @return {string} instock | outofstock | onbackorder | ''.
 */
function stockStatus( raw ) {
	const value = typeof raw === 'string' ? raw : str( obj( raw ).status );
	return [ 'instock', 'outofstock', 'onbackorder' ].includes( value ) ? value : '';
}

/**
 * Availability of a catalogue item: explicit stock status, else derived from the number of
 * plannable units that can currently be bought (`in_stock_units` of Repository::search()).
 *
 * @param {Object} item Raw item.
 * @return {string} instock | outofstock | onbackorder | ''.
 */
function stockStatusOfItem( item ) {
	const explicit = stockStatus( item.stock_status ?? item.availability );
	if ( explicit !== '' ) {
		return explicit;
	}
	if ( typeof item.in_stock_units === 'number' ) {
		return item.in_stock_units > 0 ? 'instock' : 'outofstock';
	}
	return '';
}

/**
 * Normalized catalogue list item (GET /catalog `items[]`).
 *
 * @param {Object} raw Raw item.
 * @return {Object|null} Item { id, name, permalink, image, formats, priceMin, priceMax, stockStatus }.
 */
export function normalizeCatalogItem( raw ) {
	const item = obj( raw );
	const id = intOf( item.id, 0 ) || intOf( item.product_id, 0 );
	if ( id <= 0 ) {
		return null;
	}
	let formats = Array.isArray( item.formats ) ? item.formats : [];
	if ( formats.length === 0 ) {
		formats = [ item.format, item.container_type ].filter( ( f ) => typeof f === 'string' && f !== '' );
		if ( Array.isArray( item.container_types ) ) {
			formats = item.container_types;
		}
	}
	const prices = obj( item.prices || item.price_range );
	const priceMin = decimal( item.price_min ?? item.min_price ?? prices.min ?? item.price );
	const priceMax = decimal( item.price_max ?? item.max_price ?? prices.max ?? item.price ) || priceMin;
	return {
		id,
		name: str( item.name ) || str( item.title ),
		permalink: str( item.permalink ),
		image: normalizeImage( item.image ),
		formats: [ ...new Set( formats.filter( ( f ) => FORMATS.includes( f ) ) ) ],
		priceMin,
		priceMax,
		stockStatus: stockStatusOfItem( item ),
		unitCount: intOf( item.ready_units ?? item.unit_count, 0 ),
		categoryIds: ( Array.isArray( item.categories ) ? item.categories : [] ).map( ( c ) => ( typeof c === 'number' ? c : intOf( obj( c ).id, 0 ) ) ).filter( ( c ) => Number.isSafeInteger( c ) && c > 0 ),
		sizes: ( Array.isArray( item.sizes ) ? item.sizes : [] )
			.filter( ( size ) => typeof size === 'string' && size.trim() !== '' )
			.map( ( size ) => size.trim().slice( 0, 40 ) )
			.filter( ( size, i, all ) => all.indexOf( size ) === i )
			.slice( 0, 12 ),
		cheapestCapacity: normalizeCapacity( item.cheapest_capacity ),
		// Containers per purchase unit of that cheapest unit (1 when the server does not say).
		cheapestPackCount: Math.min( MAX_PACK_COUNT, Math.max( 1, intOf( item.cheapest_pack_count, 1 ) ) ),
	};
}

/**
 * A capacity in array form (`Capacity::to_array()`), or null when it is not a valid capacity.
 *
 * @param {*} raw Raw capacity.
 * @return {{dimension: string, amount: string, unit: string, basis: string}|null} Capacity.
 */
export function normalizeCapacity( raw ) {
	const c = obj( raw );
	const unit = canonicalUnit( str( c.unit ) );
	const amount = decimal( c.amount );
	if ( unit === null || amount === '' || ! [ 'labelled', 'usable', 'fill_volume' ].includes( c.basis ) ) {
		return null;
	}
	return { dimension: dimensionOf( unit ), amount, unit, basis: c.basis };
}

/** Largest number of containers per purchase unit (Catalog\Validator::MAX_PACK_COUNT). */
export const MAX_PACK_COUNT = 1000;

/**
 * Price per mg for display ("Rp 85,000/mg"): the price of one PURCHASE unit ÷ (the verified MASS
 * capacity of one container in mg × the containers per purchase unit), rounded half-up to the
 * currency decimals — the capacity a purchase unit buys, as the calculation counts it (capacity ×
 * pack count). Display arithmetic only; null for any other dimension, a missing price, an invalid
 * capacity or an invalid pack count.
 *
 * @param {string}      price     Price of one purchase unit (decimal string).
 * @param {Object|null} capacity  Capacity of one container { dimension, amount, unit }.
 * @param {number}      decimals  Currency decimals.
 * @param {number}      packCount Containers per purchase unit (whole number 1–1000).
 * @return {string|null} Price per mg (decimal string).
 */
export function perMgPrice( price, capacity, decimals, packCount = 1 ) {
	const c = capacity && typeof capacity === 'object' ? capacity : null;
	if ( typeof price !== 'string' || price === '' || ! c || c.dimension !== 'mass' ) {
		return null;
	}
	if ( ! Number.isSafeInteger( packCount ) || packCount < 1 || packCount > MAX_PACK_COUNT ) {
		return null;
	}
	try {
		const scaled = parseAmount( String( c.amount ), c.unit ) * BigInt( packCount );
		if ( scaled <= 0n ) {
			return null;
		}
		const mg = parseAmount( '1', 'mg' );
		const minor = priceToMinor( price, decimals );
		return priceFromMinor( ( minor * mg * 2n + scaled ) / ( scaled * 2n ), decimals );
	} catch ( e ) {
		return null;
	}
}

/**
 * First verified mass capacity of a unit (the per-mg price of a product line).
 *
 * @param {Object|null} unit Unit.
 * @return {Object|null} Capacity.
 */
export function massCapacity( unit ) {
	const list = unit && Array.isArray( unit.capacities ) ? unit.capacities : [];
	return list.find( ( c ) => c.dimension === 'mass' ) || null;
}

/**
 * Query of GET /catalog for the picker state. The category-chip group applies only while the
 * Vials tab is active.
 *
 * @param {Object} state { query, category, format, group, page, perPage }.
 * @return {Object} Query parameters (empty values are dropped by the API client).
 */
export function catalogQuery( state ) {
	const s = obj( state );
	const format = FORMATS.includes( s.format ) ? s.format : '';
	const group = format === 'vial' && typeof s.group === 'string' && /^[a-z0-9-]{1,60}$/.test( s.group ) ? s.group : '';
	return {
		search: str( s.query ),
		category: s.category === null || s.category === undefined ? '' : String( s.category ),
		format,
		group,
		page: Math.max( 1, intOf( s.page, 1 ) ),
		per_page: Math.max( 1, intOf( s.perPage, 12 ) ),
	};
}

/**
 * Normalized combinations (GET /combinations).
 *
 * @param {*} raw Response.
 * @return {Array<{id: string, name: string, blurb: string, items: Array<{productId: number, variationId: number, defaultVariationId: number, name: string, image: Object|null}>, fromPrice: string}>} Combinations.
 */
export function normalizeCombinations( raw ) {
	const list = Array.isArray( raw ) ? raw : obj( raw ).items;
	const seen = new Set();
	return ( Array.isArray( list ) ? list : [] )
		.map( ( c ) => {
			const combo = obj( c );
			const items = ( Array.isArray( combo.items ) ? combo.items : [] )
				.map( ( i ) => {
					const item = obj( i );
					return { productId: intOf( item.product_id, 0 ), variationId: intOf( item.variation_id, 0 ), defaultVariationId: intOf( item.default_variation_id, 0 ), name: str( item.name ), image: normalizeImage( item.image ) };
				} )
				.filter( ( item ) => item.productId > 0 );
			return {
				id: str( combo.id ),
				name: str( combo.name ).trim(),
				blurb: str( combo.blurb ).trim() || items.map( ( item ) => item.name ).filter( Boolean ).join( ' + ' ),
				items,
				fromPrice: decimal( combo.from_price ),
			};
		} )
		.filter( ( combo ) => {
			if ( ! /^[a-z0-9-]{1,40}$/.test( combo.id ) || combo.name === '' || combo.items.length === 0 || seen.has( combo.id ) ) {
				return false;
			}
			seen.add( combo.id );
			return true;
		} );
}

/**
 * Products of a combination that "Add all" still has to add: one per product that is not in the
 * protocol yet (a product listed twice in the combination is added once), with the configured
 * variation, else the variation the server chose for "Add all" (default_variation_id: the first
 * plannable variation in stock, else the first on backorder), else 0 (chosen in the browser,
 * comboSelection()).
 *
 * @param {Object}   combo Combination (normalizeCombinations()).
 * @param {Object[]} lines Protocol lines.
 * @return {Array<{productId: number, variationId: number}>} Items to add, in combination order.
 */
export function comboAdditions( combo, lines ) {
	const present = new Set( ( Array.isArray( lines ) ? lines : [] ).map( ( line ) => line.product_id ) );
	const out = [];
	( combo && Array.isArray( combo.items ) ? combo.items : [] ).forEach( ( item ) => {
		if ( ! present.has( item.productId ) ) {
			present.add( item.productId );
			out.push( { productId: item.productId, variationId: item.variationId || item.defaultVariationId || 0 } );
		}
	} );
	return out;
}

/**
 * Whether every product of a combination is in the protocol ("✓ In your protocol").
 *
 * @param {Object}   combo Combination.
 * @param {Object[]} lines Protocol lines.
 * @return {boolean} In protocol.
 */
export function comboInProtocol( combo, lines ) {
	return !! combo && Array.isArray( combo.items ) && combo.items.length > 0 && comboAdditions( combo, lines ).length === 0;
}

/**
 * Normalized catalogue page (GET /catalog).
 *
 * @param {Object} raw Response.
 * @return {{items: Object[], total: number, pages: number, page: number, formats: string[]}} Page.
 */
export function normalizeCatalogPage( raw ) {
	const data = obj( raw );
	const items = ( Array.isArray( data.items ) ? data.items : [] ).map( normalizeCatalogItem ).filter( Boolean );
	const facets = obj( data.facets );
	const formatSource = Array.isArray( data.formats ) ? data.formats : facets.formats;
	let formats = null;
	if ( Array.isArray( formatSource ) ) {
		formats = formatSource.map( ( f ) => ( typeof f === 'string' ? f : str( obj( f ).value || obj( f ).format ) ) ).filter( ( f ) => FORMATS.includes( f ) );
	} else if ( formatSource && typeof formatSource === 'object' ) {
		formats = Object.keys( formatSource ).filter( ( f ) => FORMATS.includes( f ) && num( formatSource[ f ], 1 ) > 0 );
	}
	return {
		items,
		total: intOf( data.total, items.length ),
		pages: Math.max( 1, intOf( data.pages, 1 ) ),
		page: Math.max( 1, intOf( data.page, 1 ) ),
		formats,
	};
}

/**
 * Normalized category list (GET /catalog/categories), ordered as a tree with depth.
 *
 * @param {*} raw Response (array or { items }).
 * @return {Array<{id: number, name: string, slug: string, parent: number, count: number, depth: number}>} Categories.
 */
export function normalizeCategories( raw ) {
	const list = Array.isArray( raw ) ? raw : ( Array.isArray( obj( raw ).items ) ? raw.items : obj( raw ).categories || [] );
	const cats = ( Array.isArray( list ) ? list : [] )
		.map( ( c ) => {
			const cat = obj( c );
			return {
				id: intOf( cat.id, 0 ) || intOf( cat.term_id, 0 ),
				name: str( cat.name ),
				slug: str( cat.slug ),
				parent: intOf( cat.parent, 0 ),
				count: intOf( cat.count, 0 ),
				depth: 0,
			};
		} )
		.filter( ( c ) => c.id > 0 && c.name !== '' );
	const byParent = new Map();
	const ids = new Set( cats.map( ( c ) => c.id ) );
	cats.forEach( ( c ) => {
		const parent = ids.has( c.parent ) ? c.parent : 0;
		if ( ! byParent.has( parent ) ) {
			byParent.set( parent, [] );
		}
		byParent.get( parent ).push( c );
	} );
	const out = [];
	const walk = ( parent, depth, seen ) => {
		( byParent.get( parent ) || [] )
			.sort( ( a, b ) => a.name.localeCompare( b.name ) )
			.forEach( ( c ) => {
				if ( seen.has( c.id ) ) {
					return;
				}
				seen.add( c.id );
				out.push( { ...c, depth: Math.min( depth, 4 ) } );
				walk( c.id, depth + 1, seen );
			} );
	};
	walk( 0, 0, new Set() );
	return out;
}

/**
 * Capacities in array form `{dimension, amount, unit, basis}` (from the unit, else derived from
 * the public mapping exactly as ARCHITECTURE §4.1 describes).
 *
 * @param {Object} unit    Raw unit.
 * @param {Object} mapping Raw public mapping.
 * @return {Array<{dimension: string, amount: string, unit: string, basis: string}>} Capacities.
 */
function capacitiesOf( unit, mapping ) {
	const valid = ( c ) => {
		const u = canonicalUnit( str( c.unit ) );
		return u !== null && decimal( c.amount ) !== '' && [ 'labelled', 'usable', 'fill_volume' ].includes( c.basis )
			? { dimension: dimensionOf( u ), amount: decimal( c.amount ), unit: u, basis: c.basis }
			: null;
	};
	if ( Array.isArray( unit.capacities ) ) {
		return unit.capacities.map( ( c ) => valid( obj( c ) ) ).filter( Boolean );
	}
	const out = [];
	const add = ( amount, unitName, basis ) => {
		const c = valid( { amount, unit: unitName, basis } );
		if ( c ) {
			const same = out.findIndex( ( o ) => o.dimension === c.dimension );
			if ( same < 0 ) {
				out.push( c );
			} else if ( basis === 'usable' ) {
				out[ same ] = c;
			}
		}
	};
	add( mapping.strength_value, mapping.strength_unit, 'labelled' );
	add( mapping.unit_amount, mapping.unit_unit, 'usable' );
	if ( ! out.some( ( c ) => c.dimension === 'volume' && c.basis === 'usable' ) ) {
		const fill = valid( { amount: mapping.fill_volume_ml, unit: 'mL', basis: 'fill_volume' } );
		if ( fill ) {
			const same = out.findIndex( ( o ) => o.dimension === 'volume' );
			if ( same < 0 ) {
				out.push( fill );
			}
		}
	}
	return out;
}

/**
 * Normalized sellable unit (simple product or variation) from GET /product/{id} `units[]`.
 *
 * @param {Object} raw Raw unit.
 * @return {Object|null} Unit.
 */
export function normalizeSellable( raw ) {
	const unit = obj( raw );
	const productId = intOf( unit.product_id, 0 );
	if ( productId <= 0 ) {
		return null;
	}
	const variationId = intOf( unit.variation_id, 0 );
	const mapping = obj( unit.mapping );
	const capacities = capacitiesOf( unit, mapping );
	const dims = [ ...new Set( capacities.map( ( c ) => c.dimension ) ) ];
	const attributes = {};
	for ( const [ key, value ] of Object.entries( obj( unit.attributes ) ) ) {
		if ( key.startsWith( 'attribute_' ) && typeof value === 'string' ) {
			attributes[ key ] = value;
		}
	}
	const components = ( Array.isArray( mapping.component_composition ) ? mapping.component_composition : [] )
		.map( ( c ) => obj( c ) )
		.filter( ( c ) => intOf( c.product_id, 0 ) > 0 && intOf( c.quantity, 0 ) > 0 )
		.map( ( c ) => ( { product_id: intOf( c.product_id ), variation_id: intOf( c.variation_id, 0 ), quantity: intOf( c.quantity ) } ) );
	const readiness = str( unit.readiness ) || 'unavailable';
	const packCount = intOf( unit.pack_count ?? mapping.pack_count, 1 );
	return {
		productId,
		variationId,
		key: productId + ':' + variationId,
		type: str( unit.type ) || ( variationId > 0 ? 'variation' : 'simple' ),
		name: str( unit.name ),
		parentName: str( unit.parent_name ),
		attributes,
		attributeLabels: obj( unit.attribute_labels ),
		image: normalizeImage( unit.image ),
		price: decimal( unit.price ),
		regularPrice: decimal( unit.regular_price ),
		onSale: unit.on_sale === true,
		stockStatus: stockStatus( unit.stock_status ),
		backordersAllowed: unit.backorders_allowed === true,
		stockQuantity: typeof unit.stock_quantity === 'number' ? unit.stock_quantity : null,
		purchasable: unit.is_purchasable !== false,
		soldIndividually: unit.sold_individually === true,
		minQty: Math.max( 1, intOf( unit.min_qty, 1 ) ),
		maxQty: typeof unit.max_qty === 'number' ? unit.max_qty : -1,
		readiness,
		readinessMessage: str( unit.readiness_message ),
		fetchedAt: str( unit.fetched_at ),
		capacities,
		packCount: packCount >= 1 && packCount <= 1000 ? packCount : 1,
		compatibleUnits: Array.isArray( unit.compatible_units ) ? unit.compatible_units.map( ( u ) => canonicalUnit( str( u ) ) ).filter( Boolean ) : compatibleUnits( dims ),
		containerType: str( unit.container_type ) || str( mapping.container_type ),
		modes: Array.isArray( unit.modes ) ? unit.modes.filter( ( m ) => [ 'schedule', 'direct', 'manual' ].includes( m ) ) : null,
		verifiedAt: str( mapping.verified_at ) || str( unit.verified_at ),
		publicNote: str( mapping.public_note ),
		components,
	};
}

/**
 * Role of a variation attribute: strength (pa_mg / pa_iu), pen format (pa_pen-type) or other.
 *
 * @param {string} key   Attribute key (attribute_pa_mg).
 * @param {string} label Attribute label.
 * @return {string} strength | pen_format | other.
 */
export function attributeRole( key, label ) {
	const k = String( key || '' ).replace( /^attribute_/, '' ).toLowerCase();
	const l = String( label || '' ).trim().toLowerCase();
	if ( /^pa_(mg|mcg|iu|strength)$/.test( k ) || /^(mg|mcg|iu|strength)$/.test( l ) ) {
		return 'strength';
	}
	if ( k === 'pa_pen-type' || /^pen[\s_-]?type$/.test( l ) ) {
		return 'pen_format';
	}
	return 'other';
}

/**
 * Role reported by the server (Mapper::attribute_role()), mapped to the UI roles.
 *
 * @param {Object} attribute Raw attribute { key, role }.
 * @return {string} strength | pen_format | format | other | '' (unknown).
 */
function serverRole( attribute ) {
	if ( attribute.role === 'strength' || attribute.role === 'other' ) {
		return attribute.role;
	}
	if ( attribute.role === 'format' ) {
		return /pen/.test( attribute.key ) ? 'pen_format' : 'format';
	}
	return '';
}

/**
 * Normalized product detail (GET /product/{id}).
 *
 * @param {Object} raw Response.
 * @return {Object|null} Product { id, name, type, permalink, image, attributes, defaultAttributes, units }.
 */
export function normalizeProduct( raw ) {
	const data = obj( raw );
	const id = intOf( data.id, 0 );
	if ( id <= 0 ) {
		return null;
	}
	const attributes = ( Array.isArray( data.attributes ) ? data.attributes : [] )
		.map( ( a ) => obj( a ) )
		.filter( ( a ) => typeof a.key === 'string' && a.key.startsWith( 'attribute_' ) )
		.map( ( a ) => ( {
			key: a.key,
			label: str( a.label ) || a.key.replace( /^attribute_(pa_)?/, '' ),
			role: serverRole( a ) || attributeRole( a.key, a.label ),
			options: ( Array.isArray( a.options ) ? a.options : [] )
				.map( ( o ) => ( typeof o === 'string' ? { slug: o, name: o } : { slug: str( obj( o ).slug ), name: str( obj( o ).name ) || str( obj( o ).slug ) } ) )
				.filter( ( o ) => o.slug !== '' ),
		} ) );
	const defaults = {};
	for ( const [ key, value ] of Object.entries( obj( data.default_attributes ) ) ) {
		const full = key.startsWith( 'attribute_' ) ? key : 'attribute_' + key;
		if ( typeof value === 'string' && value !== '' ) {
			defaults[ full ] = value;
		}
	}
	return {
		id,
		name: str( data.name ),
		type: str( data.type ) || 'simple',
		permalink: str( data.permalink ),
		image: normalizeImage( data.image ),
		attributes,
		defaultAttributes: defaults,
		units: ( Array.isArray( data.units ) ? data.units : [] ).map( normalizeSellable ).filter( Boolean ),
	};
}

/**
 * Whether a unit can be planned (ready or manual add-on).
 *
 * @param {Object|null} unit Unit.
 * @return {boolean} Plannable.
 */
export function isPlannable( unit ) {
	return !! unit && PLANNABLE.includes( unit.readiness );
}

/**
 * Calculation modes the unit allows. The `modes` list of GET /product is authoritative; the
 * fallback (older responses without it) mirrors the server: manual only for manual add-ons and
 * bundles, no schedule for supplies.
 *
 * @param {Object|null} unit Unit.
 * @return {string[]} Modes.
 */
export function modesFor( unit ) {
	if ( ! isPlannable( unit ) ) {
		return [];
	}
	if ( Array.isArray( unit.modes ) && unit.modes.length > 0 ) {
		return unit.modes;
	}
	if ( unit.readiness === 'manual_addon' || unit.containerType === 'bundle' || unit.capacities.length === 0 ) {
		return [ 'manual' ];
	}
	if ( unit.containerType === 'supply' ) {
		return [ 'direct', 'manual' ];
	}
	return [ 'schedule', 'direct', 'manual' ];
}

/**
 * Whether a unit matches the attribute choices given so far ('' on the unit = any value, except on
 * the attributes listed in `exactKeys`).
 *
 * @param {Object}   unit      Unit.
 * @param {Object}   selection attribute key => slug ('' = not chosen).
 * @param {string[]} exactKeys Attribute keys where a unit's "any" value never matches a chosen value
 *                             (strength attributes with several options: see exactAttributeKeys()).
 * @return {boolean} Matches.
 */
export function unitMatches( unit, selection, exactKeys = [] ) {
	for ( const [ key, value ] of Object.entries( selection || {} ) ) {
		if ( value === '' || value === null || value === undefined ) {
			continue;
		}
		const own = unit.attributes[ key ];
		if ( own === '' && exactKeys.includes( key ) ) {
			return false;
		}
		if ( own !== undefined && own !== '' && own !== value ) {
			return false;
		}
	}
	return true;
}

/**
 * Strength attributes (pa_mg / pa_iu) offering more than one option. A variation with "any"
 * strength on such an attribute has one mapped strength that cannot match every strength a
 * customer could pick, so it never matches a chosen strength (the server refuses it as well:
 * Catalog\Validator `strength_attribute_any`, Cart\CartValidator).
 *
 * @param {Object} product Product.
 * @return {string[]} Attribute keys.
 */
export function exactAttributeKeys( product ) {
	const attributes = product && Array.isArray( product.attributes ) ? product.attributes : [];
	return attributes
		.filter( ( a ) => ( a.role === 'strength' || attributeRole( a.key, a.label ) === 'strength' ) && Array.isArray( a.options ) && a.options.length > 1 )
		.map( ( a ) => a.key );
}

/**
 * The exact unit for a complete selection (null until every attribute is chosen).
 *
 * @param {Object} product   Product.
 * @param {Object} selection Choices.
 * @return {Object|null} Unit.
 */
export function resolveUnit( product, selection ) {
	if ( ! product ) {
		return null;
	}
	if ( product.type !== 'variable' ) {
		return product.units.find( ( u ) => u.variationId === 0 ) || product.units[ 0 ] || null;
	}
	const complete = product.attributes.every( ( a ) => typeof ( selection || {} )[ a.key ] === 'string' && selection[ a.key ] !== '' );
	if ( ! complete ) {
		return null;
	}
	const matches = product.units.filter( ( u ) => u.variationId > 0 && unitMatches( u, selection, exactAttributeKeys( product ) ) );
	const anyCount = ( u ) => Object.values( u.attributes ).filter( ( v ) => v === '' ).length;
	matches.sort( ( a, b ) => anyCount( a ) - anyCount( b ) );
	return matches[ 0 ] || null;
}

/**
 * Unit by variation ID (0 = the simple product's unit).
 *
 * @param {Object} product     Product.
 * @param {number} variationId Variation ID.
 * @return {Object|null} Unit.
 */
export function unitById( product, variationId ) {
	if ( ! product ) {
		return null;
	}
	return product.units.find( ( u ) => u.variationId === ( variationId || 0 ) ) || ( product.type !== 'variable' ? product.units[ 0 ] || null : null );
}

/**
 * State of every option of one attribute given the other choices.
 *
 * @param {Object} product   Product.
 * @param {Object} selection Choices.
 * @param {string} key       Attribute key.
 * @return {Array<{slug: string, name: string, disabled: boolean, reason: string}>} Options.
 */
export function optionStates( product, selection, key ) {
	const attribute = product.attributes.find( ( a ) => a.key === key );
	if ( ! attribute ) {
		return [];
	}
	const exact = exactAttributeKeys( product );
	return attribute.options.map( ( option ) => {
		const choice = { ...( selection || {} ), [ key ]: option.slug };
		const matches = product.units.filter( ( u ) => u.variationId > 0 && unitMatches( u, choice, exact ) );
		if ( matches.length === 0 ) {
			return { ...option, disabled: true, reason: __( 'not offered with the other choices' ) };
		}
		const plannable = matches.filter( isPlannable );
		if ( plannable.length === 0 ) {
			const first = matches[ 0 ];
			return { ...option, disabled: true, reason: first.readiness === 'unavailable' ? readinessText( 'unavailable' ) : readinessText( first.readiness ) };
		}
		if ( ! plannable.some( ( u ) => u.purchasable ) ) {
			return { ...option, disabled: true, reason: __( 'not purchasable right now' ) };
		}
		return { ...option, disabled: false, reason: '' };
	} );
}

/**
 * Initial choices for a new line: the store's default form values when they resolve to a plannable
 * unit, else the only plannable unit when there is exactly one, else nothing.
 *
 * @param {Object} product Product.
 * @return {Object} Choices (attribute key => slug).
 */
export function initialSelection( product ) {
	if ( ! product || product.type !== 'variable' ) {
		return {};
	}
	const defaults = {};
	product.attributes.forEach( ( a ) => {
		defaults[ a.key ] = product.defaultAttributes[ a.key ] || '';
	} );
	if ( isPlannable( resolveUnit( product, defaults ) ) ) {
		return defaults;
	}
	const plannable = product.units.filter( ( u ) => u.variationId > 0 && isPlannable( u ) );
	if ( plannable.length === 1 ) {
		const only = {};
		product.attributes.forEach( ( a ) => {
			const own = plannable[ 0 ].attributes[ a.key ];
			only[ a.key ] = own && own !== '' ? own : '';
		} );
		return only;
	}
	const empty = {};
	product.attributes.forEach( ( a ) => {
		empty[ a.key ] = '';
	} );
	return empty;
}

/**
 * Human label of the chosen variant ("5 MG · Disposable Pen").
 *
 * @param {Object} product   Product.
 * @param {Object} selection Choices.
 * @return {string} Label ('' for simple products).
 */
export function variantLabel( product, selection ) {
	if ( ! product || product.type !== 'variable' ) {
		return '';
	}
	return product.attributes
		.map( ( a ) => {
			const slug = ( selection || {} )[ a.key ];
			const option = a.options.find( ( o ) => o.slug === slug );
			return option ? option.name : '';
		} )
		.filter( Boolean )
		.join( ' · ' );
}

/**
 * Label of an attribute by role.
 *
 * @param {Object} attribute Attribute { label, role }.
 * @return {string} Label.
 */
export function attributeLabel( attribute ) {
	if ( attribute.role === 'strength' ) {
		return __( 'Strength' );
	}
	if ( attribute.role === 'pen_format' ) {
		return __( 'Pen type' );
	}
	if ( attribute.role === 'format' ) {
		return __( 'Format' );
	}
	return attribute.label;
}

/**
 * Lowest and highest plannable price of a product (decimal strings).
 *
 * @param {Object} product Product.
 * @return {{min: string, max: string}} Range.
 */
export function priceRange( product ) {
	const prices = product.units.filter( ( u ) => isPlannable( u ) && u.price !== '' ).map( ( u ) => u.price );
	if ( prices.length === 0 ) {
		return { min: '', max: '' };
	}
	const cmp = ( a, b ) => {
		const [ ai, af = '' ] = a.split( '.' );
		const [ bi, bf = '' ] = b.split( '.' );
		const ia = ai.replace( /^0+(?=\d)/, '' );
		const ib = bi.replace( /^0+(?=\d)/, '' );
		if ( ia.length !== ib.length ) {
			return ia.length - ib.length;
		}
		if ( ia !== ib ) {
			return ia < ib ? -1 : 1;
		}
		const len = Math.max( af.length, bf.length );
		const fa = af.padEnd( len, '0' );
		const fb = bf.padEnd( len, '0' );
		if ( fa === fb ) {
			return 0;
		}
		return fa < fb ? -1 : 1;
	};
	prices.sort( cmp );
	return { min: prices[ 0 ], max: prices[ prices.length - 1 ] };
}

/**
 * Unit and attribute choices for a product added by a combination: the configured variation, else
 * the first plannable, purchasable variation in stock, else the first one on backorder, else the
 * usual initial choices. Attributes a variation leaves open ("any") take the store's default value when there is
 * one; otherwise the customer chooses them on the line.
 *
 * @param {Object} product     Product (normalized).
 * @param {number} variationId Configured variation (0 = customer picks).
 * @return {{unit: Object|null, selection: Object}} Choice.
 */
export function comboSelection( product, variationId = 0 ) {
	if ( ! product ) {
		return { unit: null, selection: {} };
	}
	if ( product.type !== 'variable' ) {
		return { unit: resolveUnit( product, {} ), selection: {} };
	}
	const fill = ( unit ) => {
		const selection = {};
		product.attributes.forEach( ( a ) => {
			const own = unit.attributes[ a.key ];
			selection[ a.key ] = own !== undefined && own !== '' ? own : product.defaultAttributes[ a.key ] || '';
		} );
		return { unit, selection };
	};
	const fixed = variationId > 0 ? product.units.find( ( u ) => u.variationId === variationId ) : null;
	if ( fixed && isPlannable( fixed ) ) {
		return fill( fixed );
	}
	// In stock first; a variation on backorder only when none is in stock (BuilderLayout::default_unit()).
	const usable = ( u ) => u.variationId > 0 && isPlannable( u ) && u.purchasable && u.stockStatus !== 'outofstock';
	const first = product.units.find( ( u ) => usable( u ) && u.stockStatus === 'instock' ) || product.units.find( usable );
	if ( first ) {
		return fill( first );
	}
	const selection = initialSelection( product );
	return { unit: resolveUnit( product, selection ), selection };
}
