/**
 * Plans dialog: local drafts (open, rename, duplicate, delete, new), account plans via /plans
 * (list, open, save, save as, rename, duplicate, delete with confirmation, consent on first save,
 * optimistic concurrency), sign-in link for guests, plan file import/export (.json ≤ 64 KB),
 * "clear local data" and, for logged-in customers, withdrawing the consent (which deletes every
 * plan saved in the account).
 *
 * Store managers also get "Publish as pre-built protocol" (CHANGE-1.7.0 §6.10): the workspace becomes a
 * new store protocol (saved switched off) or updates the store protocol it was opened from with
 * "Edit in builder" or published as; the result is reported in the dialog's message region.
 *
 * @module components/plans
 */

import { h, uid, button, render, downloadBlob } from '../app/dom.js';
import { __, _n, sprintf } from '../app/i18n.js';
import { formatDate } from '../app/format.js';
import { parsePlanFile, MAX_PLAN_BYTES } from '../app/plan.js';
import { openDialog, confirmDialog, promptDialog, dialogSection } from './modal.js';
import { focusElement } from '../app/a11y.js';
import { createLiveMessage } from './live-message.js';
import { MAX_TITLE_LENGTH } from '../app/store.js';
import { storeProtocolId, STORE_PROTOCOL_NAME_MAX } from '../app/store-templates.js';
import { withMerchant } from './store-protocols.js';

/**
 * Normalized account plan record.
 *
 * @param {*} raw Response.
 * @return {{uuid: string, title: string, plan: Object, updated_at: string, created_at: string, line_count: number}|null} Record.
 */
export function normalizeAccountPlan( raw ) {
	const data = raw && typeof raw === 'object' ? raw : null;
	if ( ! data ) {
		return null;
	}
	const plan = data.plan && typeof data.plan === 'object' ? data.plan : ( Array.isArray( data.lines ) ? data : null );
	const uuid = typeof data.uuid === 'string' ? data.uuid : '';
	if ( uuid === '' ) {
		return null;
	}
	return {
		uuid,
		title: typeof data.title === 'string' ? data.title : ( plan && typeof plan.title === 'string' ? plan.title : '' ),
		plan,
		updated_at: typeof data.updated_at === 'string' ? data.updated_at : '',
		created_at: typeof data.created_at === 'string' ? data.created_at : '',
		line_count: Number.isInteger( data.line_count ) ? data.line_count : ( plan && Array.isArray( plan.lines ) ? plan.lines.length : 0 ),
	};
}

/**
 * Date part of a timestamp formatted for display.
 *
 * @param {string} value  Timestamp (ISO or MySQL).
 * @param {string} locale Locale.
 * @return {string} Date.
 */
function shortDate( value, locale ) {
	return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}/.test( value ) ? formatDate( value.slice( 0, 10 ), locale ) : '';
}

/**
 * Message for an account plan API error.
 *
 * @param {Object} error   ApiError.
 * @param {Object} context { maxPlans }.
 * @return {string} Message.
 */
export function planErrorMessage( error, context = {} ) {
	switch ( error && error.code ) {
		case 'arp_consent_required':
			return __( 'Please confirm that the protocol may be stored in your account.' );
		case 'arp_conflict':
			return __( 'This protocol was changed in another tab or on another device. Open the saved version or save your changes as a new protocol.' );
		case 'arp_plan_limit':
			return context.maxPlans
				? sprintf( /* translators: %d: maximum number of saved plans. */ __( 'You can save up to %d protocols. Delete a protocol to save a new one.' ), context.maxPlans )
				: __( 'You have reached the maximum number of saved protocols. Delete a protocol to save a new one.' );
		case 'arp_payload_too_large':
			return __( 'This protocol is too large to save. Remove some items and try again.' );
		case 'arp_not_found':
			return __( 'This protocol no longer exists.' );
		case 'arp_feature_disabled':
			return __( 'Saving protocols to your account is currently not available.' );
		default:
			return error && error.message ? error.message : __( 'The protocol could not be saved. Please try again.' );
	}
}

/**
 * Normalized response of POST /store-protocols and PUT /store-protocols/{id} (CHANGE-1.7.0 §4.6).
 *
 * @param {*} raw Response.
 * @return {{id: string, name: string, created: boolean, enabled: boolean, visible: boolean, adminUrl: string, updatedAt: string}|null}
 *   Result, or null when the response is not one.
 */
export function normalizePublishResult( raw ) {
	const data = raw && typeof raw === 'object' && ! Array.isArray( raw ) ? raw : {};
	const id = storeProtocolId( data.id );
	const name = typeof data.name === 'string' ? data.name.trim() : '';
	if ( id === null || name === '' ) {
		return null;
	}
	return {
		id,
		name,
		created: data.created === true,
		enabled: data.enabled === true,
		visible: data.visible === true,
		adminUrl: typeof data.admin_url === 'string' && /^https?:\/\//i.test( data.admin_url ) ? data.admin_url : '',
		updatedAt: typeof data.updated_at === 'string' ? data.updated_at : '',
	};
}

/**
 * Result message of a publish (CHANGE-1.7.0 §6.10): created (saved switched off), updated and shown
 * to customers, or updated but not shown at the moment.
 *
 * @param {Object} result normalizePublishResult() result.
 * @return {string} Message.
 */
export function publishMessage( result ) {
	if ( result.created ) {
		/* translators: %s: pre-built protocol name. */
		return sprintf( __( 'Saved as the pre-built protocol "%s". Customers do not see it until you switch it on in the admin.' ), result.name );
	}
	return result.visible
		? sprintf( /* translators: %s: pre-built protocol name. */ __( 'The pre-built protocol "%s" was updated. Customers see the new values.' ), result.name )
		: sprintf( /* translators: %s: pre-built protocol name. */ __( 'The pre-built protocol "%s" was updated. Customers do not see it at the moment; the admin shows why.' ), result.name );
}

/**
 * Error message of a failed publish: the first field message the server sent (validation), else the
 * server's message (e.g. another manager changed the store protocol meanwhile), else a generic one.
 *
 * @param {*} error ApiError (or any error).
 * @return {string} Message.
 */
export function publishErrorMessage( error ) {
	const errors = error && error.data && Array.isArray( error.data.errors ) ? error.data.errors : [];
	const first = errors.find( ( entry ) => entry && typeof entry.message === 'string' && entry.message.trim() !== '' );
	if ( first ) {
		return first.message.trim();
	}
	if ( error && typeof error.code === 'string' && error.code !== 'bad_response' && typeof error.message === 'string' && error.message !== '' ) {
		return error.message;
	}
	return __( 'The pre-built protocol could not be published. Please try again.' );
}

/**
 * Message for a plan file import error code.
 *
 * @param {string} code Code from parsePlanFile().
 * @param {number} max  Maximum lines.
 * @return {string} Message.
 */
function importMessage( code, max ) {
	switch ( code ) {
		case 'too_large':
			return __( 'The file is larger than 64 KB and cannot be imported.' );
		case 'invalid_json':
			return __( 'The file is not a valid protocol file.' );
		case 'wrong_schema':
			return __( 'This is not an Atlas research protocol file (or it was created by a newer version).' );
		case 'too_many_lines':
			/* translators: %d: maximum number of items. */
			return sprintf( __( 'The protocol has more than %d items.' ), max );
		default:
			return __( 'The protocol file contains invalid data and was not imported.' );
	}
}

/**
 * Opens the Plans dialog.
 *
 * Every control carries a stable `data-focus-key` (action + draft ID / plan UUID), so after an
 * action re-renders the dialog, focus returns to the same control — or, when it no longer exists
 * (a deleted row), to the in-dialog status message — and never falls back to <body>. Results are
 * reported in that message (page toasts sit behind the modal and are not announced); its status and
 * alert regions persist across re-renders, so each result is announced once (live-message.js), and
 * a new action clears the previous result first.
 *
 * @param {Object} ctx Context from app.js: api, drafts, locale, maxLines, maxPlans, features, urls,
 *                     loggedIn, getPlan(), getMeta(), lineCount(), loadPlan( plan, meta ), resetPlan(),
 *                     setMeta( meta ), toast( message, tone ), clearLocal(); for store managers
 *                     canPublish, getStoreOrigin(), publishStoreProtocol( { create, id, name } ).
 */
export function openPlansDialog( ctx ) {
	const state = { accountStatus: 'idle', accountPlans: [], accountError: '', message: null, consentRequired: false, busy: false, reloading: false, conflict: false, publishLink: '' };
	const consentId = uid( 'consent' );
	const fileId = uid( 'plan-file' );
	const publishEmptyId = uid( 'publish-empty' );
	const live = createLiveMessage();
	const body = h( 'div', { class: 'arp-plans__body' } );
	const root = h( 'div', { class: 'arp-plans' }, live.el, body );
	let dialog = null;

	const accountEnabled = () => !! ( ctx.features.account_plans && ctx.loggedIn );
	/**
	 * Stored account plans stay under the customer's control while the merchant has turned saved
	 * plans off: they can still be listed, opened (as a copy on this device) and deleted.
	 */
	const accountManageOnly = () => !! ctx.loggedIn && ! accountEnabled();
	const untitled = () => __( 'Untitled research protocol' );

	const setMessage = ( text, tone = 'info' ) => {
		state.message = text ? { text, tone } : null;
		refresh();
	};

	const confirmReplace = async () => {
		if ( ctx.lineCount() === 0 ) {
			return true;
		}
		return confirmDialog( {
			title: __( 'Replace the current workspace?' ),
			message: __( 'The protocol you are working on will be replaced. Save it first if you want to keep it.' ),
			confirmLabel: __( 'Replace' ),
		} );
	};

	/* ------------------------------------------------------------ Account plans. */

	/**
	 * Loads the account plan list. A list already shown stays in place while it reloads (so the
	 * focused row button is not replaced by a loading message).
	 */
	const loadAccountPlans = async () => {
		if ( ! ctx.loggedIn ) {
			return;
		}
		if ( state.accountStatus === 'ready' ) {
			state.reloading = true;
		} else {
			state.accountStatus = 'loading';
		}
		refresh();
		try {
			const data = await ctx.api.listPlans();
			const list = Array.isArray( data ) ? data : ( data && Array.isArray( data.items ) ? data.items : [] );
			state.accountPlans = list.map( normalizeAccountPlan ).filter( Boolean );
			state.accountStatus = 'ready';
		} catch ( e ) {
			state.accountStatus = 'error';
			state.accountError = e.message;
		}
		state.reloading = false;
		refresh();
	};

	/**
	 * POST /plans. Consent is sent only when the visitor gave it in this dialog; when the server
	 * answers 403 arp_consent_required (no consent on record), a consent dialog is shown and the
	 * save is retried once with consent: true.
	 *
	 * @param {Object}  body    { title, plan }.
	 * @param {boolean} consent Consent given in the dialog.
	 * @return {Promise<Object>} Created plan.
	 */
	const createWithConsent = async ( body, consent ) => {
		try {
			return await ctx.api.createPlan( { ...body, consent } );
		} catch ( e ) {
			if ( consent || ! e || e.code !== 'arp_consent_required' ) {
				throw e;
			}
			const ok = await confirmDialog( {
				title: __( 'Store this protocol in your account?' ),
				message: __( 'Store this research protocol in my account. I can delete it at any time.' ),
				confirmLabel: __( 'Save to my account' ),
			} );
			if ( ! ok ) {
				throw e;
			}
			return ctx.api.createPlan( { ...body, consent: true } );
		}
	};

	const saveToAccount = async ( asNew ) => {
		if ( state.busy ) {
			return;
		}
		const meta = ctx.getMeta();
		const plan = ctx.getPlan();
		const title = plan.title.trim() !== '' ? plan.title : untitled();
		const needsConsent = asNew || meta.kind !== 'account';
		const consentBox = root.querySelector( '#' + consentId );
		const consentGiven = !! ( consentBox && consentBox.checked );
		if ( needsConsent && ( state.consentRequired || state.accountPlans.length === 0 ) && ! consentGiven ) {
			state.consentRequired = true;
			setMessage( __( 'Please tick the consent box to store this protocol in your account.' ), 'error' );
			const box = root.querySelector( '#' + consentId );
			if ( box ) {
				box.focus();
			}
			return;
		}
		state.busy = true;
		state.message = null;
		refresh();
		try {
			let record;
			if ( ! needsConsent ) {
				record = normalizeAccountPlan( await ctx.api.updatePlan( meta.uuid, { title, plan: { ...plan, title }, if_unmodified_since: meta.updated_at || undefined } ) );
			} else {
				record = normalizeAccountPlan( await createWithConsent( { title, plan: { ...plan, title } }, consentGiven ) );
			}
			if ( record ) {
				ctx.setMeta( { kind: 'account', uuid: record.uuid, updated_at: record.updated_at, title: record.title } );
			}
			state.busy = false;
			state.consentRequired = false;
			state.conflict = false;
			setMessage( __( 'Saved to your account.' ), 'success' );
			loadAccountPlans();
		} catch ( e ) {
			state.busy = false;
			if ( e.code === 'arp_consent_required' ) {
				state.consentRequired = true;
			}
			state.conflict = e.code === 'arp_conflict';
			setMessage( planErrorMessage( e, { maxPlans: ctx.maxPlans } ), 'error' );
		}
	};

	const openAccountPlan = async ( item ) => {
		if ( ! ( await confirmReplace() ) ) {
			return;
		}
		try {
			const record = normalizeAccountPlan( await ctx.api.getPlan( item.uuid ) );
			if ( ! record || ! record.plan ) {
				throw new Error( __( 'The protocol could not be opened.' ) );
			}
			// While saving to the account is turned off, the plan is opened as a copy on this device
			// (it cannot be saved back, so the workspace must not claim to be linked to it).
			const meta = accountEnabled() ? { kind: 'account', uuid: record.uuid, updated_at: record.updated_at, title: record.title } : { kind: 'local' };
			ctx.loadPlan( { ...record.plan, title: record.title || record.plan.title }, meta );
			dialog.close( 'opened' );
		} catch ( e ) {
			setMessage( e.code ? planErrorMessage( e ) : e.message, 'error' );
		}
	};

	/**
	 * Runs an account action, reports its result in the dialog and reloads the list.
	 *
	 * @param {Function} fn      async () => void.
	 * @param {string}   success Success message.
	 */
	const accountAction = async ( fn, success ) => {
		state.message = null;
		refresh();
		try {
			await fn();
			if ( success ) {
				state.message = { text: success, tone: 'success' };
			}
			loadAccountPlans();
		} catch ( e ) {
			setMessage( planErrorMessage( e, { maxPlans: ctx.maxPlans } ), 'error' );
		}
	};

	/** Withdraws the consent and deletes every plan saved in the account (after confirmation). */
	const withdrawConsent = async () => {
		const ok = await confirmDialog( {
			title: __( 'Withdraw consent and delete all saved protocols?' ),
			message: __( 'Every protocol saved in your account and all of their share links will be deleted, and your consent to store protocols will be withdrawn. Protocols saved on this device are not affected. This cannot be undone.' ),
			confirmLabel: __( 'Withdraw and delete' ),
			danger: true,
		} );
		if ( ! ok ) {
			return;
		}
		state.message = null;
		refresh();
		try {
			const data = await ctx.api.withdrawConsent();
			const meta = ctx.getMeta();
			if ( meta.kind === 'account' ) {
				// The workspace keeps its lines; it is no longer linked to a saved plan.
				ctx.setMeta( { kind: 'local' } );
			}
			state.accountPlans = [];
			state.consentRequired = true;
			state.conflict = false;
			// DELETE /plans/consent answers { deleted_plans, deleted_shares }.
			const deleted = data && Number.isInteger( data.deleted_plans ) ? data.deleted_plans : null;
			state.message = {
				tone: 'success',
				text:
					deleted === null
						? __( 'Your consent was withdrawn and your saved protocols were deleted.' )
						: sprintf(
							/* translators: %d: number of deleted plans. */
							_n( 'Your consent was withdrawn and %d saved protocol was deleted.', 'Your consent was withdrawn and %d saved protocols were deleted.', deleted ),
							deleted
						),
			};
			refresh();
			loadAccountPlans();
		} catch ( e ) {
			setMessage( e && e.message ? e.message : __( 'Your consent could not be withdrawn. Please try again.' ), 'error' );
		}
	};

	/* ------------------------------------------------------------ Drafts. */

	const saveDraft = () => {
		const meta = ctx.getMeta();
		const plan = ctx.getPlan();
		const result = ctx.drafts.save( { id: meta.kind === 'draft' ? meta.draftId : undefined, title: plan.title || untitled(), plan } );
		if ( ! result.ok ) {
			if ( result.code === 'limit' ) {
				setMessage( __( 'You can keep up to 20 protocols on this device. Delete one to save another.' ), 'error' );
			} else {
				setMessage( __( 'Your browser storage is full or unavailable, so the protocol could not be saved on this device.' ), 'error' );
			}
			return;
		}
		ctx.setMeta( { kind: 'draft', draftId: result.draft.id } );
		setMessage( __( 'Saved on this device.' ), 'success' );
	};

	/* ------------------------------------------------------------ File import/export. */

	const exportFile = () => {
		const plan = ctx.getPlan();
		const blob = new Blob( [ JSON.stringify( plan, null, 2 ) ], { type: 'application/json' } );
		downloadBlob( blob, 'research-protocol-' + new Date().toISOString().slice( 0, 10 ) + '.json' );
		setMessage( __( 'Protocol file downloaded. It contains the values you entered; store it safely.' ), 'success' );
	};

	const importFile = async ( file ) => {
		if ( ! file ) {
			return;
		}
		if ( file.size > MAX_PLAN_BYTES ) {
			setMessage( importMessage( 'too_large', ctx.maxLines ), 'error' );
			return;
		}
		let text;
		try {
			text = await file.text();
		} catch ( e ) {
			setMessage( importMessage( 'invalid_json', ctx.maxLines ), 'error' );
			return;
		}
		const parsed = parsePlanFile( text, ctx.maxLines );
		if ( ! parsed.ok ) {
			setMessage( importMessage( parsed.code, ctx.maxLines ), 'error' );
			return;
		}
		if ( ! ( await confirmReplace() ) ) {
			return;
		}
		ctx.loadPlan( parsed.plan, { kind: 'local' } );
		ctx.toast( __( 'Protocol imported.' ), 'success' );
		dialog.close( 'imported' );
	};

	/* ------------------------------------------------------------ Store protocol (managers). */

	/**
	 * "Publish as pre-built protocol" (CHANGE-1.7.0 §6.10): a stacked dialog. When the newest store
	 * protocol of the workspace's origin has a known `updated_at` (opened with "Edit in builder" or
	 * published from this workspace), it offers "Update "…"" (default) or a new store protocol;
	 * otherwise only a new one (a workspace filled with "Use this protocol" cannot update safely).
	 * The result is reported in this dialog's message region.
	 */
	const openPublishDialog = () => {
		if ( ctx.lineCount() === 0 ) {
			return;
		}
		const origin = typeof ctx.getStoreOrigin === 'function' ? ctx.getStoreOrigin() : null;
		const protocols = origin && Array.isArray( origin.protocols ) ? origin.protocols : [];
		const newest = protocols.length > 0 ? protocols[ protocols.length - 1 ] : null;
		const canUpdate = !! newest && typeof newest.updatedAt === 'string' && newest.updatedAt !== '';
		const modeName = uid( 'publish-mode' );
		const nameId = uid( 'publish-name' );
		const helpId = uid( 'publish-help' );
		const errorId = uid( 'publish-error' );
		const title = String( ctx.getPlan().title || '' ).trim();
		const input = h( 'input', {
			id: nameId,
			class: 'arp-input',
			type: 'text',
			maxlength: String( STORE_PROTOCOL_NAME_MAX ),
			autocomplete: 'off',
			'aria-required': 'true',
			'aria-describedby': helpId,
			value: Array.from( title ).slice( 0, STORE_PROTOCOL_NAME_MAX ).join( '' ),
		} );
		const error = h( 'p', { class: 'arp-field__error', id: errorId, hidden: true } );
		const nameField = h( 'div', { class: 'arp-field arp-publish__name', hidden: canUpdate }, h( 'label', { class: 'arp-label', for: nameId }, __( 'Pre-built protocol name' ) ), input, error );
		const updateRadio = canUpdate ? h( 'input', { type: 'radio', name: modeName, value: 'update', checked: true } ) : null;
		const createRadio = canUpdate ? h( 'input', { type: 'radio', name: modeName, value: 'create', checked: false } ) : null;
		const syncMode = () => {
			nameField.hidden = !! updateRadio && updateRadio.checked;
		};
		const modes = canUpdate
			? h(
				'fieldset',
				{ class: 'arp-fieldset arp-publish__modes' },
				h( 'legend', { class: 'arp-sr-only' }, __( 'Publish as pre-built protocol' ) ),
				h( 'label', { class: 'arp-radio' }, updateRadio, h( 'span', null, withMerchant( /* translators: %s: name of the pre-built protocol the workspace was opened from. */ __( 'Update "%s"' ), [ { text: newest.name, merchant: true } ] ) ) ),
				h( 'label', { class: 'arp-radio' }, createRadio, h( 'span', null, __( 'Create a new pre-built protocol' ) ) )
			)
			: null;
		if ( canUpdate ) {
			updateRadio.addEventListener( 'change', syncMode );
			createRadio.addEventListener( 'change', syncMode );
		}
		const clearError = () => {
			if ( ! error.hidden ) {
				error.hidden = true;
				error.textContent = '';
				input.removeAttribute( 'aria-invalid' );
				input.setAttribute( 'aria-describedby', helpId );
			}
		};
		input.addEventListener( 'input', clearError );

		let busy = false;
		let dlg = null;
		const submit = async () => {
			if ( busy ) {
				return;
			}
			const create = ! updateRadio || ! updateRadio.checked;
			const name = input.value.trim();
			if ( create && name === '' ) {
				error.textContent = __( 'Enter a name for the pre-built protocol.' );
				error.hidden = false;
				input.setAttribute( 'aria-invalid', 'true' );
				input.setAttribute( 'aria-describedby', errorId + ' ' + helpId );
				input.focus();
				return;
			}
			busy = true;
			// aria-busy (never disabled): the focused button keeps focus while the request runs.
			publishButton.setAttribute( 'aria-busy', 'true' );
			state.publishLink = '';
			let message;
			let tone = 'success';
			let link = '';
			try {
				const result = await ctx.publishStoreProtocol( create ? { create: true, id: null, name } : { create: false, id: newest.id, name: newest.name } );
				message = publishMessage( result );
				link = result.created ? result.adminUrl : '';
			} catch ( e ) {
				message = publishErrorMessage( e );
				tone = 'error';
			}
			busy = false;
			publishButton.removeAttribute( 'aria-busy' );
			state.publishLink = link;
			dlg.close( 'published' );
			setMessage( message, tone );
		};
		const publishButton = button( { label: __( 'Publish' ), variant: 'primary', cls: 'arp-publish__submit', onClick: () => submit() } );
		const form = h(
			'form',
			{
				class: 'arp-publish',
				onSubmit: ( event ) => {
					event.preventDefault();
					submit();
				},
			},
			modes,
			nameField,
			h( 'p', { class: 'arp-field__help', id: helpId }, __( 'New pre-built protocols are saved switched off. Add the group, description and notes and switch it on under WooCommerce › Atlas Research Planner › Pre-built protocols.' ) )
		);
		dlg = openDialog( {
			title: __( 'Publish as pre-built protocol' ),
			size: 'sm',
			content: form,
			// The dialog below may have re-rendered meanwhile: return to its current Publish button.
			returnFocus: () => root.querySelector( '[data-focus-key="publish"]' ),
			actions: ( d ) => [ publishButton, button( { label: __( 'Cancel' ), cls: 'arp-publish__cancel', onClick: () => d.close( null ) } ) ],
		} );
	};

	/* ------------------------------------------------------------ Rendering. */

	const list = ( items, empty, renderItem ) =>
		items.length === 0 ? h( 'p', { class: 'arp-plans__empty' }, empty ) : h( 'ul', { class: 'arp-plans__list' }, items.map( renderItem ) );

	/**
	 * One plan row. Its buttons are described by the plan name ("Delete, button, Q4 inventory").
	 *
	 * @param {string}   key       Row key (draft:ID or account:UUID).
	 * @param {string}   titleText Plan name.
	 * @param {string}   metaText  Line count and date.
	 * @param {boolean}  current   The workspace is this plan.
	 * @param {Array}    actions   [ [ action, label, onClick, variant ] ].
	 * @return {HTMLElement} Row.
	 */
	const itemRow = ( key, titleText, metaText, current, actions ) => {
		const nameId = uid( 'plan-name' );
		return h(
			'li',
			{ class: [ 'arp-plans__item', current ? 'is-current' : '' ] },
			h(
				'div',
				{ class: 'arp-plans__info' },
				h( 'p', { class: 'arp-plans__name' }, h( 'span', { id: nameId }, titleText || untitled() ), current ? h( 'span', { class: 'arp-badge arp-badge--primary' }, __( 'Current' ) ) : null ),
				h( 'p', { class: 'arp-plans__meta' }, metaText )
			),
			h(
				'div',
				{ class: 'arp-plans__actions' },
				actions.map( ( [ action, label, onClick, variant ] ) =>
					button( {
						label,
						size: 'sm',
						variant: variant || 'ghost',
						cls: action === 'delete' ? 'arp-btn--danger-ghost' : '',
						attrs: { 'aria-describedby': nameId, 'data-focus-key': key + ':' + action },
						onClick,
					} )
				)
			)
		);
	};

	function refresh() {
		const meta = ctx.getMeta();
		const drafts = ctx.drafts.list();
		const lines = ( n ) => sprintf( /* translators: %d: number of items. */ _n( '%d item', '%d items', n ), n );
		const busyAttr = state.busy ? 'true' : null;

		const current = dialogSection(
			__( 'Current protocol' ),
			h(
				'div',
				{ class: 'arp-plans__buttons' },
				button( { label: meta.kind === 'draft' ? __( 'Update device copy' ) : __( 'Save on this device' ), iconName: 'download', onClick: saveDraft, attrs: { 'data-focus-key': 'device-save' } } ),
				accountEnabled()
					? button( {
						label: meta.kind === 'account' ? __( 'Save changes to account' ) : __( 'Save to my account' ),
						iconName: 'check',
						variant: 'primary',
						// aria-disabled (not disabled) while saving: disabling the focused button would drop focus.
						attrs: { 'aria-disabled': busyAttr, 'data-focus-key': 'account-save' },
						onClick: () => saveToAccount( false ),
					} )
					: null,
				accountEnabled() && meta.kind === 'account' ? button( { label: __( 'Save as new protocol' ), onClick: () => saveToAccount( true ), attrs: { 'aria-disabled': busyAttr, 'data-focus-key': 'account-save-new' } } ) : null,
				button( {
					label: __( 'New protocol' ),
					iconName: 'plus',
					variant: 'ghost',
					attrs: { 'data-focus-key': 'new-plan' },
					onClick: async () => {
						if ( await confirmReplace() ) {
							ctx.resetPlan();
							dialog.close( 'new' );
						}
					},
				} )
			),
			accountEnabled() && ( state.consentRequired || ( state.accountStatus === 'ready' && state.accountPlans.length === 0 && meta.kind !== 'account' ) )
				? h(
					'label',
					{ class: 'arp-check' },
					h( 'input', { type: 'checkbox', id: consentId } ),
					h( 'span', null, __( 'Store this research protocol in my account. I can delete it at any time.' ) )
				)
				: null,
			state.conflict && meta.kind === 'account'
				? h(
					'div',
					{ class: 'arp-plans__buttons' },
					button( { label: __( 'Open saved version' ), size: 'sm', attrs: { 'data-focus-key': 'conflict-open' }, onClick: () => openAccountPlan( { uuid: meta.uuid } ) } ),
					button( { label: __( 'Save as new protocol' ), size: 'sm', attrs: { 'data-focus-key': 'conflict-save-new' }, onClick: () => saveToAccount( true ) } )
				)
				: null
		);

		const noItems = ctx.lineCount() === 0;
		const publish = ctx.canPublish
			? dialogSection(
				__( 'Pre-built protocol' ),
				h(
					'div',
					{ class: 'arp-plans__buttons' },
					button( {
						label: __( 'Publish as pre-built protocol' ),
						// aria-disabled (not disabled) and described by the reason while there is nothing to publish.
						attrs: { 'data-focus-key': 'publish', 'aria-haspopup': 'dialog', 'aria-disabled': noItems ? 'true' : null, 'aria-describedby': noItems ? publishEmptyId : null },
						onClick: openPublishDialog,
					} )
				),
				noItems ? h( 'p', { class: 'arp-field__help', id: publishEmptyId }, __( 'Add at least one item before you publish.' ) ) : null,
				state.publishLink !== '' ? h( 'p', { class: 'arp-plans__publish-link' }, h( 'a', { href: state.publishLink, class: 'arp-link' }, __( 'Open in the admin' ) ) ) : null
			)
			: null;

		const device = dialogSection(
			__( 'Saved on this device' ),
			! ctx.drafts.available ? h( 'p', { class: 'arp-notice arp-notice--warning' }, __( 'Browser storage is unavailable (for example in private browsing), so protocols cannot be kept on this device.' ) ) : null,
			list( drafts, __( 'No protocols saved on this device yet.' ), ( draft ) =>
				itemRow( 'draft:' + draft.id, draft.title, [ lines( draft.line_count ), shortDate( draft.updated_at, ctx.locale ) ].filter( Boolean ).join( ' · ' ), meta.kind === 'draft' && meta.draftId === draft.id, [
					[
						'open',
						__( 'Open' ),
						async () => {
							const record = ctx.drafts.get( draft.id );
							if ( record && ( await confirmReplace() ) ) {
								ctx.loadPlan( { ...record.plan, title: record.title }, { kind: 'draft', draftId: draft.id } );
								dialog.close( 'opened' );
							}
						},
						'secondary',
					],
					[
						'rename',
						__( 'Rename' ),
						async () => {
							const name = await promptDialog( { title: __( 'Rename protocol' ), label: __( 'Protocol name' ), value: draft.title, maxLength: MAX_TITLE_LENGTH } );
							if ( name ) {
								ctx.drafts.rename( draft.id, name );
								setMessage( __( 'Protocol renamed.' ), 'success' );
							}
						},
					],
					[
						'duplicate',
						__( 'Duplicate' ),
						() => {
							/* translators: %s: title of the plan that is copied. */
							const result = ctx.drafts.duplicate( draft.id, ( title ) => sprintf( __( '%s (copy)' ), title ) );
							if ( ! result.ok ) {
								setMessage( result.code === 'limit' ? __( 'You can keep up to 20 protocols on this device. Delete one to save another.' ) : __( 'The protocol could not be duplicated.' ), 'error' );
								return;
							}
							setMessage( __( 'Protocol duplicated.' ), 'success' );
						},
					],
					[
						'delete',
						__( 'Delete' ),
						async () => {
							const ok = await confirmDialog( {
								title: __( 'Delete this protocol?' ),
								/* translators: %s: plan name. */
								message: sprintf( __( '"%s" will be removed from this device. This cannot be undone.' ), draft.title || untitled() ),
								confirmLabel: __( 'Delete' ),
								danger: true,
							} );
							if ( ok ) {
								ctx.drafts.remove( draft.id );
								const m = ctx.getMeta();
								if ( m.kind === 'draft' && m.draftId === draft.id ) {
									ctx.setMeta( { kind: 'local' } );
								}
								setMessage( __( 'Protocol deleted.' ), 'success' );
							}
						},
					],
				] )
			)
		);

		let account = null;
		const manageOnly = accountManageOnly();
		if ( accountEnabled() || ( manageOnly && state.accountStatus === 'ready' && state.accountPlans.length > 0 ) ) {
			let body;
			if ( state.accountStatus === 'loading' || state.accountStatus === 'idle' ) {
				body = h( 'p', { class: 'arp-plans__empty', role: 'status' }, __( 'Loading your saved protocols…' ) );
			} else if ( state.accountStatus === 'error' ) {
				body = h( 'div', { class: 'arp-notice arp-notice--error' }, h( 'p', null, state.accountError || __( 'Your saved protocols could not be loaded.' ) ), button( { label: __( 'Try again' ), size: 'sm', attrs: { 'data-focus-key': 'account-retry' }, onClick: loadAccountPlans } ) );
			} else {
				body = list( state.accountPlans, __( 'No protocols saved in your account yet.' ), ( item ) =>
					itemRow( 'account:' + item.uuid, item.title, [ lines( item.line_count ), shortDate( item.updated_at, ctx.locale ) ].filter( Boolean ).join( ' · ' ), meta.kind === 'account' && meta.uuid === item.uuid, [
						[ 'open', __( 'Open' ), () => openAccountPlan( item ), 'secondary' ],
						manageOnly ? null : [
							'rename',
							__( 'Rename' ),
							async () => {
								const name = await promptDialog( { title: __( 'Rename protocol' ), label: __( 'Protocol name' ), value: item.title, maxLength: MAX_TITLE_LENGTH } );
								if ( name ) {
									accountAction( async () => {
										const record = normalizeAccountPlan( await ctx.api.updatePlan( item.uuid, { title: name } ) );
										const m = ctx.getMeta();
										if ( record && m.kind === 'account' && m.uuid === item.uuid ) {
											ctx.setMeta( { ...m, updated_at: record.updated_at, title: record.title } );
										}
									}, __( 'Protocol renamed.' ) );
								}
							},
						],
						manageOnly ? null : [ 'duplicate', __( 'Duplicate' ), () => accountAction( () => ctx.api.duplicatePlan( item.uuid ), __( 'Protocol duplicated.' ) ) ],
						[
							'delete',
							__( 'Delete' ),
							async () => {
								const ok = await confirmDialog( {
									title: __( 'Delete this saved protocol?' ),
									/* translators: %s: plan name. */
									message: sprintf( __( '"%s" and all of its share links will be deleted from your account. This cannot be undone.' ), item.title || untitled() ),
									confirmLabel: __( 'Delete' ),
									danger: true,
								} );
								if ( ok ) {
									accountAction( async () => {
										await ctx.api.deletePlan( item.uuid );
										const m = ctx.getMeta();
										if ( m.kind === 'account' && m.uuid === item.uuid ) {
											ctx.setMeta( { kind: 'local' } );
										}
									}, __( 'Protocol deleted.' ) );
								}
							},
						],
					].filter( Boolean ) )
				);
			}
			account = dialogSection(
				__( 'Saved in your account' ),
				manageOnly
					? h( 'p', { class: 'arp-field__help' }, __( 'Saving protocols to your account is currently turned off. You can still open a copy of the protocols you saved earlier or delete them.' ) )
					: null,
				state.reloading ? h( 'p', { class: 'arp-plans__updating' }, __( 'Updating your saved protocols…' ) ) : null,
				body
			);
		} else if ( ctx.features.account_plans_enabled && ! ctx.loggedIn && ctx.urls.login ) {
			account = dialogSection(
				__( 'Saved in your account' ),
				h( 'p', null, h( 'a', { href: ctx.urls.login, class: 'arp-link' }, __( 'Sign in to save protocols to your account' ) ) )
			);
		}

		const fileInput = h( 'input', {
			id: fileId,
			type: 'file',
			accept: '.json,application/json',
			class: 'arp-sr-only',
			tabindex: '-1',
			// Operated through the visible "Import plan file" button; hidden from assistive
			// technology so it is not announced as a second, unlabelled control.
			'aria-hidden': 'true',
			'aria-label': __( 'Import protocol file' ),
			onChange: ( event ) => importFile( event.target.files && event.target.files[ 0 ] ),
		} );
		const files = dialogSection(
			__( 'Protocol file' ),
			h( 'p', { class: 'arp-field__help' }, __( 'Move a protocol between devices with a .json file (up to 64 KB).' ) ),
			h(
				'div',
				{ class: 'arp-plans__buttons' },
				button( { label: __( 'Import protocol file' ), iconName: 'file', attrs: { 'data-focus-key': 'file-import' }, onClick: () => fileInput.click() } ),
				button( { label: __( 'Export protocol file' ), iconName: 'download', attrs: { 'data-focus-key': 'file-export' }, onClick: exportFile } ),
				fileInput
			)
		);

		const privacy = dialogSection(
			__( 'Privacy' ),
			h( 'p', { class: 'arp-field__help' }, __( 'Your workspace and device protocols are stored only in this browser. They are never sent to the store unless you save a protocol to your account.' ) ),
			button( {
				label: __( 'Clear local data' ),
				variant: 'ghost',
				cls: 'arp-btn--danger-ghost',
				attrs: { 'data-focus-key': 'clear-local' },
				onClick: async () => {
					const ok = await confirmDialog( {
						title: __( 'Clear local planner data?' ),
						message: __( 'All protocols saved on this device and the current workspace will be deleted from this browser. Protocols saved in your account are not affected.' ),
						confirmLabel: __( 'Clear data' ),
						danger: true,
					} );
					if ( ok ) {
						ctx.clearLocal();
						dialog.close( 'cleared' );
					}
				},
			} ),
			// Offered while saving to the account is on, or while plans saved earlier still exist (a
			// store that never offered saved plans has nothing to withdraw).
			ctx.loggedIn && ( accountEnabled() || ( state.accountStatus === 'ready' && state.accountPlans.length > 0 ) )
				? h(
					'div',
					{ class: 'arp-plans__consent' },
					h( 'p', { class: 'arp-field__help' }, __( 'Protocols are stored in your account only with your consent. You can withdraw it at any time: every protocol saved in your account and its share links are then deleted.' ) ),
					button( {
						label: __( 'Withdraw consent and delete all saved protocols' ),
						variant: 'ghost',
						cls: 'arp-btn--danger-ghost',
						attrs: { 'data-focus-key': 'withdraw-consent', 'aria-haspopup': 'dialog' },
						onClick: withdrawConsent,
					} )
				)
				: null
		);

		const focused = document.activeElement;
		const inside = !! ( focused && root.contains( focused ) );
		const focusKey = inside && focused.dataset ? focused.dataset.focusKey || '' : '';
		const focusId = inside && ! focusKey ? focused.id : '';
		// The message regions are never re-rendered: an unchanged result is not announced again.
		const messageEl = live.set( state.message );
		render( body, current, publish, device, account, files, privacy );
		if ( inside ) {
			// The re-render replaced the focused control: focus its successor with the same key (or ID),
			// else the result message, else the dialog — never <body>.
			let again = null;
			if ( focusKey ) {
				again = root.querySelector( '[data-focus-key="' + focusKey.replace( /["\\]/g, '\\$&' ) + '"]' );
			} else if ( focusId ) {
				again = root.querySelector( '#' + focusId );
			}
			if ( again && ! again.closest( '[hidden]' ) ) {
				again.focus();
			} else {
				focusElement( messageEl || root.closest( '.arp-dialog' ) || root, { preventScroll: true } );
			}
		}
	}

	refresh();
	dialog = openDialog( {
		title: __( 'My protocols' ),
		size: 'lg',
		content: root,
	} );
	loadAccountPlans();
}
