/**
 * Timeline (CHANGE-1.1.0 §9.5): an estimated inventory timeline, not a dosing schedule. One row per
 * product ("BPC-157 10 mg · 20 Oct → 15 Dec") with a gold bar split into numbered container blocks
 * on a shared weekly axis (dates when the protocol has a start date); a shortfall is red and
 * hatched and labelled (never colour alone). An equivalent data table is always available to
 * screen readers (visible with "Show as table"), and the "Research inventory review" dates are in a
 * collapsed "Show review dates" disclosure. Rows are keyed by line and redrawn only when their own
 * data changed (performance with long protocols).
 *
 * @module components/timeline
 */

import { h, s, uid, render, icon } from '../app/dom.js';
import { __, _n, sprintf } from '../app/i18n.js';
import { formatDate, formatNumber, formatPercent } from '../app/format.js';
import { periodStart, parseDate, daysFromCivil, addDays } from '../app/engine.js';
import { containerKind } from '../app/catalog.js';
import { unitName } from './explain.js';

const MAX_SEGMENTS = 200;
const MAX_TABLE_ROWS = 400;

/** Delay (ms) between an update and drawing it: keeps typing responsive and skips superseded previews. */
const RENDER_DELAY = 250;

/**
 * Label of period `index` (0-based) without a date.
 *
 * @param {string} unit  day | week | month.
 * @param {number} index Index.
 * @return {string} Label.
 */
export function periodLabel( unit, index ) {
	const n = String( index + 1 );
	switch ( unit ) {
		case 'day':
			/* translators: %s: 1-based day number or range. */
			return sprintf( __( 'Day %s' ), n );
		case 'month':
			/* translators: %s: 1-based month number or range. */
			return sprintf( __( 'Month %s' ), n );
		default:
			/* translators: %s: 1-based week number or range. */
			return sprintf( __( 'Week %s' ), n );
	}
}

/**
 * Label of a range of periods (1-based, inclusive), e.g. "Weeks 1–4" (translatable as a whole, so
 * every language can order the words and numbers its own way).
 *
 * @param {string} unit  day | week | month.
 * @param {number} first First index (0-based).
 * @param {number} last  Last index (0-based).
 * @return {string} Label.
 */
export function periodRangeLabel( unit, first, last ) {
	if ( last <= first ) {
		return periodLabel( unit, first );
	}
	const from = String( first + 1 );
	const to = String( last + 1 );
	switch ( unit ) {
		case 'day':
			/* translators: 1: first day number, 2: last day number. */
			return sprintf( __( 'Days %1$s–%2$s' ), from, to );
		case 'month':
			/* translators: 1: first month number, 2: last month number. */
			return sprintf( __( 'Months %1$s–%2$s' ), from, to );
		default:
			/* translators: 1: first week number, 2: last week number. */
			return sprintf( __( 'Weeks %1$s–%2$s' ), from, to );
	}
}

/**
 * Caption of the timeline for the formats shown.
 *
 * @param {string[]} formats Formats of the rows.
 * @return {string} Caption.
 */
export function timelineCaption( formats ) {
	const kinds = [ ...new Set( formats.map( containerKind ) ) ];
	switch ( kinds.length === 1 ? kinds[ 0 ] : '' ) {
		case 'vial':
			return __( 'Each block is one vial. Red means your vials run out before the protocol ends.' );
		case 'pen':
			return __( 'Each block is one pen. Red means your pens run out before the protocol ends.' );
		case 'bottle':
			return __( 'Each block is one bottle. Red means your bottles run out before the protocol ends.' );
		default:
			return __( 'Each block is one container. Red means the supply runs out before the protocol ends.' );
	}
}

/**
 * Label of a review event type.
 *
 * @param {string} type start | container_depleted | run_out | end.
 * @return {string} Label.
 */
function reviewTypeLabel( type ) {
	switch ( type ) {
		case 'start':
			return __( 'start of the protocol' );
		case 'container_depleted':
			return __( 'a container is estimated to be used up' );
		case 'run_out':
			return __( 'estimated run-out' );
		default:
			return __( 'last day of the protocol' );
	}
}

/**
 * Status label of a timeline point.
 *
 * @param {string} status ok | depleted | short.
 * @return {string} Label.
 */
function statusLabel( status ) {
	if ( status === 'short' ) {
		return __( 'Shortfall' );
	}
	if ( status === 'depleted' ) {
		return __( 'Used up' );
	}
	return __( 'Enough' );
}

/**
 * Days since 1970-01-01 of a Y-m-d (null when invalid).
 *
 * @param {string|null} ymd Date.
 * @return {number|null} Days.
 */
function dayOf( ymd ) {
	const p = parseDate( ymd );
	return p === null ? null : daysFromCivil( p[ 0 ], p[ 1 ], p[ 2 ] );
}

/**
 * Shared axis of the rows: days from the earliest start to the latest end when every row is dated
 * and weekly, weeks from 0 when every row is weekly without dates, else null (each row uses its
 * own periods, e.g. protocols saved with day or month periods).
 *
 * @param {Object[]} rows Rows { timeline }.
 * @return {{kind: string, start: number, end: number, startDate: string|null}|null} Axis.
 */
export function sharedAxis( rows ) {
	if ( rows.length === 0 || ! rows.every( ( row ) => row.timeline.period_unit === 'week' ) ) {
		return null;
	}
	const dated = rows.every( ( row ) => dayOf( row.timeline.start_date ) !== null && dayOf( row.timeline.end_date ) !== null );
	if ( dated ) {
		const starts = rows.map( ( row ) => dayOf( row.timeline.start_date ) );
		const ends = rows.map( ( row ) => dayOf( row.timeline.end_date ) );
		const start = Math.min( ...starts );
		const first = rows[ starts.indexOf( start ) ].timeline.start_date;
		return { kind: 'days', start, end: Math.max( ...ends ), startDate: first };
	}
	if ( rows.every( ( row ) => ! row.timeline.start_date ) ) {
		return { kind: 'weeks', start: 0, end: Math.max( ...rows.map( ( row ) => row.timeline.periods ) ) * 7, startDate: null };
	}
	return null;
}

/**
 * Where a row sits on the axis (in days from the axis start).
 *
 * @param {Object}      tl   Timeline.
 * @param {Object|null} axis Shared axis.
 * @return {{from: number, to: number, total: number}} Position (total = axis length in days, or the row's own periods).
 */
export function rowSpan( tl, axis ) {
	if ( axis && axis.kind === 'days' ) {
		return { from: dayOf( tl.start_date ) - axis.start, to: dayOf( tl.end_date ) - axis.start, total: Math.max( 1, axis.end - axis.start ) };
	}
	if ( axis && axis.kind === 'weeks' ) {
		return { from: 0, to: tl.periods * 7, total: Math.max( 1, axis.end ) };
	}
	return { from: 0, to: tl.periods, total: Math.max( 1, tl.periods ) };
}

/**
 * SVG chart of one row.
 *
 * @param {Object} row  { name, result, timeline }.
 * @param {Object} view Timeline view (width, axis, locale, currency).
 * @return {SVGElement} Chart.
 */
function chart( row, view ) {
	const r = row.result;
	const tl = row.timeline;
	const axis = view.axis;
	const eventCount = r.event_count || tl.periods * ( r.events_per_period || 1 );
	const covered = Math.min( r.events_covered ?? eventCount, eventCount );
	const span = rowSpan( tl, axis );
	const weeksOnAxis = axis ? span.total / 7 : tl.periods;
	// Fill the available width; very long protocols get a wider chart that scrolls inside its box.
	const width = Math.min( 2400, Math.max( view.width || 560, Math.ceil( weeksOnAxis ) * ( weeksOnAxis > 120 ? 6 : 22 ) ) );
	const height = 64;
	const pad = 8;
	const inner = width - pad * 2;
	const barY = 6;
	const barH = 28;
	const ax = ( day ) => pad + ( Math.min( Math.max( day, 0 ), span.total ) / span.total ) * inner;
	const rowStart = ax( span.from );
	const rowEnd = ax( span.to );
	const x = ( events ) => rowStart + ( Math.min( Math.max( events, 0 ), eventCount ) / eventCount ) * ( rowEnd - rowStart );
	const patternId = uid( 'hatch' );

	const nodes = [
		s(
			'defs',
			null,
			s( 'pattern', { id: patternId, width: '8', height: '8', patternUnits: 'userSpaceOnUse', patternTransform: 'rotate(45)' }, s( 'rect', { width: '8', height: '8', class: 'arp-tl__short-bg' } ), s( 'line', { x1: '0', y1: '0', x2: '0', y2: '8', class: 'arp-tl__short-line' } ) )
		),
		s( 'rect', { x: String( pad ), y: String( barY ), width: String( inner ), height: String( barH ), rx: '6', class: 'arp-tl__track' } ),
	];

	// Numbered container blocks up to the coverage.
	let previous = 0;
	let drawn = 0;
	const block = ( from, to, number ) => {
		const bx = x( from );
		const bw = Math.max( 1, x( to ) - bx );
		nodes.push( s( 'rect', { x: String( bx ), y: String( barY ), width: String( bw ), height: String( barH ), rx: '3', class: 'arp-tl__seg' } ) );
		if ( bw >= 18 ) {
			nodes.push( s( 'text', { x: String( bx + bw / 2 ), y: String( barY + barH / 2 + 4 ), class: 'arp-tl__num', 'text-anchor': 'middle' }, String( number ) ) );
		}
	};
	for ( const depletion of tl.depletions || [] ) {
		if ( previous >= covered || drawn >= MAX_SEGMENTS ) {
			break;
		}
		const end = Math.min( depletion.event, covered );
		block( previous, end, drawn + 1 );
		if ( depletion.event < eventCount && end < covered ) {
			nodes.push( s( 'line', { x1: String( x( end ) ), y1: String( barY ), x2: String( x( end ) ), y2: String( barY + barH ), class: 'arp-tl__sep' } ) );
		}
		previous = depletion.event;
		drawn++;
	}
	if ( previous < covered && drawn < MAX_SEGMENTS ) {
		block( previous, covered, drawn + 1 );
	}
	if ( tl.run_out && covered < eventCount ) {
		const sx = x( covered );
		const sw = Math.max( 2, x( eventCount ) - sx );
		nodes.push( s( 'rect', { x: String( sx ), y: String( barY ), width: String( sw ), height: String( barH ), fill: `url(#${ patternId })`, class: 'arp-tl__short' } ) );
		if ( sw > 70 ) {
			nodes.push( s( 'text', { x: String( sx + sw / 2 ), y: String( barY + barH / 2 + 4 ), class: 'arp-tl__short-text', 'text-anchor': 'middle' }, __( 'Shortfall' ) ) );
		}
		nodes.push( s( 'line', { x1: String( sx ), y1: String( barY - 4 ), x2: String( sx ), y2: String( barY + barH + 4 ), class: 'arp-tl__runout' } ) );
	}

	// Axis: weekly ticks (dates when dated).
	const ticks = [];
	if ( axis ) {
		const weeks = Math.max( 1, Math.round( span.total / 7 ) );
		const step = Math.max( 1, Math.ceil( weeks / Math.max( 2, Math.floor( width / 90 ) ) ) );
		for ( let w = 0; w <= weeks; w += step ) {
			const date = axis.kind === 'days' ? addDays( axis.startDate, w * 7 ) : null;
			ticks.push( { px: ax( w * 7 ), label: date ? formatDate( date, view.locale, { month: 'short', day: 'numeric' } ) : periodLabel( 'week', w ), last: w + step > weeks, first: w === 0 } );
		}
	} else {
		const periods = tl.periods;
		const step = Math.max( 1, Math.ceil( periods / 8 ) );
		for ( let i = 0; i <= periods; i += step ) {
			const date = tl.start_date ? periodStart( tl.start_date, tl.period_unit, i ) : null;
			ticks.push( { px: ax( i ), label: date ? formatDate( date, view.locale, { month: 'short', day: 'numeric' } ) : periodLabel( tl.period_unit, i ), last: i + step > periods, first: i === 0 } );
		}
	}
	ticks.forEach( ( tick ) => {
		nodes.push( s( 'line', { x1: String( tick.px ), y1: String( barY + barH + 2 ), x2: String( tick.px ), y2: String( barY + barH + 7 ), class: 'arp-tl__tick' } ) );
		if ( ! tick.last || tick.first ) {
			nodes.push( s( 'text', { x: String( tick.px ), y: String( height - 8 ), class: 'arp-tl__label', 'text-anchor': tick.first ? 'start' : 'middle' }, tick.label ) );
		}
	} );

	const summary = tl.run_out
		? sprintf(
			/* translators: 1: product, 2: uses covered, 3: total uses, 4: run-out date or period. */
			__( '%1$s: the quantity covers %2$s of %3$s uses; estimated run-out %4$s.' ),
			row.name,
			formatNumber( String( covered ), view.currency ),
			formatNumber( String( eventCount ), view.currency ),
			tl.run_out.date ? formatDate( tl.run_out.date, view.locale ) : periodLabel( tl.period_unit, tl.run_out.period_index )
		)
		: sprintf(
			/* translators: 1: product, 2: total uses. */
			__( '%1$s: the quantity covers all %2$s uses.' ),
			row.name,
			formatNumber( String( eventCount ), view.currency )
		);

	return s( 'svg', { class: 'arp-tl__svg', viewBox: `0 0 ${ width } ${ height }`, width: String( width ), height: String( height ), role: 'img', 'aria-label': summary }, ...nodes );
}

/**
 * Heading of a row: "BPC-157 — 10 MG · 20 Oct → 15 Dec" (or the duration without dates).
 *
 * @param {Object} row  Row.
 * @param {Object} view View.
 * @return {string} Heading.
 */
function rowHeading( row, view ) {
	const tl = row.timeline;
	if ( tl.start_date && tl.last_day ) {
		/* translators: 1: product, 2: first day, 3: last day. */
		return sprintf( __( '%1$s · %2$s → %3$s' ), row.name, formatDate( tl.start_date, view.locale, { day: 'numeric', month: 'short' } ), formatDate( tl.last_day, view.locale, { day: 'numeric', month: 'short' } ) );
	}
	if ( tl.period_unit === 'week' ) {
		/* translators: 1: product, 2: number of weeks. */
		return sprintf( _n( '%1$s · %2$s week', '%1$s · %2$s weeks', tl.periods ), row.name, formatNumber( String( tl.periods ), view.currency ) );
	}
	return row.name;
}

/**
 * Cell texts of the data table of one line: one entry per table row.
 *
 * @param {Object} row  Row.
 * @param {Object} view View.
 * @return {Array<{short: boolean, cells: string[]}>} Rows (first cell: the period label).
 */
function tableData( row, view ) {
	const tl = row.timeline;
	const unit = ( value ) => formatNumber( value, view.currency ) + ' ' + unitName( row.result.unit, value );
	return ( tl.points || [] ).slice( 0, MAX_TABLE_ROWS ).map( ( point ) => {
		const last = Math.min( point.index + ( tl.step || 1 ), tl.periods ) - 1;
		const cells = [ periodRangeLabel( tl.period_unit, point.index, last ) ];
		if ( tl.start_date ) {
			cells.push( point.date ? formatDate( point.date, view.locale ) : '' );
		}
		cells.push( unit( point.consumed ), unit( point.remaining ), formatPercent( point.remaining_percent, view.currency ), statusLabel( point.status ) );
		return { short: point.status === 'short', cells };
	} );
}

/**
 * Updates the texts of a table built for the same rows and columns in place (a new amount changes
 * only numbers; rebuilding hundreds of cells per keystroke is what made long protocols slow).
 *
 * @param {HTMLTableElement}                         tableEl Table.
 * @param {Array<{short: boolean, cells: string[]}>} data    Rows.
 */
function patchTable( tableEl, data ) {
	const rows = tableEl.tBodies[ 0 ].rows;
	data.forEach( ( rowData, i ) => {
		const tr = rows[ i ];
		tr.classList.toggle( 'is-short', rowData.short );
		rowData.cells.forEach( ( text, j ) => {
			const cell = tr.cells[ j ];
			if ( cell.textContent !== text ) {
				cell.textContent = text;
			}
		} );
	} );
}

/**
 * Data table of one line.
 *
 * @param {Object}                                   row  Row.
 * @param {Array<{short: boolean, cells: string[]}>} data Rows from tableData().
 * @return {HTMLElement} Table.
 */
function table( row, data ) {
	const tl = row.timeline;
	const rows = data.map( ( rowData ) => h( 'tr', { class: rowData.short ? 'is-short' : '' }, rowData.cells.map( ( text, j ) => ( j === 0 ? h( 'th', { scope: 'row' }, text ) : h( 'td', null, text ) ) ) ) );
	return h(
		'table',
		{ class: 'arp-table' },
		/* translators: %s: product name. */
		h( 'caption', null, sprintf( __( 'Estimated inventory per period: %s' ), row.name ) ),
		h(
			'thead',
			null,
			h(
				'tr',
				null,
				h( 'th', { scope: 'col' }, __( 'Period' ) ),
				tl.start_date ? h( 'th', { scope: 'col' }, __( 'Starts' ) ) : null,
				h( 'th', { scope: 'col' }, __( 'Used in period' ) ),
				h( 'th', { scope: 'col' }, __( 'Remaining at end' ) ),
				h( 'th', { scope: 'col' }, __( 'Remaining' ) ),
				h( 'th', { scope: 'col' }, __( 'Status' ) )
			)
		),
		h( 'tbody', null, rows )
	);
}

/**
 * Creates the timeline section.
 *
 * Rendering is deferred (RENDER_DELAY ms after the last update, so typing never waits for it and a
 * preview that the server result replaces moments later is usually never drawn) and incremental:
 * rows are keyed by line ID and a row's chart or table is rebuilt only when its own data changed.
 *
 * @return {{el: HTMLElement, update: Function, flush: Function}} Timeline.
 */
export function createTimeline() {
	const titleId = uid( 'tl-title' );
	let showTable = false;
	const toggle = h( 'button', { type: 'button', class: 'arp-btn arp-btn--secondary arp-btn--sm', 'aria-pressed': 'false' }, __( 'Show as table' ) );
	const body = h( 'div', { class: 'arp-tl__body' } );
	const empty = h( 'p', { class: 'arp-empty arp-empty--inline' }, __( 'Products with an amount per use, times per week and a duration appear here.' ) );
	const caption = h( 'p', { class: 'arp-tl__intro' } );
	const legend = h(
		'ul',
		{ class: 'arp-tl__legend', 'aria-label': __( 'Legend' ) },
		h( 'li', null, h( 'span', { class: 'arp-swatch arp-swatch--seg', 'aria-hidden': 'true' } ), __( 'Container in stock (numbered)' ) ),
		h( 'li', null, h( 'span', { class: 'arp-swatch arp-swatch--short', 'aria-hidden': 'true' } ), __( 'Shortfall (red, hatched)' ) )
	);
	const reviewsPanelId = uid( 'tl-reviews' );
	const reviewsToggle = h(
		'button',
		{ type: 'button', class: 'arp-disclosure', 'aria-expanded': 'false', 'aria-controls': reviewsPanelId },
		icon( 'chevron', 'arp-disclosure__icon' ),
		h( 'span', null, __( 'Show review dates' ) )
	);
	const reviewsPanel = h( 'div', { id: reviewsPanelId, class: 'arp-disclosure__panel', hidden: true } );
	const reviewsNote = h( 'p', { class: 'arp-tl__note', hidden: true } );
	const reviews = h( 'div', { class: 'arp-tl__reviews' }, reviewsNote, reviewsToggle, reviewsPanel );
	reviewsToggle.addEventListener( 'click', () => {
		const open = reviewsPanel.hidden;
		reviewsPanel.hidden = ! open;
		reviewsToggle.setAttribute( 'aria-expanded', open ? 'true' : 'false' );
	} );
	const el = h(
		'section',
		{ class: 'arp-card arp-tl', 'aria-labelledby': titleId },
		h( 'div', { class: 'arp-tl__head' }, h( 'h2', { class: 'arp-section-head__title', id: titleId }, __( 'Timeline' ) ), toggle ),
		caption,
		h( 'p', { class: 'arp-tl__safety' }, __( 'Estimated inventory for research stock review — not a dosing schedule.' ) ),
		legend,
		body,
		reviews
	);

	toggle.addEventListener( 'click', () => {
		showTable = ! showTable;
		toggle.setAttribute( 'aria-pressed', showTable ? 'true' : 'false' );
		el.classList.toggle( 'is-table', showTable );
	} );

	/** Row ID => { el, name, chartBox, tableBox, note, data, chartSig, tableSig, timeline }. */
	const rows = new Map();
	let reviewsSig = null;
	let lastData = null;
	let timer = null;

	/**
	 * Data of a row that its table depends on (JSON compared only when the timeline object changed).
	 *
	 * @param {Object} row  Row.
	 * @param {Object} view View.
	 * @return {string} Signature.
	 */
	const tableSignature = ( row, view ) => JSON.stringify( [ row.name, row.timeline, row.result && row.result.unit, view.locale, view.currency.decimalSeparator, view.currency.thousandSeparator ] );

	/**
	 * Creates or patches the DOM of one row.
	 *
	 * @param {Object} row  { id, name, result, timeline }.
	 * @param {Object} view View (rows, currency, locale, width, axis).
	 * @return {HTMLElement} Row element.
	 */
	const renderRow = ( row, view ) => {
		let entry = rows.get( row.id );
		if ( ! entry ) {
			const name = h( 'h3', { class: 'arp-tl__name' } );
			const chartBox = h( 'div', { class: 'arp-tl__chart', tabindex: '0', role: 'group' } );
			const tableBox = h( 'div', { class: 'arp-tl__table' } );
			const note = h( 'p', { class: 'arp-tl__note', hidden: true }, __( 'Long protocols are summarised: each table row groups several periods.' ) );
			entry = { el: h( 'div', { class: 'arp-tl__row' }, name, chartBox, tableBox, note ), name, chartBox, tableBox, note, timeline: null, tableSig: '', chartSig: '' };
			rows.set( row.id, entry );
		}
		// Unchanged objects (the same result as last time) are skipped without serialising them.
		const sameTimeline = entry.timeline === row.timeline && entry.result === row.result;
		const tableSig = sameTimeline && entry.nameText === row.name && entry.locale === view.locale ? entry.tableSig : tableSignature( row, view );
		const chartSig = tableSig + '|' + ( row.result && row.result.events_covered ) + '|' + view.width + '|' + JSON.stringify( view.axis );
		entry.timeline = row.timeline;
		entry.result = row.result;
		entry.nameText = row.name;
		entry.locale = view.locale;
		const heading = rowHeading( row, view );
		if ( entry.name.textContent !== heading ) {
			entry.name.textContent = heading;
			entry.chartBox.setAttribute( 'aria-label', row.name );
		}
		if ( chartSig !== entry.chartSig ) {
			entry.chartSig = chartSig;
			render( entry.chartBox, chart( row, view ) );
		}
		if ( tableSig !== entry.tableSig ) {
			entry.tableSig = tableSig;
			const data = tableData( row, view );
			const shape = JSON.stringify( [ row.name, data.length, !! row.timeline.start_date ] );
			const existing = entry.tableBox.firstElementChild;
			if ( existing && entry.tableShape === shape ) {
				patchTable( existing, data );
			} else {
				entry.tableShape = shape;
				render( entry.tableBox, table( row, data ) );
			}
			entry.note.hidden = ! ( row.timeline.warnings || [] ).some( ( w ) => w.code === 'timeline_aggregated' );
		}
		return entry.el;
	};

	/**
	 * Review dates of every row (rebuilt only when they changed).
	 *
	 * @param {Object} view View.
	 */
	const renderReviews = ( view ) => {
		const events = [];
		view.rows.forEach( ( row ) => {
			( row.timeline.review_events || [] ).forEach( ( event ) => events.push( { date: event.date, type: event.type, name: row.name } ) );
		} );
		events.sort( ( a, b ) => ( a.date === b.date ? 0 : a.date < b.date ? -1 : 1 ) );
		const sig = JSON.stringify( [ events, view.locale ] );
		if ( sig === reviewsSig ) {
			return;
		}
		reviewsSig = sig;
		if ( events.length === 0 ) {
			reviewsNote.textContent = __( 'Add a protocol start date to list research inventory review dates.' );
			reviewsNote.hidden = false;
			reviewsToggle.hidden = true;
			reviewsPanel.hidden = true;
			reviewsToggle.setAttribute( 'aria-expanded', 'false' );
			render( reviewsPanel );
			return;
		}
		reviewsNote.hidden = true;
		reviewsToggle.hidden = false;
		const shown = events.slice( 0, 60 );
		render(
			reviewsPanel,
			h( 'h3', { class: 'arp-tl__sub' }, __( 'Research inventory review dates' ) ),
			h(
				'ul',
				{ class: 'arp-tl__review-list' },
				shown.map( ( event ) =>
					h(
						'li',
						null,
						h( 'time', { datetime: event.date }, formatDate( event.date, view.locale ) ),
						h( 'span', { class: 'arp-tl__review-title' }, __( 'Research inventory review' ) ),
						/* translators: 1: name (product or option), 2: short explanation (review reason or why the option cannot be chosen). */
						h( 'span', { class: 'arp-tl__review-meta' }, sprintf( __( '%1$s — %2$s' ), event.name, reviewTypeLabel( event.type ) ) )
					)
				)
			),
			events.length > shown.length
				? h( 'p', { class: 'arp-tl__note' }, sprintf( /* translators: %d: number of further dates. */ _n( '%d more date is included in the calendar export.', '%d more dates are included in the calendar export.', events.length - shown.length ), events.length - shown.length ) )
				: null
		);
	};

	/** Draws the latest data now. */
	const flush = () => {
		clearTimeout( timer );
		timer = null;
		if ( ! lastData ) {
			return;
		}
		const view = { ...lastData, width: Math.max( 280, Math.floor( body.clientWidth || 0 ) ), axis: sharedAxis( lastData.rows ) };
		const ids = new Set( view.rows.map( ( row ) => row.id ) );
		for ( const [ id, entry ] of rows ) {
			if ( ! ids.has( id ) ) {
				entry.el.remove();
				rows.delete( id );
			}
		}
		if ( view.rows.length === 0 ) {
			if ( body.firstChild !== empty || body.childNodes.length !== 1 ) {
				render( body, empty );
			}
			legend.hidden = true;
			toggle.hidden = true;
			caption.hidden = true;
			reviews.hidden = true;
			reviewsSig = null;
			return;
		}
		if ( empty.parentNode === body ) {
			empty.remove();
		}
		legend.hidden = false;
		toggle.hidden = false;
		reviews.hidden = false;
		const text = timelineCaption( view.rows.map( ( row ) => row.format || '' ) );
		if ( caption.textContent !== text ) {
			caption.textContent = text;
		}
		caption.hidden = false;
		view.rows.forEach( ( row, index ) => {
			const node = renderRow( row, view );
			if ( body.children[ index ] !== node ) {
				body.insertBefore( node, body.children[ index ] || null );
			}
		} );
		renderReviews( view );
	};

	const api = {
		el,
		/**
		 * Updates the timeline: drawn RENDER_DELAY ms after the LAST update (while the visitor types,
		 * nothing is redrawn; the latest data is drawn once typing pauses).
		 *
		 * @param {Object} data { rows: [{ id, name, format, result, timeline }], currency, locale }.
		 */
		update( data ) {
			lastData = data;
			clearTimeout( timer );
			timer = setTimeout( flush, RENDER_DELAY );
		},
		flush,
	};

	// Re-draw the charts when the available width changes (rotation, sidebar, window resize).
	if ( typeof ResizeObserver === 'function' ) {
		let lastWidth = 0;
		new ResizeObserver( () => {
			const width = Math.floor( body.clientWidth || 0 );
			if ( Math.abs( width - lastWidth ) < 8 || ! lastData ) {
				lastWidth = width || lastWidth;
				return;
			}
			lastWidth = width;
			api.update( lastData );
		} ).observe( body );
	}
	return api;
}
