/**
 * Translated messages for the stable codes of ARCHITECTURE §1.3 that the browser may show for
 * local previews (the server translates its own responses through Api\Messages).
 *
 * @module messages
 */

import { __ } from './i18n.js';

/**
 * Message for a validation code.
 *
 * @param {string} code Code.
 * @return {string} Message.
 */
export function validationText( code ) {
	switch ( code ) {
		case 'unknown_field':
			return __( 'This field is not recognised.' );
		case 'required':
			return __( 'This field is required.' );
		case 'invalid_type':
			return __( 'This value has the wrong type or format.' );
		case 'invalid_number':
			return __( 'Enter a plain number using digits and an optional decimal separator, for example 250 or 0.5.' );
		case 'too_many_decimals':
			return __( 'Use at most 4 decimal places.' );
		case 'not_positive':
			return __( 'The value must be greater than zero.' );
		case 'too_large':
			return __( 'The value is too large.' );
		case 'integer_required':
			return __( 'Enter a whole number.' );
		case 'invalid_unit':
			return __( 'This unit is not supported for this product.' );
		case 'invalid_mode':
			return __( 'Choose a calculation mode.' );
		case 'invalid_period_unit':
			return __( 'Choose day, week or month.' );
		case 'out_of_range':
			return __( 'The value is outside the allowed range.' );
		case 'invalid_date':
			return __( 'Enter a real calendar date.' );
		case 'invalid_id':
			return __( 'Choose a product option.' );
		case 'too_long':
			return __( 'The text is too long.' );
		case 'too_many_lines':
			return __( 'The protocol has too many items.' );
		default:
			return __( 'The value is not valid.' );
	}
}

/**
 * Message for a calculation code.
 *
 * @param {string} code Code.
 * @return {string} Message.
 */
export function calculationText( code ) {
	switch ( code ) {
		case 'unit_incompatible':
			return __( 'The selected unit does not match the verified capacity of this product. Mass, activity (IU), volume, actuations and pieces are never converted into each other.' );
		case 'no_capacity':
			return __( 'This product has no verified capacity, so quantities cannot be calculated.' );
		case 'quantity_too_large':
			return __( 'The calculation exceeds the supported size. Reduce the amount, the number of uses or the quantity.' );
		case 'invalid_pack_count':
			return __( 'This product has an invalid pack size and needs store verification.' );
		case 'mode_not_allowed':
			return __( 'This calculation mode is not available for this product.' );
		default:
			return __( 'The calculation could not be completed.' );
	}
}

/**
 * Message for a readiness code of a product or variation.
 *
 * @param {string} code Readiness code.
 * @return {string} Message.
 */
export function readinessText( code ) {
	switch ( code ) {
		case 'product_not_found':
			return __( 'This product no longer exists.' );
		case 'unavailable':
			return __( 'Currently unavailable in the store.' );
		case 'excluded_category':
		case 'excluded_format':
			return __( 'Not available in the planner.' );
		case 'needs_mapping':
		case 'disabled':
		case 'unverified':
		case 'stale_mapping':
		case 'invalid':
			return __( 'Needs store verification before it can be calculated.' );
		default:
			return __( 'Not available for planning.' );
	}
}

/**
 * Message for a warning or assumption code.
 *
 * @param {string} code     Code.
 * @param {string} fallback Message from the server, used for unknown codes.
 * @return {string} Message.
 */
export function noticeText( code, fallback = '' ) {
	switch ( code ) {
		case 'price_unavailable':
			return __( 'No current store price is available, so no estimate is shown.' );
		case 'override_shortfall':
			return __( 'The chosen quantity does not cover the total required amount.' );
		case 'bundle_coverage_applied':
			return __( 'Units supplied by a bundle in this protocol were subtracted from the required quantity.' );
		case 'timeline_aggregated':
			return __( 'The timeline groups several periods into each point.' );
		case 'no_start_date':
			return __( 'No start date was entered, so the timeline uses relative periods and no review dates are created.' );
		case 'containers_capped':
			return __( 'Only the first 500 containers are listed individually.' );
		case 'out_of_stock':
			return __( 'This item is currently out of stock.' );
		case 'on_backorder':
			return __( 'This item is currently on backorder.' );
		case 'price_hidden':
			return __( 'Price estimates are hidden by the store.' );
		case 'usable_equals_labelled':
			return __( 'The labelled amount per container is treated as fully usable.' );
		case 'usable_amount_verified':
			return __( 'The calculation uses the merchant-verified usable amount per container.' );
		case 'event_count_explicit':
			return __( 'Number of uses = times per period × number of periods, exactly as entered.' );
		case 'whole_units_rounded_up':
			return __( 'Quantities are rounded up to whole purchase units.' );
		case 'pack_boundary':
			return __( 'Each purchase unit contains several containers; quantities are counted in whole purchase units.' );
		case 'calendar_months':
			return __( 'Monthly periods follow calendar months; when the start day does not exist in a month, the last day of that month is used.' );
		case 'end_date_exclusive':
			return __( 'The end date is the first day after the protocol; the last day of the protocol is the day before it.' );
		case 'estimate_excludes_tax_shipping_discounts':
			return __( 'Estimates use current store prices and exclude shipping, taxes and discounts.' );
		default:
			return fallback !== '' ? fallback : code;
	}
}
