/**
 * Share dialog (logged-in customer + plan saved to the account + sharing enabled): scope
 * (quantities only by default, or full plan), expiry in days, create → private link with copy
 * button, list and revoke existing links. Unsaved changes are saved before a link is created.
 *
 * @module components/share
 */

import { h, uid, button, render } from '../app/dom.js';
import { __, _n, sprintf } from '../app/i18n.js';
import { formatDate } from '../app/format.js';
import { shareUrlFrom } from '../app/api.js';
import { openDialog, confirmDialog, dialogSection } from './modal.js';
import { focusElement } from '../app/a11y.js';
import { createLiveMessage } from './live-message.js';

/**
 * Copies text to the clipboard (navigator.clipboard with a selection fallback).
 *
 * @param {string}           text  Text.
 * @param {HTMLInputElement} input Input holding the text (fallback).
 * @return {Promise<boolean>} Copied.
 */
export async function copyText( text, input = null ) {
	try {
		if ( navigator.clipboard && window.isSecureContext ) {
			await navigator.clipboard.writeText( text );
			return true;
		}
	} catch ( e ) {
		// Fall back to the selection below.
	}
	try {
		if ( input ) {
			input.focus();
			input.select();
			input.setSelectionRange( 0, text.length );
			return document.execCommand( 'copy' );
		}
	} catch ( e ) {
		return false;
	}
	return false;
}

/**
 * Opens the share dialog.
 *
 * A link is a frozen copy of the plan SAVED in the account. When the workspace has changes that
 * are not saved yet, the dialog says so and "Create link" becomes "Save changes and create link":
 * the plan is saved first (PATCH, optimistic concurrency) and the link is created only when that
 * succeeded, so a link never silently shows an older version.
 *
 * Every control keeps a stable `data-focus-key`, so re-rendering after an action never drops focus.
 *
 * @param {Object} ctx { api, locale, defaultDays, maxDays, getMeta(), onSaveFirst(),
 *                     saveChanges() => Promise<{ok: boolean, message: string}> }.
 */
export function openShareDialog( ctx ) {
	const meta = ctx.getMeta();
	const live = createLiveMessage();
	const body = h( 'div', { class: 'arp-share__body' } );
	const intro = h( 'p', { class: 'arp-share__intro' }, __( 'Share links are private: they are not listed anywhere, are hidden from search engines, expire automatically and can be revoked at any time. Anyone who has the link can view the protocol read-only.' ) );
	// The result regions are created once and never re-rendered (each result is announced once).
	const root = h( 'div', { class: 'arp-share' }, intro, live.el, body );
	const state = { shares: [], status: 'loading', error: '', created: null, message: null, busy: '' };

	if ( meta.kind !== 'account' || ! meta.uuid ) {
		openDialog( {
			title: __( 'Share this protocol' ),
			size: 'sm',
			content: h( 'p', null, __( 'Share links are created from protocols saved in your account. Save this protocol to your account first.' ) ),
			actions: ( dlg ) => [
				button( { label: __( 'Cancel' ), onClick: () => dlg.close( null ) } ),
				button( {
					label: __( 'Save to my account' ),
					variant: 'primary',
					onClick: () => {
						dlg.close( null );
						ctx.onSaveFirst();
					},
				} ),
			],
		} );
		return;
	}

	const uuid = meta.uuid;
	const dirty = () => !! ctx.getMeta().dirty;
	const scopeName = uid( 'scope' );
	const daysId = uid( 'days' );
	const daysHelp = uid( 'days-help' );
	const urlId = uid( 'share-url' );
	const max = Math.max( 1, ctx.maxDays || 90 );
	const days = h( 'input', { id: daysId, class: 'arp-input arp-input--short', type: 'number', min: '1', max: String( max ), step: '1', value: String( Math.min( max, ctx.defaultDays || 30 ) ), inputmode: 'numeric', 'aria-describedby': daysHelp } );
	const scopeOption = ( value, label, help, checked ) =>
		h( 'label', { class: 'arp-radio arp-radio--card' }, h( 'input', { type: 'radio', name: scopeName, value, checked, 'data-focus-key': 'scope:' + value } ), h( 'span', null, h( 'strong', null, label ), h( 'span', { class: 'arp-field__help' }, help ) ) );

	const scopeFieldset = h(
		'fieldset',
		{ class: 'arp-fieldset' },
		h( 'legend', { class: 'arp-label' }, __( 'What the link shows' ) ),
		scopeOption( 'quantities', __( 'Quantities only' ), __( 'Product names, options and quantities. Your research inputs are not included.' ), true ),
		scopeOption( 'full', __( 'Full protocol including research inputs' ), __( 'Also includes the amounts, units, schedules and dates you entered.' ), false )
	);

	const loadShares = async () => {
		if ( state.status !== 'ready' ) {
			state.status = 'loading';
		}
		refresh();
		try {
			const data = await ctx.api.listShares( uuid );
			state.shares = Array.isArray( data ) ? data : ( data && Array.isArray( data.items ) ? data.items : [] );
			state.status = 'ready';
		} catch ( e ) {
			state.status = 'error';
			state.error = e.message;
		}
		refresh();
	};

	const create = async () => {
		if ( state.busy ) {
			return;
		}
		const scope = ( root.querySelector( `input[name="${ scopeName }"]:checked` ) || {} ).value || 'quantities';
		const n = Number( days.value );
		if ( ! Number.isInteger( n ) || n < 1 || n > max ) {
			/* translators: %d: maximum number of days. */
			state.message = { tone: 'error', text: sprintf( __( 'Enter a number of days from 1 to %d.' ), max ) };
			refresh();
			days.focus();
			return;
		}
		state.message = null;
		if ( dirty() ) {
			state.busy = 'saving';
			refresh();
			const saved = await ctx.saveChanges();
			if ( ! saved || ! saved.ok ) {
				state.busy = '';
				state.message = { tone: 'error', text: ( saved && saved.message ) || __( 'Your changes could not be saved, so no link was created.' ) };
				refresh();
				return;
			}
		}
		state.busy = 'creating';
		refresh();
		try {
			const data = await ctx.api.createShare( uuid, { scope, days: n } );
			state.created = { url: shareUrlFrom( data, window.location.href ), expires_at: String( ( data && data.expires_at ) || '' ), scope };
			state.message = null;
			state.busy = '';
			await loadShares();
			const input = root.querySelector( '#' + urlId );
			if ( input ) {
				input.focus();
				input.select();
			}
		} catch ( e ) {
			state.busy = '';
			state.message = { tone: 'error', text: e.message };
			refresh();
		}
	};

	const revoke = async ( share ) => {
		const ok = await confirmDialog( {
			title: __( 'Revoke this link?' ),
			message: __( 'Anyone using this link will no longer be able to open the protocol.' ),
			confirmLabel: __( 'Revoke' ),
			danger: true,
		} );
		if ( ! ok ) {
			return;
		}
		state.message = null;
		refresh();
		try {
			await ctx.api.revokeShare( uuid, share.share_id ?? share.id );
			state.message = { tone: 'success', text: __( 'The link was revoked.' ) };
			loadShares();
		} catch ( e ) {
			state.message = { tone: 'error', text: e.message };
			refresh();
		}
	};

	const dateOf = ( value ) => ( typeof value === 'string' && /^\d{4}-\d{2}-\d{2}/.test( value ) ? formatDate( value.slice( 0, 10 ), ctx.locale ) : '' );
	const scopeText = ( scope ) => ( scope === 'full' ? __( 'Full protocol' ) : __( 'Quantities only' ) );

	function refresh() {
		const unsaved = dirty();
		const copyButton = button( {
			label: __( 'Copy protocol link' ),
			iconName: 'copy',
			attrs: { 'data-focus-key': 'copy' },
			onClick: async () => {
				// A new action: clear the previous result so a repeated "Link copied." is announced again.
				if ( state.message ) {
					state.message = null;
					refresh();
				}
				const input = root.querySelector( '#' + urlId );
				const ok = await copyText( state.created.url, input );
				state.message = ok ? { tone: 'success', text: __( 'Link copied.' ) } : { tone: 'error', text: __( 'Copy failed. Select the link and copy it manually.' ) };
				refresh();
			},
		} );
		let list;
		if ( state.status === 'loading' ) {
			list = h( 'p', { role: 'status' }, __( 'Loading links…' ) );
		} else if ( state.status === 'error' ) {
			list = h( 'p', { class: 'arp-notice arp-notice--error' }, state.error );
		} else if ( state.shares.length === 0 ) {
			list = h( 'p', { class: 'arp-plans__empty' }, __( 'No links have been created for this protocol.' ) );
		} else {
			list = h(
				'ul',
				{ class: 'arp-plans__list' },
				state.shares.map( ( share ) => {
					const revoked = share.status ? share.status === 'revoked' : !! share.revoked_at;
					const expired = share.status
						? share.status === 'expired'
						: ! revoked && typeof share.expires_at === 'string' && share.expires_at.replace( ' ', 'T' ) < new Date().toISOString().slice( 0, 19 );
					let status = __( 'Active' );
					if ( revoked ) {
						status = __( 'Revoked' );
					} else if ( expired ) {
						status = __( 'Expired' );
					}
					const opens = Number.isInteger( share.access_count ) ? sprintf( /* translators: %d: number of times opened. */ _n( 'opened %d time', 'opened %d times', share.access_count ), share.access_count ) : '';
					const metaId = uid( 'share-meta' );
					return h(
						'li',
						{ class: 'arp-plans__item' },
						h(
							'div',
							{ class: 'arp-plans__info' },
							h( 'p', { class: 'arp-plans__name' }, scopeText( share.scope ), h( 'span', { class: 'arp-badge ' + ( revoked || expired ? 'arp-badge--muted' : 'arp-badge--success' ) }, status ) ),
							h(
								'p',
								{ class: 'arp-plans__meta', id: metaId },
								[
									/* translators: %s: date. */
									share.created_at ? sprintf( __( 'created %s' ), dateOf( share.created_at ) ) : '',
									/* translators: %s: date. */
									share.expires_at ? sprintf( __( 'expires %s' ), dateOf( share.expires_at ) ) : '',
									opens,
								]
									.filter( Boolean )
									.join( ' · ' )
							)
						),
						revoked || expired
							? null
							: h(
								'div',
								{ class: 'arp-plans__actions' },
								button( {
									label: __( 'Revoke' ),
									size: 'sm',
									variant: 'ghost',
									cls: 'arp-btn--danger-ghost',
									attrs: { 'aria-describedby': metaId, 'data-focus-key': 'revoke:' + String( share.share_id ?? share.id ) },
									onClick: () => revoke( share ),
								} )
							)
					);
				} )
			);
		}

		let createLabel = unsaved ? __( 'Save changes and create link' ) : __( 'Create link' );
		if ( state.busy === 'saving' ) {
			createLabel = __( 'Saving your changes…' );
		} else if ( state.busy === 'creating' ) {
			createLabel = __( 'Creating…' );
		}

		const focused = document.activeElement && root.contains( document.activeElement ) ? document.activeElement : null;
		const focusKey = focused && focused.dataset ? focused.dataset.focusKey || '' : '';
		const focusedId = focused && ! focusKey ? focused.id : '';
		const messageEl = live.set( state.message );
		render(
			body,
			unsaved
				? h(
					'div',
					{ class: 'arp-notice arp-notice--warning arp-share__unsaved' },
					h( 'p', { class: 'arp-notice__title' }, __( 'This protocol has unsaved changes' ) ),
					h( 'p', null, __( 'A link shows the version saved in your account, never later changes. Your changes are saved to your account before the link is created.' ) )
				)
				: null,
			dialogSection(
				__( 'Create a link' ),
				scopeFieldset,
				h(
					'div',
					{ class: 'arp-field' },
					h( 'label', { class: 'arp-label', for: daysId }, __( 'Link expires after (days)' ) ),
					days,
					/* translators: %d: maximum number of days. */
					h( 'p', { class: 'arp-field__help', id: daysHelp }, sprintf( __( 'From 1 to %d days.' ), max ) )
				),
				// aria-disabled while busy: a disabled button would drop keyboard focus.
				button( { label: createLabel, iconName: 'link', variant: 'primary', attrs: { 'aria-disabled': state.busy ? 'true' : null, 'aria-busy': state.busy ? 'true' : null, 'data-focus-key': 'create' }, onClick: create } )
			),
			state.created
				? dialogSection(
					__( 'Your new link' ),
					h(
						'div',
						{ class: 'arp-field' },
						h( 'label', { class: 'arp-label', for: urlId }, __( 'Link' ) ),
						h( 'div', { class: 'arp-input-group' }, h( 'input', { id: urlId, class: 'arp-input', type: 'text', readonly: true, value: state.created.url } ), copyButton ),
						h( 'p', { class: 'arp-field__help' }, __( 'This link is shown only once. Copy it now.' ) )
					)
				)
				: null,
			dialogSection( __( 'Existing links' ), list )
		);
		if ( focused && document.activeElement !== focused ) {
			let again = null;
			if ( focusKey ) {
				again = root.querySelector( '[data-focus-key="' + focusKey.replace( /["\\]/g, '\\$&' ) + '"]' );
			} else if ( focusedId ) {
				again = root.querySelector( '#' + focusedId );
			}
			if ( again ) {
				again.focus();
			} else {
				focusElement( messageEl || root.closest( '.arp-dialog' ) || root, { preventScroll: true } );
			}
		}
	}

	refresh();
	openDialog( { title: __( 'Share this protocol' ), size: 'md', content: root } );
	loadShares();
}
